def _virtual_workspace_rclone_spec() -> Optional[dict[str, Any]]:
    """The deployment's object-store spec for the ``virtual`` tier, or None.

    Built from env wired by Helm (``virtualWorkspace.*``):

    - ``VIRTUAL_WORKSPACE_RCLONE_TYPE`` — rclone backend (``s3`` or, for a
      non-durable dev store, ``memory``). Empty ⇒ tier disabled (None).
    - ``VIRTUAL_WORKSPACE_RCLONE_ROOT`` — bucket or ``bucket/subpath``.
    - For ``s3``: discrete fields rather than a JSON blob, mirroring the
      snapshot S3 wiring. ``VIRTUAL_WORKSPACE_S3_ACCESS_KEY_ID`` /
      ``_SECRET_ACCESS_KEY`` are the (Secret-held) credentials; ``_ENDPOINT`` /
      ``_REGION`` / ``_PROVIDER`` are non-secret config. Each ``config`` key
      becomes ``RCLONE_CONFIG_*`` env in the agent, so secrets never reach argv.

    Returns the ``{type, config, root}`` shape the agent's
    ``object_store_from_spec`` consumes as ``rclone_spec`` (§4/§5). ``config``
    holds rclone backend key/values; for ``memory`` it is empty.
    """
    return _build_virtual_workspace_rclone_spec()


def _object_store_startup_warning(
    env: Optional[Mapping[str, str]] = None,
) -> Optional[str]:
    """One consolidated warning when EITHER object-store seam is unconfigured.

    Reads the same env the features read, so it reflects the real resolved
    config whether the store is external or the chart-bundled Garage:
    ``S3_ENDPOINT`` (snapshots / suspend-resume / IDE persistence / VM S3
    extract) and ``VIRTUAL_WORKSPACE_RCLONE_TYPE`` (the virtual/default session
    tier). Emits one loud line naming whichever seam is degraded: the two
    almost always point at the SAME store, so a half-configured deployment is
    usually a mistake, and — with instant-landing making ``virtual`` the
    default session backend — a snapshots-only config silently breaks the
    default UX. Returns None only when BOTH seams have a durable store. Replaces
    the scattered, late per-feature failures (``LiteWorkspaceConfigError`` at
    dispatch, silent snapshot no-ops) with one signal at startup. See
    knowledge-history/done/s3_object_store_bundled_fallback.md item 3.
    """
    env = os.environ if env is None else env
    s3_endpoint = (env.get("S3_ENDPOINT") or "").strip()
    rclone_type = (env.get("VIRTUAL_WORKSPACE_RCLONE_TYPE") or "").strip()

    bullets: list[str] = []
    if not s3_endpoint:
        bullets.append(
            "workspace snapshots + suspend/resume, IDE session persistence, and "
            "VM-lifecycle S3 extract are disabled (S3_ENDPOINT unset)"
        )
    if rclone_type != "s3":
        if rclone_type == "memory":
            bullets.append(
                "virtual/instant sessions run but are NON-DURABLE (in-process "
                "'memory' store — files vanish on pod restart)"
            )
        else:
            bullets.append(
                "virtual/instant sessions FAIL at dispatch "
                "(LiteWorkspaceConfigError) — if your deployment uses them"
            )

    if not bullets:
        return None

    return (
        "Object store not fully configured — "
        + "; ".join(bullets)
        + ". Fix: point at an external S3 (S3_ENDPOINT / VIRTUAL_WORKSPACE_S3_*) "
        "or enable the chart-bundled store (garage.enabled=true). "
        "See knowledge-history/done/s3_object_store_bundled_fallback.md."
    )


def _check_object_store_config(
    env: Optional[Mapping[str, str]] = None,
) -> Optional[str]:
    """Warn (return the message) or fail-closed (raise) on an incomplete
    object-store config.

    Default (``OBJECT_STORE_REQUIRED`` unset/falsey) is warn-only, matching the
    platform's degrade-open convention. When ``OBJECT_STORE_REQUIRED`` is set
    (``true``/``1``/``yes``) and either seam lacks a durable store, raises
    ``RuntimeError`` so the orchestrator refuses to start — crash-looping until
    the operator fixes it — for deployments that prefer fail-closed over silent
    degradation. Returns None when both seams have a durable store.
    """
    env = os.environ if env is None else env
    msg = _object_store_startup_warning(env)
    if msg and (env.get("OBJECT_STORE_REQUIRED") or "").lower().strip() in (
        "true",
        "1",
        "yes",
    ):
        raise RuntimeError(
            msg + " OBJECT_STORE_REQUIRED is set, so the orchestrator refuses "
            "to start with an incomplete object-store config."
        )
    return msg


def _inject_lite_workspace_config(
    config_override: Optional[dict[str, Any]], *, prefix: str
) -> Optional[dict[str, Any]]:
    """Enrich ``config_override.workspace`` for the lite tiers (``virtual``/``none``).

    No-op for any other backend. For ``virtual`` it attaches the object-store
    ``mounts`` (credentials sourced from deployment env and injected *in-flight*
    only — never persisted to the job/thread row, matching how dispatch keeps
    API keys inline). For ``none`` it strips any stray mounts. Both force
    ``git_versioning`` off (§8 — lite tiers have no git).

    ``prefix`` is the object-store key prefix for this owner
    (``jobs/<id>/`` for jobs, ``threads/<id>/`` for sessions).

    Raises:
        LiteWorkspaceConfigError: ``virtual`` requested but no object store is
            configured for this deployment.
    """
    backend = _backend_from_override(config_override)
    if backend not in LITE_BACKENDS:
        return config_override

    config_override = config_override or {}
    ws = config_override.setdefault("workspace", {})
    ws["backend"] = backend
    ws["git_versioning"] = False

    if backend == "virtual":
        spec = _virtual_workspace_rclone_spec()
        if spec is None:
            raise LiteWorkspaceConfigError(
                "workspace.backend='virtual' needs an object store, but this "
                "deployment has none configured. Set virtualWorkspace.rclone.type "
                "(+ .root) and, for s3, virtualWorkspace.s3.* plus the "
                "VIRTUAL_WORKSPACE_S3_ACCESS_KEY_ID / _SECRET_ACCESS_KEY secrets "
                "— or use backend='none' for a no-file-tools agent, or "
                "'sandbox'/'vm' for a full workspace."
            )
        ws["mounts"] = [
            {
                "name": "workspace",
                "rclone_spec": spec,
                "prefix": prefix,
                "access": "read_write",
            }
        ]
    else:  # "none" — no file tools, so no object-store mounts
        ws.pop("mounts", None)

    return config_override


def _repository_datasource_names(datasources: Any) -> list[str]:
    """Names of any ``repository``-type datasources in a resolved list.

    Repository datasources require a shell-capable workspace to clone into;
    the lite tiers have none (§4/§7), so their presence is the tier boundary.
    Returns a (possibly empty) list of human-readable names for the error.
    """
    names: list[str] = []
    for ds in datasources or []:
        if not isinstance(ds, dict):
            continue
        if (ds.get("type") or "").lower() == "repository":
            names.append(str(ds.get("name") or ds.get("id") or "?"))
    return names


async def _inherit_parent_datasource_ids(
    *, thread_id: str | None, parent_job_id: str | None
) -> list[str]:
    """Datasource IDs a parented subjob inherits when it passes no explicit
    selection (delegation keeps working without force-attaching anything).

    Prefers the parent thread's persisted selection
    (``threads.metadata.datasource_ids``), then the parent job's
    immutable datasource-selection snapshot. Returns [] when neither parent
    actually exists/yields a selection; database and policy failures propagate.
    """
    if thread_id:
        thread = await postgres_db.get_thread(thread_id)
        if thread:
            meta = thread.get("metadata") or {}
            if isinstance(meta, str):
                try:
                    meta = json.loads(meta)
                except (json.JSONDecodeError, TypeError):
                    meta = {}
            # Presence is authoritative, including an explicit empty list.
            # Falling through on ``[]`` would resurrect the parent job's
            # connectors and make a deliberate opt-out impossible.
            if "datasource_ids" in meta:
                ids = meta.get("datasource_ids") or []
                return [str(x) for x in ids]
    if parent_job_id:
        parent = await postgres_db.get_job(parent_job_id)
        if parent is None:
            return []
        selected, _policy_revisions = await _revalidate_job_datasource_selection(parent)
        return selected
    return []


async def _filter_implicit_lite_datasource_ids(
    datasource_ids: list[str], workspace_backend: str | None
) -> list[str]:
    """Drop clone-based repositories from an implicit/default selection.

    Explicit selections fail loudly in the central policy service. Inherited
    and automatic choices are creation-time seeds, so lite tiers keep the
    usable connectors while omitting repositories they cannot materialize.
    Missing IDs remain in the list and therefore still fail closed when the
    complete set is authorized.
    """
    if workspace_backend not in LITE_BACKENDS or not datasource_ids:
        return datasource_ids
    rows = await postgres_db.get_datasource_policy_rows(datasource_ids)
    repositories = {
        str(row["id"])
        for row in rows
        if str(row.get("type") or "").lower() == "repository"
    }
    return [value for value in datasource_ids if str(value) not in repositories]


async def _datasource_selection_provenance(
    *,
    datasource_ids: list[str],
    policy_revisions: dict[str, int],
    origin: str,
    effective_work_owner_id: str | None,
    actor: dict[str, Any] | None,
    project_ids: list[str],
    creation_path: str,
) -> dict[str, Any]:
    """Build the credential-free audit stamp materialized with work."""
    return {
        "origin": origin,
        "creation_path": creation_path,
        "effective_work_owner_id": effective_work_owner_id,
        "initiating_actor_id": str(actor.get("id"))
        if actor and actor.get("id")
        else None,
        "project_ids": list(project_ids),
        "datasource_ids": list(datasource_ids),
        "policy_revisions": dict(policy_revisions),
        "materialized_at": datetime.now(timezone.utc).isoformat(),
    }


async def _revalidate_job_datasource_selection(
    job: dict[str, Any],
) -> tuple[list[str], dict[str, int]]:
    """Reauthorize a job and return the exact connector policy snapshot."""
    job_id = str(job["id"])
    selected = await postgres_db.list_job_datasource_ids(job_id)
    job_context = job.get("context") or {}
    if isinstance(job_context, str):
        try:
            job_context = json.loads(job_context)
        except (json.JSONDecodeError, TypeError) as exc:
            raise HTTPException(
                status_code=403,
                detail="One or more selected connectors are unavailable",
            ) from exc
    materialized = (
        job_context.get("datasource_selection")
        if isinstance(job_context, dict)
        else None
    )
    raw_ids = None
    if isinstance(materialized, dict):
        # ``datasource_ids`` is the shipped provenance key.  Accept the
        # feature-document name too so both writers share the same immutable
        # materialization contract during rollout.
        raw_ids = materialized.get("selected_ids", materialized.get("datasource_ids"))
    try:
        if not isinstance(raw_ids, list):
            raise ValueError
        snapshot_ids = [str(UUID(str(value))) for value in raw_ids]
        junction_ids = [str(UUID(str(value))) for value in selected]
        if len(snapshot_ids) != len(set(snapshot_ids)):
            raise ValueError
    except (TypeError, ValueError) as exc:
        raise HTTPException(
            status_code=403,
            detail="One or more selected connectors are unavailable",
        ) from exc
    if set(snapshot_ids) != set(junction_ids) or len(snapshot_ids) != len(junction_ids):
        raise HTTPException(
            status_code=403,
            detail="One or more selected connectors are unavailable",
        )
    selected = snapshot_ids
    owner_id = str(job["user_id"]) if job.get("user_id") else None
    actor = await postgres_db.get_user(owner_id) if owner_id else None
    config_override = job.get("config_override") or {}
    if isinstance(config_override, str):
        try:
            config_override = json.loads(config_override)
        except (json.JSONDecodeError, TypeError):
            config_override = {}
    return await _authorize_thread_datasource_selection(
        actor,
        selected,
        workspace_backend=_backend_from_override(config_override),
        target_project_ids=([str(job["project_id"])] if job.get("project_id") else []),
        effective_work_owner_id=owner_id,
        trusted_system_inheritance=owner_id is None,
        legacy_job_id=job_id,
    )


def _require_exact_datasource_resolution(
    selected_ids: list[str],
    policy_revisions: dict[str, int],
    resolved: list[dict[str, Any]] | None,
) -> list[dict[str, Any]]:
    """Fail closed unless resolution matches the authorized snapshot exactly.

    This is the last gate before credential payload construction.  A deleted
    connector, a revision change, duplicate resolver rows, or any silent
    reduction is one unavailable data contract rather than a partial attach.
    """
    unavailable = HTTPException(
        status_code=403,
        detail="One or more selected connectors are unavailable",
    )
    try:
        expected_ids = [str(UUID(str(value))) for value in selected_ids]
        expected_revisions = {
            str(UUID(str(datasource_id))): int(revision)
            for datasource_id, revision in policy_revisions.items()
        }
        rows = list(resolved or [])
        actual_ids = [str(UUID(str(row["id"]))) for row in rows]
        actual_revisions = {
            str(UUID(str(row["id"]))): int(row.get("policy_revision") or 0)
            for row in rows
        }
    except (KeyError, TypeError, ValueError) as exc:
        raise unavailable from exc

    if (
        len(expected_ids) != len(set(expected_ids))
        or len(actual_ids) != len(set(actual_ids))
        or len(rows) != len(expected_ids)
        or set(actual_ids) != set(expected_ids)
        or set(expected_revisions) != set(expected_ids)
        or actual_revisions != expected_revisions
    ):
        raise unavailable
    return rows


async def _resolve_authorized_job_datasources(
    job: dict[str, Any],
) -> list[dict[str, Any]]:
    """Authorize and exactly resolve a job's immutable connector snapshot."""
    selected, policy_revisions = await _revalidate_job_datasource_selection(job)
    resolved = await postgres_db.resolve_datasources_for_job(
        str(job["id"]),
        project_id=(str(job["project_id"]) if job.get("project_id") else None),
    )
    return _require_exact_datasource_resolution(selected, policy_revisions, resolved)


async def _revalidate_job_datasource_ids(job: dict[str, Any]) -> list[str]:
    """Reauthorize a job's materialized set before credential delivery."""
    selected, _revisions = await _revalidate_job_datasource_selection(job)
    return selected


def _job_needs_vm(job: dict) -> bool:
    """Whether the authoritative contract assigns the VM tier."""

    try:
        return resolve_workspace_contract(job).assigned_backend == "vm"
    except WorkspaceContractError:
        # Malformed/ambiguous jobs are refused by the bundle resolver. Never
        # guess a tier here merely because one runtime happens to be ready.
        return False


def _get_vm_context(job: dict) -> dict:
    """Extract the vm sub-dict from job context."""
    ctx = job.get("context") or {}
    if isinstance(ctx, str):
        try:
            ctx = json.loads(ctx)
        except (json.JSONDecodeError, TypeError):
            ctx = {}
    return ctx.get("vm", {})


def _get_infra_transient_context(job: dict) -> dict:
    """Extract the infra_transient sub-dict from job context.

    The attempt counter lives in ``context``, NOT in ``freeze_data``: the
    sweeper clears ``freeze_data`` to make the job dispatchable again, so a
    counter kept there would reset to zero on every retry and the give-up
    ceiling would never be reached. Mirrors ``context.llm_outage``.
    """
    ctx = job.get("context") or {}
    if isinstance(ctx, str):
        try:
            ctx = json.loads(ctx)
        except (json.JSONDecodeError, TypeError):
            ctx = {}
    value = ctx.get("infra_transient")
    return value if isinstance(value, dict) else {}


async def _fail_vm_parked_job(job_id: str, vm_error: str) -> None:
    """Fail a job whose VM provisioning parked terminally.

    A parked VM context alone leaves the job in 'created' with nothing
    scheduled to ever change its state — an invisible wedge that stalls any
    loop whose current_job never turns terminal. Failing the job makes the
    park visible (cockpit/API) and lets loop failure handling advance. See
    knowledge-base/knowledge/issues/vm_ssh_readiness_probe_unroutable_from_orchestrator.md.
    """
    await postgres_db.update_job_status(
        job_id,
        status="failed",
        error_message=(
            f"VM provisioning failed: {vm_error}. "
            "To retry, clear context.vm and re-queue the job."
        ),
    )


def _job_needs_sandbox(job: dict) -> bool:
    """Check if a job needs a sandbox workspace container.

    Returns True if:
    - config_override.workspace.backend == "sandbox" (or legacy "container"), OR
    - backend is not explicitly set to "vm" AND a workspace
      provisioner is available (k8s ContainerProvisioner OR DockerProvisioner).

    Returns False if the job already has a ready VM or container inherited
    from a parent job (worktree sharing — no new container needed).
    """
    try:
        contract = resolve_workspace_contract(job)
    except WorkspaceContractError:
        return False
    if contract.assigned_backend != "sandbox":
        return False
    decision = resolve_workspace_runtime(job, vm_mode=vm_provisioner.mode)
    # An opposite-tier VM must never suppress sandbox provisioning.
    return decision.effective_backend != "sandbox"


def _resolve_requested_job_execution_lane(
    requested_lane: Literal["pinned", "stateless"] | None,
    *,
    default_stateless: bool,
    needs_vm: bool,
    needs_sandbox: bool,
) -> Literal["pinned", "stateless"] | None:
    """Apply the default-off, pod-network-workspace worker admission gate.

    ``None`` is preserved unless a capable omitted root opts into defaulting,
    so Postgres can still distinguish authoritative child-lane inheritance.
    """
    same_cluster_vm = needs_vm and vm_workspaces_on_pod_network()
    if needs_vm and not same_cluster_vm:
        # External VMs still require the registered agent's mesh sidecar. The
        # shared executor Deployment deliberately has no tailnet identity.
        return "pinned"
    if requested_lane is None and default_stateless:
        if STATELESS_WORKER_ENABLED and (
            same_cluster_vm
            or (
                container_provisioner.is_available
                and container_provisioner.in_cluster
                and needs_sandbox
            )
        ):
            return "stateless"
        return None
    if requested_lane != "stateless":
        return requested_lane
    if not STATELESS_WORKER_ENABLED:
        raise HTTPException(
            status_code=409, detail="Stateless worker admission is disabled"
        )
    if not same_cluster_vm and not (
        container_provisioner.is_available and container_provisioner.in_cluster
    ):
        raise HTTPException(
            status_code=503,
            detail=(
                "Stateless workers require an in-cluster Kubernetes "
                "workspace provisioner"
            ),
        )
    if not (needs_sandbox or same_cluster_vm):
        raise HTTPException(
            status_code=422,
            detail=(
                "Stateless workers currently require a Kubernetes sandbox or "
                "same-cluster VM workspace"
            ),
        )
    return "stateless"


def _get_container_context(job: dict) -> dict:
    """Extract the workspace_container sub-dict from job context."""
    ctx = job.get("context") or {}
    if isinstance(ctx, str):
        try:
            ctx = json.loads(ctx)
        except (json.JSONDecodeError, TypeError):
            ctx = {}
    return ctx.get("workspace_container", {})


def _stateless_worker_workspace_owner(job: dict) -> WorkspaceOwner:
    """Resolve whose Kubernetes workspace a stateless worker must attest."""

    ctx = job.get("context") or {}
    if isinstance(ctx, str):
        try:
            ctx = json.loads(ctx)
        except (json.JSONDecodeError, TypeError):
            ctx = {}
    parent_id = job.get("parent_job_id")
    if parent_id and ctx.get("inherits_parent_workspace"):
        return WorkspaceOwner.job(str(parent_id))
    return WorkspaceOwner.job(str(job["id"]))


@dataclass(frozen=True, slots=True)
class _PinnedK8sJobWorkspaceAuthority:
    """One exact server-attested Kubernetes workspace delivery tuple."""

    owner: WorkspaceOwner
    attestation: WorkspaceRuntimeAttestation


async def _attest_pinned_k8s_job_workspace(
    job: dict[str, Any],
) -> tuple[dict[str, Any], _PinnedK8sJobWorkspaceAuthority | None]:
    """Replace a pinned job's Kubernetes endpoint with a fresh attestation."""

    decision = resolve_workspace_runtime(job, vm_mode=vm_provisioner.mode)
    if not decision.ready or decision.effective_backend != "sandbox":
        return job, None
    workspace = _get_container_context(job)
    provisioner = str(workspace.get("provisioner") or "").strip().lower()
    if provisioner == "docker":
        return job, None
    if provisioner != "k8s":
        raise WorkspaceRuntimeAuthorityError(
            "sandbox workspace provisioner authority is unavailable"
        )
    try:
        expected_runtime = str(
            UUID(str(workspace.get(WORKSPACE_RUNTIME_INCARNATION_KEY)))
        )
        stored_port = int(workspace.get("port") or 30022)
    except (TypeError, ValueError) as exc:
        raise WorkspaceRuntimeAuthorityError(
            "sandbox workspace runtime authority is malformed"
        ) from exc

    owner = _stateless_worker_workspace_owner(job)
    attestation = await container_provisioner.attest_workspace_runtime(owner)
    if attestation.runtime_incarnation != expected_runtime:
        raise WorkspaceRuntimeAuthorityError(
            "sandbox workspace runtime changed before delivery"
        )
    stored_host = workspace.get("host")
    stored_ip = workspace.get("pod_ip")
    if (
        (stored_host and str(stored_host) != attestation.host)
        or (stored_ip and str(stored_ip) != attestation.pod_ip)
        or stored_port != attestation.port
    ):
        raise WorkspaceRuntimeAuthorityError(
            "sandbox workspace endpoint changed before delivery"
        )

    exact_workspace = copy.deepcopy(workspace)
    exact_workspace.update(
        {
            "status": "ready",
            "provisioner": "k8s",
            "host": attestation.host,
            "pod_ip": attestation.pod_ip,
            "port": attestation.port,
            WORKSPACE_RUNTIME_INCARNATION_KEY: attestation.runtime_incarnation,
        }
    )
    context = job.get("context") or {}
    if isinstance(context, str):
        try:
            context = json.loads(context)
        except (json.JSONDecodeError, TypeError) as exc:
            raise WorkspaceRuntimeAuthorityError(
                "sandbox workspace context is malformed"
            ) from exc
    if not isinstance(context, Mapping):
        raise WorkspaceRuntimeAuthorityError("sandbox workspace context is malformed")
    exact_job = copy.deepcopy(job)
    exact_context = copy.deepcopy(dict(context))
    exact_context["workspace_container"] = exact_workspace
    exact_job["context"] = exact_context
    return exact_job, _PinnedK8sJobWorkspaceAuthority(owner, attestation)


async def _pinned_k8s_job_workspace_authority_is_current(
    durable_job: dict[str, Any],
    authority: _PinnedK8sJobWorkspaceAuthority | None,
) -> bool:
    """Revalidate the exact workspace tuple at the final network boundary."""

    if not await _workspace_runtime_unchanged_before_delivery(durable_job):
        return False
    if authority is None:
        return True
    try:
        latest = await postgres_db.get_job(str(durable_job["id"]))
        if latest is None:
            return False
        expected_owner = _stateless_worker_workspace_owner(latest)
        if expected_owner != authority.owner:
            return False
        confirmed = await container_provisioner.attest_workspace_runtime(expected_owner)
        return confirmed == authority.attestation
    except Exception:
        return False


async def _attest_stateless_worker_workspace(
    owner: WorkspaceOwner,
) -> WorkspaceRuntimeAttestation:
    """Return one exact worker workspace identity or a generic claim refusal."""

    try:
        return await container_provisioner.attest_workspace_runtime(owner)
    except WorkspaceRuntimeAuthorityError as exc:
        logger.warning(
            "Stateless worker workspace attestation refused for %s %s: %s",
            owner.kind,
            owner.id,
            exc,
        )
    except Exception as exc:
        logger.warning(
            "Stateless worker workspace attestation failed for %s %s: %s",
            owner.kind,
            owner.id,
            exc,
            exc_info=True,
        )
    raise HTTPException(
        status_code=409,
        detail="Stateless worker workspace authority unavailable",
    )


async def _attest_stateless_worker_vm_workspace(
    owner: WorkspaceOwner,
) -> WorkspaceRuntimeAttestation:
    """Return one exact same-cluster VM identity or a generic refusal."""

    try:
        if owner.kind != "job":
            raise WorkspaceRuntimeAuthorityError(
                "stateless worker VM owner is not a job"
            )
        return await vm_provisioner.attest_workspace_runtime(owner.id)
    except WorkspaceRuntimeAuthorityError as exc:
        logger.warning(
            "Stateless worker VM workspace attestation refused for %s %s: %s",
            owner.kind,
            owner.id,
            exc,
        )
    except Exception as exc:
        logger.warning(
            "Stateless worker VM workspace attestation failed for %s %s: %s",
            owner.kind,
            owner.id,
            exc,
            exc_info=True,
        )
    raise HTTPException(
        status_code=409,
        detail="Stateless worker workspace authority unavailable",
    )


def _container_ssh_key_path(container_ctx: dict) -> str:
    """Resolve the private-key path shipped to a managed sandbox worker.

    The key itself is never persisted in job state. The path must therefore be
    reconstructed on every start and resume, using the same rules in both
    paths. Docker and Kubernetes mount the shared key at different defaults.
    """
    override = os.environ.get("SSH_KEY_PATH", "").strip()
    if override:
        return override
    if container_ctx.get("provisioner") == "docker":
        return "/run/secrets/ssh/id_ed25519"
    return "/run/secrets/vm-ssh-key"


def _inject_container_workspace_config(
    config_override: dict | None,
    container_ctx: dict,
    *,
    replace_endpoint: bool = False,
) -> dict:
    """Inject a complete managed-sandbox SSH configuration.

    ``replace_endpoint`` is used on resume because a recreated pod may have a
    new address. Managed username/key fields are always refreshed because they
    are in-flight deployment configuration and are deliberately not written
    back to ``jobs.config_override``.
    """
    container_host = container_ctx.get("host") or container_ctx.get("pod_ip")
    if container_ctx.get("status") != "ready" or not container_host:
        return config_override or {}

    config_override = config_override or {}
    workspace = config_override.setdefault("workspace", {})
    workspace["backend"] = "sandbox"
    remote = workspace.setdefault("remote", {})

    if replace_endpoint or not remote.get("host"):
        remote["host"] = container_host
    if replace_endpoint or not remote.get("port"):
        remote["port"] = container_ctx.get("port", 22)
    # These are properties of the orchestrator-managed sandbox image and agent
    # deployment, not user/job settings. Always refresh them so a stale
    # persisted remote block cannot point a resumed worker at an obsolete mount.
    remote["username"] = "agent-host"
    remote["key_path"] = _container_ssh_key_path(container_ctx)
    if not remote.get("workspace_path"):
        remote["workspace_path"] = "/home/agent-host/workspace"

    # Managed sandboxes freeze on sudo so an operator can approve a VM upgrade.
    config_override.setdefault("shell", {}).setdefault("sudo_action", "freeze")
    return config_override


def _inject_vm_workspace_config(
    config_override: dict | None,
    vm_ctx: dict,
    *,
    replace_endpoint: bool = False,
) -> dict:
    """Inject only the authoritative VM endpoint into a worker config."""

    if vm_ctx.get("status") != "ready" or not vm_ctx.get("ssh_host"):
        return config_override or {}
    config_override = config_override or {}
    workspace = config_override.setdefault("workspace", {})
    workspace["backend"] = "vm"
    remote = workspace.setdefault("remote", {})
    if replace_endpoint or not remote.get("host"):
        remote["host"] = vm_ctx["ssh_host"]
    if replace_endpoint or not remote.get("port"):
        remote["port"] = vm_ctx.get("ssh_port", 22)
    remote.setdefault("username", "agent-host")
    remote.setdefault("key_path", "/run/secrets/vm-ssh-key")
    remote.setdefault("workspace_path", "/home/agent-host/workspace")
    remote.setdefault(
        "connect_timeout", int(os.environ.get("VM_REMOTE_CONNECT_TIMEOUT_S", "10"))
    )
    remote.setdefault(
        "max_retries", int(os.environ.get("VM_REMOTE_CONNECT_MAX_RETRIES", "6"))
    )
    remote.setdefault("retry_timeouts_as_booting", True)
    config_override.setdefault("shell", {})["sudo_action"] = "allow"
    return config_override


def _inject_matching_workspace_config(
    job: Mapping[str, Any],
    config_override: dict | None,
    *,
    replace_endpoint: bool = False,
) -> tuple[dict, Any]:
    """Apply exactly one runtime selected by the server-owned tier contract."""

    decision = resolve_workspace_runtime(job, vm_mode=vm_provisioner.mode)
    config = copy.deepcopy(config_override or {})
    if not decision.ready:
        return config, decision
    if decision.effective_backend == "vm":
        config = _inject_vm_workspace_config(
            config,
            _get_vm_context(dict(job)),
            replace_endpoint=replace_endpoint,
        )
    elif decision.effective_backend == "sandbox":
        config = _inject_container_workspace_config(
            config,
            _get_container_context(dict(job)),
            replace_endpoint=replace_endpoint,
        )
    return config, decision


async def _workspace_runtime_unchanged_before_delivery(job: dict[str, Any]) -> bool:
    """Recheck the selected runtime after slow bundle assembly.

    Provisioner callbacks can race config/model/credential resolution.  Refetch
    the durable job at the last network boundary and require the exact selected
    runtime authority to match what the bundle was built from.  Opposite-tier
    residue is deliberately excluded from the digest, so it is observable but
    can neither block nor replace the assigned runtime.
    """

    expected = workspace_runtime_authority_digest(job, vm_mode=vm_provisioner.mode)
    if expected is None:
        return False
    fresh = await postgres_db.get_job(str(job["id"]))
    if fresh is None:
        return False
    context = fresh.get("context") or {}
    if isinstance(context, str):
        try:
            context = json.loads(context)
        except (json.JSONDecodeError, TypeError):
            return False
    if isinstance(context, dict) and context.get("inherits_parent_workspace"):
        action, _reason = await _resolve_subjob_inherited_workspace(fresh)
        if action != "proceed":
            return False
    if (
        workspace_runtime_authority_digest(fresh, vm_mode=vm_provisioner.mode)
        != expected
    ):
        return False
    return await verify_adopted_k8s_runtime_before_delivery(
        postgres_db, container_provisioner, fresh
    )


# Job context key holding each remote tier's live workspace, by tier name.
_WORKSPACE_CONTEXT_KEYS = {"vm": "vm", "sandbox": "workspace_container"}


def _resume_missing_workspace(job: dict) -> Optional[str]:
    """Which remote workspace a resume would ship without an address, if any.

    Returns ``'vm'`` / ``'sandbox'`` when the job's backend needs a remote
    workspace but its context holds no live one, else ``None``.

    ``_resume_job_on_agent`` injects ``workspace.remote`` only when the context
    says the workspace is ready, and neither of its two injection blocks has an
    else. So resuming a job whose workspace never came up — or was reaped —
    silently skips injection while config_override still names the backend, and
    the agent dies at ``init_workspace`` with "no workspace.remote config was
    provided" (src/agent.py:1896). Job 4435994d hit exactly this.

    Nothing in the resume path provisions; only the dispatcher does. So callers
    must hand such a job to the dispatcher rather than push it at an agent.
    This is the resume-side sibling of the dispatch backstop in
    ``_dispatch_job_to_agent``, which *fails* the job instead — correct there,
    because the dispatcher was supposed to have resolved the workspace already,
    but wrong here: an explicit Resume means "re-provision it".

    Uses the same ``_job_needs_vm`` / ``_job_needs_sandbox`` predicates the
    dispatcher uses to decide what to provision, so resume and dispatch agree
    on what a job needs. Keep the readiness conditions in step with the two
    injection blocks in ``_resume_job_on_agent``.
    """

    try:
        contract = resolve_workspace_contract(job)
    except WorkspaceContractError:
        # No tier can be shed safely when authority itself is ambiguous. The
        # shared bundle resolver will refuse it rather than choosing one.
        return None
    if contract.assigned_backend in LITE_BACKENDS:
        return None
    decision = resolve_workspace_runtime(job, vm_mode=vm_provisioner.mode)
    return None if decision.ready else contract.assigned_backend


def _scholar_provision_parent_id(job: dict) -> str | None:
    """Parent id a provisioning-scholar subjob should provision the shared,
    parent-owned workspace under, or None for a normal job.

    A scholar spawned before its parent had any workspace carries
    ``context.provisions_parent_workspace = <parentId>`` (stamped by
    ``_spawn_scholar_subjob``). It provisions the ONE pod ``workspace-<parentId>``
    under the parent's identity and rides it, rather than self-provisioning a
    throwaway pod (Phase 1,
    knowledge-base/knowledge/issues/scholar_selfprovisioned_workspace_misclassified_as_inherited.md).
    """
    ctx = job.get("context") or {}
    if isinstance(ctx, str):
        try:
            ctx = json.loads(ctx)
        except (json.JSONDecodeError, ValueError):
            return None
    pid = ctx.get("provisions_parent_workspace")
    return str(pid) if pid else None


def _scholar_should_provision_parent_container(config_override: Any) -> bool:
    """True if a scholar spawned with no parent workspace should provision the
    parent's SHARED container workspace (Phase 1) rather than self-provision.

    Backend gate only: container/sandbox (or unset → default sandbox) qualifies;
    VM/remote and lite (virtual/none) parents keep today's behavior. The dispatch
    seam additionally enforces a k8s in-cluster provisioner before acting on the
    marker, so a non-k8s deployment falls through to the self-provision path.
    """
    backend = _backend_from_override(config_override)
    if backend in ("vm", "remote"):
        return False
    if backend in LITE_BACKENDS:
        return False
    return True


# Bounded wait for a subjob to inherit its parent's provisioned workspace.
# Parent container/VM readiness is an async event that lands AFTER the subjob is
# spawned (a scholar is created ~3s after its parent, mid-provisioning), so we
# resolve from the parent's live row every dispatch tick. This bounds how long
# we wait before giving up with a diagnosable failure instead of stranding the job.
_INHERIT_WORKSPACE_MAX_WAIT_S = int(
    os.environ.get("WORKSPACE_INHERIT_MAX_WAIT_S", "600")
)


async def _resolve_subjob_inherited_workspace(job: dict) -> tuple[str, str | None]:
    """Refresh a subjob's inherited workspace from its parent's LIVE context.

    Subjobs that share a parent's workspace (scholar research,
    verification/critic) persist only ``inherits_parent_workspace`` and a
    parent-inheritance workspace contract. We re-read the parent's current
    workspace here and overlay it onto the in-memory ``job['context']``. The
    live runtime is never copied into the child row: doing so both creates a
    stale snapshot and claims the parent's Kubernetes authority under the
    child's identity. The subjob rides the parent's pod via its
    ``worktree_path``; it must never provision its own.

    Returns one of:
      ``("proceed", None)`` — not an inheriting subjob, or the parent workspace
        is ready and now overlaid; let normal dispatch continue.
      ``("wait", None)`` — inheriting, parent workspace still provisioning;
        caller should skip this tick and retry.
      ``("fail", message)`` — inheriting, but the parent workspace is gone/failed
        or the wait budget is exhausted; caller should fail the job.
    """
    parent_id = job.get("parent_job_id")
    if not parent_id:
        return ("proceed", None)

    ctx = job.get("context") or {}
    if isinstance(ctx, str):
        try:
            ctx = json.loads(ctx)
        except (json.JSONDecodeError, ValueError):
            return ("proceed", None)

    # Discriminate INHERITED from SELF-PROVISIONED. Both eventually carry a
    # workspace_container/vm on their context — an inheriting subjob copies its
    # parent's at spawn; a self-provisioned subjob (parent had no workspace when
    # it was spawned) writes its OWN once its pod comes up. Only true inheritors
    # carry the explicit inherits_parent_workspace flag, stamped by
    # _spawn_scholar_subjob / _trigger_verification_on_complete when they copy the
    # parent snapshot. Gating on key *presence* (as this once did) misread a
    # self-provisioned scholar as inheriting and waited the full budget on a
    # parent workspace that never exists, then failed. See
    # knowledge-base/knowledge/issues/scholar_selfprovisioned_workspace_misclassified_as_inherited.md.
    if not ctx.get("inherits_parent_workspace"):
        return ("proceed", None)

    adoption = await ensure_legacy_k8s_job_runtime_authority(
        postgres_db, container_provisioner, job
    )
    if adoption.retryable:
        logger.warning(
            "Dispatcher: subjob %s parent workspace needs live Kubernetes "
            "adoption (%s); waiting without dispatch",
            job.get("id"),
            adoption.reason,
        )
        return ("wait", None)
    if adoption.reason == "authority_ambiguous":
        return ("fail", "Inherited workspace authority is ambiguous.")

    try:
        parent = (
            adoption.authority_job
            if adoption.owner is not None and adoption.owner.id == str(parent_id)
            else await postgres_db.get_job(str(parent_id))
        )
    except Exception as e:
        logger.warning(
            "Dispatcher: subjob %s — failed to read parent %s for workspace "
            "resolution: %s (waiting)",
            job.get("id"),
            parent_id,
            e,
        )
        return ("wait", None)

    if not parent:
        return (
            "fail",
            f"Parent job {parent_id} no longer exists; cannot inherit its workspace.",
        )

    parent_ctx = parent.get("context") or {}
    if isinstance(parent_ctx, str):
        try:
            parent_ctx = json.loads(parent_ctx)
        except (json.JSONDecodeError, ValueError):
            parent_ctx = {}
    parent_container = parent_ctx.get("workspace_container") or {}
    parent_vm = parent_ctx.get("vm") or {}
    try:
        parent_contract = resolve_workspace_contract(parent)
    except WorkspaceContractError as exc:
        return ("fail", f"Parent workspace contract is invalid ({exc.code}).")
    # Resolve against a temporary overlay only. A waiting child keeps its
    # original durable-looking snapshot untouched; a genuine pre-0175 child
    # can still inherit the newly adopted parent UID without teaching the pure
    # resolver to trust its old endpoint.
    resolved_child_ctx = dict(ctx)
    if parent_contract.assigned_backend == "sandbox":
        resolved_child_ctx["workspace_container"] = parent_container
        resolved_child_ctx.pop("vm", None)
    elif parent_contract.assigned_backend == "vm":
        resolved_child_ctx["vm"] = parent_vm
        resolved_child_ctx.pop("workspace_container", None)
    try:
        child_contract = resolve_workspace_contract(
            {**job, "context": resolved_child_ctx}
        )
    except WorkspaceContractError as exc:
        return ("fail", f"Child workspace contract is invalid ({exc.code}).")
    if parent_contract.assigned_backend != child_contract.assigned_backend:
        return (
            "fail",
            "Parent and child workspace assignments differ; refusing cross-tier "
            f"inheritance ({parent_contract.assigned_backend} -> "
            f"{child_contract.assigned_backend}).",
        )
    inherited_backend = child_contract.assigned_backend

    # Parent's workspace is ready → overlay the live context and dispatch. All
    # downstream machinery (_job_needs_sandbox/_job_needs_vm, the dispatch-time
    # injectors) then keys off the ready context and injects workspace.remote.
    if inherited_backend == "sandbox" and parent_container.get("status") == "ready":
        ctx["workspace_container"] = parent_container
        ctx.pop("vm", None)
        job["context"] = ctx
        logger.info(
            "Dispatcher: subjob %s inheriting parent %s sandbox runtime — "
            "resolved live at dispatch",
            job.get("id"),
            parent_id,
        )
        return ("proceed", None)
    if inherited_backend == "vm" and parent_vm.get("status") == "ready":
        ctx["vm"] = parent_vm
        ctx.pop("workspace_container", None)
        job["context"] = ctx
        logger.info(
            "Dispatcher: subjob %s inheriting parent %s VM runtime — resolved "
            "live at dispatch",
            job.get("id"),
            parent_id,
        )
        return ("proceed", None)

    # Parent workspace is dead (reaped/failed) or the parent itself reached a
    # terminal state — no point waiting on a workspace that will never be ready.
    dead_states = ("failed", "deleted")
    parent_status = parent.get("status")
    if (
        (
            inherited_backend == "sandbox"
            and parent_container.get("status") in dead_states
        )
        or (inherited_backend == "vm" and parent_vm.get("status") in dead_states)
        or parent_status in ("failed", "cancelled", "completed")
    ):
        return (
            "fail",
            (
                f"Parent job {parent_id} workspace is unavailable (parent "
                f"status={parent_status}, container="
                f"{parent_container.get('status')}, vm={parent_vm.get('status')}); "
                "subjob cannot inherit it."
            ),
        )

    # Still provisioning — bounded wait keyed on the subjob's age, re-anchored
    # on the outage's scheduled wake for a resumed subjob: an outage-paused
    # subjob re-dispatched hours after spawn has long exhausted a created_at
    # budget, and would insta-fail on any transiently non-ready parent
    # workspace at resume. Anchor = max(created_at, llm_outage.next_retry_at)
    # — the same next-wake philosophy as the outage reset window.
    # knowledge-base/knowledge/features/llm_outage_subjob_resilience.md (#5)
    ref: datetime | None = None
    created_at = job.get("created_at")
    if isinstance(created_at, datetime):
        ref = (
            created_at if created_at.tzinfo else created_at.replace(tzinfo=timezone.utc)
        )
    wake_raw = (ctx.get("llm_outage") or {}).get("next_retry_at")
    if isinstance(wake_raw, str):
        try:
            wake = datetime.fromisoformat(wake_raw)
            if wake.tzinfo is None:
                wake = wake.replace(tzinfo=timezone.utc)
            if ref is None or wake > ref:
                ref = wake
        except ValueError:
            pass
    age_s = 0.0
    if ref is not None:
        age_s = (datetime.now(timezone.utc) - ref).total_seconds()
    if age_s > _INHERIT_WORKSPACE_MAX_WAIT_S:
        return (
            "fail",
            (
                f"Timed out after {int(age_s)}s waiting for parent job "
                f"{parent_id} workspace to become ready (container="
                f"{parent_container.get('status')}, vm={parent_vm.get('status')})."
            ),
        )
    return ("wait", None)


async def _prepare_job_workspace_runtime(
    job: dict[str, Any],
) -> tuple[str, dict[str, Any], str | None]:
    """Converge historical K8s authority before any dispatch decision.

    Automatic dispatch, direct/manual start, resume and stateless claim bundles
    all enter here. Inherited jobs delegate adoption to their exact parent
    owner through ``_resolve_subjob_inherited_workspace``.
    """

    context = job.get("context") or {}
    if isinstance(context, str):
        try:
            context = json.loads(context)
        except (TypeError, ValueError):
            context = {}
    if isinstance(context, dict) and context.get("inherits_parent_workspace"):
        action, reason = await _resolve_subjob_inherited_workspace(job)
        return action, job, reason

    adoption = await ensure_legacy_k8s_job_runtime_authority(
        postgres_db, container_provisioner, job
    )
    if adoption.retryable:
        return "wait", job, adoption.reason
    if (
        adoption.owner is not None
        and adoption.owner.id == str(job.get("id"))
        and adoption.authority_job is not None
    ):
        job = dict(adoption.authority_job)
    return "proceed", job, adoption.reason


async def _fail_subjob_and_unblock_parent(job: dict, message: str) -> None:
    """Fail a subjob at dispatch time AND unblock the parent it was holding.

    The dispatcher can decide a subjob will never run (e.g. it cannot inherit its
    parent's workspace). Marking it ``failed`` is not enough: a parent held in
    ``waiting`` by ``_spawn_scholar_subjob`` — or a delegation parent — is only
    transitioned back to ``created`` by the completion-side unblock handlers,
    which run inside ``complete_job``, a path a dispatch-time failure never
    reaches. Without this the parent strands in ``waiting`` forever (secondary
    bug in
    knowledge-base/knowledge/issues/scholar_selfprovisioned_workspace_misclassified_as_inherited.md).
    Mirror ``complete_job``'s terminal-subjob unblock here so any dispatch-path
    failure is self-healing, not just today's inherit-timeout.
    """
    job_id = str(job["id"])
    stateless_worker = job.get("execution_lane") == "stateless"
    updated = await postgres_db.update_job_status(
        job_id,
        status="failed",
        error_message=message,
        expected_status=(str(job.get("status")) if stateless_worker else None),
    )
    if stateless_worker and not updated:
        # The dispatcher row is a stale snapshot. A control verb may have
        # cancelled/completed the child while workspace inheritance was being
        # resolved; never overwrite that winner or unblock the parent from a
        # failure disposition that did not commit.
        logger.info(
            "Dispatcher: skipped stale stateless subjob failure for %s "
            "(expected_status=%s)",
            job_id,
            job.get("status"),
        )
        return
    # The unblock handlers classify the outcome from job['status']; the in-memory
    # row still holds the pre-fail status, so sync it before delegating. Each
    # handler is a no-op for the wrong subjob type (scholar_target / creation_order
    # guards), so calling both is safe.
    job["status"] = "failed"
    for handler in (_handle_scholar_completion, _handle_delegation_child_completion):
        try:
            await handler(job, [])
        except Exception as e:
            logger.error(
                "Dispatcher: subjob %s failed but could not unblock its parent "
                "via %s: %s",
                job_id,
                handler.__name__,
                e,
                exc_info=True,
            )


async def _provision_parent_workspace_for_scholar(job: dict, parent_id: str) -> str:
    """Drive the PARENT's shared workspace container toward ready on a scholar's
    behalf, then promote the scholar to a normal inheriting subjob.

    Phase 1 (knowledge-base/knowledge/issues/scholar_selfprovisioned_workspace_misclassified_as_inherited.md):
    a scholar spawned before its parent had any workspace provisions the parent's
    ONE shared pod (``workspace-<parentId>``, owner = parent) instead of a
    throwaway pod of its own, so the parent and later the critic ride the same
    pod. ``create_workspace`` keys the pod name and the context write-back on the
    owner, so provisioning under ``WorkspaceOwner.job(parent_id)`` lands the ready
    host/pod_ip on the PARENT's row automatically — no copy-back needed.

    Returns:
      ``"wait"``     — parent workspace still provisioning; retry next tick.
      ``"promoted"`` — parent workspace ready; the scholar row now inherits it and
                       dispatches via the normal inherit path on its next tick.
      ``"fail"``     — provisioning failed; the scholar was failed and its parent
                       unblocked via ``_fail_subjob_and_unblock_parent``.
    """
    scholar_id = str(job["id"])
    parent = await postgres_db.get_job(parent_id)
    if not parent:
        await _fail_subjob_and_unblock_parent(
            job,
            f"Parent job {parent_id} no longer exists; cannot provision its "
            "shared workspace for the research phase.",
        )
        return "fail"

    parent_ctx = parent.get("context") or {}
    if isinstance(parent_ctx, str):
        try:
            parent_ctx = json.loads(parent_ctx)
        except (json.JSONDecodeError, ValueError):
            parent_ctx = {}
    parent_container = parent_ctx.get("workspace_container") or {}

    parent_co = parent.get("config_override") or {}
    if isinstance(parent_co, str):
        try:
            parent_co = json.loads(parent_co)
        except (json.JSONDecodeError, ValueError):
            parent_co = {}
    ws_cfg = (parent_co.get("workspace") or {}).get("container") or {}

    res = await ensure_workspace(
        WorkspaceOwner.job(parent_id),
        provisioner=container_provisioner,
        suspension=workspace_suspension_service,
        current_status=parent_container.get("status"),
        ws_config={
            k: ws_cfg[k]
            for k in ("cpu", "memory", "cpu_limit", "memory_limit", "image")
            if k in ws_cfg
        },
    )
    if res.outcome is EnsureOutcome.FAILED:
        # create_workspace records the concrete failure in the parent's
        # context before returning False — surface it on the job row instead
        # of punting operators to the orchestrator logs (the dispatcher's own
        # sandbox arm already does this; see the EnsureOutcome.FAILED branch
        # in _try_dispatch_pending_jobs).
        reason = None
        try:
            refreshed_parent = await postgres_db.get_job(parent_id)
            refreshed_ctx = (refreshed_parent or {}).get("context") or {}
            if isinstance(refreshed_ctx, str):
                refreshed_ctx = json.loads(refreshed_ctx)
            reason = (refreshed_ctx.get("workspace_container") or {}).get("error")
        except Exception:
            logger.warning(
                "Dispatcher: could not refresh failed parent workspace context "
                "for scholar %s (parent %s)",
                scholar_id,
                parent_id,
                exc_info=True,
            )
        detail = (
            f"Shared parent workspace failed: {reason}"
            if reason
            else (
                "Shared parent workspace could not be created for the research "
                "phase (see orchestrator logs for image/resource/RBAC details)."
            )
        )
        await _fail_subjob_and_unblock_parent(job, detail)
        return "fail"
    if res.outcome is EnsureOutcome.PENDING:
        logger.info(
            "Dispatcher: scholar %s provisioning shared parent workspace "
            "workspace-%s (status=%s) — waiting",
            scholar_id,
            parent_id[:12],
            res.status,
        )
        return "wait"

    # READY — promote the scholar to inherit the now-ready shared workspace so
    # the normal inherit path (fresh parent resolver overlay + worktree injection)
    # dispatches it. The child row must not copy the parent's live runtime
    # authority; doing so looks like an unreserved runtime bind for the child.
    fresh_parent = await postgres_db.get_job(parent_id)
    fresh_ctx = (fresh_parent or {}).get("context") or {}
    if isinstance(fresh_ctx, str):
        try:
            fresh_ctx = json.loads(fresh_ctx)
        except (json.JSONDecodeError, ValueError):
            fresh_ctx = {}
    ready_container = fresh_ctx.get("workspace_container") or parent_container

    worktree_path = (
        "/home/agent-host/workspace/worktrees/"
        f"{scholar_id[:8]}-{job.get('config_name') or 'scholar'}"
    )
    await postgres_db.merge_job_context(
        scholar_id,
        {"inherits_parent_workspace": True},
    )
    async with postgres_db.acquire() as conn:
        await conn.execute(
            "UPDATE jobs SET worktree_path = $1 WHERE id = $2::uuid",
            worktree_path,
            scholar_id,
        )
    logger.info(
        "Dispatcher: scholar %s promoted to inherit shared parent workspace "
        "workspace-%s (host=%s)",
        scholar_id,
        parent_id[:12],
        ready_container.get("host") or ready_container.get("pod_ip"),
    )
    return "promoted"


def _apply_sticky_sudo_denial(job: dict, config_override: dict | None) -> dict | None:
    """Flip the agent's sudo gate to a reasoned block when the job carries a
    sudo/VM-upgrade denial (``context.sudo_denial``, written by
    ``_resume_job_without_vm_internal``).

    Without this, the agent resuming from its checkpoint replays the gated
    command, hits ``sudo_action="freeze"`` again, and re-freezes into a brand
    new approval loop the operator just declined. Applies to non-VM backends
    only — a VM owns its own sudo gate, and reaching one means the upgrade was
    approved after all.

    Returns the (possibly newly created) config_override.
    """
    ctx = job.get("context") or {}
    if isinstance(ctx, str):
        try:
            ctx = json.loads(ctx)
        except (json.JSONDecodeError, TypeError):
            ctx = {}
    denial = ctx.get("sudo_denial")
    if not isinstance(denial, dict):
        return config_override
    if ((config_override or {}).get("workspace") or {}).get("backend") == "vm":
        return config_override
    config_override = config_override or {}
    shell_cfg = config_override.setdefault("shell", {})
    shell_cfg["sudo_action"] = "block"
    decided_by = denial.get("decided_by") or "the operator"
    reason = denial.get("reason") or ""
    shell_cfg["sudo_block_message"] = (
        "Command blocked: sudo was "
        + ("denied" if denial.get("denied", True) else "waived (resume without VM)")
        + f" for this job by {decided_by}"
        + (f" — {reason}" if reason else "")
        + ". Do not re-attempt sudo; use a rootless alternative or record the "
        "limitation in your results."
    )
    return config_override


# =============================================================================
# Capability grants (User-Defined Experts, Slice 2) — PEPs + helpers
#
# One pure PDP (src/core/capability_grants.evaluate) is enforced at four points:
# save-time (the 3 expert endpoints), job dispatch, job resume, and session
# attach. Deny-by-default for security keys; existing approved users were
# grandfathered by migration 0030 (shell_tools + delegation). See
# knowledge-history/done/global_expert_management.md (decisions 8, 9, 19, 21-23).
# =============================================================================


class GrantDenied(Exception):
    """A merged config exceeds the runner's grants (dispatch PEP). Must NOT be
    swallowed by a resolve fallback (fail closed)."""

    def __init__(self, violations: list[str]):
        self.violations = violations
        super().__init__("; ".join(violations))


async def _user_experts_enabled() -> bool:
    """Runtime kill-switch (decision 8). Absent row = enabled (fail-open for fresh
    installs). When disabled, DB-expert creation + grant enforcement are off."""
    try:
        row = await postgres_db.get_system_setting("user_experts")
    except Exception:
        logger.exception("user_experts read failed; fail-open")
        return True
    value = (row or {}).get("value") or {}
    return not (isinstance(value, dict) and value.get("enabled") is False)


def _grant_violations_detail(violations: list[str]) -> str:
    return "config exceeds your capability grants: " + "; ".join(violations)


_PUBLIC_JOB_CONTEXT_RESERVED_KEYS = {
    "automation_id",
    "automation_name",
    "automation_trigger",
    "cloud_baseline",
    "delegation_results",
    "datasource_selection",
    "delegation_timed_out",
    "git_remote_url",
    "graft_output_path",
    # Completion finalization is the only writer. Accepting this manifest at
    # creation turns the Gitea service into a confused deputy because its
    # repository/revision coordinates would otherwise arrive in caller data.
    "evidence_manifest",
    # Pull-request evidence and immutable contract provenance are minted only
    # by server-owned repository/admission paths.
    "pull_request",
    "deliverable_contract_provenance",
    "prior_deliverable_contract",
    "required_pr_repositories",
    "required_deliverables",
    "lifecycle_marker",
    "loop_campaign_id",
    "loop_campaign_index",
    "loop_id",
    "loop_iteration",
    "loop_remaining",
    "loop_role",
    "loop_seq_index",
    "parent_job_id",
    "runner_kind",
    "runner_source",
    "scholar_target",
    "snapshot",
    # The verification ledger is server-owned end to end: the server assigns
    # finding ids, computes the verdict from the open set, and reads the round
    # count for the cap. A caller-seeded ledger plants phantom findings into
    # the first critic's brief and can trip the cap/no-progress escalation on
    # round one, so it is stripped alongside its `verification_target` pair.
    "verification_rounds",
    "verification_target",
    "vm",
    "workspace_container",
}
_SERVER_OWNED_OFFICER_CONTEXT_KEYS = {
    "ticket_note_id",
    "officer_admission",
    "ticket_ready_at",
    "ready_generation_at",
    "ticket_claim_source",
    "claim_source",
    "officer_thread_id",
    "officer_incarnation",
    "provisioning_preflight",
}
_SERVER_OWNED_REPOSITORY_CONTEXT_KEYS = {
    "git_remote_url",
    "repo_name",
    "managed_repository_credentials",
    "managed_repository_authority",
    "repository_auth",
    "repository_credentials",
    "_managed_repository_authority_pending",
    "_managed_repository_process_zero",
    "_stateless_workspace_process_zero_observation",
}
_SERVER_OWNED_RAW_CREATE_CONTEXT_KEYS = (
    _SERVER_OWNED_OFFICER_CONTEXT_KEYS
    | _SERVER_OWNED_REPOSITORY_CONTEXT_KEYS
    | {
        "evidence_manifest",
        "pull_request",
        "deliverable_contract_provenance",
        "prior_deliverable_contract",
        "required_pr_repositories",
        "required_deliverables",
        WORKSPACE_CONTRACT_CONTEXT_KEY,
        WORKSPACE_DISPATCH_AUTHORITY_CONTEXT_KEY,
        WORKSPACE_RUNTIME_CONTEXT_KEY,
        "workspace_backend",
        "vm",
        "workspace_container",
    }
)


def _strip_raw_repository_authority(value: Any) -> Any:
    """Recursively remove server-owned Git transport from request JSON."""

    if isinstance(value, dict):
        return {
            key: _strip_raw_repository_authority(item)
            for key, item in value.items()
            if key not in _SERVER_OWNED_REPOSITORY_CONTEXT_KEYS
        }
    if isinstance(value, list):
        return [_strip_raw_repository_authority(item) for item in value]
    return value


_PUBLIC_JOB_CONFIG_RESERVED_KEYS = {
    "lifecycle_marker",
    "parent_job_id",
    "runner_kind",
    "runner_source",
}


def _strip_public_job_reserved_markers(job: "JobCreate") -> None:
    """Remove system-only job markers from public create payloads."""
    job.parent_job_id = None
    job.creation_order = None
    job.worktree_path = None
    job.delegation_context = None
    # thread_id is derived, never submitted. Only the internal path may set it,
    # and there it is authenticated: _resolve_internal_job_creation_scope
    # fetches the thread and 403s when it is missing or owned by someone else.
    # The public path never validated it — harmless while the value was merely
    # a datasource-inheritance hint whose lookup failures are swallowed, but
    # once it is PERSISTED as created_by_thread_id and woken on, an unchecked
    # body field lets a caller name a victim's live session and have a
    # completion payload POSTed into it (/api/input on the agent pod is
    # unauthenticated). Stripping is also what keeps a bogus-but-well-formed
    # UUID a no-op instead of a ForeignKeyViolationError → HTTP 500.
    job.thread_id = None
    if isinstance(job.context, dict):
        job.context = {
            key: value
            for key, value in job.context.items()
            if key not in _PUBLIC_JOB_CONTEXT_RESERVED_KEYS
        }
    if isinstance(job.config_override, dict):
        job.config_override = {
            key: value
            for key, value in job.config_override.items()
            if key not in _PUBLIC_JOB_CONFIG_RESERVED_KEYS
        }


def _strip_raw_officer_claim_context(job: "JobCreate") -> None:
    """Remove server-owned context from public and internal raw bodies.

    ``ticket=`` is the sole caller-selectable claim input. The final Officer
    admission transaction writes these context keys after resolving the ticket
    and locking the post; internal transport authentication does not make a
    model-authored context dictionary authoritative. Completion finalization
    similarly records ``evidence_manifest`` later via ``merge_job_context``;
    no job-creation body can seed repository/revision authority.
    """

    if isinstance(job.context, dict):
        job.context = {
            key: value
            for key, value in job.context.items()
            if key not in _SERVER_OWNED_RAW_CREATE_CONTEXT_KEYS
        }


async def _grant_project_ids(user: dict) -> list[str]:
    """Project scope ids for grant resolution. user_visible_project_ids returns
    'all' for admins (who bypass anyway) — treat as no project constraint."""
    vis = await user_visible_project_ids(user, postgres_db)  # security/access.py
    return [] if vis == "all" else [str(p) for p in vis]


async def _scan_raw_request_fragment(request: Request) -> None:
    """Slice-2 hardening (decision 10): scan the RAW request bytes for duplicate
    or non-ASCII keys (parser-differential + unicode-confusable defenses) that the
    parsed body has already silently collapsed. 422 on offence. Best-effort — if
    the body can't be re-read the parsed-dict hard-deny scan still ran."""
    from src.core.expert_resolution import scan_fragment_text

    try:
        raw = (await request.body()).decode("utf-8")
    except Exception:
        return
    if not raw.strip():
        return
    offending = scan_fragment_text(raw)
    if offending:
        raise HTTPException(
            status_code=422,
            detail="config rejected (malformed, duplicate/non-ASCII, or credential "
            "keys): " + "; ".join(offending),
        )


async def _resolve_user_save_grants(user: dict[str, Any]) -> dict[str, Any] | None:
    """Resolve save-time grants for `user`, or ``None`` on an admin bypass.

    Split out of the body of ``_enforce_save_grants`` so its refuse-outright
    policy and ``_strip_save_grants``'s strip-and-report policy (the
    ``duplicate_expert`` route only, decision 2026-08-04) resolve grants via
    one path and cannot drift into two admin checks."""
    if user.get("is_admin"):
        return None
    from services.grants_service import resolve_grants_for

    return await resolve_grants_for(
        postgres_db, user_id=str(user["id"]), project_ids=await _grant_project_ids(user)
    )


async def _enforce_save_grants(config: dict[str, Any], *, user: dict[str, Any]) -> None:
    """Save-time PEP (decision 9): the author's grants must cover the raw fragment.
    422 naming offending keys. Admins bypass."""
    grants = await _resolve_user_save_grants(user)
    if grants is None:
        return
    from src.core.capability_grants import evaluate

    violations = evaluate(config, grants)
    if violations:
        raise HTTPException(
            status_code=422, detail=_grant_violations_detail(violations)
        )


async def _strip_save_grants(
    config: dict[str, Any], *, user: dict[str, Any]
) -> tuple[dict[str, Any], list[str]]:
    """``duplicate_expert``'s save-time grants policy (2026-08-04 decision,
    knowledge-base/knowledge/superpowers/plans/2026-08-04-expert-write-gate-holes.md, task 3):
    strip what the copier's grants forbid from the source config instead of
    refusing the fork outright, and report the grant keys that were dropped.
    ``_enforce_save_grants`` above is unchanged and still refuses for the
    other four expert-write routes — measured against the real PDP with
    default grants, refusing here blocked 7 of the 11 shipped experts,
    including the one the route's own docstring names ("start from scholar").

    Admins bypass exactly as ``_enforce_save_grants`` does: unmodified config,
    nothing dropped.

    THE SAFETY PROPERTY, not optional: ``evaluate`` is re-run on the STRIPPED
    result, and any violation that survives is refused with the same 422
    ``_enforce_save_grants`` raises. This is what makes an incomplete or wrong
    entry in ``capability_grants.strip_to_grants`` merely a false refusal,
    never a permitted escape.
    """
    grants = await _resolve_user_save_grants(user)
    if grants is None:
        return config, []
    from src.core.capability_grants import evaluate, strip_to_grants

    stripped, dropped = strip_to_grants(config, grants)
    residual = evaluate(stripped, grants)
    if residual:
        raise HTTPException(status_code=422, detail=_grant_violations_detail(residual))
    return stripped, dropped


async def _enforce_expert_save_prelude(request: Request) -> None:
    """Kill-switch (403) + raw dup/non-ASCII key scan (422): the two save-time
    checks shared by every expert-write route regardless of how its grants
    half is enforced. ``_enforce_expert_save`` below runs this then
    ``_enforce_save_grants``; ``duplicate_expert`` runs this then
    ``_strip_save_grants`` instead, so the kill-switch and the scan cannot be
    forgotten while that one route's grants policy differs from the other
    four."""
    if not await _user_experts_enabled():
        raise HTTPException(
            status_code=403,
            detail="User-defined experts are disabled by the administrator",
        )
    await _scan_raw_request_fragment(request)


async def _enforce_expert_save(
    request: Request, config: dict[str, Any], *, user: dict[str, Any]
) -> None:
    """Combined save-time gate: kill-switch (403) + raw dup/non-ASCII key scan
    (422) + capability-grant enforcement (422). Admins bypass grants, not the
    kill-switch."""
    await _enforce_expert_save_prelude(request)
    await _enforce_save_grants(config, user=user)


async def _resolve_runner_grants(
    *,
    runner_user_id: str | None,
    project_ids: list[str],
    runner_kind: str = "user",
) -> dict[str, Any] | None:
    """Resolve effective dispatch grants for the job runner.

    ``None`` means admin bypass. Lifecycle subjobs keep the owner's capability
    grants but run with an elevated autonomy ceiling so system verification and
    research jobs do not pause on the owner's review ceiling.
    """
    user = await postgres_db.get_user(runner_user_id) if runner_user_id else None
    if user and user.get("is_admin"):
        return None
    from services.grants_service import resolve_grants_for

    grants = await resolve_grants_for(
        postgres_db, user_id=runner_user_id, project_ids=project_ids
    )
    if runner_kind == "lifecycle":
        grants = dict(grants)
        grants["autonomy_ceiling"] = "full"
    return grants


async def _enforce_dispatch_grants(
    merged: dict,
    *,
    runner_user_id: str | None,
    project_ids: list[str],
    runner_kind: str = "user",
) -> None:
    """Authoritative dispatch PEP: merged config must fit runner grants."""
    from src.core.capability_grants import evaluate

    grants = await _resolve_runner_grants(
        runner_user_id=runner_user_id,
        project_ids=project_ids,
        runner_kind=runner_kind,
    )
    if grants is None:
        return
    violations = evaluate(merged, grants)
    if violations:
        raise GrantDenied(violations)


def _strip_acknowledged_grants(
    fragment: dict[str, Any], grants: dict[str, Any], acknowledged: set[str]
) -> dict[str, Any]:
    """Drop acknowledged grant violations from a merged config fragment.

    A violation the user did NOT acknowledge is left in place, so
    ``_enforce_dispatch_grants`` still denies on all of it — acknowledging one
    grant must never smuggle a different one through.

    ``strip_to_grants`` is advisory by contract; the authoritative re-check is
    the ``_enforce_dispatch_grants`` call that runs on the resulting capture.

    Sync and pure (no grant resolution here) so it can run as
    ``resolve_config``'s ``grant_strip`` hook, applied to the fully-merged
    ``data`` before the delivered blob is built from it — not just to the
    detached ``capture["merged_fragment"]`` copy the PDP evaluates. Stripping
    only the capture leaves the delivered blob carrying the very capability
    the grant revoked (round-1 finding: acknowledging ``shell_tools`` stopped
    the denial but the agent still hydrated ``tools.shell=True``).
    """
    from src.core.capability_grants import evaluate, strip_to_grants

    violations = evaluate(fragment, grants)
    if not violations:
        return fragment
    flagged = {v.split(":", 1)[0] for v in violations}
    if not flagged <= acknowledged:
        # Something drifted that was never acknowledged. Leave the fragment
        # untouched and let the dispatch PEP fail closed on all of it.
        return fragment
    stripped, _dropped = strip_to_grants(fragment, grants)
    return stripped


async def _enforce_session_create_grants(
    fragment: dict, *, user_id: str | None, project_ids: list[str]
) -> None:
    """Create/update-time PEP for sessions (Layer 2): run the SAME PDP as attach
    (``_enforce_dispatch_grants``) on the requested config and translate a denial
    into HTTP 422 — so a never-startable config (e.g. a ``permission_mode`` above
    the owner's ceiling) is rejected synchronously at the API instead of being
    accepted and then failing later at provisioning with an opaque ready timeout.
    Admin owner bypasses (inside ``_enforce_dispatch_grants``).
    See knowledge-base/knowledge/issues/session_permission_mode_grant_denied_ready_timeout.md.
    """
    try:
        await _enforce_dispatch_grants(
            fragment, runner_user_id=user_id, project_ids=project_ids
        )
    except GrantDenied as gd:
        raise HTTPException(
            status_code=422, detail=_grant_violations_detail(gd.violations)
        ) from gd


async def _enforce_job_create_grants(
    config_override: dict | None, *, user_id: str | None, project_ids: list[str]
) -> None:
    """Submit-time PEP for jobs — the session counterpart above, for the job path.

    Without it, an over-reaching ``config_override`` (autonomy past the ceiling,
    an ungranted model, shell tools) is accepted at create and only denied at
    dispatch, which marks the job ``failed``. A session agent that created the
    job has already reported success by then, so the failure surfaces as a dead
    job rather than a refused request.

    Scoped to the OVERRIDE only: an expert's own fragment is resolved
    server-side after this point and is already PDP-checked at expert save
    (``_enforce_expert_save``). Grant scoping is the request's project rather
    than the fully resolved job scope, so this can allow something dispatch
    later denies — it fails callers early, it never grants.
    ``_enforce_dispatch_grants`` on the full merged config stays authoritative.

    No-ops for a userless system child (no principal whose grants to resolve).
    """
    if not user_id or not config_override:
        return
    try:
        await _enforce_dispatch_grants(
            config_override, runner_user_id=user_id, project_ids=project_ids
        )
    except GrantDenied as gd:
        raise HTTPException(
            status_code=422, detail=_grant_violations_detail(gd.violations)
        ) from gd


async def _check_vm_permission(
    user: dict | None,
    *,
    job_needs_vm: bool,
) -> None:
    """Enforce admin VM-workspace controls.

    Raises HTTPException(403) when either:
      - The global kill-switch `system_settings['vm_workspaces']` is set
        to `{"enabled": false}` (blocks everyone, including admins).
      - The user is a non-admin without `can_use_vm=True`.

    No-op when ``job_needs_vm`` is False. Absent/malformed setting row is
    treated as enabled (fail-open for fresh installs).
    """
    if not job_needs_vm:
        return
    row: dict | None = None
    try:
        row = await postgres_db.get_system_setting("vm_workspaces")
    except Exception:
        # DB read failure is non-fatal for the gate — defer to per-user check.
        logger.exception("Failed to read vm_workspaces kill-switch; fail-open")
    value = (row or {}).get("value") or {}
    if isinstance(value, dict) and value.get("enabled") is False:
        raise HTTPException(
            status_code=403,
            detail="VM workspaces are globally disabled by the administrator",
        )
    if user and user.get("is_admin"):
        return
    if not user or not await postgres_db.user_can_use_vm(user):
        raise HTTPException(
            status_code=403,
            detail="User is not permitted to use VM workspaces",
        )


async def _enforce_workspace_upgrade_grants_for_config(
    *,
    owner_id: Any,
    config_override: dict | None,
    target_tier: str,
) -> None:
    """Sec-1 — shared upgrade-authorization gate core (server-side, fail-closed).

    Parameterized by the raw ``(owner_id, config_override)`` so BOTH the session
    path (``thread.metadata.config_override``) and the worker path (the
    ``jobs.config_override`` column) reuse one PEP — see the thin
    ``_enforce_workspace_upgrade_grants`` (session) /
    ``_enforce_job_workspace_upgrade_grants`` (worker, §4.3 W2) wrappers.

    Re-runs the dispatch PDP (``capability_grants.evaluate``) on the POST-UPGRADE
    config — the stored ``config_override`` with ``workspace.backend`` flipped to
    ``target_tier`` — exactly as ``_enforce_dispatch_grants`` does at dispatch,
    just re-run at upgrade time:

    - ``target_tier='vm'`` trips the ``vm_workspace`` grant requirement, and
      additionally keeps the operator gate (the global ``vm_workspaces``
      kill-switch + per-user ``can_use_vm`` via ``_check_vm_permission``).
    - ``target_tier='sandbox'`` is NOT gated by the backend (the PDP gates only
      ``vm`` and explicitly-declared tool flags), so it passes by default —
      matching "sandbox is the ungated default tier" — unless the config already
      declares a gated tool (e.g. ``tools.shell``) the owner lacks, in which case
      dispatch would have rejected it too.

    Raises ``HTTPException(403)`` on violation. No new grant key, no
    sandbox-specific rule — identical to dispatch-time enforcement.
    """
    # owner_id comes back from asyncpg as a UUID object; get_user (and
    # _enforce_dispatch_grants below) expect a string — coerce once, matching the
    # str(user["id"]) convention used elsewhere.
    owner_id = str(owner_id) if owner_id is not None else None
    owner = await postgres_db.get_user(owner_id) if owner_id else None

    # vm keeps its operator gate (global kill-switch + can_use_vm), on top of the
    # vm_workspace grant the PDP enforces below.
    if target_tier == "vm":
        await _check_vm_permission(owner, job_needs_vm=True)

    if not isinstance(config_override, dict):
        config_override = {}
    # Post-upgrade config = the frozen override with the backend flipped. A
    # shallow merge of the workspace sub-dict suffices — the PDP only reads
    # workspace.backend plus declared tool/autonomy flags.
    post_upgrade = {
        **config_override,
        "workspace": {
            **(config_override.get("workspace") or {}),
            "backend": target_tier,
        },
    }
    project_ids = await _grant_project_ids(owner) if owner else []
    try:
        await _enforce_dispatch_grants(
            post_upgrade, runner_user_id=owner_id, project_ids=project_ids
        )
    except GrantDenied as exc:
        raise HTTPException(
            status_code=403, detail=_grant_violations_detail(exc.violations)
        ) from exc


async def _enforce_workspace_upgrade_grants(
    thread: dict,
    *,
    target_tier: str,
) -> None:
    """Session wrapper over the shared Sec-1 gate — extracts the owner +
    ``config_override`` from a thread row (``metadata.config_override``) and
    delegates to ``_enforce_workspace_upgrade_grants_for_config``."""
    metadata = thread.get("metadata") or {}
    if isinstance(metadata, str):
        try:
            metadata = json.loads(metadata)
        except (json.JSONDecodeError, TypeError):
            metadata = {}
    await _enforce_workspace_upgrade_grants_for_config(
        owner_id=thread.get("user_id"),
        config_override=metadata.get("config_override") or {},
        target_tier=target_tier,
    )


async def _enforce_job_workspace_upgrade_grants(
    job: dict,
    *,
    target_tier: str,
) -> None:
    """Worker wrapper over the shared Sec-1 gate (§4.3 W2). Jobs carry
    ``config_override`` as a top-level JSONB column (not under ``metadata``) and
    ``user_id`` as the owner — extract those and delegate to the shared core."""
    config_override = job.get("config_override") or {}
    if isinstance(config_override, str):
        try:
            config_override = json.loads(config_override)
        except (json.JSONDecodeError, TypeError):
            config_override = {}
    await _enforce_workspace_upgrade_grants_for_config(
        owner_id=job.get("user_id"),
        config_override=config_override,
        target_tier=target_tier,
    )


def _vm_needs_release(vm_ctx: dict | None) -> bool:
    """True when a VM context still owns cluster resources worth reclaiming.

    Shared by the thread and job branches of ``_archive_and_cleanup_workspace``
    so the two cannot drift apart again. They had: the job side used this
    denylist, the thread side an allowlist of
    ``("provisioning", "created", "ready")``. Every other status fell through on
    the thread side, so ``release_thread_vm`` never ran and each suspended VM
    leaked a 20 GiB rootdisk DataVolume plus its Headscale node — permanently,
    since kept-disk GC is jobs-only and the controller orphan backstop ships
    off. See knowledge-base/knowledge/issues/vm_reliability_assessment.md P1-7.

    A falsy context means the entity never had a VM, which must NOT count as
    "needs release" — the absent status would otherwise pass the denylist and
    fire a spurious teardown.
    """
    return bool(vm_ctx) and vm_ctx.get("status") not in ("deleted", "deleting")


async def _archive_and_cleanup_workspace(
    entity_id: str,
    entity_type: str = "jobs",
    *,
    reclaim_volume: bool = True,
) -> list[str]:
    """Snapshot workspace to S3, then delete container/VM.

    Centralized cleanup for all workspace teardown paths (job completion,
    cancellation, cascade cleanup, thread end). Each provisioner's release
    method handles snapshot-before-delete internally.

    Args:
        entity_id: Job or thread UUID.
        entity_type: "jobs" or "threads".
        reclaim_volume: Threads only — whether the workspace PVC dies with the
            pod. The caller owns this decision because "release a thread's
            workspace" covers two different intents: a thread whose status is
            ``ended`` is still RESUMABLE (``resume_thread`` requires exactly
            that status, and the agent's idle-archive sets it automatically
            after 30 idle minutes), so tearing its volume down would silently
            destroy a workspace the user can still reopen. Only a genuine
            permanent delete passes True. Jobs keep the default: reclaiming a
            job's PVC on a terminal state is correct and unchanged.

    Returns:
        List of action descriptions for logging.
    """
    actions: list[str] = []

    if entity_type == "threads":
        thread = await postgres_db.get_thread(entity_id)
        if not thread:
            return actions
        metadata = thread.get("metadata") or {}
        if isinstance(metadata, str):
            try:
                metadata = json.loads(metadata)
            except (json.JSONDecodeError, TypeError):
                metadata = {}
        ws_ctx = metadata.get("workspace_container") or {}
        vm_ctx = metadata.get("vm") or {}

        # Workspace container cleanup (snapshot + delete)
        if ws_ctx.get("status") not in ("deleted", "deleting", "released", None):
            if ws_ctx.get("provisioner") == "docker":
                released = await docker_provisioner.release_thread_workspace(entity_id)
                if not released:
                    raise RuntimeError(
                        "Docker thread workspace authority retirement is incomplete"
                    )
                actions.append("docker thread workspace authority retired")
            elif container_provisioner.is_available:
                # reclaim_volume=False snapshots + deletes the pod but KEEPS the
                # PVC, so a resumable `ended` thread comes back to its own files
                # instead of an empty volume (see the docstring above).
                teardown_identity = (
                    await container_provisioner.capture_terminal_workspace_identity(
                        WorkspaceOwner.session(entity_id)
                    )
                )
                released = await container_provisioner.release_workspace(
                    WorkspaceOwner.session(entity_id),
                    reclaim_volume=reclaim_volume,
                    teardown_identity=teardown_identity,
                    strict=True,
                )
                if not released:
                    raise RuntimeError(
                        "Kubernetes thread workspace exact teardown is incomplete"
                    )
                actions.append(
                    "k8s thread workspace released"
                    + ("" if reclaim_volume else " (volume kept)")
                )

        # VM cleanup (snapshot + delete)
        if _vm_needs_release(vm_ctx):
            if vm_provisioner.lifecycle_available:
                teardown_identity = await vm_provisioner.capture_vm_teardown_identity(
                    entity_id,
                    entity_type="thread",
                )
                outcome = await vm_provisioner.release_vm_captured(
                    entity_id,
                    teardown_identity,
                    ssh_host=vm_ctx.get("ssh_host"),
                    ssh_port=vm_ctx.get("ssh_port"),
                    entity_type="thread",
                )
                if outcome.disposition != "completed":
                    raise RuntimeError(
                        "Thread VM exact teardown remains " + outcome.disposition
                    )
                actions.append("thread vm released")

    else:
        job = await postgres_db.get_job(entity_id)
        if not job:
            return actions
        raw_context = job.get("context") or {}
        if isinstance(raw_context, str):
            try:
                raw_context = json.loads(raw_context)
            except (TypeError, ValueError):
                raw_context = {}
        if (
            job.get("parent_job_id")
            and isinstance(raw_context, dict)
            and raw_context.get("inherits_parent_workspace") is True
        ):
            # Inherited subjobs carry a diagnostic copy of the root runtime,
            # but the stable Pod/VM/Docker owner remains the root job. A child
            # terminal transition owns only its worktree/claim—not namespace-
            # wide credential retirement or compute deletion.
            actions.append("inherited workspace retained by root owner")
            return actions
        ws_ctx = _get_container_context(job)
        vm_ctx = _get_vm_context(job)

        # VM cleanup (snapshot + delete)
        if _vm_needs_release(vm_ctx):
            if vm_provisioner.lifecycle_available:
                teardown_identity = await vm_provisioner.capture_vm_teardown_identity(
                    entity_id
                )
                outcome = await vm_provisioner.release_vm_captured(
                    entity_id,
                    teardown_identity,
                    ssh_host=vm_ctx.get("ssh_host"),
                    ssh_port=vm_ctx.get("ssh_port"),
                )
                if outcome.disposition != "completed":
                    raise RuntimeError(
                        "VM exact teardown remains " + outcome.disposition
                    )
                actions.append("vm released")

        # Workspace container cleanup (snapshot + delete)
        if ws_ctx and ws_ctx.get("status") not in (
            "deleted",
            "deleting",
            "released",
            None,
        ):
            if ws_ctx.get("provisioner") == "docker":
                released = await docker_provisioner.release_workspace(entity_id)
                if not released:
                    raise RuntimeError(
                        "Docker workspace authority retirement is incomplete"
                    )
                actions.append("docker workspace authority retired")
            else:
                teardown_identity = (
                    await container_provisioner.capture_terminal_workspace_identity(
                        WorkspaceOwner.job(entity_id)
                    )
                )
                released = await container_provisioner.release_workspace(
                    WorkspaceOwner.job(entity_id),
                    teardown_identity=teardown_identity,
                    strict=True,
                )
                if not released:
                    raise RuntimeError(
                        "Kubernetes workspace exact teardown is incomplete"
                    )
                actions.append("k8s workspace released")

    return actions


async def _detach_agent_session(thread_id: str, timeout: float = 150.0) -> bool:
    """Ask the thread's live agent to terminate its session, and wait.

    Gives the agent the chance to run its full terminate path — final
    memory capture (memory_bugs.md B11) and the workspace git push —
    BEFORE ``_release_thread_resources`` tears down the workspace and
    pod. Without this, the user-facing DELETE deleted the pod outright
    and the session's final extraction died with it (the agent kept
    heartbeating through the grace period, then got SIGKILLed).

    Best-effort by design: returns False (and never raises) when the
    thread has no bound agent, the agent isn't serving a session, or the
    call fails — teardown then proceeds exactly as before. The read
    timeout is sized to the persistent auxiliary extraction budget
    (auxiliary.timeout=120s) plus git-push headroom; unreachable pods
    fail in seconds via the connect timeout, and an already-terminated
    agent answers "already_idle" instantly.
    """
    try:
        thread = await postgres_db.get_thread(thread_id)
        runtime_authority = thread_runtime_authority(thread)
        if runtime_authority is None or not _thread_uses_pinned_execution(thread):
            return False
        binding = await postgres_db.get_pinned_session_binding(
            thread_id,
            expected_runtime_generation=runtime_authority.generation,
        )
        # 'session' is the heartbeat status of an agent serving a live
        # session — anything else (ready/offline/busy) either has nothing
        # to capture or is unreachable, so skip fast and let the normal
        # teardown run.
        if binding is None or binding.agent_status != "session":
            return False
        url = f"http://{binding.pod_ip}:{binding.pod_port}/session/detach"
        async with httpx.AsyncClient(
            timeout=httpx.Timeout(timeout, connect=3.0)
        ) as client:
            resp = await client.post(
                url,
                json={
                    "session_identity_fingerprint": (
                        binding.session_identity_fingerprint
                    )
                },
            )
        if resp.status_code == 200:
            logger.info(
                "Thread %s: agent detach completed before teardown",
                thread_id,
            )
            return True
        logger.warning(
            "Thread %s: pre-teardown detach returned %s — proceeding",
            thread_id,
            resp.status_code,
        )
        return False
    except Exception as e:
        logger.warning(
            "Thread %s: pre-teardown detach failed (%s: %s) — proceeding",
            thread_id,
            type(e).__name__,
            e,
        )
        return False


async def _release_thread_resources(
    thread_id: str,
    *,
    reclaim_volume: bool = False,
    require_workspace_retirement: bool = False,
) -> None:
    """Release a thread's workspace container/VM and agent pod.

    Centralized so the user-facing DELETE, the agent-facing status flip,
    and the orphan reaper share one teardown sequence. Each step swallows
    its own exception — a failure in snapshotting must not block the
    agent-pod delete and vice versa, otherwise resources leak.

    ``reclaim_volume`` decides whether the workspace PVC dies with the pod, and
    defaults to False because most callers here do NOT mean "destroy this
    user's data". A thread reaching ``ended`` is resumable — ``resume_thread``
    accepts exactly that status, the idle-archive writes it after 30 idle
    minutes, and the orphan sweeper writes it whenever an agent pod merely goes
    offline. With PVC-backed session workspaces, reclaiming on those paths would
    permanently delete a workspace the user can still reopen, so only the
    permanent-delete branch of ``end_thread`` passes True. The safe default also
    means a future caller that forgets the argument leaks a volume (recoverable)
    rather than destroying one (not).
    """
    # Let a live session agent terminate cleanly (final memory capture +
    # git push) while its workspace still exists. No-op in seconds for
    # agent-initiated endings (already terminated → "already_idle") and
    # for the orphan reaper (agent not in 'session' status).
    await _detach_agent_session(thread_id)

    workspace_error: Exception | None = None
    try:
        await _archive_and_cleanup_workspace(
            thread_id, entity_type="threads", reclaim_volume=reclaim_volume
        )
    except Exception as exc:
        workspace_error = exc
        logger.exception("Workspace cleanup failed for thread %s", thread_id)

    # BOTH provisioners, not either/or: a thread can have pods from both over
    # its lifetime — pool pods (agent_provisioner) from normal attach, and a
    # dedicated persistent-<tid> pod + PVC from the officer watchdog's respawn
    # path. The old elif skipped the persistent cleanup whenever the pool
    # provisioner was available, leaking a 10Gi PVC per respawned officer on
    # retirement (k3d smoke, open item 7). Both deletes are idempotent no-ops
    # when nothing matches.
    try:
        if agent_provisioner.is_available:
            await agent_provisioner.delete_agent_pod_by_thread(thread_id)
    except Exception:
        logger.exception("Agent pod cleanup failed for thread %s", thread_id)
    try:
        if persistent_provisioner.is_available:
            await persistent_provisioner.delete_agent_pod(thread_id)
            # The pod is stateless and always goes; its PVC is the workspace
            # itself, so it follows the same rule as the container workspace
            # above — an `ended` thread is RESUMABLE (idle-archive and the
            # orphan sweeper both write that status without any user intent to
            # destroy data), and only a permanent delete reclaims the volume.
            # Deleting it unconditionally here meant an idle timeout or a mere
            # agent-pod crash wiped the workspace of any thread served by this
            # provisioner (magic-link wake, officer-watchdog respawn). The cost
            # is that the retirement leak noted above now drains on the
            # permanent delete rather than on every end — the right way round:
            # a leaked volume is recoverable, a deleted one is not.
            if reclaim_volume:
                await persistent_provisioner.delete_agent_pvc(thread_id)
    except Exception:
        logger.exception("Persistent pod cleanup failed for thread %s", thread_id)

    # The supported End path must not report a terminal transition while a
    # static workspace can still hold a live repo-scoped ssh-agent, or while a
    # Pod/VM delete has not proved the captured compute incarnation gone.  The
    # background orphan path retains its historical best-effort behavior so a
    # failed snapshot cannot block unrelated agent-pod cleanup; its error stays
    # visible for lifecycle reconciliation.
    if require_workspace_retirement and workspace_error is not None:
        raise workspace_error


async def _pinned_retirement_is_current(retirement: Mapping[str, Any]) -> bool:
    """Recheck one durable pinned cleanup token without reopening admission."""

    current = await postgres_db.get_thread(
        str(retirement.get("context", {}).get("thread_id") or "")
    )
    return bool(
        current
        and str(current.get("runtime_generation") or "")
        == str(retirement.get("generation") or "")
        and str(current.get("runtime_retirement_token") or "")
        == str(retirement.get("token") or "")
        and bool(current.get("runtime_retirement_permanent"))
        == bool(retirement.get("permanent"))
    )


def _retirement_context_runtime_exposed(
    retirement: Mapping[str, Any],
) -> bool:
    """Whether this generation ever delivered a process authority.

    New Begin rows carry the database-monotonic exposure bit.  The identity
    fallback is deliberately conservative for an already-pending marker
    written during a rolling upgrade.
    """

    context = retirement.get("context")
    context = {} if context is None else context
    if not isinstance(context, Mapping):
        return True
    return bool(
        context.get("runtime_authority_exposed") is True
        or context.get("agent_id")
        or context.get("runtime_attach_token")
        or context.get("agent") not in (None, {})
        or context.get("agent_pod") not in (None, {})
        or context.get("agent_pod_provision_intent") not in (None, {})
    )


def _retirement_json_field_is_nonnull(value: Mapping[str, Any], key: str) -> bool:
    return key in value and value[key] is not None


def _retirement_json_status_is_absent(value: Mapping[str, Any]) -> bool:
    if "status" not in value or value["status"] is None:
        return True
    return isinstance(value["status"], str) and value["status"] in {"", "deleted"}


def _never_delivered_protected_reader_shape(
    retirement: Mapping[str, Any],
    thread: Mapping[str, Any],
    row: Mapping[str, Any] | None,
    *,
    require_current_revoked: bool,
) -> bool:
    """Prove a protected grant existed but no runtime could receive it.

    ``cloud_ro_mounts.status='active'`` records backend probe completion, not
    credential delivery.  A retirement that captured no actor, workspace,
    binding, VM, or staged overlay may revoke that exact reader first and then
    publish a zero-stage receipt.  This predicate is shared by the pre-stage
    actuator and receipt replay so a later/replacement row cannot be relabelled
    as the captured source.
    """

    context = retirement.get("context")
    context = {} if context is None else context
    if not isinstance(context, Mapping):
        return False
    raw_metadata = thread.get("metadata")
    raw_metadata = {} if raw_metadata is None else raw_metadata
    if isinstance(raw_metadata, str):
        try:
            raw_metadata = json.loads(raw_metadata)
        except (TypeError, ValueError):
            return False
    if not isinstance(raw_metadata, Mapping):
        return False

    def _object_or_empty(value: Any) -> Mapping[str, Any] | None:
        if value is None:
            return {}
        return value if isinstance(value, Mapping) else None

    captured_workspace = _object_or_empty(context.get("workspace_container"))
    captured_binding = _object_or_empty(context.get("workspace_binding"))
    captured_vm = _object_or_empty(context.get("vm"))
    current_workspace = _object_or_empty(raw_metadata.get("workspace_container"))
    current_binding = _object_or_empty(raw_metadata.get("_workspace_binding"))
    current_vm = _object_or_empty(raw_metadata.get("vm"))
    if any(
        value is None
        for value in (
            captured_workspace,
            captured_binding,
            captured_vm,
            current_workspace,
            current_binding,
            current_vm,
        )
    ):
        return False
    assert captured_workspace is not None
    assert captured_binding is not None
    assert captured_vm is not None
    assert current_workspace is not None
    assert current_binding is not None
    assert current_vm is not None

    def _empty_actor(value: Any) -> bool:
        return value is None or isinstance(value, Mapping) and not value

    workspace_fields = (
        WORKSPACE_RUNTIME_INCARNATION_KEY,
        "_docker_workspace_lease_id",
        "pod_ip",
        "pod_name",
        "host",
        "port",
        "ide_host",
        "ide_port",
        "_canvas_workspace_generation",
    )
    vm_fields = (
        "provision_generation",
        "identity_provision_generation",
        "vm_uid",
        "_runtime_incarnation",
        "rootdisk_pvc_uid",
        "ssh_host",
        "ssh_port",
        "_canvas_workspace_generation",
    )
    captured_agent_pod = context.get("agent_pod")
    captured_provision_intent = context.get("agent_pod_provision_intent")
    pre_registration_process_zero = bool(
        context.get("runtime_authority_exposed") is True
        and thread.get("runtime_authority_exposed") is True
        and context.get("agent_id") is None
        and context.get("runtime_attach_token") is None
        and _empty_actor(context.get("agent"))
        and isinstance(captured_agent_pod, Mapping)
        and captured_agent_pod
        and _empty_actor(raw_metadata.get("agent_pod"))
        and _retirement_has_exact_local_quiescence(retirement, thread)
    )
    pre_provision_process_zero = bool(
        context.get("runtime_authority_exposed") is True
        and thread.get("runtime_authority_exposed") is True
        and context.get("agent_id") is None
        and context.get("runtime_attach_token") is None
        and _empty_actor(context.get("agent"))
        and _empty_actor(context.get("agent_pod"))
        and isinstance(captured_provision_intent, Mapping)
        and captured_provision_intent
        and _empty_actor(raw_metadata.get("agent_pod"))
        and _retirement_has_exact_local_quiescence(retirement, thread)
    )
    process_authority_zero = bool(
        context.get("runtime_authority_exposed") is False
        and thread.get("runtime_authority_exposed") is False
        and _empty_actor(context.get("agent"))
        and _empty_actor(context.get("agent_pod"))
        or pre_registration_process_zero
        or pre_provision_process_zero
    )
    no_runtime = bool(
        str(thread.get("runtime_generation") or "")
        == str(retirement.get("generation") or "")
        and str(thread.get("runtime_retirement_token") or "")
        == str(retirement.get("token") or "")
        and context.get("protected_cloud") is True
        and raw_metadata.get("protected_cloud") is True
        and process_authority_zero
        and context.get("agent_id") is None
        and context.get("control_admission_agent_id") is None
        and context.get("runtime_attach_token") is None
        and _empty_actor(raw_metadata.get("agent_pod"))
        and thread.get("agent_id") is None
        and thread.get("control_admission_agent_id") is None
        and thread.get("runtime_attach_token") is None
        and captured_workspace == current_workspace
        and captured_binding == current_binding == {}
        and captured_vm == current_vm
        and _retirement_json_status_is_absent(captured_workspace)
        and not any(
            _retirement_json_field_is_nonnull(captured_workspace, field)
            for field in workspace_fields
        )
        and _retirement_json_status_is_absent(captured_vm)
        and not any(
            _retirement_json_field_is_nonnull(captured_vm, field) for field in vm_fields
        )
    )
    if not no_runtime:
        return False

    captured_ro = context.get("protected_ro")
    if captured_ro is None:
        return row is None
    if not isinstance(captured_ro, Mapping):
        return False
    try:
        UUID(str(captured_ro["id"]))
        UUID(str(captured_ro["runtime_generation"]))
        staged_epoch = int(captured_ro["staged_epoch"])
    except (KeyError, TypeError, ValueError):
        return False
    captured_plan = ProtectedNextcloudReaderGrantPlan.from_ro_mount_row(captured_ro)
    if captured_plan is None:
        return False
    captured_status = str(captured_ro.get("status") or "")
    captured_baseline = captured_ro.get("etag_baseline")
    if not (
        str(captured_ro.get("runtime_generation") or "")
        == str(retirement.get("generation") or "")
        and captured_ro.get("backend") == "nextcloud"
        and str(captured_ro.get("user_id") or "") == str(context.get("user_id") or "")
        and str(captured_ro.get("thread_id") or "")
        == str(context.get("thread_id") or "")
        and captured_status in {"engaging", "active", "revoking", "revoked"}
        and (
            isinstance(captured_baseline, Mapping)
            if captured_status == "active"
            else captured_baseline is None or isinstance(captured_baseline, Mapping)
        )
        and staged_epoch == 0
        and captured_ro.get("staged_summary") is None
    ):
        return False
    if row is None:
        return True
    try:
        current_epoch = int(row["staged_epoch"])
    except (KeyError, TypeError, ValueError):
        return False
    current_plan = ProtectedNextcloudReaderGrantPlan.from_ro_mount_row(row)
    expected_current_statuses = (
        {"revoked"}
        if require_current_revoked
        else {
            captured_status,
            "revoking",
            "revoked",
        }
    )
    return bool(
        str(row.get("id") or "") == str(captured_ro.get("id") or "")
        and current_plan == captured_plan
        and str(row.get("user_id") or "") == str(captured_ro.get("user_id") or "")
        and str(row.get("runtime_generation") or "")
        == str(captured_ro.get("runtime_generation") or "")
        and str(row.get("engage_attempt") or "")
        == str(captured_ro.get("engage_attempt") or "")
        and str(row.get("status") or "") in expected_current_statuses
        and row.get("etag_baseline") == captured_baseline
        and current_epoch == 0
        and row.get("staged_summary") is None
    )


async def _revoke_never_delivered_protected_reader(
    retirement: Mapping[str, Any],
    thread: Mapping[str, Any],
    row: Mapping[str, Any] | None,
) -> bool:
    """Exact-revoke the pre-agent reader before mandatory soft staging."""

    context = retirement.get("context") or {}
    captured_ro = context.get("protected_ro") if isinstance(context, Mapping) else None
    if not isinstance(captured_ro, Mapping) or not (
        _never_delivered_protected_reader_shape(
            retirement,
            thread,
            row,
            require_current_revoked=False,
        )
    ):
        return False
    plan = ProtectedNextcloudReaderGrantPlan.from_ro_mount_row(captured_ro)
    if plan is None:
        return False
    backend = await _resolve_protected_reader_backend(plan)
    current_status = str((row or {}).get("status") or "")
    revoked = current_status == "revoked"
    if not revoked:
        revoked = await revoke_ro_mount_attempt(
            backend=backend,
            postgres_db=postgres_db,
            row_id=str(captured_ro.get("id") or ""),
            thread_id=str(context.get("thread_id") or ""),
            runtime_generation=str(captured_ro.get("runtime_generation") or ""),
            plan=plan,
        )
    current = await postgres_db.get_ro_mount_by_thread(
        str(context.get("thread_id") or "")
    )
    if (
        not revoked
        and current is not None
        and str(current.get("status") or "") != "revoked"
    ):
        return False
    fresh_thread = await postgres_db.get_thread(str(context.get("thread_id") or ""))
    return bool(
        fresh_thread
        and _never_delivered_protected_reader_shape(
            retirement,
            fresh_thread,
            current,
            require_current_revoked=True,
        )
    )


def _retirement_has_exact_local_quiescence(
    retirement: Mapping[str, Any], thread: Mapping[str, Any]
) -> bool:
    """Validate the append-only local cleanup receipt for this exact life."""

    context = retirement.get("context")
    context = {} if context is None else context
    receipt = thread.get("runtime_retirement_local_quiescence")
    if isinstance(receipt, str):
        try:
            receipt = json.loads(receipt)
        except (TypeError, ValueError):
            return False
    if not isinstance(context, Mapping) or not isinstance(receipt, Mapping):
        return False
    workspace = context.get("workspace_container")
    binding = context.get("workspace_binding")
    vm = context.get("vm")
    agent = context.get("agent")
    agent_pod = context.get("agent_pod")
    provision_intent = context.get("agent_pod_provision_intent")
    workspace_provision_intent = context.get("workspace_provision_intent")
    workspace_claim = context.get("agent_workspace_claim")
    protected_ro = context.get("protected_ro")
    workspace = {} if workspace is None else workspace
    binding = {} if binding is None else binding
    vm = {} if vm is None else vm
    agent = {} if agent is None else agent
    agent_pod = {} if agent_pod is None else agent_pod
    provision_intent = {} if provision_intent is None else provision_intent
    workspace_provision_intent = (
        {} if workspace_provision_intent is None else workspace_provision_intent
    )
    workspace_claim = {} if workspace_claim is None else workspace_claim
    protected_ro = {} if protected_ro is None else protected_ro
    if not all(
        isinstance(value, Mapping)
        for value in (
            workspace,
            binding,
            vm,
            agent,
            agent_pod,
            provision_intent,
            workspace_provision_intent,
            workspace_claim,
            protected_ro,
        )
    ):
        return False
    if (
        agent
        and (not agent.get("hostname") or not agent.get("pod_uid"))
        or agent_pod
        and (not agent_pod.get("pod_name") or not agent_pod.get("pod_uid"))
        or provision_intent
        and (
            not provision_intent.get("attempt_id")
            or not provision_intent.get("pod_name")
            or provision_intent.get("provisioner") not in {"agent", "persistent"}
            or provision_intent.get("status") != "planned"
        )
        or workspace_claim
        and (
            not workspace_claim.get("claim_id")
            or not workspace_claim.get("pvc_name")
            or workspace_claim.get("provisioner") not in {"agent", "persistent"}
            or workspace_claim.get("status") not in {"planned", "ready"}
            or (workspace_claim.get("status") == "ready")
            != bool(str(workspace_claim.get("pvc_uid") or ""))
        )
    ):
        return False
    backend = str(context.get("workspace_backend") or "")
    sandbox_generation = binding.get("generation")
    sandbox_runtime = (
        workspace.get("_docker_workspace_lease_id")
        if workspace.get("provisioner") == "docker"
        else workspace.get(WORKSPACE_RUNTIME_INCARNATION_KEY)
    )
    sandbox_physical_evidence = bool(
        binding
        or _retirement_json_field_is_nonnull(
            workspace, WORKSPACE_RUNTIME_INCARNATION_KEY
        )
        or not _retirement_json_status_is_absent(workspace)
        or any(
            _retirement_json_field_is_nonnull(workspace, field)
            for field in (
                "pod_ip",
                "pod_name",
                "host",
                "port",
                "ide_host",
                "ide_port",
                "_canvas_workspace_generation",
            )
        )
    )
    pre_provision_intent_zero = bool(
        provision_intent
        and not agent
        and not agent_pod
        and context.get("agent_id") is None
        and context.get("runtime_attach_token") is None
    )
    workspace_create_pending = bool(workspace_provision_intent)
    if pre_provision_intent_zero or workspace_create_pending:
        expected_protocol = "agent_runtime_zero_v1"
    elif backend == "sandbox":
        if (
            bool(retirement.get("permanent"))
            and sandbox_physical_evidence
            and str(receipt.get("quiescence_actor") or "") == "orchestrator"
            and str(receipt.get("quiescence_protocol") or "")
            == "sandbox_actuator_zero_v1"
        ):
            expected_protocol = "sandbox_actuator_zero_v1"
        elif sandbox_generation and sandbox_runtime:
            expected_protocol = "workspace_process_zero_v1"
        elif not sandbox_generation and not sandbox_runtime:
            expected_protocol = "agent_runtime_zero_v1"
        else:
            return False
    elif backend in {"virtual", "none"}:
        expected_protocol = "agent_runtime_zero_v1"
    elif backend in {"vm", "remote"}:
        expected_protocol = "workspace_actuator_zero_v1"
    else:
        expected_protocol = None
    expected_workspace_generation = (
        None
        if pre_provision_intent_zero or workspace_create_pending
        else sandbox_generation
        if backend == "sandbox"
        else vm.get("provision_generation")
        if backend in {"vm", "remote"}
        else None
    )
    expected_workspace_runtime = (
        None
        if pre_provision_intent_zero or workspace_create_pending
        else sandbox_runtime
        if backend == "sandbox"
        else vm.get("vm_uid")
        if backend in {"vm", "remote"}
        else None
    )
    pre_registration_pod_zero = bool(
        agent_pod
        and not agent
        and context.get("agent_id") is None
        and context.get("runtime_attach_token") is None
    )
    return bool(
        int(receipt.get("version") or 0) == 1
        and str(receipt.get("runtime_generation") or "")
        == str(retirement.get("generation") or "")
        and str(receipt.get("retirement_token") or "")
        == str(retirement.get("token") or "")
        and str(receipt.get("agent_id") or "") == str(context.get("agent_id") or "")
        and str(receipt.get("runtime_attach_token") or "")
        == str(context.get("runtime_attach_token") or "")
        and str(receipt.get("settle_status") or "")
        == str(context.get("settle_status") or "")
        and expected_protocol is not None
        and str(receipt.get("quiescence_protocol") or "") == expected_protocol
        and str(receipt.get("quiescence_actor") or "") in {"agent", "orchestrator"}
        and str(receipt.get("workspace_generation") or "")
        == str(expected_workspace_generation or "")
        and str(receipt.get("workspace_runtime_incarnation") or "")
        == str(expected_workspace_runtime or "")
        and (
            not pre_registration_pod_zero
            or (
                str(receipt.get("quiescence_actor") or "") == "orchestrator"
                and str(receipt.get("quiescence_protocol") or "") == expected_protocol
                and str(receipt.get("agent_pod_name") or "")
                == str(agent_pod.get("pod_name") or "")
                and str(receipt.get("agent_pod_uid") or "")
                == str(agent_pod.get("pod_uid") or "")
            )
        )
        and (
            not pre_provision_intent_zero
            or (
                str(receipt.get("quiescence_actor") or "") == "orchestrator"
                and str(receipt.get("quiescence_protocol") or "")
                == "agent_runtime_zero_v1"
                and str(receipt.get("agent_pod_provision_attempt") or "")
                == str(provision_intent.get("attempt_id") or "")
                and str(receipt.get("agent_pod_name") or "")
                == str(provision_intent.get("pod_name") or "")
                and bool(str(receipt.get("agent_pod_uid") or ""))
                and receipt.get("agent_pod_fence_protocol") == "k8s_name_tombstone_v1"
            )
        )
    )


async def _wait_for_captured_agent_pod_retired(
    pod_name: str,
    pod_uid: str,
    *,
    namespace: str,
    allowed: set[str],
    timeout_s: float = 60.0,
) -> str | None:
    """Wait until one exact Pod process is absent/terminal, never by name."""

    deadline = asyncio.get_running_loop().time() + timeout_s
    while True:
        authority = await agent_provisioner.agent_pod_authority(
            pod_name, expected_pod_uid=pod_uid, namespace=namespace
        )
        if authority in allowed:
            return authority
        if authority != "exact_live" and asyncio.get_running_loop().time() >= deadline:
            return None
        if asyncio.get_running_loop().time() >= deadline:
            return None
        await asyncio.sleep(0.25)


def _captured_retirement_agent_pods(
    retirement: Mapping[str, Any],
) -> set[tuple[str, str, str, str]]:
    """Return immutable agent Pod name/UID pairs from one Begin context."""

    context = retirement.get("context")
    context = {} if context is None else context
    if not isinstance(context, Mapping):
        return set()
    captured: set[tuple[str, str, str, str]] = set()
    agent_pod = context.get("agent_pod") or {}
    pod_namespace = (
        str(agent_pod.get("namespace") or "") if isinstance(agent_pod, Mapping) else ""
    )
    protection_protocol = (
        str(agent_pod.get("protection_protocol") or "")
        if isinstance(agent_pod, Mapping)
        else ""
    )
    agent = context.get("agent") or {}
    if isinstance(agent, Mapping) and agent:
        captured.add(
            (
                str(agent.get("hostname") or ""),
                str(agent.get("pod_uid") or ""),
                pod_namespace,
                protection_protocol,
            )
        )
    if isinstance(agent_pod, Mapping) and agent_pod:
        captured.add(
            (
                str(agent_pod.get("pod_name") or ""),
                str(agent_pod.get("pod_uid") or ""),
                pod_namespace,
                protection_protocol,
            )
        )
    return captured


async def _stop_captured_retirement_agent(
    retirement: Mapping[str, Any],
) -> None:
    """Delete/wait only the exact captured actor process, never by name."""

    for (
        pod_name,
        pod_uid,
        namespace,
        protection_protocol,
    ) in _captured_retirement_agent_pods(retirement):
        if not pod_name and not pod_uid:
            continue
        if not (
            pod_name
            and pod_uid
            and namespace
            and protection_protocol == "finalizer_v1"
            and agent_provisioner.is_available
        ):
            raise RuntimeError("captured agent Pod identity is incomplete")
        if not await agent_provisioner.delete_agent_pod_exact(
            pod_name,
            expected_pod_uid=pod_uid,
            namespace=namespace,
        ):
            raise RuntimeError("exact agent Pod deletion is retryable")
        terminal = await _wait_for_captured_agent_pod_retired(
            pod_name,
            pod_uid,
            namespace=namespace,
            allowed={"exact_terminal"},
        )
        if terminal != "exact_terminal":
            raise RuntimeError("exact agent Pod termination is retryable")
        if not await agent_provisioner.release_agent_pod_finalizer_exact(
            pod_name,
            expected_pod_uid=pod_uid,
            namespace=namespace,
            terminal_required=True,
        ):
            raise RuntimeError("exact agent Pod finalizer release is retryable")
        absent = await _wait_for_captured_agent_pod_retired(
            pod_name,
            pod_uid,
            namespace=namespace,
            allowed={"exact_absent", "replacement"},
        )
        if absent not in {"exact_absent", "replacement"}:
            raise RuntimeError("exact agent Pod final deletion is retryable")


def _pre_registration_agent_pod_zero_candidate(
    retirement: Mapping[str, Any], thread: Mapping[str, Any]
) -> tuple[str, str] | None:
    """Return the sole captured Pod for a created life never registered.

    The retirement token closes the persistent registration/bind boundary.
    This shape has no session identity capable of acknowledging cleanup, so an
    exact Pod UID stop is the only truthful process-zero actuator.  A bound,
    active, incomplete, replaced, or already-cleared marker is never adopted.
    """

    context = retirement.get("context")
    context = {} if context is None else context
    if not isinstance(context, Mapping):
        return None
    raw_metadata = thread.get("metadata")
    raw_metadata = {} if raw_metadata is None else raw_metadata
    if isinstance(raw_metadata, str):
        try:
            raw_metadata = json.loads(raw_metadata)
        except (TypeError, ValueError):
            return None
    if not isinstance(raw_metadata, Mapping):
        return None
    captured_agent = context.get("agent")
    captured_pod = context.get("agent_pod")
    current_pod = raw_metadata.get("agent_pod")
    if not (
        str(thread.get("runtime_generation") or "")
        == str(retirement.get("generation") or "")
        and str(thread.get("runtime_retirement_token") or "")
        == str(retirement.get("token") or "")
        and str(thread.get("status") or "") == "created"
        and str(context.get("entry_status") or "") == "created"
        and context.get("runtime_authority_exposed") is True
        and context.get("agent_id") is None
        and context.get("control_admission_agent_id") is None
        and context.get("runtime_attach_token") is None
        and (
            captured_agent is None
            or isinstance(captured_agent, Mapping)
            and not captured_agent
        )
        and isinstance(captured_pod, Mapping)
        and captured_pod
        and current_pod == captured_pod
        and thread.get("agent_id") is None
        and thread.get("control_admission_agent_id") is None
        and thread.get("runtime_attach_token") is None
    ):
        return None
    pod_name = str(captured_pod.get("pod_name") or "")
    pod_uid = str(captured_pod.get("pod_uid") or "")
    return (pod_name, pod_uid) if pod_name and pod_uid else None


async def _recover_pre_registration_agent_pod_zero(
    retirement: Mapping[str, Any], thread: Mapping[str, Any]
) -> bool:
    """Exact-stop and receipt one pre-registration claimant Pod."""

    pod = _pre_registration_agent_pod_zero_candidate(retirement, thread)
    if pod is None:
        return False
    context = retirement.get("context") or {}
    thread_id = str(context.get("thread_id") or "")
    # Sanctioned registration takes the same advisory lifecycle lock as End;
    # this pre-effect check therefore cannot race its unbound-agent insert.
    # The post-effect receipt CAS repeats it against direct/legacy writers. A
    # registration that lost publication can leave one exact offline row
    # behind after its Pod is gone; retain that identity and delete it only
    # through the atomic offline+unbound predicate after exact Pod-zero.
    matching_agents = await postgres_db.fetch(
        "SELECT id::text,hostname,pod_uid::text,status,thread_id::text,"
        "current_job_id::text FROM agents "
        "WHERE thread_id=$1::uuid OR hostname=$2 OR pod_uid=$3 ORDER BY id",
        thread_id,
        pod[0],
        pod[1],
    )
    if len(matching_agents) > 1:
        return False
    orphan_agent_id: str | None = None
    if matching_agents:
        matching = matching_agents[0]
        if not (
            str(matching.get("hostname") or "") == pod[0]
            and str(matching.get("pod_uid") or "") == pod[1]
            and str(matching.get("status") or "") in {"offline", "failed"}
            and matching.get("thread_id") is None
            and matching.get("current_job_id") is None
        ):
            return False
        orphan_agent_id = str(matching.get("id") or "")
        if not orphan_agent_id:
            return False
    try:
        await _stop_captured_retirement_agent(retirement)
    except Exception:
        logger.exception(
            "Pre-registration agent Pod stop remains retryable for thread %s",
            thread_id,
        )
        return False
    if orphan_agent_id and not await postgres_db.delete_exact_offline_unbound_agent(
        orphan_agent_id,
        expected_hostname=pod[0],
        expected_pod_uid=pod[1],
    ):
        return False
    workspace = context.get("workspace_container")
    binding = context.get("workspace_binding")
    workspace = {} if workspace is None else workspace
    binding = {} if binding is None else binding
    if not isinstance(workspace, Mapping) or not isinstance(binding, Mapping):
        return False
    workspace_generation = str(binding.get("generation") or "")
    workspace_runtime = str(workspace.get(WORKSPACE_RUNTIME_INCARNATION_KEY) or "")
    physical_workspace_evidence = bool(
        binding
        or str(workspace.get("status") or "") not in {"", "deleted"}
        or any(
            workspace.get(field) is not None
            for field in (
                WORKSPACE_RUNTIME_INCARNATION_KEY,
                "pod_ip",
                "pod_name",
                "host",
                "port",
                "ide_host",
                "ide_port",
                "_canvas_workspace_generation",
            )
        )
    )
    if physical_workspace_evidence and not (workspace_generation and workspace_runtime):
        return False
    if physical_workspace_evidence:
        if not (
            retirement.get("permanent")
            and context.get("workspace_backend") == "sandbox"
            and workspace.get("provisioner") == "k8s"
            and workspace.get("status")
            in {"ready", "suspending", "suspended", "deleted"}
            and binding.get("kind") == "remote"
            and str(binding.get("backing_id") or "").startswith(
                ("k8s-pvc:", "k8s-pod:")
            )
            and str(workspace.get("_canvas_workspace_generation") or "")
            == workspace_generation
            and not context.get("workspace_provision_intent")
            and container_provisioner.is_available
        ):
            return False
        workspace_authority = await container_provisioner.workspace_pod_authority(
            WorkspaceOwner.session(thread_id),
            expected_runtime_incarnation=workspace_runtime,
        )
        if workspace_authority in {"exact_live", "exact_terminal"}:
            deleted = await container_provisioner.delete_workspace(
                WorkspaceOwner.session(thread_id),
                expected_runtime_incarnation=workspace_runtime,
                wait_for_exact_absence=True,
                exact_absence_timeout_seconds=120.0,
                defer_context_clear=True,
            )
            if not deleted:
                return False
        elif workspace_authority != "exact_absent":
            return False
    receipt = await postgres_db.acknowledge_pinned_thread_pre_registration_pod_zero(
        thread_id,
        expected_runtime_generation=str(retirement.get("generation") or ""),
        expected_retirement_token=str(retirement.get("token") or ""),
        expected_pod_name=pod[0],
        expected_pod_uid=pod[1],
        expected_workspace_generation=workspace_generation or None,
        expected_workspace_runtime_incarnation=workspace_runtime or None,
    )
    return receipt is not None


def _agent_pod_provision_intent_zero_candidate(
    retirement: Mapping[str, Any], thread: Mapping[str, Any]
) -> dict[str, str] | None:
    """Return one captured pre-effect Pod attempt with no session owner."""

    context = retirement.get("context")
    context = {} if context is None else context
    if not isinstance(context, Mapping):
        return None
    intent = context.get("agent_pod_provision_intent")
    if not isinstance(intent, Mapping) or not intent:
        return None
    metadata = thread.get("metadata")
    metadata = {} if metadata is None else metadata
    if isinstance(metadata, str):
        try:
            metadata = json.loads(metadata)
        except (TypeError, ValueError):
            return None
    if not isinstance(metadata, Mapping):
        return None
    attempt_id = str(intent.get("attempt_id") or "")
    pod_name = str(intent.get("pod_name") or "")
    provisioner = str(intent.get("provisioner") or "")
    namespace = str(intent.get("namespace") or "")
    protection_protocol = str(intent.get("protection_protocol") or "")
    try:
        UUID(attempt_id)
    except (TypeError, ValueError):
        return None
    if not (
        provisioner in {"agent", "persistent"}
        and pod_name
        and namespace
        and protection_protocol == "finalizer_v1"
        and str(intent.get("status") or "") == "planned"
        and str(intent.get("thread_id") or "") == str(context.get("thread_id") or "")
        and str(intent.get("runtime_generation") or "")
        == str(retirement.get("generation") or "")
        and str(thread.get("runtime_generation") or "")
        == str(retirement.get("generation") or "")
        and str(thread.get("runtime_retirement_token") or "")
        == str(retirement.get("token") or "")
        and context.get("runtime_authority_exposed") is True
        and context.get("agent_id") is None
        and context.get("control_admission_agent_id") is None
        and context.get("runtime_attach_token") is None
        and context.get("agent") in (None, {})
        and context.get("agent_pod") in (None, {})
        and thread.get("agent_id") is None
        and thread.get("control_admission_agent_id") is None
        and thread.get("runtime_attach_token") is None
        and metadata.get("agent_pod") in (None, {})
    ):
        return None
    return {
        "attempt_id": attempt_id,
        "pod_name": pod_name,
        "provisioner": provisioner,
        "namespace": namespace,
        "protection_protocol": protection_protocol,
    }


async def _recover_agent_pod_provision_intent_zero(
    retirement: Mapping[str, Any], thread: Mapping[str, Any]
) -> bool:
    """Resolve an accepted-or-absent create attempt before settlement."""

    intent = _agent_pod_provision_intent_zero_candidate(retirement, thread)
    if intent is None:
        return False
    context = retirement.get("context") or {}
    thread_id = str(context.get("thread_id") or "")
    provider = (
        persistent_provisioner
        if intent["provisioner"] == "persistent"
        else agent_provisioner
    )
    if not provider.is_available:
        return False
    if await postgres_db.fetchval(
        "SELECT EXISTS (SELECT 1 FROM agents WHERE thread_id=$1::uuid OR hostname=$2)",
        thread_id,
        intent["pod_name"],
    ):
        return False
    generation = str(retirement.get("generation") or "")
    token = str(retirement.get("token") or "")
    if not await postgres_db.revoke_pinned_agent_pod_provision_intent(
        thread_id,
        expected_runtime_generation=generation,
        expected_retirement_token=token,
        expected_attempt_id=intent["attempt_id"],
        expected_pod_name=intent["pod_name"],
    ):
        return False

    intent_row = await postgres_db.fetchrow(
        "SELECT status,pod_uid FROM thread_agent_pod_provision_intents "
        "WHERE attempt_id=$1::uuid AND thread_id=$2::uuid",
        intent["attempt_id"],
        thread_id,
    )
    if intent_row is None:
        return False
    intent_status = str(intent_row["status"] or "")
    fence_uid = str(intent_row["pod_uid"] or "")
    if intent_status == "fenced":
        observed = await provider.agent_pod_provision_intent_authority(
            intent["pod_name"],
            expected_thread_id=thread_id,
            expected_runtime_generation=generation,
            expected_attempt_id=intent["attempt_id"],
            namespace=intent["namespace"],
        )
        if not (
            isinstance(observed, Mapping)
            and str(observed.get("state") or "") == "exact_fence"
            and str(observed.get("pod_uid") or "") == fence_uid
        ):
            return False
    elif intent_status == "revoking":
        # A same-name CREATE is the causal barrier. A GET 404 alone could run
        # before the original credential-bearing request commits. If an
        # original manifest already owns the name, delete that exact UID and
        # retry until the *secret-free* fence itself wins. The retained fence
        # stays live through settlement/deletion so no delayed create CAS can
        # observe the key absent.
        deadline = asyncio.get_running_loop().time() + 60.0
        while True:
            fenced = await provider.fence_agent_pod_provision_intent(
                intent["pod_name"],
                expected_thread_id=thread_id,
                expected_runtime_generation=generation,
                expected_attempt_id=intent["attempt_id"],
                namespace=intent["namespace"],
            )
            if not isinstance(fenced, Mapping):
                return False
            fence_state = str(fenced.get("state") or "")
            candidate_uid = str(fenced.get("pod_uid") or "")
            if fence_state == "exact_fence":
                fence_uid = candidate_uid
                break
            if fence_state != "exact_original" or not candidate_uid:
                return False
            deleted = (
                await persistent_provisioner.delete_agent_pod_exact(
                    thread_id,
                    expected_pod_uid=candidate_uid,
                    namespace=intent["namespace"],
                )
                if intent["provisioner"] == "persistent"
                else await agent_provisioner.delete_agent_pod_exact(
                    intent["pod_name"],
                    expected_pod_uid=candidate_uid,
                    namespace=intent["namespace"],
                )
            )
            if not deleted:
                return False
            released = (
                await persistent_provisioner.release_agent_pod_finalizer_exact(
                    thread_id,
                    expected_pod_uid=candidate_uid,
                    namespace=intent["namespace"],
                    terminal_required=True,
                )
                if intent["provisioner"] == "persistent"
                else await agent_provisioner.release_agent_pod_finalizer_exact(
                    intent["pod_name"],
                    expected_pod_uid=candidate_uid,
                    namespace=intent["namespace"],
                    terminal_required=True,
                )
            )
            if not released:
                return False
            while True:
                authority = await provider.agent_pod_authority(
                    intent["pod_name"],
                    expected_pod_uid=candidate_uid,
                    namespace=intent["namespace"],
                )
                if authority == "exact_absent":
                    break
                if authority == "replacement":
                    # The next loop classifies whether another delayed exact
                    # create or a foreign successor won the name.
                    break
                if asyncio.get_running_loop().time() >= deadline:
                    return False
                await asyncio.sleep(0.2)
            if asyncio.get_running_loop().time() >= deadline:
                return False
        if (
            not fence_uid
            or not await postgres_db.fence_pinned_agent_pod_provision_intent(
                thread_id,
                expected_runtime_generation=generation,
                expected_retirement_token=token,
                expected_attempt_id=intent["attempt_id"],
                expected_pod_name=intent["pod_name"],
                fence_pod_uid=fence_uid,
            )
        ):
            return False
        intent_status = "fenced"
    if intent_status != "fenced" or not fence_uid:
        return False

    receipt = await postgres_db.acknowledge_pinned_agent_pod_provision_intent_zero(
        thread_id,
        expected_runtime_generation=generation,
        expected_retirement_token=token,
        expected_attempt_id=intent["attempt_id"],
        expected_pod_name=intent["pod_name"],
        observed_pod_uid=fence_uid,
    )
    return receipt is not None


def _captured_agent_workspace_claim(
    retirement: Mapping[str, Any],
) -> dict[str, str] | None:
    """Validate the immutable PVC claim frozen by retirement Begin."""

    context = retirement.get("context")
    context = {} if context is None else context
    if not isinstance(context, Mapping):
        return None
    raw = context.get("agent_workspace_claim")
    if raw in (None, {}):
        return None
    if not isinstance(raw, Mapping):
        raise RuntimeError("captured agent workspace claim is malformed")
    values = {
        "claim_id": str(raw.get("claim_id") or ""),
        "thread_id": str(raw.get("thread_id") or ""),
        "created_runtime_generation": str(raw.get("created_runtime_generation") or ""),
        "create_attempt": str(raw.get("create_attempt") or ""),
        "provisioner": str(raw.get("provisioner") or ""),
        "pvc_name": str(raw.get("pvc_name") or ""),
        "status": str(raw.get("status") or ""),
        "pvc_uid": str(raw.get("pvc_uid") or ""),
        "namespace": str(raw.get("namespace") or ""),
        "protection_protocol": str(raw.get("protection_protocol") or ""),
    }
    try:
        UUID(values["claim_id"])
        UUID(values["thread_id"])
        UUID(values["created_runtime_generation"])
        UUID(values["create_attempt"])
    except (TypeError, ValueError):
        raise RuntimeError("captured agent workspace claim UUID is malformed") from None
    if not (
        values["thread_id"] == str(context.get("thread_id") or "")
        and values["provisioner"] in {"agent", "persistent"}
        and values["pvc_name"]
        and values["namespace"]
        and values["protection_protocol"] == "finalizer_v1"
        and values["status"] in {"planned", "ready"}
        and (values["status"] == "ready") == bool(values["pvc_uid"])
    ):
        raise RuntimeError("captured agent workspace claim authority is incomplete")
    return values


async def _reconcile_agent_workspace_claim_for_retirement(
    retirement: Mapping[str, Any],
) -> None:
    """Retain a soft PVC or causally fence a permanently retired PVC name."""

    claim = _captured_agent_workspace_claim(retirement)
    if claim is None:
        return
    provider = (
        persistent_provisioner
        if claim["provisioner"] == "persistent"
        else agent_provisioner
    )
    if not provider.is_available:
        raise RuntimeError("captured agent workspace provisioner is unavailable")
    context = retirement.get("context") or {}
    thread_id = str(context.get("thread_id") or "")
    generation = str(retirement.get("generation") or "")
    token = str(retirement.get("token") or "")
    if not bool(retirement.get("permanent")):
        retained_uid = await provider.ensure_agent_workspace_claim(
            claim["pvc_name"],
            expected_thread_id=thread_id,
            expected_runtime_generation=claim["created_runtime_generation"],
            expected_claim_id=claim["claim_id"],
            expected_create_attempt=claim["create_attempt"],
            namespace=claim["namespace"],
            expected_pvc_uid=claim["pvc_uid"] or None,
        )
        if (
            not retained_uid
            or not await postgres_db.publish_pinned_agent_workspace_claim(
                thread_id,
                expected_runtime_generation=generation,
                expected_retirement_token=token,
                claim_id=claim["claim_id"],
                pvc_name=claim["pvc_name"],
                pvc_uid=retained_uid,
                namespace=claim["namespace"],
            )
        ):
            raise RuntimeError("exact agent workspace retention is retryable")
        return

    if not await postgres_db.revoke_pinned_agent_workspace_claim(
        thread_id,
        expected_runtime_generation=generation,
        expected_retirement_token=token,
        expected_claim_id=claim["claim_id"],
        expected_pvc_name=claim["pvc_name"],
    ):
        raise RuntimeError("agent workspace claim revocation is retryable")
    claim_row = await postgres_db.fetchrow(
        "SELECT status,pvc_uid FROM thread_agent_workspace_claims "
        "WHERE claim_id=$1::uuid AND thread_id=$2::uuid",
        claim["claim_id"],
        thread_id,
    )
    if claim_row is None:
        raise RuntimeError("agent workspace claim disappeared")
    claim_status = str(claim_row["status"] or "")
    fence_uid = str(claim_row["pvc_uid"] or "")
    if claim_status == "reclaimed":
        # The post-horizon GC reconciler already deleted the exact fence UID
        # and durably closed this immutable claim. This can happen when an
        # earlier retirement attempt finished name fencing but failed in a
        # later obligation. The row-locked revoke call above revalidated the
        # captured claim tuple, so terminal replay has nothing left to actuate.
        return
    if claim_status == "fenced":
        observed = await provider.agent_workspace_claim_authority(
            claim["pvc_name"],
            expected_thread_id=thread_id,
            expected_runtime_generation=claim["created_runtime_generation"],
            expected_claim_id=claim["claim_id"],
            expected_create_attempt=claim["create_attempt"],
            namespace=claim["namespace"],
            expected_pvc_uid=fence_uid,
        )
        if not (
            isinstance(observed, Mapping)
            and str(observed.get("state") or "") == "exact_fence"
            and str(observed.get("pvc_uid") or "") == fence_uid
        ):
            raise RuntimeError("agent workspace fence reattestation failed")
        return
    if claim_status != "revoking":
        raise RuntimeError("agent workspace claim transition is malformed")

    deadline = asyncio.get_running_loop().time() + 120.0
    while True:
        fenced = await provider.fence_agent_workspace_claim(
            claim["pvc_name"],
            expected_thread_id=thread_id,
            expected_runtime_generation=claim["created_runtime_generation"],
            expected_claim_id=claim["claim_id"],
            expected_create_attempt=claim["create_attempt"],
            namespace=claim["namespace"],
        )
        if not isinstance(fenced, Mapping):
            raise RuntimeError("agent workspace fence observation is malformed")
        state = str(fenced.get("state") or "")
        candidate_uid = str(fenced.get("pvc_uid") or "")
        if state == "exact_fence" and candidate_uid:
            fence_uid = candidate_uid
            break
        if state != "exact_original" or not candidate_uid:
            raise RuntimeError("agent workspace name has foreign authority")
        if not await provider.delete_agent_workspace_claim_exact(
            claim["pvc_name"],
            expected_pvc_uid=candidate_uid,
            namespace=claim["namespace"],
        ):
            raise RuntimeError("exact agent workspace deletion is retryable")
        if not await provider.release_agent_workspace_claim_finalizer_exact(
            claim["pvc_name"],
            expected_pvc_uid=candidate_uid,
            namespace=claim["namespace"],
        ):
            raise RuntimeError("agent workspace finalizer release is retryable")
        if asyncio.get_running_loop().time() >= deadline:
            raise RuntimeError("agent workspace fence acquisition timed out")
        await asyncio.sleep(0.25)
    if not await postgres_db.fence_pinned_agent_workspace_claim(
        thread_id,
        expected_runtime_generation=generation,
        expected_retirement_token=token,
        expected_claim_id=claim["claim_id"],
        expected_pvc_name=claim["pvc_name"],
        fence_pvc_uid=fence_uid,
    ):
        raise RuntimeError("agent workspace fence publication is retryable")


def _captured_workspace_provision_intent(
    retirement: Mapping[str, Any],
) -> dict[str, Any] | None:
    """Validate the immutable multi-resource K8s create attempt from Begin."""

    context = retirement.get("context")
    context = {} if context is None else context
    if not isinstance(context, Mapping):
        raise RuntimeError("captured retirement context is malformed")
    raw = context.get("workspace_provision_intent")
    if raw in (None, {}):
        return None
    if not isinstance(raw, Mapping):
        raise RuntimeError("captured workspace provision intent is malformed")
    intent = dict(raw)
    try:
        attempt_id = str(UUID(str(intent.get("attempt_id") or "")))
        thread_id = str(UUID(str(intent.get("thread_id") or "")))
        generation = str(UUID(str(intent.get("runtime_generation") or "")))
    except (TypeError, ValueError):
        raise RuntimeError(
            "captured workspace provision intent UUID is malformed"
        ) from None
    if not (
        attempt_id == str(intent.get("attempt_id") or "")
        and thread_id == str(context.get("thread_id") or "")
        and generation == str(retirement.get("generation") or "")
        and str(intent.get("namespace") or "")
        and str(intent.get("pod_name") or "")
        and str(intent.get("network_tier") or "")
        and re.fullmatch(r"[0-9a-f]{64}", str(intent.get("manifest_fingerprint") or ""))
        and intent.get("status") in {"planned", "fenced", "retired"}
        and isinstance(intent.get("previous_binding"), Mapping)
        and (intent.get("created_agent_id") is None)
        == (intent.get("created_attach_token") is None)
        and (intent.get("pvc_name") is None) == (intent.get("service_name") is None)
    ):
        raise RuntimeError("captured workspace provision intent is incomplete")
    return intent


async def _reconcile_workspace_provision_intent_for_retirement(
    retirement: Mapping[str, Any],
) -> bool:
    """Causally fence every name submitted by one pinned workspace create."""

    captured = _captured_workspace_provision_intent(retirement)
    if captured is None:
        return False
    if not container_provisioner.is_available:
        raise RuntimeError("captured workspace provisioner is unavailable")
    context = retirement.get("context") or {}
    thread_id = str(context.get("thread_id") or "")
    generation = str(retirement.get("generation") or "")
    token = str(retirement.get("token") or "")
    permanent = bool(retirement.get("permanent"))
    current = await postgres_db.revoke_pinned_thread_workspace_provision_intent(
        thread_id,
        expected_runtime_generation=generation,
        expected_retirement_token=token,
        expected_attempt_id=str(captured.get("attempt_id") or ""),
    )
    if not isinstance(current, Mapping):
        raise RuntimeError("workspace provision intent revocation is retryable")
    fences = await container_provisioner.fence_pinned_workspace_provision_intent(
        current,
        permanent=permanent,
    )
    if not isinstance(fences, Mapping):
        raise RuntimeError("workspace provision name fencing is retryable")

    previous_binding = captured.get("previous_binding") or {}
    if permanent and isinstance(previous_binding, Mapping) and previous_binding:
        if previous_binding.get("kind") == "virtual":
            from services.thread_uploads import (
                purge_attested_pinned_virtual_workspace,
            )

            current_thread = await postgres_db.get_thread(thread_id)
            if (
                current_thread is None
                or not await purge_attested_pinned_virtual_workspace(
                    current_thread,
                    expected_runtime_generation=generation,
                    expected_retirement_token=token,
                )
            ):
                raise RuntimeError("exact prior virtual backing cleanup is retryable")

    if not await postgres_db.fence_pinned_thread_workspace_provision_intent(
        thread_id,
        expected_runtime_generation=generation,
        expected_retirement_token=token,
        expected_attempt_id=str(captured.get("attempt_id") or ""),
        fence_pod_uid=str(fences.get("fence_pod_uid") or ""),
        fence_pvc_uid=str(fences.get("fence_pvc_uid") or "") or None,
        fence_configmap_uid=(str(fences.get("fence_configmap_uid") or "") or None),
        fence_service_uid=(str(fences.get("fence_service_uid") or "") or None),
        permanent=permanent,
    ):
        raise RuntimeError("workspace provision fence publication is retryable")
    return True


def _captured_virtual_binding_agent_zero_only(
    context: Mapping[str, Any],
    workspace: Mapping[str, Any],
    binding: Mapping[str, Any],
) -> bool:
    """Return whether the captured virtual backing owns no process runtime."""

    if str(context.get("workspace_backend") or "") != "virtual":
        return False
    raw_generation = str(binding.get("generation") or "")
    try:
        canonical_generation = str(UUID(raw_generation))
    except (TypeError, ValueError):
        return False
    return bool(
        not workspace
        and context.get("vm") in (None, {})
        and context.get("workspace_provision_intent") in (None, {})
        and set(binding)
        == {
            "generation",
            "kind",
            "backing_id",
            "ssh_host_key_fingerprint",
        }
        and binding.get("kind") == "virtual"
        and re.fullmatch(
            r"rclone:[0-9a-f]{64}",
            str(binding.get("backing_id") or ""),
        )
        is not None
        and canonical_generation == raw_generation
        and binding.get("ssh_host_key_fingerprint") is None
    )


async def _recover_captured_sandbox_process_zero(
    retirement: Mapping[str, Any],
) -> bool:
    """Mint a crash-recovery zero proof for one exact runtime incarnation.

    The agent process is stopped and proven absent *before* the workspace is
    contacted, so cached SSH credentials cannot reconnect behind the zero
    proof.  The thread advisory lock is deliberately not held while waiting
    for the agent Pod: a graceful SIGTERM path may be concurrently finishing
    its own ACK/settlement through that lock.  Once the Pod is absent, the
    immutable retirement token serializes the exact remote UID-zero command
    with staging and settlement.
    """

    context = retirement.get("context")
    context = {} if context is None else context
    if not isinstance(context, Mapping):
        return False
    if not _retirement_context_runtime_exposed(retirement):
        return True

    thread_id = str(context.get("thread_id") or "")
    permanent = bool(retirement.get("permanent"))
    current = await postgres_db.get_thread(thread_id)
    if current and _agent_pod_provision_intent_zero_candidate(retirement, current):
        async with postgres_db.try_thread_advisory_lock(thread_id) as lock_owner:
            if not lock_owner:
                return False
            current = await postgres_db.get_thread(thread_id)
            return bool(
                current
                and await _recover_agent_pod_provision_intent_zero(retirement, current)
            )

    captured_workspace = context.get("workspace_container")
    captured_binding = context.get("workspace_binding")
    captured_workspace = {} if captured_workspace is None else captured_workspace
    captured_binding = {} if captured_binding is None else captured_binding
    if not isinstance(captured_workspace, Mapping) or not isinstance(
        captured_binding, Mapping
    ):
        return False
    workspace_backend = str(context.get("workspace_backend") or "sandbox")
    virtual_binding_agent_zero_only = _captured_virtual_binding_agent_zero_only(
        context, captured_workspace, captured_binding
    )
    if workspace_backend != "sandbox" and not virtual_binding_agent_zero_only:
        return False
    captured_pods = _captured_retirement_agent_pods(retirement)
    if not captured_pods or any(
        not name or not uid or not namespace or protection_protocol != "finalizer_v1"
        for name, uid, namespace, protection_protocol in captured_pods
    ):
        return False
    if current and _pre_registration_agent_pod_zero_candidate(retirement, current):
        # Unlike a registered session, this Pod has no caller that could need
        # the lifecycle lock to publish its own ACK. Serialize against its
        # still-in-flight registration before exact UID deletion.
        async with postgres_db.try_thread_advisory_lock(thread_id) as lock_owner:
            if not lock_owner:
                return False
            current = await postgres_db.get_thread(thread_id)
            return bool(
                current
                and await _recover_pre_registration_agent_pod_zero(retirement, current)
            )

    captured_docker_lease = str(
        captured_workspace.get("_docker_workspace_lease_id") or ""
    )
    if captured_workspace.get("provisioner") == "docker":
        try:
            UUID(captured_docker_lease)
        except (TypeError, ValueError):
            return False
        # Allocation is fenced before the old agent disappears or the remote
        # strict-zero command runs. A delayed allocator can therefore never
        # hand this host/lease to another thread during crash recovery.
        if not await docker_provisioner.fence_thread_workspace_lease(
            str(context.get("thread_id") or ""),
            expected_lease_id=captured_docker_lease,
        ):
            return False

    # Never hold the DB lifecycle mutex while waiting for a Pod whose graceful
    # shutdown may need that same mutex to append its own exact proof.
    try:
        await _stop_captured_retirement_agent(retirement)
    except Exception:
        logger.exception(
            "Pinned retirement agent stop remains retryable for thread %s",
            context.get("thread_id"),
        )
        return False

    generation = str(retirement.get("generation") or "")
    token = str(retirement.get("token") or "")
    if not thread_id or not generation or not token:
        return False

    async with postgres_db.try_thread_advisory_lock(thread_id) as lock_owner:
        if not lock_owner:
            return False
        current = await postgres_db.get_thread(thread_id)
        if current is None:
            return True
        if str(current.get("runtime_retirement_token") or "") != token:
            # A graceful exact-agent settlement may have won while the Pod
            # stop was converging.  Never act on whichever runtime is current.
            return str(current.get("runtime_generation") or "") != generation or str(
                current.get("status") or ""
            ) in {"ended", "suspended"}
        if str(current.get("runtime_generation") or "") != generation:
            return False
        if _retirement_has_exact_local_quiescence(retirement, current):
            return True

        workspace = captured_workspace
        binding = captured_binding
        if not isinstance(workspace, Mapping) or not isinstance(binding, Mapping):
            return False
        if not workspace and (not binding or virtual_binding_agent_zero_only):
            receipt = await postgres_db.acknowledge_pinned_thread_local_quiescence(
                thread_id,
                expected_runtime_generation=generation,
                expected_retirement_token=token,
                expected_agent_id=str(context.get("agent_id") or ""),
                expected_attach_token=str(context.get("runtime_attach_token") or ""),
                expected_settle_status=str(context.get("settle_status") or ""),
                expected_quiescence_protocol="agent_runtime_zero_v1",
                expected_workspace_generation=None,
                expected_workspace_runtime_incarnation=None,
                quiescence_actor="orchestrator",
                expected_agent_pod_uid=next(iter(captured_pods))[1],
                require_zero_admission=True,
            )
            return receipt is not None
        workspace_generation = str(binding.get("generation") or "")
        runtime_incarnation = str(
            (
                workspace.get("_docker_workspace_lease_id")
                if workspace.get("provisioner") == "docker"
                else workspace.get(WORKSPACE_RUNTIME_INCARNATION_KEY)
            )
            or ""
        )
        fingerprint = str(binding.get("ssh_host_key_fingerprint") or "")
        host = str(workspace.get("pod_ip") or workspace.get("host") or "")
        workspace_status = str(workspace.get("status") or "")
        raw_port = workspace.get("port", 30022)
        try:
            UUID(thread_id)
            UUID(generation)
            UUID(token)
            UUID(str(context.get("agent_id") or ""))
            UUID(str(context.get("runtime_attach_token") or ""))
            UUID(workspace_generation)
            UUID(runtime_incarnation)
            port = int(raw_port)
        except (TypeError, ValueError):
            return False
        if (
            not host
            or not 1 <= port <= 65535
            or not fingerprint.startswith("SHA256:")
            or binding.get("kind") != "remote"
            or str(workspace.get("_canvas_workspace_generation") or "")
            != workspace_generation
        ):
            return False

        # A permanent retirement token prevents a same-name successor from
        # being admitted.  After the exact captured agent Pod is stopped, a
        # Kubernetes 404 (or an exact UID whose containers are all terminal)
        # is therefore a stronger process-zero proof than SSH: there is no
        # workspace process namespace left to contact.  Receipt that actuator
        # proof before the ordinary retirement cleanup removes the residual
        # PVC/Service.  Replacement and ambiguous observations stay refused.
        if permanent and workspace_status in {
            "ready",
            "suspending",
            "suspended",
            "deleted",
        }:
            workspace_authority = await container_provisioner.workspace_pod_authority(
                WorkspaceOwner.session(thread_id),
                expected_runtime_incarnation=runtime_incarnation,
            )
            if workspace_authority in {"exact_absent", "exact_terminal"}:
                receipt = await postgres_db.acknowledge_pinned_thread_local_quiescence(
                    thread_id,
                    expected_runtime_generation=generation,
                    expected_retirement_token=token,
                    expected_agent_id=str(context.get("agent_id") or ""),
                    expected_attach_token=str(
                        context.get("runtime_attach_token") or ""
                    ),
                    expected_settle_status=str(context.get("settle_status") or ""),
                    expected_quiescence_protocol="sandbox_actuator_zero_v1",
                    expected_workspace_generation=workspace_generation,
                    expected_workspace_runtime_incarnation=runtime_incarnation,
                    quiescence_actor="orchestrator",
                )
                return receipt is not None

        # SSH is a live-runtime actuator. A captured suspension/deletion state
        # may use exact Pod absence above, but may never dial its stale endpoint
        # when the Kubernetes observation is live, replaced, or ambiguous.
        if workspace_status != "ready":
            return False

        from services import resolve_ssh_key_path
        from src.core.backends.remote import RemoteBackend

        key_path = resolve_ssh_key_path()
        if not key_path:
            return False
        backend = RemoteBackend(
            host=host,
            port=port,
            username="agent-host",
            key_path=key_path,
            workspace_path="/home/agent-host/workspace",
            job_id=thread_id,
            workspace_generation=workspace_generation,
            runtime_incarnation=runtime_incarnation,
            expected_host_key_fingerprint=fingerprint,
            workspace_owner_kind="session",
            workspace_owner_id=thread_id,
            workspace_tier="sandbox",
            sudo_action="freeze",
        )
        try:
            protocol = await asyncio.to_thread(
                backend.protected_workspace_zero_cleanup_strict
            )
        except Exception:
            logger.exception(
                "Pinned retirement workspace zero remains retryable for thread %s",
                thread_id,
            )
            return False
        finally:
            await asyncio.to_thread(backend.disconnect)
        if protocol != "workspace_process_zero_v1":
            return False
        current = await postgres_db.get_thread(thread_id)
        if not current or not await _pinned_retirement_is_current(retirement):
            return False
        receipt = await postgres_db.acknowledge_pinned_thread_local_quiescence(
            thread_id,
            expected_runtime_generation=generation,
            expected_retirement_token=token,
            expected_agent_id=str(context.get("agent_id") or ""),
            expected_attach_token=str(context.get("runtime_attach_token") or ""),
            expected_settle_status=str(context.get("settle_status") or ""),
            expected_quiescence_protocol=protocol,
            expected_workspace_generation=workspace_generation,
            expected_workspace_runtime_incarnation=runtime_incarnation,
            quiescence_actor="orchestrator",
        )
        return receipt is not None


async def _complete_retiring_soft_warm_binding_release(
    retirement: Mapping[str, Any],
) -> bool:
    """Finish the durable finalizer release started by soft settlement."""

    if bool(retirement.get("permanent")):
        return True
    context = retirement.get("context")
    context = {} if context is None else context
    marker = context.get("agent_pod") if isinstance(context, Mapping) else None
    protection_id = (
        str(marker.get("warm_binding_protection") or "")
        if isinstance(marker, Mapping)
        else ""
    )
    if not protection_id:
        return True
    return await release_pinned_warm_binding_protection(
        postgres_db,
        protection_id=protection_id,
        agent_provisioner=agent_provisioner,
        persistent_provisioner=persistent_provisioner,
    )


async def _cleanup_pinned_thread_retirement(
    retirement: Mapping[str, Any],
    *,
    cleanup_agent_pod: bool = True,
    defer_agent_workspace_claim_until_caller_exit: bool = False,
) -> None:
    """Actuate only identities captured by ``begin_pinned_thread_retirement``.

    Every ambiguous failure raises and deliberately leaves the durable token
    pending. Resume and all runtime/credential admission stay closed until an
    exact retry completes. Deterministic names are lookup keys only; every K8s
    deletion carries a captured UID and soft End never deletes a PVC.
    """

    context = retirement.get("context")
    context = {} if context is None else context
    if not isinstance(context, Mapping):
        raise RuntimeError("pinned retirement context is malformed")
    thread_id = str(context.get("thread_id") or "")
    generation = str(retirement.get("generation") or "")
    if not thread_id or str(context.get("generation") or "") != generation:
        raise RuntimeError("pinned retirement context authority is malformed")
    permanent = bool(retirement.get("permanent"))

    # Wait out/prohibit every protected-engage producer before touching its
    # stable remote grant key. The scheduler uses this same cross-replica lock.
    if not await _pinned_retirement_is_current(retirement):
        raise RuntimeError("pinned retirement authority changed")
    if permanent and await postgres_db.pinned_retirement_external_cleanup_complete(
        thread_id,
        runtime_generation=generation,
        retirement_token=str(retirement.get("token") or ""),
    ):
        # The prior attempt crossed the append-once external-cleanup CAS only
        # after route teardown, exact resource actuators, reader revocation and
        # any required captured-agent stop.  A lost response/restart therefore
        # replays from this receipt without probing deterministic resource names
        # or adopting a successor endpoint.
        return

    agent = context.get("agent")
    agent = {} if agent is None else agent
    if not isinstance(agent, Mapping):
        raise RuntimeError("captured agent identity is malformed")
    agent_pod = context.get("agent_pod")
    agent_pod = {} if agent_pod is None else agent_pod
    if not isinstance(agent_pod, Mapping):
        raise RuntimeError("captured agent Pod identity is malformed")

    # Never address a captured Pod by IP here. Pod IPs are reusable, and an
    # old cleanup cannot prove that the process currently listening there is
    # the captured Pod/runtime. Agent-initiated End already performs its own
    # graceful memory/git flush; owner/offline retirement deliberately relies
    # on the exact UID deletion below instead of risking a successor detach.

    # Remove only the route owned by this Pod UID + runtime generation.
    route = context.get("route")
    route = {} if route is None else route
    if not isinstance(route, Mapping):
        raise RuntimeError("captured route identity is malformed")
    route_owner_uid = str((route or {}).get("owner_pod_uid") or "")
    if route_owner_uid:
        route_namespace = str(
            (route or {}).get("namespace") or (agent_pod or {}).get("namespace") or ""
        ).strip()
        if not route_namespace:
            raise RuntimeError("captured route namespace authority is malformed")
        if not await session_router.teardown_route(
            thread_id,
            expected_namespace=route_namespace,
            expected_runtime_generation=generation,
            expected_owner_uid=route_owner_uid,
        ):
            raise RuntimeError("exact session route cleanup is retryable")

    workspace_provision_intent_zero = (
        await _reconcile_workspace_provision_intent_for_retirement(retirement)
    )

    # Workspace teardown is separately identity-fenced. PVC deletion occurs
    # only for permanent End; soft End preserves the backing for Resume.
    ws = context.get("workspace_container")
    ws = {} if ws is None else ws
    if not isinstance(ws, Mapping):
        raise RuntimeError("captured workspace identity is malformed")
    backend = str(context.get("workspace_backend") or "sandbox")
    vm = context.get("vm")
    vm = {} if vm is None else vm
    if not isinstance(vm, Mapping):
        raise RuntimeError("captured VM identity is malformed")
    vm_identity_present = any(
        _retirement_json_field_is_nonnull(vm, field)
        for field in (
            "provision_generation",
            "identity_provision_generation",
            "vm_uid",
            "_runtime_incarnation",
            "rootdisk_pvc_uid",
            "ssh_host",
            "ssh_port",
            "_canvas_workspace_generation",
        )
    ) or not _retirement_json_status_is_absent(vm)
    binding = context.get("workspace_binding")
    binding = {} if binding is None else binding
    if not isinstance(binding, Mapping):
        raise RuntimeError("captured workspace binding is malformed")
    retained_soft_workspace = context.get("retained_soft_workspace")
    retained_soft_workspace = (
        {} if retained_soft_workspace is None else retained_soft_workspace
    )
    if not isinstance(retained_soft_workspace, Mapping):
        raise RuntimeError("captured retained workspace authority is malformed")
    virtual_binding_present = bool(binding and binding.get("kind") == "virtual")
    sandbox_identity_present = bool(
        _retirement_json_field_is_nonnull(ws, WORKSPACE_RUNTIME_INCARNATION_KEY)
        or (binding and not virtual_binding_present)
        or not _retirement_json_status_is_absent(ws)
        or any(
            _retirement_json_field_is_nonnull(ws, field)
            for field in (
                "pod_ip",
                "pod_name",
                "host",
                "port",
                "ide_host",
                "ide_port",
                "_canvas_workspace_generation",
            )
        )
    )
    if backend not in {"sandbox", "virtual", "none", "vm", "remote"}:
        raise RuntimeError("captured workspace backend is unsupported")
    if workspace_provision_intent_zero and vm_identity_present:
        raise RuntimeError("workspace create intent also contains VM authority")
    if (
        not workspace_provision_intent_zero
        and backend in {"vm", "remote"}
        and sandbox_identity_present
    ):
        raise RuntimeError("captured VM retirement also contains sandbox authority")
    if (
        not workspace_provision_intent_zero
        and backend == "sandbox"
        and vm_identity_present
    ):
        raise RuntimeError("captured sandbox retirement also contains VM authority")
    if (
        not workspace_provision_intent_zero
        and backend == "virtual"
        and (
            sandbox_identity_present
            or vm_identity_present
            or (binding and not virtual_binding_present)
        )
    ):
        raise RuntimeError("captured virtual retirement contains physical authority")
    if (
        not workspace_provision_intent_zero
        and backend == "none"
        and (sandbox_identity_present or vm_identity_present or binding)
    ):
        raise RuntimeError("captured lite retirement contains physical authority")
    completed_quiescence_protocol: str | None = None
    completed_external_cleanup_protocol: str | None = None
    if workspace_provision_intent_zero:
        completed_external_cleanup_protocol = "workspace_provision_fence_v1"
    elif backend in {"vm", "remote"} and vm_identity_present:
        from services.vm_provisioner import VMTeardownIdentity

        provision_generation = str(vm.get("provision_generation") or "")
        vm_uid = str(vm.get("vm_uid") or "")
        rootdisk_uid = str(vm.get("rootdisk_pvc_uid") or "")
        if (
            not vm_provisioner.lifecycle_available
            or not provision_generation
            or not vm_uid
            or (permanent and not rootdisk_uid)
        ):
            raise RuntimeError("exact VM cleanup authority is incomplete")
        vm_result = await vm_provisioner.release_vm_captured(
            thread_id,
            VMTeardownIdentity(
                provision_generation=provision_generation,
                vm_uid=vm_uid,
                rootdisk_pvc_uid=rootdisk_uid or None,
                ssh_host=vm.get("ssh_host"),
                ssh_port=vm.get("ssh_port"),
                ssh_host_key_fingerprint=vm.get("ssh_host_key_fingerprint"),
                credential_runtime_started=vm.get("credential_runtime_started"),
            ),
            ssh_host=vm.get("ssh_host"),
            ssh_port=vm.get("ssh_port"),
            purge_disk=permanent,
            entity_type="thread",
            capture_snapshot=False,
        )
        if vm_result.disposition != "completed":
            raise RuntimeError("exact VM cleanup is retryable")
        completed_quiescence_protocol = "workspace_actuator_zero_v1"
        completed_external_cleanup_protocol = "workspace_actuator_zero_v1"
    elif backend in {"vm", "remote"}:
        pass
    elif backend == "sandbox" and ws.get("provisioner") == "docker":
        lease_id = str(ws.get("_docker_workspace_lease_id") or "")
        if not lease_id or not await docker_provisioner.release_thread_workspace(
            thread_id,
            expected_lease_id=lease_id,
            force_quarantine=True,
        ):
            raise RuntimeError("exact Docker workspace cleanup is retryable")
        # Quarantine/release fences allocation of this exact lease, but does
        # not prove its remote same-UID processes stopped. Exposed Docker lives
        # need a pre-existing host-key/lease-bound workspace_process_zero_v1
        # receipt from the live agent (or the dedicated recovery actuator).
        completed_external_cleanup_protocol = "sandbox_actuator_zero_v1"
    elif backend == "sandbox" and sandbox_identity_present:
        if not container_provisioner.is_available:
            raise RuntimeError("Kubernetes workspace cleanup is unavailable")
        workspace_identity = (
            await container_provisioner.capture_workspace_teardown_identity(
                WorkspaceOwner.session(thread_id)
            )
        )
        captured_runtime = str(ws.get(WORKSPACE_RUNTIME_INCARNATION_KEY) or "")
        captured_generation = str(binding.get("generation") or "")
        captured_backing = str(binding.get("backing_id") or "")
        retained_pvc_uid = str(retained_soft_workspace.get("pvc_uid") or "")
        retained_authority = bool(retained_soft_workspace)
        if (
            not captured_generation
            or binding.get("kind") != "remote"
            or not (
                captured_backing.startswith("k8s-pvc:")
                or captured_backing.startswith("k8s-pod:")
            )
        ):
            raise RuntimeError("exact Kubernetes cleanup authority is incomplete")
        try:
            UUID(captured_generation)
            backing_resource_uid = str(UUID(captured_backing.rsplit(":", 1)[-1]))
            if captured_runtime:
                UUID(captured_runtime)
            if retained_authority:
                UUID(str(retained_soft_workspace.get("attempt_id") or ""))
                UUID(retained_pvc_uid)
        except (TypeError, ValueError):
            raise RuntimeError(
                "exact Kubernetes cleanup authority is malformed"
            ) from None
        if retained_authority:
            expected_owner = WorkspaceOwner.session(thread_id)
            expected_pvc_name = f"pvc-{expected_owner.pod_name}"
            if (
                not permanent
                or context.get("entry_status") != "ended"
                or retained_soft_workspace.get("version") != 1
                or str(retained_soft_workspace.get("runtime_generation") or "")
                != generation
                or str(retained_soft_workspace.get("workspace_generation") or "")
                != captured_generation
                or str(retained_soft_workspace.get("namespace") or "")
                != str(ws.get("namespace") or "")
                or str(retained_soft_workspace.get("pod_name") or "")
                != expected_owner.pod_name
                or str(ws.get("pod_name") or "") != expected_owner.pod_name
                or str(retained_soft_workspace.get("pvc_name") or "")
                != expected_pvc_name
                or retained_pvc_uid != backing_resource_uid
                or captured_backing
                != (
                    f"k8s-pvc:{retained_soft_workspace.get('namespace')}:"
                    f"{retained_pvc_uid}"
                )
                or ws.get("status") != "deleted"
                or ws.get("provisioner") != "k8s"
                or ws.get(WORKSPACE_RUNTIME_INCARNATION_KEY) is not None
                or ws.get("pod_ip") is not None
                or ws.get("ide_host") is not None
                or ws.get("ide_port") is not None
                or str(ws.get("_canvas_workspace_generation") or "")
                != captured_generation
                or captured_runtime
                or workspace_identity.pod_uid is not None
                or workspace_identity.service_uid is not None
                or workspace_identity.pvc_uid != retained_pvc_uid
            ):
                raise RuntimeError(
                    "retained Kubernetes workspace authority changed before deletion"
                )
        elif not captured_runtime:
            raise RuntimeError("exact Kubernetes cleanup authority is incomplete")
        if (
            workspace_identity.pod_uid is not None
            and workspace_identity.pod_uid != captured_runtime
        ):
            raise RuntimeError("workspace Pod identity changed before retirement")
        if captured_backing.startswith("k8s-pod:"):
            if backing_resource_uid != captured_runtime:
                raise RuntimeError("workspace Pod backing authority is inconsistent")
            if workspace_identity.pvc_uid is not None:
                # ``k8s-pod`` is the immutable emptyDir shape. A PVC that
                # appeared after Begin belongs to a replacement/provisioning
                # attempt and must never be adopted by deterministic name.
                raise RuntimeError(
                    "workspace PVC appeared outside captured retirement authority"
                )
        elif (
            workspace_identity.pvc_uid is not None
            and workspace_identity.pvc_uid != backing_resource_uid
        ):
            # A present same-name PVC must still be the exact captured UID.
            # Absence is an idempotent replay after an earlier exact release
            # deleted the volume but a later retirement obligation remained
            # retryable; _release_captured_workspace rechecks Pod absence and
            # never adopts a deterministic-name successor.
            raise RuntimeError("workspace PVC identity changed before retirement")
        released = await container_provisioner.release_workspace(
            WorkspaceOwner.session(thread_id),
            reclaim_volume=permanent,
            capture_snapshot=True,
            strict=True,
            teardown_identity=workspace_identity,
        )
        if not released:
            raise RuntimeError("exact Kubernetes workspace cleanup is retryable")
        completed_quiescence_protocol = "sandbox_actuator_zero_v1"
        completed_external_cleanup_protocol = "sandbox_actuator_zero_v1"
    elif backend == "virtual" and virtual_binding_present and permanent:
        from services.thread_uploads import purge_attested_pinned_virtual_workspace

        current = await postgres_db.get_thread(thread_id)
        if current is None or not await purge_attested_pinned_virtual_workspace(
            current,
            expected_runtime_generation=generation,
            expected_retirement_token=str(retirement.get("token") or ""),
        ):
            raise RuntimeError("exact virtual backing cleanup is retryable")
        completed_external_cleanup_protocol = "virtual_backing_zero_v1"

    # Reader cleanup uses the captured row+attempt; never re-read a row by
    # thread and accidentally revoke a successor grant.
    protected_ro = context.get("protected_ro")
    protected_ro = {} if protected_ro is None else protected_ro
    if not isinstance(protected_ro, Mapping):
        raise RuntimeError("captured protected reader identity is malformed")
    if protected_ro.get("status") in {
        "engaging",
        "active",
        "revoking",
    }:
        row_id = str(protected_ro.get("id") or "")
        ro_generation = str(protected_ro.get("runtime_generation") or "")
        plan = ProtectedNextcloudReaderGrantPlan.from_ro_mount_row(protected_ro)
        if not row_id or not ro_generation or plan is None:
            raise RuntimeError("protected reader cleanup lacks exact identity")
        backend_client = await _resolve_protected_reader_backend(plan)
        if not await revoke_ro_mount_attempt(
            backend=backend_client,
            postgres_db=postgres_db,
            row_id=row_id,
            thread_id=thread_id,
            runtime_generation=ro_generation,
            plan=plan,
        ):
            current_ro = await postgres_db.get_ro_mount_by_thread(thread_id)
            if not current_ro or str(current_ro.get("status") or "") in {
                "engaging",
                "active",
                "revoking",
            }:
                raise RuntimeError("protected reader row cleanup is retryable")

    # Agent Pods last: workspace snapshots/detach may still need the process.
    # The exact self-settlement route is itself awaiting this HTTP response;
    # synchronously deleting/waiting for that caller creates a lifecycle
    # cycle.  Its append-only local-quiescence receipt proves writers are
    # stopped, so settlement may answer first and the process exits itself.
    stopped_agent_pod_name: str | None = None
    stopped_agent_pod_uid: str | None = None
    if cleanup_agent_pod:
        captured_agent_pods = _captured_retirement_agent_pods(retirement)
        if len(captured_agent_pods) > 1:
            raise RuntimeError("captured retirement agent identities disagree")
        await _stop_captured_retirement_agent(retirement)
        if captured_agent_pods:
            (
                stopped_agent_pod_name,
                stopped_agent_pod_uid,
                _stopped_agent_pod_namespace,
                _stopped_agent_pod_protection_protocol,
            ) = next(iter(captured_agent_pods))
            if completed_quiescence_protocol is None:
                completed_quiescence_protocol = "agent_runtime_zero_v1"

    if defer_agent_workspace_claim_until_caller_exit:
        # A permanent final ACK is sent by the same agent process whose Pod
        # mounts this claim. Its append-only local-quiescence receipt proves
        # the runtime stopped all writers, but Kubernetes cannot remove the
        # PVC until this HTTP response lets that caller exit. Leave the claim
        # completely untouched; an owner/reconciler retry exact-stops the
        # captured Pod first and then resumes the ordinary fenced cleanup.
        if (
            not permanent
            or cleanup_agent_pod
            or _captured_agent_workspace_claim(retirement) is None
        ):
            raise RuntimeError("agent workspace cleanup handoff is malformed")
        return

    # A bootstrap Pod can have a distinct persistent PVC whose create was
    # already sent before registration. Soft settlement retains/re-attests the
    # exact UID. Permanent settlement deletes only exact claimants and leaves
    # a same-name inert PVC tombstone until the API-request horizon expires.
    # This runs after agent stop so a mounted claim is never torn down first.
    await _reconcile_agent_workspace_claim_for_retirement(retirement)

    if permanent and not (
        await postgres_db.clear_pinned_retirement_physical_runtime_endpoint(
            thread_id,
            runtime_generation=generation,
            retirement_token=str(retirement.get("token") or ""),
            completed_quiescence_protocol=completed_quiescence_protocol,
            completed_external_cleanup_protocol=(completed_external_cleanup_protocol),
            expected_stopped_agent_pod_name=stopped_agent_pod_name,
            expected_stopped_agent_pod_uid=stopped_agent_pod_uid,
        )
    ):
        raise RuntimeError(
            "permanent retirement physical endpoint cleanup CAS is retryable"
        )

    if not await _pinned_retirement_is_current(retirement):
        raise RuntimeError("pinned retirement authority changed before settlement")


# Threads with a suspend currently in flight. Two triggers can race on the
# same thread within a second (e.g. the disconnect watchdog and the agent's
# own status→ended PUT); without this guard the loser found the workspace
# already suspended, misread it as a failure, and deleted the agent pod a
# second time (knowledge-base/knowledge/issues/session_silent_failure_audit.md #13).
_threads_suspending: set[str] = set()


async def _suspend_thread_resources(thread_id: str) -> None:
    """Suspend a thread's workspace to S3 and release the agent pod.

    Used for agent-initiated `ended` transitions where the user has not
    asked to destroy data — idle timeout, drain, watchdog, WS disconnect.
    Preserves the workspace via S3 snapshot so /resume can restore it
    later (resume already routes through restore_thread_workspace when
    it sees workspace_container.status == 'suspended').

    Falls back gracefully if the suspension service is disabled or the
    snapshot fails: the workspace stays alive (reconciler will reap it
    eventually) but we still delete the agent pod so the slot frees.
    """
    if thread_id in _threads_suspending:
        logger.info(
            "Thread %s: suspend already in flight — skipping duplicate", thread_id
        )
        return
    _threads_suspending.add(thread_id)
    try:
        await _suspend_thread_resources_inner(thread_id)
    finally:
        _threads_suspending.discard(thread_id)


async def _suspend_thread_resources_inner(thread_id: str) -> None:
    thread = await postgres_db.get_thread(thread_id)
    if thread is not None and thread.get("execution_lane") == "stateless":
        # Queue-served physical sessions require the terminal claimant /
        # resident / runtime protocol. Legacy suspension must not fall through
        # to name-only agent deletion when the central service refuses it.
        logger.info(
            "Skipping legacy resource suspension for stateless thread %s",
            thread_id,
        )
        return
    suspended = False
    metadata = thread_metadata_object(thread or {})
    workspace = metadata.get("workspace_container") or {}
    if workspace.get("provisioner") == "docker":
        # Static Docker suspension cannot destroy the process namespace.  It
        # must nevertheless retire and independently prove zero repo-scoped
        # ssh-agents before the persistent runtime Pod is removed.  The deploy
        # key remains server-side and can be delivered again on a supported
        # resume; only this resident bearer process is retired.
        try:
            if not await docker_provisioner.release_thread_workspace(thread_id):
                logger.error(
                    "Docker workspace authority retirement failed for ended thread %s",
                    thread_id,
                )
        except Exception:
            logger.exception(
                "Docker workspace authority retirement raised for ended thread %s",
                thread_id,
            )
    else:
        try:
            if workspace_suspension_service.is_enabled:
                suspended = await workspace_suspension_service.suspend_thread_workspace(
                    thread_id
                )
        except Exception:
            logger.exception("Workspace suspend failed for thread %s", thread_id)

    if suspended:
        # suspend_thread_workspace already deletes the agent pod.
        return

    logger.warning(
        "Workspace suspend unavailable or failed for thread %s — keeping "
        "workspace alive (reconciler will reap) but deleting the agent pod",
        thread_id,
    )
    # Pods from BOTH provisioners (see _release_thread_resources), but NOT the
    # persistent PVC: suspend serves resumable threads, and for a dedicated
    # pod that PVC is the workspace itself. It is reclaimed at retirement by
    # the release path.
    try:
        if agent_provisioner.is_available:
            await agent_provisioner.delete_agent_pod_by_thread(thread_id)
    except Exception:
        logger.exception("Agent pod cleanup failed for thread %s", thread_id)
    try:
        if persistent_provisioner.is_available:
            await persistent_provisioner.delete_agent_pod(thread_id)
    except Exception:
        logger.exception("Persistent pod cleanup failed for thread %s", thread_id)


def _provider_of_model(model: str) -> str | None:
    """Sync prefix-based provider heuristic for legacy dispatch paths.

    Catalog rows carry ``provider_ref`` explicitly; this helper exists for
    the small set of code paths that don't have a row in hand and only
    need the factory name (aux-model key injection, vision-model key
    lookup, dispatcher provider-key inference). Returns None on any miss
    so callers fall through to their config_name / env-var heuristics.

    The legacy ``resolve_builtin`` lookup that this replaced was the entry
    point for the YAML fallback path — removed in chunk 6 of the
    models_yaml_removal work.
    """
    if not model:
        return None
    name = model.lower()
    for prefix in ("openrouter/", "groq/"):
        if name.startswith(prefix):
            return prefix.rstrip("/")
    if name.startswith("codex/"):
        return "codex"
    if name.startswith("openai/"):
        return "openai"
    if name.startswith(("claude-",)):
        return "anthropic"
    if name.startswith("gemini-") or name.startswith("gemma-"):
        return "google"
    if name.startswith(("gpt-", "o1", "o3", "o4", "text-embedding-")):
        return "openai"
    return None


async def _inject_model_credentials(
    *,
    section: dict,
    model_id: str,
    user_id: str | None,
    resolved_keys: dict[str, str] | None,
    capability: str = "chat",
) -> None:
    """Populate a config-override section with the right base_url + api_key
    for a given model ID.

    For endpoint-backed models (``origin`` in {``custom``, ``system``}):
    looks up the endpoint row and inlines its ``base_url`` + ``api_key``.
    Custom endpoints are user-scoped; system endpoints are helm-seeded or
    managed via Admin → Providers. Both live in llm_endpoints.

    For built-ins: injects the named provider's key from ``resolved_keys``
    (the user > project > env resolution chain). No base_url injection —
    the agent's own registry handles env-driven base URLs for local models.

    Endpoint-backed models use the endpoint row as the transport authority. That
    intentionally replaces stale persisted transports when a session or paused
    job is rehydrated.
    """
    meta = None
    try:
        meta = await _resolve_model(model_id, user_id=user_id, capability=capability)
    except UnknownModelError:
        meta = None

    transport_complete = "base_url" in section and "api_key" in section

    # Per-model context window (chat capability only — auxiliary/vision sections
    # carry their own windows and aren't derived this way). Set before the
    # endpoint/provider branches so it also reaches endpoint-backed (self-hosted)
    # models. setdefault keeps a caller-pinned value; truthy guard skips None/0.
    if capability == "chat" and meta is not None and meta.context_window:
        section.setdefault("model_max_context_tokens", meta.context_window)
    # Per-model output cap (chat slot — strategic/tactical reasoning models are
    # where output truncation bites); overrides the family value, ctx-clamped.
    if capability == "chat" and meta is not None and meta.max_output_tokens:
        section.setdefault("max_output_tokens", meta.max_output_tokens)

    # Inject the agent-side factory name so the section always routes to the
    # correct LLM factory — e.g. an OpenRouter row → _create_openrouter_llm
    # (openrouter.ai), not the OpenAI default at api.openai.com. meta.provider
    # already holds the factory name ("openai" for endpoint-backed rows).
    # This must happen for endpoint rows too: a session hot-swap deep-merges
    # the enriched override into the existing config, so leaving `provider`
    # unset keeps the PREVIOUS model's factory (e.g. minimax via openrouter →
    # gpt-5.5 endpoint row kept routing through _create_openrouter_llm).
    if meta is not None and meta.provider:
        section["provider"] = meta.provider

    if transport_complete and not (meta is not None and meta.endpoint_id):
        return

    if (
        meta is not None
        and meta.origin in ("custom", "system", "catalog")
        and meta.endpoint_id
    ):
        endpoint_row = await postgres_db.get_user_llm_endpoint(meta.endpoint_id)
        if endpoint_row:
            if endpoint_row.get("base_url"):
                section["base_url"] = endpoint_row["base_url"]
            if endpoint_row.get("api_key"):
                section["api_key"] = endpoint_row["api_key"]
        return

    provider = meta.api_key_ref if meta is not None else _provider_of_model(model_id)
    if meta is None and provider:
        section.setdefault("provider", provider)
    if (
        provider
        and resolved_keys
        and provider in resolved_keys
        and "api_key" not in section
    ):
        section["api_key"] = resolved_keys[provider]


async def _inject_env_key_credentials(
    *,
    env_keys: dict,
    prefix: str,
    model_id: str,
    user_id: str | None,
    resolved_keys: dict[str, str] | None,
    capability: str = "chat",
) -> None:
    """Populate ``env_keys`` with ``{PREFIX}_MODEL/_BASE_URL/_API_KEY``.

    Sibling of ``_inject_model_credentials`` for capabilities that travel as
    flat env vars (vision, whisper, tts, ...) rather than structured config
    sections. Endpoint-backed models (origin in {'custom','system','catalog'}
    with an endpoint_id) contribute the inline base_url+api_key from the
    endpoint row; built-ins and system-anchored catalog rows resolve the
    api_key via ``resolved_keys[provider]``. All writes are setdefault so
    caller / earlier overrides win.
    """
    env_keys.setdefault(f"{prefix}_MODEL", model_id)

    meta = None
    try:
        meta = await _resolve_model(model_id, user_id=user_id, capability=capability)
    except UnknownModelError:
        meta = None

    if (
        meta is not None
        and meta.origin in ("custom", "system", "catalog")
        and meta.endpoint_id
    ):
        endpoint_row = await postgres_db.get_user_llm_endpoint(meta.endpoint_id)
        if endpoint_row:
            base_url = endpoint_row.get("base_url")
            api_key = endpoint_row.get("api_key")
            if base_url and not api_key:
                # The endpoint is configured but its stored key didn't decrypt
                # (get_user_llm_endpoint -> _decrypt_stored already logged the
                # cause) or is empty. Surface it loudly and do NOT emit a
                # half-credential (base_url without api_key) that silently
                # degrades the agent to a keyless 'local' provider — the failure
                # mode in knowledge-history/done/embedding_key_missing_silently_disables_memory_and_kb.md.
                logger.error(
                    "Dispatch: %s endpoint %s resolved a base_url but no usable "
                    "api_key (decrypt failed or empty) — not injecting "
                    "%s_BASE_URL/_API_KEY; re-add the key in Admin → Models.",
                    prefix,
                    meta.endpoint_id,
                    prefix,
                )
                return
            if base_url:
                env_keys.setdefault(f"{prefix}_BASE_URL", base_url)
            if api_key:
                env_keys.setdefault(f"{prefix}_API_KEY", api_key)
        return

    provider = meta.api_key_ref if meta is not None else _provider_of_model(model_id)
    if provider and resolved_keys and provider in resolved_keys:
        env_keys.setdefault(f"{prefix}_API_KEY", resolved_keys[provider])


async def _inject_search_credentials(
    config_override: dict[str, Any],
    *,
    user_settings: dict[str, Any],
    user_id: str | None,
    resolved_keys: dict[str, str],
) -> dict[str, Any]:
    """Inject catalog-resolved search/fetch adapters into research config.

    Transport credentials stay in the per-dispatch override and are stripped
    before persistence by ``redact_config_override``. Adapter selection comes
    only from parsed ``params_json`` returned by the shared capability resolver.
    """

    from services.capability_credentials import resolve_capability_credentials

    research = config_override.setdefault("research", {})
    resolved: dict[str, Any] = {}
    for capability in ("search", "fetch"):
        creds = await resolve_capability_credentials(
            capability=capability,
            user_settings=user_settings,
            user_id=user_id,
            resolved_keys=resolved_keys,
            postgres_db=postgres_db,
        )
        if creds is None:
            research.pop(capability, None)
            continue
        ops_value = creds.params.get("ops")
        ops = (
            [str(op) for op in ops_value if isinstance(op, str)]
            if isinstance(ops_value, list)
            else []
        )
        if not creds.provider or not ops:
            research.pop(capability, None)
            logger.warning(
                "Dispatch: %s model %r has no valid params_json.provider/ops; "
                "web tools for that capability are disabled",
                capability,
                creds.model,
            )
            continue

        resolved[capability] = creds
        research[capability] = {
            "provider": creds.provider,
            "base_url": creds.base_url,
            "api_key": creds.api_key,
            "ops": ops,
        }
        logger.info(
            "Dispatch: injected %s provider %s (%s)",
            capability,
            creds.provider,
            creds.model,
        )

    primary = resolved.get("search")
    fallback = await resolve_capability_credentials(
        capability="search",
        setting_key="default_search_fallback_model",
        user_settings=user_settings,
        user_id=user_id,
        resolved_keys=resolved_keys,
        postgres_db=postgres_db,
    )
    fallback_ops_value = fallback.params.get("ops") if fallback is not None else None
    fallback_ops = (
        [str(op) for op in fallback_ops_value if isinstance(op, str)]
        if isinstance(fallback_ops_value, list)
        else []
    )
    different_row = bool(
        primary is not None
        and fallback is not None
        and primary.catalog_id
        and fallback.catalog_id
        and primary.catalog_id != fallback.catalog_id
    )
    if (
        primary is None
        or fallback is None
        or not different_row
        or not fallback.provider
        or "search" not in fallback_ops
    ):
        research.pop("search_fallback", None)
    else:
        research["search_fallback"] = {
            "provider": fallback.provider,
            "base_url": fallback.base_url,
            "api_key": fallback.api_key,
            "ops": fallback_ops,
        }
        logger.info(
            "Dispatch: injected search fallback provider %s (%s)",
            fallback.provider,
            fallback.model,
        )

    if not research:
        config_override.pop("research", None)
    return config_override


async def _inject_system_kb_embedding_profile(env_keys: dict[str, Any]) -> str | None:
    """Inject the stable, system-owned embedding profile for knowledge bases.

    The OKF datasource indexer runs in the orchestrator and therefore embeds
    every repository with the admin-curated *system* embedding model. Agent
    memory may instead use a user's embedding preference. Shipping the system
    profile under a separate prefix lets KnowledgeStore query with the exact
    model/transport used by the indexer without changing RecallStore semantics.

    ``KB_EMBEDDING_*`` is intentionally authoritative: callers cannot pin a
    different profile in ``config_override``, and persisted non-secret values
    are refreshed after an administrator changes the system default.
    """
    prefix = "KB_EMBEDDING_"
    for key in [key for key in env_keys if key.startswith(prefix)]:
        del env_keys[key]

    model_id = await postgres_db.resolve_default_for_capability("embedding")
    if not model_id:
        # Dev/compose compatibility: the central indexer historically used the
        # orchestrator's EMBEDDING_* environment when no catalog pin existed.
        # Materialize that *effective* profile into KB_* too; otherwise the
        # indexer would use this env model while an agent fell back to its
        # per-user model and filtered every indexed chunk out.
        from src.services.embedding_service import EmbeddingService

        fallback = EmbeddingService()
        if not fallback.api_key:
            return None
        env_keys.update(
            {
                "KB_EMBEDDING_PROVIDER": fallback.provider,
                "KB_EMBEDDING_MODEL": fallback.model,
                "KB_EMBEDDING_BASE_URL": fallback.base_url,
                "KB_EMBEDDING_API_KEY": fallback.api_key,
                "KB_EMBEDDING_DIMENSIONS": str(fallback.expected_dimensions),
            }
        )
        return fallback.model

    # Built-in/catalog transports use system_api_keys. Do not reuse the job's
    # already-resolved key map here: it includes project/user overrides and
    # would recreate the same per-user profile skew this path prevents.
    system_keys = await postgres_db.resolve_api_keys_for_job(
        user_id=None,
        project_id=None,
    )
    await _inject_env_key_credentials(
        env_keys=env_keys,
        prefix="KB_EMBEDDING",
        model_id=model_id,
        user_id=None,
        resolved_keys=system_keys,
        capability="embedding",
    )

    try:
        meta = await _resolve_model(model_id, user_id=None, capability="embedding")
    except UnknownModelError:
        meta = None
    env_keys["KB_EMBEDDING_PROVIDER"] = (
        meta.provider if meta is not None and meta.provider else "local"
    )
    if meta is not None:
        # Non-secret registry identity travels with the transport so central
        # indexing and agent-side query filtering derive the same vector stamp.
        # Prefer the concrete endpoint UUID; provider-key catalog rows fall
        # back to their registry/key-reference identity (never the key value).
        profile_anchor = meta.endpoint_id or meta.api_key_ref or meta.model_id
        env_keys["KB_EMBEDDING_PROFILE_ID"] = f"{meta.origin}:{profile_anchor}"
    env_keys["KB_EMBEDDING_DIMENSIONS"] = str(
        os.environ.get("KB_EMBEDDING_DIMENSIONS")
        or os.environ.get("EMBEDDING_DIMENSIONS")
        or "4096"
    )
    return model_id


async def _inject_thread_dispatch_credentials(
    config_override: dict[str, Any],
    *,
    user_id: str | None,
    project_id: str | None = None,
    user_settings: dict[str, Any] | None = None,
    include_kb_profile: bool = False,
) -> dict[str, Any]:
    """Resolve + inject LLM / auxiliary / embedding credentials into a thread's
    ``config_override`` IN PLACE (creating sections as needed). Returns the dict.

    The persistent-session sibling of the worker-job ``_inject_dispatch_credentials``.
    Secrets travel **in-flight only** — at thread create, and re-injected at session
    attach/resume (the agent workspace endpoint + the resume dispatcher) — and are
    stripped via ``redact_config_override`` before persistence, so
    ``threads.metadata.config_override`` never stores plaintext keys.

    Re-injection-safe: endpoint-backed model transports are refreshed from the
    endpoint row, while provider-key models keep caller-supplied transports.
    ``_inject_env_key_credentials`` is ``setdefault``-based, so running this on a
    stripped copy repopulates the removed secrets without clobbering surviving
    model choices.
    """
    user_settings = user_settings or {}

    # Drop None-valued keys in the model sections before injecting. A prior
    # hot-swap persists explicit ``provider/base_url/api_key = None`` sentinels
    # (they make the live agent's deep_merge CLEAR the previous model's
    # transport); in a stored copy those Nones would block the setdefault-based
    # injection below. Treat them as absent so the transport is repopulated.
    for _sect_name in ("llm", "auxiliary"):
        _sect = config_override.get(_sect_name)
        if isinstance(_sect, dict):
            for _k in [_k for _k, _v in _sect.items() if _v is None]:
                del _sect[_k]

    resolved_keys = await postgres_db.resolve_api_keys_for_job(
        user_id=user_id,
        project_id=project_id,
    )

    # Chat model. Fall back to the system default chat pin so the agent never
    # boots on its YAML default (which has no transport → api.openai.com 401).
    llm_section = config_override.get("llm") or {}
    if not llm_section.get("model"):
        system_chat_model = await postgres_db.resolve_default_for_capability("chat")
        if system_chat_model:
            llm_section["model"] = system_chat_model
            logger.info(
                "Thread dispatch: injected system default chat model: %s",
                system_chat_model,
            )
    if llm_section.get("model"):
        await _inject_model_credentials(
            section=llm_section,
            model_id=llm_section["model"],
            user_id=user_id,
            resolved_keys=resolved_keys,
        )
        config_override["llm"] = llm_section

    # Auxiliary slot (title generation, memory extraction, knowledge curation).
    aux_section = config_override.get("auxiliary") or {}
    if not aux_section.get("model"):
        aux_model = user_settings.get("default_auxiliary_model")
        if not aux_model:
            aux_model = await postgres_db.resolve_default_for_capability("auxiliary")
        if aux_model:
            aux_section["model"] = aux_model
            logger.info("Thread dispatch: injected auxiliary model: %s", aux_model)
    if aux_section.get("model"):
        await _inject_model_credentials(
            section=aux_section,
            model_id=aux_section["model"],
            user_id=user_id,
            resolved_keys=resolved_keys,
            capability="auxiliary",
        )
        config_override["auxiliary"] = aux_section

    # Nested model slots (U1): `llm.summarization`, the roster-wide
    # `subagents.llm` and every roster entry's `llm` — the same slots and the
    # same helper as the job injector, so a session's roster children reach
    # their endpoints too. None sentinels are stripped per slot for the same
    # reason as the top-level sections above; an inheriting entry carries its
    # parent's model NAME and is routed by it, the bare `inherit` sentinel is
    # not a model.
    for _label, _section, _capability in _nested_model_slots(config_override):
        for _k in [_k for _k, _v in _section.items() if _v is None]:
            del _section[_k]
        _model = _section.get("model")
        if not _model or _model == INHERIT_MODEL:
            continue
        await _inject_model_credentials(
            section=_section,
            model_id=_model,
            user_id=user_id,
            resolved_keys=resolved_keys,
            capability=_capability,
        )
        logger.info("Thread dispatch: injected credentials for %s: %s", _label, _model)

    # Embedding capability travels as flat env vars. Source provider/model from
    # the (possibly stripped) persisted block first so re-injection on resume is
    # stable, then user settings, then the system default. Unconditionally call
    # the env-key injector when a model is known: it is setdefault-based, so it
    # re-adds the stripped EMBEDDING_API_KEY without clobbering surviving
    # EMBEDDING_MODEL / EMBEDDING_BASE_URL.
    env_keys_block = config_override.setdefault("env_keys", {})
    embedding_provider = env_keys_block.get("EMBEDDING_PROVIDER") or user_settings.get(
        "embedding_provider"
    )
    embedding_model = env_keys_block.get("EMBEDDING_MODEL") or user_settings.get(
        "default_embedding_model"
    )
    if not embedding_model:
        embedding_model = await postgres_db.resolve_default_for_capability("embedding")
    if embedding_provider:
        env_keys_block.setdefault("EMBEDDING_PROVIDER", embedding_provider)
    if embedding_model:
        await _inject_env_key_credentials(
            env_keys=env_keys_block,
            prefix="EMBEDDING",
            model_id=embedding_model,
            user_id=user_id,
            resolved_keys=resolved_keys,
            capability="embedding",
        )
    if (
        embedding_provider == "openrouter"
        and resolved_keys
        and "openrouter" in resolved_keys
    ):
        env_keys_block.setdefault("OPENROUTER_API_KEY", resolved_keys["openrouter"])
    if include_kb_profile:
        await _inject_system_kb_embedding_profile(env_keys_block)
    else:
        for key in [key for key in env_keys_block if key.startswith("KB_EMBEDDING_")]:
            del env_keys_block[key]
    if not env_keys_block:
        config_override.pop("env_keys", None)

    await _inject_search_credentials(
        config_override,
        user_settings=user_settings,
        user_id=user_id,
        resolved_keys=resolved_keys,
    )

    return config_override


def _dispatch_llm_provider_fallback(
    job: dict, config_override: dict | None
) -> str | None:
    """Legacy dispatcher provider detection, used only when the model ID
    can't be resolved through the registry.

    Mirrors the pre-registry behavior: explicit ``llm.provider`` wins,
    then the known built-in model catalog, then a config-name heuristic
    (only ``anthropic`` today), finally ``openai``.
    """
    if config_override:
        llm = config_override.get("llm", {})
        if llm.get("provider"):
            return llm["provider"].lower()
        model = llm.get("model")
        if model:
            prov = _provider_of_model(model)
            if prov is not None:
                return prov

    config_name = canonical_config_name(job.get("config_name") or "worker_base")
    if config_name and "anthropic" in config_name.lower():
        return "anthropic"
    return "openai"


async def _try_dispatch_pending_jobs() -> None:
    """Core dispatcher: match pending jobs to available agents.

    Phase 1: Direct assignment (free agents → highest priority pending jobs)
    Phase 2: Preemption (remaining high-priority jobs → lowest-priority running jobs)

    VM-aware: jobs needing a VM are auto-provisioned and held until the VM
    registers as ready. Jobs with a ready VM get workspace config injected
    into config_override before dispatch.
    """
    if not AUTO_ASSIGN_ENABLED and not STATELESS_WORKER_ENABLED:
        return

    async with _dispatch_lock:
        try:
            # Both lanes retain the same leader-owned workspace preflight. The
            # pinned set proceeds to registered-agent matching; a ready
            # stateless set is admitted to run_queue and never reaches that
            # half of this function.
            pending_jobs = (
                await postgres_db.get_dispatchable_jobs(
                    limit=50,
                    **_completion_dispatch_guard_kwargs(),
                )
                if AUTO_ASSIGN_ENABLED
                else []
            )
            if STATELESS_WORKER_ENABLED:
                pending_jobs.extend(
                    await postgres_db.get_admittable_stateless_jobs(
                        limit=50,
                        **_completion_dispatch_guard_kwargs(),
                    )
                )
            if not pending_jobs:
                return

            # Pre-filter: auto-provision VMs/containers for jobs that need one
            dispatchable_jobs = []
            for job in pending_jobs:
                job_id = str(job["id"])
                stateless_worker = job.get("execution_lane") == "stateless"
                (
                    workspace_action,
                    job,
                    workspace_recovery_reason,
                ) = await _prepare_job_workspace_runtime(job)
                if workspace_action == "wait":
                    logger.warning(
                        "Dispatcher: job %s waiting for live workspace authority "
                        "recovery (%s)",
                        job_id,
                        workspace_recovery_reason or "retryable",
                    )
                    continue
                if workspace_action == "fail":
                    await _fail_subjob_and_unblock_parent(
                        job,
                        workspace_recovery_reason
                        or "Inherited workspace authority is unavailable.",
                    )
                    continue
                workspace_decision = resolve_workspace_runtime(
                    job, vm_mode=vm_provisioner.mode
                )
                if (
                    workspace_decision.contract is None
                    or workspace_decision.state == "invalid"
                ):
                    logger.error(
                        "Dispatcher: refusing job %s with invalid workspace "
                        "authority (%s)",
                        job_id,
                        workspace_decision.reason or workspace_decision.state,
                    )
                    await postgres_db.update_job_status(
                        job_id,
                        status="failed",
                        error_message=(
                            "Workspace contract is ambiguous or invalid; "
                            "refusing dispatch"
                        ),
                        expected_status=str(job.get("status")),
                    )
                    continue

                job_needs_vm = _job_needs_vm(job)
                stateless_same_cluster_vm = bool(
                    stateless_worker and job_needs_vm and vm_workspaces_on_pod_network()
                )

                # Defense for inherited/operator-created rows. External VMs
                # still belong to the mesh-enabled registered-agent plane; a
                # same-cluster VM remains on the pool lane below.
                if (
                    stateless_worker
                    and job_needs_vm
                    and not vm_workspaces_on_pod_network()
                ):
                    moved_to_pinned = False
                    async with postgres_db.acquire() as conn:
                        async with conn.transaction():
                            await conn.fetchrow(
                                "SELECT state FROM run_queue "
                                "WHERE unit_id = $1::uuid "
                                "AND unit_kind = 'worker_batch' FOR UPDATE",
                                job_id,
                            )
                            moved = await conn.fetchrow(
                                "UPDATE jobs SET execution_lane = 'pinned', "
                                "updated_at = CURRENT_TIMESTAMP "
                                "WHERE id = $1::uuid "
                                "AND execution_lane = 'stateless' "
                                "AND status::text = $2::text "
                                "RETURNING id",
                                job_id,
                                str(job.get("status") or ""),
                            )
                            if moved is not None:
                                moved_to_pinned = True
                                await conn.execute(
                                    "UPDATE run_queue SET state = 'done', "
                                    "lease_token = lease_token + 1, "
                                    "leased_by = NULL, last_leased_by = NULL, "
                                    "leased_until = NULL, run_after = now(), "
                                    "queued_at = now() "
                                    "WHERE unit_id = $1::uuid "
                                    "AND unit_kind = 'worker_batch'",
                                    job_id,
                                )
                    if moved_to_pinned:
                        logger.info(
                            "Dispatcher: moved VM job %s from stateless to pinned lane",
                            job_id,
                        )
                    else:
                        logger.debug(
                            "Dispatcher: VM lane repair lost the status CAS for job %s",
                            job_id,
                        )
                    continue
                _stateless_container = _get_container_context(job)
                _stateless_has_k8s_workspace = (
                    _stateless_container.get("status") == "ready"
                    and _stateless_container.get("provisioner") == "k8s"
                    and bool(
                        _stateless_container.get("host")
                        or _stateless_container.get("pod_ip")
                    )
                )
                if stateless_worker and not (
                    stateless_same_cluster_vm
                    or _job_needs_sandbox(job)
                    or _stateless_has_k8s_workspace
                ):
                    logger.error(
                        "Dispatcher: refusing stateless job %s without a compatible "
                        "workspace",
                        job_id,
                    )
                    await postgres_db.update_job_status(
                        job_id,
                        status="failed",
                        error_message=(
                            "Stateless workers currently require a Kubernetes "
                            "sandbox or same-cluster VM workspace"
                        ),
                        expected_status=str(job.get("status")),
                    )
                    continue
                if (
                    stateless_worker
                    and not stateless_same_cluster_vm
                    and not (
                        container_provisioner.is_available
                        and container_provisioner.in_cluster
                    )
                ):
                    logger.warning(
                        "Dispatcher: stateless job %s waiting for the in-cluster "
                        "Kubernetes workspace provisioner",
                        job_id,
                    )
                    continue

                if job_needs_vm:
                    # Admin-gated permission check (kill-switch + per-user grant).
                    # Re-verified here in case a grant was revoked or the
                    # kill-switch flipped after the job was submitted. Already
                    # running VMs aren't torn down by this check — the gate
                    # only blocks jobs that haven't been dispatched yet.
                    creator = None
                    creator_id = job.get("user_id")
                    if creator_id:
                        try:
                            creator = await postgres_db.get_user(str(creator_id))
                        except Exception:
                            creator = None
                    try:
                        await _check_vm_permission(creator, job_needs_vm=True)
                    except HTTPException as permission_error:
                        logger.error(
                            "Dispatcher: job %s denied VM workspace: %s",
                            job_id,
                            permission_error.detail,
                        )
                        await postgres_db.update_job_status(
                            job_id,
                            status="failed",
                            error_message=str(permission_error.detail),
                        )
                        continue
                    vm_ctx = _get_vm_context(job)
                    vm_status = vm_ctx.get("status")
                    # Bounded provisioning retries. A VM that never reaches 'ready'
                    # (real infra failure) must park after N attempts instead of
                    # re-provisioning forever against the shared VM cluster. The
                    # counter is monotonic in context.vm and reset to 0 once the VM
                    # boots (VM_READY below), so it survives the async controller
                    # status callbacks that a status-based park cannot. Decision
                    # logic is extracted + unit-tested in dispatch_guards.
                    provision_attempts = int(vm_ctx.get("provision_attempts") or 0)
                    max_provision_attempts = int(
                        os.environ.get("VM_PROVISION_MAX_ATTEMPTS", "3")
                    )
                    timeout_s = int(os.environ.get("VM_PROVISION_TIMEOUT_S", "600"))
                    golden_timeout_s = int(
                        os.environ.get("VM_GOLDEN_WAIT_TIMEOUT_S", "2700")
                    )
                    capacity_timeout_s = int(
                        os.environ.get("VM_CAPACITY_WAIT_TIMEOUT_S", "2700")
                    )
                    headscale_timeout_s = int(
                        os.environ.get("VM_HEADSCALE_WAIT_TIMEOUT_S", "900")
                    )
                    vm_decision = vm_provisioning_decision(
                        vm_ctx,
                        provision_attempts=provision_attempts,
                        max_provision_attempts=max_provision_attempts,
                        now=time.time(),
                        timeout_s=timeout_s,
                        golden_timeout_s=golden_timeout_s,
                        capacity_timeout_s=capacity_timeout_s,
                        headscale_timeout_s=headscale_timeout_s,
                    )
                    if vm_decision == VM_PARK_EXHAUSTED:
                        # Retries used up — park the VM context AND fail the job.
                        # 'failed' is terminal for the dispatcher (VM_PARKED) and
                        # skipped by the reconciler (_PARKED_VM_STATUSES), so the
                        # park holds. The job itself must go terminal too: leaving
                        # it 'created' with nothing scheduled to change its state
                        # is an invisible wedge (a loop's current_job never turns
                        # terminal → the loop stalls forever). See knowledge-base/knowledge/issues/
                        # vm_ssh_readiness_probe_unroutable_from_orchestrator.md.
                        park_error = (
                            f"provisioning exhausted after "
                            f"{provision_attempts} attempts "
                            f"(never reached 'ready')"
                        )
                        logger.warning(
                            "Dispatcher: job %s VM provisioning exhausted "
                            "(%d/%d attempts) — failing job",
                            job_id,
                            provision_attempts,
                            max_provision_attempts,
                        )
                        await postgres_db.merge_vm_context(
                            job_id,
                            {"status": "failed", "error": park_error},
                        )
                        await _fail_vm_parked_job(job_id, park_error)
                        continue
                    if vm_decision == VM_PROVISION:
                        # VM needed but absent — never provisioned, torn down while
                        # parked ('deleted': deploy-drain / crash recovery release
                        # it; work survives in the pushed branch + checkpoint), or
                        # recycled by the timeout. Without re-provisioning here a
                        # paused VM job waits forever on a VM nothing will create.
                        if not vm_provisioner.is_available:
                            # VM explicitly requested but no provisioner — fail
                            logger.error(
                                "Dispatcher: job %s requires VM workspace but VM "
                                "provisioner is unavailable for VM_MODE=%s. "
                                "Failing job.",
                                job_id,
                                vm_provisioner.mode,
                            )
                            await postgres_db.update_job_status(
                                job_id,
                                status="failed",
                                error_message=(
                                    "VM workspace requested but VM provisioner is not "
                                    f"available for VM_MODE={vm_provisioner.mode!r}. "
                                    "Configure VM_MODE and its required controller, use "
                                    "workspace.backend='container', or "
                                    "remove the explicit backend override."
                                ),
                            )
                            continue
                        config_override = job.get("config_override") or {}
                        if isinstance(config_override, str):
                            config_override = json.loads(config_override)
                        vm_cfg = config_override.get("workspace", {}).get("vm", {})
                        ok = await vm_provisioner.create_vm(
                            job_id=job_id,
                            agent_config=canonical_config_name(
                                job.get("config_name", "worker_base")
                            ),
                            vm_image=vm_cfg.get("image"),
                            cpu_cores=vm_cfg.get("cpu_cores", 8),
                            memory=vm_cfg.get("memory", "16Gi"),
                            disk_size=vm_cfg.get("disk_size"),
                            description=job.get("description", ""),
                        )
                        if ok:
                            # Count the attempt so a VM that never boots parks
                            # after max_provision_attempts. create_vm stamped a
                            # fresh provisioned_at; the timeout recycles this
                            # attempt if it stalls.
                            await postgres_db.merge_vm_context(
                                job_id,
                                {"provision_attempts": provision_attempts + 1},
                            )
                            logger.info(
                                "Dispatcher: auto-provisioned VM for job %s "
                                "(attempt %d/%d)",
                                job_id,
                                provision_attempts + 1,
                                max_provision_attempts,
                            )
                        else:
                            logger.warning(
                                "Dispatcher: VM provisioning failed for job %s",
                                job_id,
                            )
                        continue  # Skip this job — wait for VM to register
                    if vm_decision == VM_PARKED:
                        # Provisioning failed terminally — do NOT hot-retry every
                        # tick (shared VM cluster). The job is still non-terminal
                        # (it's in the dispatchable list), which means something
                        # left it parked-but-alive: an older build's park, or a
                        # controller-callback race with PARK_EXHAUSTED. Heal it
                        # to 'failed' so it stops wedging its loop.
                        vm_error = vm_ctx.get("error") or "VM provisioning failed"
                        logger.warning(
                            "Dispatcher: job %s VM parked (%s) — failing job",
                            job_id,
                            vm_error,
                        )
                        await _fail_vm_parked_job(job_id, vm_error)
                        continue
                    if vm_decision in (VM_GOLDEN_POLL, VM_CAPACITY_POLL):
                        # No VM exists yet — the controller is waiting on a
                        # shared golden-image import (cold import after an
                        # agent-vm-base bump: ~30 min, longer than timeout_s).
                        # Re-issue create as the poll: the controller answers
                        # waiting_golden (cheap DV GET) until the golden is
                        # Succeeded, then actually builds the VM. fresh=False
                        # keeps the golden budget anchor + counters and does
                        # NOT consume a provision attempt — the attempt budget
                        # bounds VM boots, and no boot is happening. See
                        # knowledge-history/done/
                        # golden_image_cold_import_fails_inflight_vm_jobs.md.
                        wait_anchor = (
                            "capacity_wait_started_at"
                            if vm_decision == VM_CAPACITY_POLL
                            else "golden_wait_started_at"
                        )
                        if not vm_ctx.get(wait_anchor):
                            await postgres_db.merge_vm_context(
                                job_id,
                                {wait_anchor: time.time()},
                            )
                        config_override = job.get("config_override") or {}
                        if isinstance(config_override, str):
                            config_override = json.loads(config_override)
                        vm_cfg = config_override.get("workspace", {}).get("vm", {})
                        await vm_provisioner.create_vm(
                            job_id=job_id,
                            agent_config=canonical_config_name(
                                job.get("config_name", "worker_base")
                            ),
                            vm_image=vm_cfg.get("image"),
                            cpu_cores=vm_cfg.get("cpu_cores", 8),
                            memory=vm_cfg.get("memory", "16Gi"),
                            disk_size=vm_cfg.get("disk_size"),
                            description=job.get("description", ""),
                            fresh=False,
                        )
                        if vm_decision == VM_CAPACITY_POLL:
                            logger.info(
                                "Dispatcher: job %s waiting on VM capacity (%s/%s) "
                                "— polling",
                                job_id,
                                vm_ctx.get("running_vms") or "?",
                                vm_ctx.get("max_concurrent_vms") or "?",
                            )
                        else:
                            logger.info(
                                "Dispatcher: job %s waiting on golden image %s "
                                "(%s) — polling",
                                job_id,
                                vm_ctx.get("golden") or "?",
                                vm_ctx.get("golden_progress")
                                or vm_ctx.get("golden_phase")
                                or "importing",
                            )
                        continue
                    if vm_decision == VM_PARK_CAPACITY:
                        elapsed = int(
                            time.time()
                            - float(vm_ctx.get("capacity_wait_started_at") or 0)
                        )
                        park_error = (
                            "VM capacity did not become available within "
                            f"{capacity_timeout_s}s (running "
                            f"{vm_ctx.get('running_vms') or 'unknown'}/"
                            f"{vm_ctx.get('max_concurrent_vms') or 'unknown'}, "
                            f"waited {elapsed}s) — VM never created"
                        )
                        await postgres_db.merge_vm_context(
                            job_id, {"status": "failed", "error": park_error}
                        )
                        await _fail_vm_parked_job(job_id, park_error)
                        continue
                    if vm_decision == VM_PARK_GOLDEN:
                        # The golden import outlived even the golden budget —
                        # CDI is wedged or the registry is unreachable. No VM
                        # was ever created, so there is nothing to recycle;
                        # fail the job with the truth (not the misleading
                        # "provisioning exhausted after N attempts").
                        elapsed = int(
                            time.time()
                            - float(vm_ctx.get("golden_wait_started_at") or 0)
                        )
                        park_error = (
                            f"golden image import did not complete within "
                            f"{golden_timeout_s}s (golden "
                            f"{vm_ctx.get('golden') or 'unknown'}, last progress "
                            f"{vm_ctx.get('golden_progress') or 'unknown'}, "
                            f"waited {elapsed}s) — VM never created"
                        )
                        logger.warning(
                            "Dispatcher: job %s golden wait exhausted — "
                            "failing job (%s)",
                            job_id,
                            park_error,
                        )
                        await postgres_db.merge_vm_context(
                            job_id,
                            {"status": "failed", "error": park_error},
                        )
                        await _fail_vm_parked_job(job_id, park_error)
                        continue
                    if vm_decision == VM_HEADSCALE_POLL:
                        # No VM exists yet — the controller refused to build one
                        # while Headscale is unreachable, because a VM with no
                        # tailnet pre-auth key boots and heartbeats but is never
                        # reachable over SSH. Poll create (fresh=False, no
                        # attempt consumed) until the mesh recovers; the
                        # controller then builds the VM on the very next poll.
                        if not vm_ctx.get("headscale_wait_started_at"):
                            await postgres_db.merge_vm_context(
                                job_id,
                                {"headscale_wait_started_at": time.time()},
                            )
                        config_override = job.get("config_override") or {}
                        if isinstance(config_override, str):
                            config_override = json.loads(config_override)
                        vm_cfg = config_override.get("workspace", {}).get("vm", {})
                        await vm_provisioner.create_vm(
                            job_id=job_id,
                            agent_config=canonical_config_name(
                                job.get("config_name", "worker_base")
                            ),
                            vm_image=vm_cfg.get("image"),
                            cpu_cores=vm_cfg.get("cpu_cores", 8),
                            memory=vm_cfg.get("memory", "16Gi"),
                            disk_size=vm_cfg.get("disk_size"),
                            description=job.get("description", ""),
                            fresh=False,
                        )
                        logger.info(
                            "Dispatcher: job %s waiting on Headscale (%s) — polling",
                            job_id,
                            vm_ctx.get("headscale_error") or "mesh VPN unavailable",
                        )
                        continue
                    if vm_decision == VM_PARK_HEADSCALE:
                        # Headscale never came back inside its budget. No VM was
                        # ever created, so there is nothing to recycle — fail
                        # with the real cause rather than the misleading
                        # "provisioning exhausted after N attempts".
                        elapsed = int(
                            time.time()
                            - float(vm_ctx.get("headscale_wait_started_at") or 0)
                        )
                        park_error = (
                            f"Headscale (mesh VPN) unavailable for {elapsed}s "
                            f"(budget {headscale_timeout_s}s, last error: "
                            f"{vm_ctx.get('headscale_error') or 'unknown'}) — "
                            f"VM never created"
                        )
                        logger.warning(
                            "Dispatcher: job %s Headscale wait exhausted — "
                            "failing job (%s)",
                            job_id,
                            park_error,
                        )
                        await postgres_db.merge_vm_context(
                            job_id,
                            {"status": "failed", "error": park_error},
                        )
                        await _fail_vm_parked_job(job_id, park_error)
                        continue
                    if vm_decision == VM_RECYCLE:
                        # Stuck short of 'ready' past the budget — tear it down so
                        # the next tick re-provisions (VM_PROVISION) or parks
                        # (VM_PARK_EXHAUSTED). With the reconciler now handing off
                        # provisioning VMs (is_reapable=False for dispatchable jobs)
                        # nothing else would time it out.
                        elapsed = int(time.time() - float(vm_ctx["provisioned_at"]))
                        logger.warning(
                            "Dispatcher: job %s VM stuck in '%s' for %ss "
                            "(> %ss budget) — recycling (attempt %d/%d)",
                            job_id,
                            vm_status,
                            elapsed,
                            timeout_s,
                            provision_attempts,
                            max_provision_attempts,
                        )
                        try:
                            await vm_provisioner.delete_vm(job_id)
                        except Exception:
                            logger.exception(
                                "Dispatcher: failed to delete timed-out VM for job %s",
                                job_id,
                            )
                        continue
                    if vm_decision == VM_WAIT:
                        # Provisioning / creating / deleting in flight — wait.
                        continue
                    # VM_READY: proceed with dispatch.
                    if provision_attempts:
                        # VM booted — clear the retry budget so a later
                        # re-provision (crash recovery) starts fresh.
                        await postgres_db.merge_vm_context(
                            job_id, {"provision_attempts": 0}
                        )
                    logger.info("Dispatcher: job %s using VM workspace", job_id)
                elif _job_needs_sandbox(job):
                    # Phase 1: a pre-agent scholar spawned before its parent had a
                    # workspace provisions the parent's ONE shared pod under the
                    # parent's identity and rides it, instead of self-provisioning
                    # a throwaway pod. k8s only — VM/docker parents fall through to
                    # the normal self-provision path below.
                    provision_parent_id = _scholar_provision_parent_id(job)
                    if (
                        provision_parent_id
                        and container_provisioner.is_available
                        and container_provisioner.in_cluster
                    ):
                        await _provision_parent_workspace_for_scholar(
                            job, provision_parent_id
                        )
                        # wait → retry next tick; promoted → dispatches next tick
                        # via the inherit path; fail → already failed + unblocked.
                        continue
                    container_ctx = _get_container_context(job)
                    container_status = container_ctx.get("status")
                    # K8s in-cluster takes priority; a local kubeconfig must not
                    # shadow Docker Compose when running outside the cluster.
                    use_k8s = container_provisioner.is_available and (
                        container_provisioner.in_cluster
                        or not docker_provisioner.is_available
                    )
                    # States that mean "no live workspace yet" → (re)create.
                    needs_create = container_status in (None, "", "deleted", "none")
                    if needs_create and not use_k8s:
                        # Docker Compose pool / no-provisioner CREATE path (unchanged).
                        if docker_provisioner.is_available:
                            logger.info(
                                "Dispatcher: job %s assigning workspace from "
                                "Docker Compose pool",
                                job_id,
                            )
                            result = await docker_provisioner.assign_workspace(job_id)
                            if not result:
                                logger.warning(
                                    "Dispatcher: no free workspace for job %s "
                                    "— all containers occupied, will retry",
                                    job_id,
                                )
                        else:
                            logger.error(
                                "Dispatcher: job %s needs workspace but no "
                                "provisioner available. Failing job.",
                                job_id,
                            )
                            await postgres_db.update_job_status(
                                job_id,
                                status="failed",
                                error_message=(
                                    "No workspace provisioner available. "
                                    "Neither Kubernetes API nor WORKSPACE_HOSTS "
                                    "configured."
                                ),
                            )
                        continue  # Skip — wait for container to become ready
                    # K8s create (when status absent) + all lifecycle states route
                    # through the shared, owner-agnostic state machine.
                    config_override = job.get("config_override") or {}
                    if isinstance(config_override, str):
                        config_override = json.loads(config_override)
                    ws_cfg = config_override.get("workspace", {}).get("container", {})
                    res = await ensure_workspace(
                        WorkspaceOwner.job(job_id),
                        provisioner=container_provisioner,
                        suspension=workspace_suspension_service,
                        current_status=container_status,
                        ws_config={
                            k: ws_cfg[k]
                            for k in (
                                "cpu",
                                "memory",
                                "cpu_limit",
                                "memory_limit",
                                "image",
                            )
                            if k in ws_cfg
                        },
                    )
                    if res.outcome is EnsureOutcome.FAILED:
                        failed_ctx = container_ctx
                        if container_status != "failed":
                            # create_workspace records the concrete failure in
                            # context before returning False. Refresh once so a
                            # first-attempt auth/RBAC/image failure reaches the
                            # job error instead of being replaced by the generic
                            # "could not be created" wrapper.
                            try:
                                refreshed_job = await postgres_db.get_job(job_id)
                                if refreshed_job:
                                    failed_ctx = _get_container_context(refreshed_job)
                            except Exception:
                                logger.warning(
                                    "Dispatcher: could not refresh failed workspace "
                                    "context for job %s",
                                    job_id,
                                    exc_info=True,
                                )
                        error = failed_ctx.get("error")
                        if error:
                            msg = f"Workspace container failed: {error}"
                        else:
                            msg = (
                                "Workspace container could not be created. Check "
                                "orchestrator logs for details (image pull failures, "
                                "insufficient resources, RBAC issues)."
                            )
                        logger.error(
                            "Dispatcher: workspace ensure failed for job %s: %s. "
                            "Failing job.",
                            job_id,
                            msg,
                        )
                        await postgres_db.update_job_status(
                            job_id,
                            status="failed",
                            error_message=msg,
                            expected_status=(
                                str(job.get("status")) if stateless_worker else None
                            ),
                        )
                        continue
                    if res.outcome is EnsureOutcome.PENDING:
                        if container_status not in (
                            None,
                            "",
                            "deleted",
                            "none",
                            "created",
                            "creating",
                            "restoring",
                            "suspending",
                            "pending",
                        ):
                            logger.warning(
                                "Dispatcher: job %s has unexpected workspace "
                                "container status %r — waiting",
                                job_id,
                                container_status,
                            )
                        continue  # in progress — wait for next cycle
                    # READY → proceed with dispatch
                    logger.info("Dispatcher: job %s using workspace container", job_id)
                else:
                    # No VM or container provisioning needed — check if a workspace
                    # was already assigned (e.g. Docker provisioner assigned it on a
                    # previous cycle and the job is now ready for dispatch).
                    existing_ctx = _get_container_context(job)
                    if existing_ctx.get("status") == "ready":
                        logger.info(
                            "Dispatcher: job %s using pre-assigned workspace",
                            job_id,
                        )
                    else:
                        logger.debug(
                            "Dispatcher: job %s — no workspace provisioner needed",
                            job_id,
                        )
                if not await _prepare_job_repository_before_claim(job):
                    # Retry on the next dispatcher tick. A Gitea/SSH outage is
                    # not a worker failure and must not make the job cross the
                    # processing boundary with unproven repository authority.
                    continue
                if stateless_worker:
                    (
                        admitted,
                        queue_result,
                    ) = await postgres_db.admit_stateless_worker_job(
                        job_id,
                        fair_key=(str(job["user_id"]) if job.get("user_id") else None),
                        priority=int(job.get("priority") or 0),
                        allow_vm_workspace=vm_workspaces_on_pod_network(),
                        **_completion_dispatch_guard_kwargs(),
                    )
                    if not admitted:
                        logger.warning(
                            "Dispatcher: stateless admission CAS lost for job %s; "
                            "workspace/lane/status changed after preflight",
                            job_id,
                        )
                        continue
                    logger.info(
                        "Dispatcher: admitted stateless worker job %s "
                        "(queue=%s, workspace=k8s-ready)",
                        job_id,
                        queue_result,
                    )
                    continue
                dispatchable_jobs.append(job)

            if not dispatchable_jobs:
                return

            # Get available agents (ready, cooldown passed), skip stale images
            all_agents = await postgres_db.get_available_agents(limit=50)
            available_agents = []
            for ag in all_agents:
                meta = ag.get("metadata") or {}
                if isinstance(meta, str):
                    try:
                        meta = json.loads(meta)
                    except (json.JSONDecodeError, ValueError):
                        meta = {}
                if _agent_sha_is_current(meta):
                    available_agents.append(ag)
                else:
                    # Stale-SHA agents are skipped here; the lifecycle
                    # reconciler is responsible for draining them.
                    logger.debug(
                        "Skipping stale worker agent %s (build_sha=%s)",
                        ag["id"],
                        meta.get("build_sha", ""),
                    )

            # Phase 1: Direct assignment
            matched_job_ids = set()
            matched_agent_ids = set()

            agents_iter = iter(available_agents)
            for job in dispatchable_jobs:
                agent = next(agents_iter, None)
                if agent is None:
                    break  # No more free agents

                job_id = str(job["id"])
                # Atomically claim the job for this agent BEFORE notifying the
                # pod. Closes the dual-leader double-assign that leader election
                # cannot fence (M1): two transient leaders may both scan the same
                # candidate, but only one CAS wins — the loser skips. The claim
                # sets status='processing'+assigned_agent_id; a failed
                # dispatch/resume below self-heals via recover_orphaned_jobs.
                if not await postgres_db.claim_job_for_agent(
                    job_id,
                    str(agent["id"]),
                    **_completion_dispatch_guard_kwargs(),
                ):
                    logger.debug(
                        "Dispatcher: job %s already claimed by another replica; skipping",
                        job_id,
                    )
                    continue
                if resume_lane_applies(
                    job,
                    has_checkpoint=await postgres_db.job_has_checkpoint(job_id),
                ):
                    success = await _resume_job_on_agent(job, agent)
                else:
                    if job["status"] == "paused":
                        logger.info(
                            "Dispatcher: job %s is paused with no checkpoint "
                            "to resume from (never started, or pruned at a "
                            "terminal state) — dispatching via the fresh "
                            "/job/start lane",
                            job_id,
                        )
                    success = await _dispatch_job_to_agent(job, agent)

                if success:
                    matched_job_ids.add(job_id)
                    matched_agent_ids.add(str(agent["id"]))

            # Phase 1.5: Provision agent pods for unmatched jobs (K8s only)
            remaining = [
                j for j in dispatchable_jobs if str(j["id"]) not in matched_job_ids
            ]
            if remaining and agent_provisioner.is_available:
                for job in remaining:
                    if (
                        await agent_provisioner.active_count()
                        >= agent_provisioner.max_agents
                    ):
                        break
                    pod_name = await agent_provisioner.provision_agent(purpose="job")
                    if pod_name:
                        logger.info(
                            "Provisioned agent %s for pending job %s",
                            pod_name,
                            str(job["id"]),
                        )
                    else:
                        break  # At capacity or error
                    # Don't assign yet — pod needs to register first.
                    # Agent heartbeats "ready" → _trigger_dispatch() → next
                    # cycle matches it.

            # Phase 2: Preemption (non-blocking). D1 placeability guard: only
            # workspace-ready jobs (dispatchable_jobs, not the full pending set)
            # may drive preemption — pausing a running job to free an agent is
            # pointless for a job that has no workspace to run in.
            remaining = [
                j for j in dispatchable_jobs if str(j["id"]) not in matched_job_ids
            ]
            if not remaining:
                return

            candidates = await postgres_db.get_preemption_candidates()
            if not candidates:
                return

            for pending_job in remaining:
                pending_priority = pending_job.get("priority", 5)
                pending_job_id = str(pending_job["id"])

                # D1 Guard 2: a verification/critic subjob whose parent is
                # already terminal can never run, so it must not preempt — even
                # if it slipped past Guard 1 by inheriting a (now-dead) parent
                # workspace. Costs one lookup, only for sub-jobs reaching Phase 2.
                parent_status = None
                parent_id = pending_job.get("parent_job_id")
                if parent_id:
                    parent = await postgres_db.get_job(str(parent_id))
                    parent_status = parent.get("status") if parent else None
                block_reason = preemption_blocked_reason(pending_job, parent_status)
                if block_reason:
                    logger.warning(
                        "Preempt: skipping pending job %s — %s",
                        pending_job_id,
                        block_reason,
                    )
                    continue

                # Find lowest-priority running job that can be preempted
                for candidate in candidates:
                    candidate_id = str(candidate["id"])
                    candidate_priority = candidate.get("priority", 5)

                    # Only preempt if strictly higher priority
                    if pending_priority <= candidate_priority:
                        continue

                    # Skip if already being paused
                    if candidate_id in _pause_pending_job_ids:
                        continue

                    # Skip if already matched (agent taken)
                    if str(candidate.get("assigned_agent_id", "")) in matched_agent_ids:
                        continue

                    # Initiate preemption (fire-and-forget)
                    _pause_pending_job_ids.add(candidate_id)
                    asyncio.create_task(_initiate_pause(candidate))
                    logger.info(
                        f"Preempt: pausing job {candidate_id} (priority={candidate_priority}) "
                        f"for pending job {pending_job_id} (priority={pending_priority})"
                    )
                    # Remove this candidate so it's not preempted again in this cycle
                    candidates.remove(candidate)
                    break  # One preemption per pending job per cycle

        except Exception as e:
            logger.error(f"Dispatcher error: {e}", exc_info=True)


async def auto_assign_dispatcher(shutdown_event: asyncio.Event) -> None:
    """Background task that periodically dispatches pending jobs to available agents.

    Runs every 30 seconds as a catch-all. Event-driven triggers (job creation,
    agent heartbeat) also call _try_dispatch_pending_jobs() for faster response.
    """
    logger.info(
        "Auto-assign dispatcher started (pinned=%s, stateless_workers=%s)",
        AUTO_ASSIGN_ENABLED,
        STATELESS_WORKER_ENABLED,
    )
    while not shutdown_event.is_set():
        try:
            await _try_dispatch_pending_jobs()
        except Exception as e:
            logger.error(f"Error in auto-assign dispatcher: {e}")

        # Wait 30 seconds or until shutdown
        try:
            await asyncio.wait_for(shutdown_event.wait(), timeout=30.0)
            break
        except asyncio.TimeoutError:
            pass

    logger.info("Auto-assign dispatcher stopped")


def _trigger_dispatch() -> None:
    """Fire-and-forget trigger for the dispatcher. Safe to call from any endpoint.

    Gated on leadership (M1): only the elected leader dispatches, so a job
    created via a REST handler on a non-leader replica is picked up by the
    leader's periodic dispatcher loop rather than dispatched here.
    """
    from services.leader_election import is_leader

    if (AUTO_ASSIGN_ENABLED or STATELESS_WORKER_ENABLED) and is_leader.is_set():
        asyncio.create_task(_try_dispatch_pending_jobs())


