@app.get("/debug/emails", response_class=HTMLResponse)
async def debug_email_index() -> str:
    """Dev-only index of rendered transactional emails (Zulip's /emails idea).

    Calls the real builders with fixture data — never fixtures rendered
    independently of the code that ships — so this page cannot drift from
    the emails users actually receive.

    Gated by ``EMAIL_PREVIEW_ENABLED`` (default off, same as
    ``CANVAS_LIVE_PREVIEW_ENABLED`` / ``COLLABORA_ENABLED``): disabled, it
    raises a bare 404 with no detail, matching FastAPI's own default response
    for an unmapped route exactly — not the ``"unknown email preview"`` detail
    used below for a bad name, which would leak that the route exists.
    """
    if os.getenv("EMAIL_PREVIEW_ENABLED", "").strip().lower() not in {
        "1",
        "true",
        "yes",
        "on",
    }:
        raise HTTPException(status_code=404)
    links = "".join(
        f'<li><a href="/debug/emails/{n}">{n}</a></li>'
        for n in ("system", "agent", "permission")
    )
    return f"<!DOCTYPE html><html><body><h1>Email previews</h1><ul>{links}</ul></body></html>"


@app.get("/debug/emails/{name}", response_class=HTMLResponse)
async def debug_email_preview(name: str) -> str:
    """Render one transactional email through its real builder for inspection.

    Gated by ``EMAIL_PREVIEW_ENABLED`` — see ``debug_email_index`` for why
    the disabled-state 404 has no detail.
    """
    if os.getenv("EMAIL_PREVIEW_ENABLED", "").strip().lower() not in {
        "1",
        "true",
        "yes",
        "on",
    }:
        raise HTTPException(status_code=404)
    link = "https://cockpit.example/preview"
    if name == "system":
        return email_service._build_system_notification_html(
            to_name="Ada Lovelace",
            body_md=(
                "Your automation **Nightly ledger sync** was disabled after "
                "3 consecutive failures.\n\n"
                "The last run failed in `reconcile.py` with:\n\n"
                "```\nValueError: unbalanced ledger (delta 4.20)\n```\n\n"
                "Re-enable it from [Automations](https://cockpit.example/automations) "
                "once the job is fixed."
            ),
            cockpit_link=link,
        )
    if name == "agent":
        # The fixture deliberately exercises the markdown subset (headings,
        # emphasis, code, lists, tables, quotes) — this page is the only place
        # the rendering is looked at with human eyes before it reaches an inbox.
        return email_service._build_agent_message_html(
            message_md=(
                "**Job `5706c684`** (`developer`) has completed and is "
                "awaiting review.\n\n"
                "## Summary\n\n"
                "Migrated the billing schema to the new ledger format. The "
                "`amount_cents` column is now `NOT NULL`, and every historical "
                "row was backfilled from `legacy_amount`.\n\n"
                "> One caveat: 14 rows in 2019 had no legacy value and were "
                "left at zero.\n\n"
                "**Deliverables:**\n\n"
                "- `migrations/app/0163_billing_ledger.sql`\n"
                "- `orchestrator/services/billing.py`\n"
                "  - new `LedgerEntry` dataclass\n"
                "  - `reconcile()` now returns a diff\n\n"
                "| Check | Result |\n"
                "| --- | --- |\n"
                "| `pytest tests/test_billing.py` | 42 passed |\n"
                "| `ruff check` | clean |\n\n"
                "Full diff: https://git.example/srw/compare/main...ledger\n\n"
                "---\n\n"
                "*Confidence: 92%*"
            ),
            job_description="Migrate the billing schema to the new ledger format",
            config_name="developer",
            phase_str="phase 2",
            cockpit_link=link,
            reply_to_addr="reply@example.com",
        )
    if name == "permission":
        # A permission gate is a feed notification now; its mail is the
        # notification template with the magic links as labeled bare URLs.
        body = (
            "**run_command** is waiting for your approval in session "
            "**Nightly build** (requested 4 min ago).\n\n"
            '```\n{"command": "rm -rf ./build"}\n```\n\n'
            f"Approve: {link}/magic/approve/preview-approve\n"
            f"Deny: {link}/magic/approve/preview-deny\n\n"
            "These links need no sign-in and expire in 30 minutes. "
            f"Session: {link}/sessions/preview"
        )
        return email_service.render_notification_html(body, f"{link}/inbox?n=preview")
    raise HTTPException(status_code=404, detail="unknown email preview")


@app.get("/api/workspace/status")
async def workspace_status(request: Request) -> dict[str, Any]:
    """Get workspace configuration status for debugging.

    **Admin only** (P4a): leaks job UUIDs, filesystem paths, and env-var
    values, so it shouldn't be anonymous. No callers currently rely on it.

    Returns:
        Dict with workspace path, availability, and sample job directories
    """
    await _require_admin(request)

    import os

    base_path = workspace_service.base_path
    is_available = workspace_service.is_available

    # List top-level entries (workspace is a flat directory now, no job_* subdirs)
    entries = []
    if is_available:
        try:
            entries = [d.name for d in base_path.iterdir()][:20]
        except Exception:
            pass

    return {
        "configured_path": str(base_path),
        "resolved_path": str(base_path.resolve()) if base_path.exists() else None,
        "is_available": is_available,
        "env_workspace_path": os.environ.get("WORKSPACE_PATH"),
        "entries": entries,
    }


#: Beyond this the list is not a list any more, it is a table scan wearing a
#: page number. Elasticsearch's ``max_result_window`` draws the same line.
JOBS_MAX_OFFSET = 50_000


def _resolve_submitted_job_origin(
    *,
    context: dict[str, Any] | None,
    parent_job_id: Any,
    thread_id: Any,
) -> str:
    """Classify a job arriving through ``POST /api/jobs``.

    That endpoint is not "the user path". It is the shared funnel for human
    submissions, session launches, delegation/critic children forwarded over
    the internal key, and the job bench — all of which arrive with the same
    request shape, which is why origin has to be resolved here rather than
    assumed. (Officer admissions also pass through, but they branch earlier
    and are stamped by ``admit_and_create_job``.)

    Bench is recognised by ``context['bench']``, which
    ``services/bench.py::build_bench_job_payload`` already sets — otherwise
    benchmark traffic is byte-identical to a normal internal submission and
    would land in every user's job list and spend attribution.

    The order mirrors migration 0172's backfill so historic rows and new ones
    are classified the same way.
    """
    if context and "bench" in context:
        return "bench"
    if parent_job_id:
        return "subjob"
    if thread_id:
        return "session"
    return "user"


@dataclass(frozen=True)
class _JobProjectFilters:
    """Parsed ``?project_id=`` for the jobs list and its facet counts."""

    project_ids: list[str]
    has_project: bool | None


def _parse_job_project_filters(
    *,
    project_id: list[str] | None,
    has_project: bool | None,
    is_admin: bool,
    visible_project_ids: list[str] | None,
    scope_project_id: str | None,
) -> _JobProjectFilters:
    """Validate and authorize the project filter for both jobs endpoints.

    Shared so ``GET /api/jobs`` and ``GET /api/stats/jobs`` reject the same
    inputs with the same status codes. Chip counts that accepted a filter the
    list refuses (or vice versa) would disagree with each other in a way no
    test of either endpoint alone would catch.

    ``visible_project_ids`` is the caller's already-resolved membership set;
    pass ``None`` for admins, who may filter by any project in the fleet.
    """
    # 'none' is the project-less bucket. A model will guess it, so accept it
    # rather than treating it as a malformed uuid.
    raw = list(dict.fromkeys(str(value) for value in (project_id or [])))
    wants_projectless = any(value.lower() in ("none", "null") for value in raw)
    ids = sorted(value for value in raw if value.lower() not in ("none", "null"))

    if len(ids) > JOBS_MAX_PROJECT_FILTERS:
        raise HTTPException(
            status_code=422,
            detail=(
                f"Too many project_id values ({len(ids)}); "
                f"the maximum is {JOBS_MAX_PROJECT_FILTERS}."
            ),
        )
    for value in ids:
        try:
            UUID(value)
        except ValueError as exc:
            raise HTTPException(
                status_code=422,
                detail=f"project_id is not a uuid: {value}",
            ) from exc

    effective_has_project = has_project
    if wants_projectless and not ids:
        effective_has_project = False
    elif wants_projectless and ids:
        # "these projects OR no project" is a union the AND-composed filter
        # set cannot express; say so instead of quietly returning one arm.
        raise HTTPException(
            status_code=422,
            detail=(
                "project_id=none cannot be combined with specific project "
                "ids; issue them as separate queries."
            ),
        )

    if scope_project_id is not None and ids and ids != [str(scope_project_id)]:
        # A project-scoped MCP token cannot widen itself by asking for another
        # project. The AND-combined scope would already return zero rows;
        # saying so is clearer than an empty page.
        raise HTTPException(
            status_code=403,
            detail="Access denied by MCP token scope",
        )

    if not is_admin and ids:
        # Refuse a project the caller cannot see rather than returning an
        # empty page. This is a narrowing filter, not an authorization
        # boundary — the visibility OR-clause already bounds the result — so
        # it must NOT run for admins, who legitimately filter by any project
        # in the fleet, and it is deliberately not `require_project_member`:
        # that gate is bypassed wholesale for X-Internal-Key callers and
        # would relabel these endpoints' security classification as
        # membership-gated, which they are not.
        #
        # Known gap: a caller who owns a job in a project they are not a
        # member of cannot filter by that project id. The OR-clause still
        # shows the job in the unfiltered list.
        unauthorized = sorted(set(ids) - set(visible_project_ids or []))
        if unauthorized:
            raise HTTPException(
                status_code=403,
                detail=(
                    f"Not authorized to filter by project(s): {', '.join(unauthorized)}"
                ),
            )

    return _JobProjectFilters(project_ids=ids, has_project=effective_has_project)


#: Repeated UUIDs run into nginx's ~4k URL ceiling around 40 values, where the
#: failure mode is a truncated request rather than a clear error.
JOBS_MAX_PROJECT_FILTERS = 40


@app.get("/api/jobs")
async def list_jobs(
    request: Request,
    status: list[str] | None = Query(
        default=None,
        description="Lifecycle status(es) to keep (repeatable)",
    ),
    origin: list[str] | None = Query(
        default=None,
        description=(
            "Where the job came from (repeatable): user, session, automation, "
            "loop, officer, subjob, lifecycle, bench. No server-side default — "
            "omit it and every origin is returned."
        ),
    ),
    project_id: list[str] | None = Query(
        default=None,
        description=(
            "Project(s) to keep (repeatable). Pass 'none' for jobs with no project."
        ),
    ),
    has_project: bool | None = Query(
        default=None,
        description="true keeps only jobs with a project, false only those without",
    ),
    include_archived_projects: bool = Query(
        default=False,
        description="Include jobs belonging to archived projects",
    ),
    search: str | None = Query(
        default=None,
        max_length=200,
        description="Match against job description (substring) or id (prefix)",
    ),
    as_of: datetime | None = Query(
        default=None,
        description=(
            "Freeze the window at this creation-time watermark so paging is "
            "not shifted by concurrent inserts. Echoed in the response; pass "
            "it back on subsequent pages."
        ),
    ),
    user_id: str | None = Query(default=None),
    limit: int = Query(default=100, ge=1, le=500),
    offset: int = Query(default=0, ge=0),
    include_total: bool = Query(
        default=True,
        description="Compute the capped total. Pass false when paging.",
    ),
) -> dict[str, Any]:
    """List jobs visible to the caller.

    Visibility model (G1):
        * Admins see the full fleet, optionally narrowed by ``?user_id=`` or
          by an MCP ``project:<uuid>`` token scope.
        * Non-admins see jobs they own OR jobs in projects they're a member
          of, additionally narrowed by any MCP project scope.
        * A non-admin passing ``?user_id=`` for anyone other than themselves
          is rejected (403). Self-query (``?user_id=<self>``) is accepted and
          then ignored — AND-ing it onto the OR-clause would narrow the view
          to own-jobs-only and silently drop the caller's project rows.

    Returns an envelope, not a bare array::

        {"jobs": [...], "total": 806, "total_is_capped": false,
         "has_more": true, "limit": 100, "offset": 0, "as_of": "...",
         "filters": {...}}

    ``total`` is exact up to 10,000 and reported as capped beyond it; an
    exact filtered count cannot be made cheap, and bounding it is what keeps
    page 1 fast at a million rows. ``has_more`` is exact regardless.

    The ``filters`` echo exists for MCP callers: it makes a server-side
    default like ``include_archived_projects: false`` visible to a model that
    never read the docs, so an agent that finds nothing knows to widen its
    query rather than concluding the job does not exist.
    """
    user = await require_approved_user(request, postgres_db)
    is_admin = bool(user.get("is_admin"))
    scope_pid = mcp_scope_project_id(user)

    if user_id is not None and not is_admin and str(user_id) != str(user["id"]):
        raise HTTPException(
            status_code=403,
            detail="Not authorized to query other users' jobs",
        )

    statuses = list(dict.fromkeys(status or []))
    unknown = [value for value in statuses if value not in JOB_STATUS_FILTER_VALUES]
    if unknown:
        # 422 rather than an empty page: a typo that silently returns zero
        # rows gets reported as data loss.
        raise HTTPException(
            status_code=422,
            detail=(
                f"Unknown job status(es): {', '.join(sorted(unknown))}. "
                f"Valid values: {', '.join(JOB_STATUS_FILTER_VALUES)}"
            ),
        )

    origins = list(dict.fromkeys(origin or []))
    unknown_origins = [value for value in origins if value not in KNOWN_JOB_ORIGINS]
    if unknown_origins:
        raise HTTPException(
            status_code=422,
            detail=(
                f"Unknown job origin(s): {', '.join(sorted(unknown_origins))}. "
                f"Valid values: {', '.join(sorted(KNOWN_JOB_ORIGINS))}"
            ),
        )

    if offset > JOBS_MAX_OFFSET:
        raise HTTPException(
            status_code=400,
            detail=(
                f"offset exceeds the maximum of {JOBS_MAX_OFFSET}. "
                "Narrow the filters instead of paging further."
            ),
        )

    if is_admin:
        owner_user_id = None
        visible_ids = None
    else:
        visible = await user_visible_project_ids(user, postgres_db)
        # Non-admin always lands on a concrete set (never "all").
        owner_user_id = str(user["id"])
        visible_ids = [str(p) for p in visible] if visible != "all" else []

    filters = _parse_job_project_filters(
        project_id=project_id,
        has_project=has_project,
        is_admin=is_admin,
        visible_project_ids=visible_ids,
        scope_project_id=str(scope_pid) if scope_pid else None,
    )

    # Freeze the window on first page so later pages see the same set. The
    # client carries it back; a shared "page 3" link therefore shows the
    # recipient what the sender saw.
    effective_as_of = as_of or datetime.now(timezone.utc)
    # Emit Zulu, not "+00:00". The offset form round-trips through a properly
    # encoded query string but breaks the moment anything concatenates it
    # naively, because '+' decodes as a space and the parse then 422s. The
    # value is meant to be pasted back verbatim, so hand out the form that
    # survives that.
    as_of_wire = effective_as_of.isoformat().replace("+00:00", "Z")

    try:
        result = await postgres_db.query_jobs(
            owner_user_id=owner_user_id,
            visible_project_ids=visible_ids,
            scope_project_id=str(scope_pid) if scope_pid else None,
            statuses=statuses or None,
            origins=origins or None,
            project_ids=filters.project_ids or None,
            has_project=filters.has_project,
            include_archived_projects=include_archived_projects,
            search=search or None,
            as_of=effective_as_of,
            # Admin-only cross-user filter. A non-admin's ?user_id= is
            # validated above but deliberately NOT forwarded: the OR-clause
            # already bounds them, and AND-ing it on would *narrow* the
            # result to own-jobs-only, dropping their project rows.
            user_id=user_id if is_admin else None,
            limit=limit,
            offset=offset,
            include_total=include_total,
        )
        jobs = result.jobs

        if audit_reader.is_available:
            counts = await audit_reader.get_audit_counts(
                [str(job["id"]) for job in jobs]
            )
            for job in jobs:
                job["audit_count"] = counts.get(str(job["id"]), 0)
        else:
            for job in jobs:
                job["audit_count"] = None

        return {
            "jobs": [
                _with_cloud_review_mode(_redact_job_config_override(job))
                for job in jobs
            ],
            "total": result.total,
            "total_is_capped": result.total_is_capped,
            "has_more": result.has_more,
            "limit": limit,
            "offset": offset,
            "as_of": as_of_wire,
            "filters": {
                "status": statuses,
                "origin": origins,
                "project_id": filters.project_ids,
                "has_project": filters.has_project,
                "include_archived_projects": include_archived_projects,
                "search": search,
                "user_id": user_id if is_admin else None,
            },
        }
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e


def _redact_job_config_override(job: dict[str, Any]) -> dict[str, Any]:
    """Strip credentials and private workspace lease identity from a job."""

    job = dict(job)
    if (
        not isinstance(job.get("workspace_contract"), dict)
        or "state" not in job["workspace_contract"]
    ):
        job["workspace_contract"] = workspace_contract_projection(
            job, vm_mode=vm_provisioner.mode
        )
    job = _redact_nested_workspace_state(job, field="context")
    context = job.get("context")
    context_was_str = isinstance(context, str)
    if context_was_str:
        try:
            context = json.loads(context)
        except (json.JSONDecodeError, TypeError):
            context = None
    if isinstance(context, dict):
        # The coordinate-free workspace_contract projection above is the
        # public contract. Provisioner branches contain SSH hosts, pod/service
        # coordinates and generation authority needed only by server and
        # worker paths; never return them from the user-facing job API.
        public_context = dict(context)
        for key in (
            "vm",
            "workspace_container",
            WORKSPACE_CONTRACT_CONTEXT_KEY,
            WORKSPACE_DISPATCH_AUTHORITY_CONTEXT_KEY,
            WORKSPACE_RUNTIME_CONTEXT_KEY,
            "workspace_backend",
        ):
            public_context.pop(key, None)
        job["context"] = (
            json.dumps(public_context) if context_was_str else public_context
        )
    co = job.get("config_override")
    if co is None:
        return job
    was_str = isinstance(co, str)
    if was_str:
        try:
            co = json.loads(co)
        except (json.JSONDecodeError, TypeError):
            # Opaque/garbage — drop it rather than risk returning a raw secret.
            job = dict(job)
            job["config_override"] = None
            return job
    job = dict(job)
    cleaned = redact_config_override(co)
    if isinstance(cleaned, dict) and isinstance(cleaned.get("workspace"), dict):
        workspace = dict(cleaned["workspace"])
        workspace.pop("remote", None)
        cleaned = {**cleaned, "workspace": workspace}
    job["config_override"] = json.dumps(cleaned) if was_str else cleaned
    return job


def _redact_nested_workspace_state(
    record: dict[str, Any], *, field: str
) -> dict[str, Any]:
    """Remove provisioner-only lease fields while preserving JSONB shape."""

    value = record.get(field)
    was_str = isinstance(value, str)
    if was_str:
        try:
            value = json.loads(value)
        except (json.JSONDecodeError, TypeError):
            return record
    if not isinstance(value, dict):
        return record

    cleaned = value
    changed = False
    for context_key in ("workspace_container", "vm"):
        context = cleaned.get(context_key)
        if not isinstance(context, dict) or not any(
            key in context
            for key in (
                "_canvas_workspace_generation",
                WORKSPACE_RUNTIME_INCARNATION_KEY,
                "_docker_workspace_lease_id",
                "_docker_workspace_trust_mode",
                "_docker_workspace_attested",
                "_docker_workspace_host_key_fingerprint",
                "quarantine_reason",
            )
        ):
            continue
        if not changed:
            cleaned = dict(cleaned)
            changed = True
        context = dict(context)
        context.pop("_canvas_workspace_generation", None)
        context.pop(WORKSPACE_RUNTIME_INCARNATION_KEY, None)
        context.pop("_docker_workspace_lease_id", None)
        context.pop("_docker_workspace_trust_mode", None)
        context.pop("_docker_workspace_attested", None)
        context.pop("_docker_workspace_host_key_fingerprint", None)
        context.pop("quarantine_reason", None)
        cleaned[context_key] = context
    if not changed:
        return record
    result = dict(record)
    result[field] = json.dumps(cleaned) if was_str else cleaned
    return result


def _resolve_exported_folder_url(handle_str: str | None) -> Optional[str]:
    """Browser URL for a job's Mode B export folder, or None.

    The job row stores only the opaque handle, so without this the cockpit has
    no way to re-open the folder after the export response is gone (a reload,
    or a popup the browser blocked). Jobs carry no per-row backend column —
    unlike threads, which is why this doesn't reuse
    :func:`_resolve_cloud_session_url` — so the discriminator comes from the
    serialized handle itself, falling back to the active backend for the bare
    legacy form. Pure URL construction, no I/O.
    """
    if not handle_str:
        return None
    backend = main_cloud_router.for_backend(None)
    if not backend.is_initialized:
        return None
    try:
        handle = SessionFolderHandle.from_db(handle_str, backend=backend.backend_id)
        if handle.backend != backend.backend_id:
            backend = main_cloud_router.for_backend(handle.backend)
            if not backend.is_initialized:
                return None
        return backend.get_session_folder_browser_url(handle)
    except Exception:
        return None


def _with_cloud_review_mode(job: dict[str, Any]) -> dict[str, Any]:
    """Attach the computed ``cloud_review_mode`` and drop the raw join column.

    Routing signal for the cockpit's job-review UI: a job whose project has a
    main-cloud folder goes through the Mode A diff-review flow (``'diff'``);
    everything else — loose jobs and projects without a cloud folder, including
    the auto-assigned default project — gets the Mode B "Open cloud folder"
    affordance (``'open_folder'``). Mirrors the seed-time gate in
    ``services/job_cloud_baseline.py``. ``project_has_cloud_folder`` is computed
    by the ``LEFT JOIN projects`` in the postgres read queries; we pop it so the
    raw column never leaves over REST.

    Also resolves ``exported_folder_handle`` into a ready-to-open
    ``exported_folder_url`` for the same reason: handles are opaque to
    everything outside the owning backend, so the cockpit can't derive it.
    """
    job = dict(job)
    job["cloud_review_mode"] = (
        "diff" if job.pop("project_has_cloud_folder", False) else "open_folder"
    )
    job["exported_folder_url"] = _resolve_exported_folder_url(
        job.get("exported_folder_handle")
    )
    return job


_INTERNAL_JOB_SCOPE_DENIED = "Internal job origin scope is unavailable"


async def _resolve_internal_job_creation_scope(
    request: Request, job: JobCreate
) -> tuple[dict[str, Any] | None, str | None, str | None, bool]:
    """Derive an internal job's user/project scope from authoritative context.

    ``X-Internal-Key`` authenticates the transport, not the user/project values
    in a request body. Agent-created jobs therefore inherit identity and allowed
    projects from ``thread_id`` and/or ``parent_job_id``. A valid MCP forwarded
    user header is the remaining user-authenticated internal path. Originless
    internal HTTP calls are rejected: the shared key reaches agent pods, so it
    cannot establish a privileged "system job" identity. A userless child is
    valid only when derived from an authoritative userless parent/thread.

    Returns ``(principal, user_id, project_id, origin_bound)``. ``origin_bound``
    suppresses the normal user-default-project fallback: an unscoped parent or
    thread must not silently widen into its owner's unrelated default project.
    """

    def denied() -> HTTPException:
        return HTTPException(status_code=403, detail=_INTERNAL_JOB_SCOPE_DENIED)

    thread: dict[str, Any] | None = None
    parent: dict[str, Any] | None = None
    thread_projects: list[str] = []

    if job.thread_id:
        try:
            thread = await postgres_db.get_thread(str(job.thread_id))
        except Exception as exc:
            raise denied() from exc
        if thread is None:
            raise denied()
        try:
            thread_projects = await _thread_project_ids(str(job.thread_id))
            column_project = thread.get("project_id")
            if column_project and str(column_project) not in thread_projects:
                thread_projects.insert(0, str(column_project))
            # Acknowledged-but-still-unavailable project drift is narrowed
            # out INSIDE _revalidate_thread_project_ids now, same as the
            # warm-attach and cold-workspace call sites, so an
            # already-acknowledged revoked/deleted project does not
            # spuriously 403 an internal job scoped off this thread — while a
            # RECOVERED acknowledged project returns automatically.
            thread_projects = await _revalidate_thread_project_ids(
                thread, thread_projects
            )
        except HTTPException as exc:
            # An archived project is the one refusal worth naming here. The
            # generic ``denied()`` exists so a caller cannot learn WHY internal
            # scope resolution failed, but the archived 409 only ever reaches a
            # caller who is already a member of that project, so it discloses
            # nothing — and the agent on the other end can act on "unarchive
            # it" where "scope is unavailable" leaves it guessing.
            if exc.status_code == 409:
                raise
            raise denied() from exc
        except Exception as exc:
            raise denied() from exc

    if job.parent_job_id:
        try:
            parent = await postgres_db.get_job(str(job.parent_job_id))
        except Exception as exc:
            raise denied() from exc
        if parent is None:
            raise denied()

    if thread is not None or parent is not None:
        thread_user_id = (
            str(thread["user_id"]) if thread and thread.get("user_id") else None
        )
        parent_user_id = (
            str(parent["user_id"]) if parent and parent.get("user_id") else None
        )
        if thread is not None and parent is not None:
            if thread_user_id != parent_user_id:
                raise denied()
        origin_user_id = parent_user_id if parent is not None else thread_user_id

        forwarded_user_id = request.headers.get("X-MCP-User-Id")
        if forwarded_user_id and str(forwarded_user_id) != str(origin_user_id or ""):
            raise denied()
        if job.user_id and str(job.user_id) != str(origin_user_id or ""):
            raise denied()

        if parent is not None:
            parent_project = (
                str(parent["project_id"]) if parent.get("project_id") else None
            )
            allowed_projects = {parent_project} if parent_project else set()
            if thread is not None and parent_project not in set(thread_projects):
                # Includes an unscoped parent paired with a project-scoped
                # thread: the parent remains the stricter authority.
                if parent_project is not None or thread_projects:
                    raise denied()
            default_project = parent_project
        else:
            allowed_projects = set(thread_projects)
            column_project = thread.get("project_id") if thread else None
            default_project = (
                str(column_project)
                if column_project and str(column_project) in allowed_projects
                else (thread_projects[0] if thread_projects else None)
            )

        requested_project = str(job.project_id) if job.project_id else None
        if requested_project and requested_project not in allowed_projects:
            raise denied()
        effective_project = requested_project or default_project

        principal = None
        if origin_user_id:
            principal = await postgres_db.get_user(origin_user_id)
            if principal is None:
                raise denied()
        return principal, origin_user_id, effective_project, True

    # MCP forwards a separately authenticated user identity. Resolve it through
    # the normal admission path; a bare internal key plus a body user_id is not
    # equivalent and is rejected below.
    forwarded_user_id = request.headers.get("X-MCP-User-Id")
    if forwarded_user_id:
        principal = await require_approved_user(request, postgres_db)
        principal_id = str(principal["id"])
        if job.user_id and str(job.user_id) != principal_id:
            raise denied()
        requested_project = str(job.project_id) if job.project_id else None
        scoped_project = mcp_scope_project_id(principal)
        if scoped_project is not None:
            scoped_project_id = str(scoped_project)
            if requested_project and requested_project != scoped_project_id:
                raise denied()
            requested_project = requested_project or scoped_project_id
        return principal, principal_id, requested_project, False

    raise denied()


async def _require_job_project_access(
    principal: dict[str, Any] | None,
    project_id: str | None,
    *,
    denial_detail: str = _INTERNAL_JOB_SCOPE_DENIED,
) -> None:
    """Require current editor access for a user-bound project job."""
    if principal is None or project_id is None or principal.get("is_admin"):
        return
    scoped_project = mcp_scope_project_id(principal)
    if scoped_project is not None and str(scoped_project) != str(project_id):
        raise HTTPException(status_code=403, detail=denial_detail)
    role = await postgres_db.get_user_role_in_project(
        str(project_id), str(principal["id"])
    )
    if role not in {"editor", "owner"}:
        raise HTTPException(status_code=403, detail=denial_detail)


def _redact_thread_metadata(thread: dict[str, Any]) -> dict[str, Any]:
    """Parse and strip credential fields from a thread's ``metadata`` before
    it leaves over REST.

    ``metadata`` is a JSONB column asyncpg hands back as a JSON *string*.
    This helper used to "re-serialize to the original representation", which
    meant the owner-facing thread endpoints returned metadata as a string —
    silently breaking every Cockpit consumer typed against
    ``metadata?: Record<string, unknown>`` (settings-pane config/tools
    prefill, the attached-datasource default, and the REST model/temperature
    seeding — the long-standing "model shows the config name until the
    welcome frame" oddity). The contract is now: metadata always leaves as a
    parsed OBJECT (unparseable/absent → ``{}``).
    """
    raw_retirement_context = thread.get("runtime_retirement_context") or {}
    if isinstance(raw_retirement_context, str):
        try:
            raw_retirement_context = json.loads(raw_retirement_context)
        except (json.JSONDecodeError, TypeError):
            raw_retirement_context = {}
    # The token is installed before abortable turn/Officer preflight.  Only
    # the append-only authorized edge is a public `ending` state; exposing the
    # hidden preflight would make Cockpit retire control even when a non-force
    # End is about to abort as an observational no-op.
    retirement_pending = bool(
        thread.get("runtime_retirement_token") is not None
        and thread.get("runtime_retirement_authorized_at") is not None
    )
    retirement_disposition: str | None = None
    if retirement_pending and isinstance(raw_retirement_context, Mapping):
        candidate = str(raw_retirement_context.get("settle_status") or "")
        if candidate in {"ended", "suspended"}:
            retirement_disposition = candidate

    thread = _redact_nested_workspace_state(thread, field="metadata")
    md = thread.get("metadata")
    if isinstance(md, str):
        try:
            md = json.loads(md)
        except (json.JSONDecodeError, TypeError):
            md = {}
    if not isinstance(md, dict):
        md = {}
    thread = dict(thread)
    md = dict(md)
    if "config_override" in md:
        md["config_override"] = redact_config_override(md["config_override"])
    md.pop("_workspace_binding", None)
    md.pop("_stateless_workspace_process_zero_observation", None)
    thread["metadata"] = md
    # These are internal capabilities or immutable physical cleanup evidence,
    # not owner API fields.  Never let a broad SELECT * list/detail response
    # leak them.  Cockpit gets only the durable, non-secret lifecycle shape.
    for internal_key in (
        "runtime_generation",
        "runtime_attach_token",
        "runtime_attach_abort_receipt",
        "runtime_authority_exposed",
        "runtime_retirement_token",
        "runtime_retirement_permanent",
        "runtime_retirement_started_at",
        "runtime_retirement_authorized_at",
        "runtime_retirement_context",
        "runtime_retirement_stage_receipt",
        "runtime_retirement_local_quiescence",
        "runtime_retirement_external_cleanup",
    ):
        thread.pop(internal_key, None)
    thread["runtime_retirement_pending"] = retirement_pending
    thread["retirement_disposition"] = retirement_disposition
    return thread


@app.get("/api/jobs/{job_id}")
async def get_job(request: Request, job_id: str) -> dict[str, Any]:
    """Get a single job by ID."""
    _, job = await require_job_access(request, postgres_db, job_id)
    try:
        if audit_reader.is_available:
            job["audit_count"] = await audit_reader.get_audit_count(job_id)
        else:
            job["audit_count"] = None
        return _with_cloud_review_mode(_redact_job_config_override(job))
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e


@app.post("/api/jobs")
async def create_job(request: Request, job: JobCreate) -> dict[str, Any]:
    """Create a new job. **Dual-callable** (P4b):

    * Cockpit / user path → ``require_approved_user``; if ``body.project_id``
      is set, the caller must be at least an editor of that project; the
      submitted ``user_id`` is forced to ``caller.id`` so a malicious body
      can't create jobs attributed to someone else.
    * Agent path (delegation/session child jobs) → transport authentication via
      ``X-Internal-Key`` plus server-side user/project derivation from
      ``parent_job_id`` or ``thread_id``. Body identity/scope is never trusted.
      Originless internal HTTP calls are rejected; userless system children
      must still derive scope from an authoritative parent/thread.

    Creates a job with status 'created'. The automatic dispatcher provisions
    its workspace and assigns a ready agent; callers should monitor the job
    rather than manually assigning it.

    If ``project_id`` is set (directly or via the user's default project),
    the project's config and resources are inherited, while the root job still
    receives its own isolated repository. Subjobs branch within that root repo.
    """
    internal_call = is_internal_call(request)
    _strip_raw_officer_claim_context(job)
    caller: dict[str, Any] | None = None
    if not internal_call:
        caller = await require_approved_user(request, postgres_db)
        # Force user_id to caller; never honor body.user_id from a cockpit
        # caller (F2 pattern). Project membership is checked below once we
        # know the resolved project_id.
        job.user_id = str(caller["id"])
        _strip_public_job_reserved_markers(job)
        if job.project_id:
            await require_project_member(
                request, postgres_db, str(job.project_id), min_role="editor"
            )
    # The job surface had no tool vocabulary at all: it stripped four lifecycle
    # markers and then accepted `tools.<anything>: [<any registered name>]`.
    # That is the exact smuggle src/core/session_tool_overrides.py was written
    # to prevent — the loader resolves a name against the global registry, not
    # against the key it arrived under, so `tools.canvas: ["run_command"]`
    # binds a shell tool — open on the other surface with only the dispatch PDP
    # behind it, and the PDP keys off the category NAME (`_truthy(tools.shell)`)
    # so it never sees the smuggled one.
    #
    # Applies to the internal path too: X-Internal-Key is transport
    # authentication, not authorization, and create_job forwards a
    # model-authored config_override verbatim. The server's own fragments are
    # unaffected — _critic_config_override and the loop's `{"loop":
    # ["loop_plan"]}` go through postgres_db.create_job directly, and the
    # officer slot patch is merged in below, after this point.
    job.config_override = _with_validated_tool_overrides(job.config_override)
    await _enforce_readiness_gate()
    try:
        # Merge upload IDs into context
        context = dict(job.context) if job.context else {}
        if job.upload_id:
            context["upload_id"] = job.upload_id
        if job.config_upload_id:
            context["config_upload_id"] = job.config_upload_id
        if job.instructions_upload_id:
            context["instructions_upload_id"] = job.instructions_upload_id
        if job.instructions:
            context["instructions"] = job.instructions
        if job.kickoff_message:
            context["kickoff_message"] = job.kickoff_message
        if job.required_deliverables:
            # Deliverable contract (P1-C): normalize + dedupe into context.
            # The dispatcher forwards context to the agent's task brief and the
            # completion gate validates the seal against committed Gitea state.
            from src.shared.deliverable_contract import parse_required_deliverables

            manifest = parse_required_deliverables(
                job.required_deliverables, strict=True
            )
            if manifest:
                context["required_deliverables"] = manifest

        # Internal transport authentication is not user authorization. Derive
        # agent-created job identity/scope from the originating thread/parent
        # (or an authenticated MCP-forwarded user), never from body user/project
        # fields. Even userless system children must have a server-resolved
        # parent/thread; a bare shared-key HTTP request is never a principal.
        internal_origin_bound = False
        internal_principal: dict[str, Any] | None = None
        if internal_call:
            (
                internal_principal,
                effective_user_id,
                scoped_project_id,
                internal_origin_bound,
            ) = await _resolve_internal_job_creation_scope(request, job)
        else:
            internal_principal = caller
            effective_user_id = job.user_id
            scoped_project_id = str(job.project_id) if job.project_id else None

        # Uploads are bound to their creator (uploads.py). Every upload this
        # job references — the three body fields merged above, or the same
        # keys arriving through ``context`` — must belong to the principal
        # the job runs as, checked here before anything is persisted or
        # dispatched: the agent later loads ``config_upload_id`` as its own
        # config, so a foreign id would run someone else's YAML under this
        # user. Admins reach any upload; legacy uploads with no recorded
        # owner are admin-only. Only a userless system child (internal
        # origin that resolved to no user at all) is exempt — there is no
        # identity to check against, and the runtime's own download path is
        # internal-key-only for the same reason.
        upload_principal = internal_principal if internal_call else caller
        for upload_key in ("upload_id", "config_upload_id", "instructions_upload_id"):
            referenced_upload = context.get(upload_key)
            if referenced_upload:
                authorize_upload_reference(
                    upload_principal,
                    str(referenced_upload),
                    internal=internal_call and upload_principal is None,
                )

        # Resolve project_id: authoritative internal origin / public request,
        # then the user's default only when no thread/parent constrained scope.
        project_id = scoped_project_id
        if not project_id and effective_user_id and not internal_origin_bound:
            try:
                user = await postgres_db.get_user(effective_user_id)
                if user and user.get("default_project_id"):
                    project_id = str(user["default_project_id"])
            except Exception as e:
                logger.warning(
                    f"Failed to resolve default project for user {effective_user_id}: {e}"
                )

        await _require_job_project_access(
            internal_principal if internal_call else caller,
            project_id,
            denial_detail=(
                _INTERNAL_JOB_SCOPE_DENIED
                if internal_call
                else "Project role 'editor' or higher required"
            ),
        )

        # Resolve project config fallback plus the authoritative DB expert
        # selection.  Root jobs persist a concrete expert id; internal
        # children/specialists keep their explicit/inherited selector and never
        # silently acquire a user's current default.
        project = None
        # One catalogue, one selector: `expert` takes a bundled slug or a DB
        # expert UUID and resolves to the (base config, DB overlay) pair this
        # funnel persists. The deprecated aliases go through the same helper,
        # so the "two experts in one call" refusal is stated once — see
        # knowledge-base/knowledge/issues/experts_one_catalogue_two_selection_paths.md.
        try:
            expert_choice = resolve_expert_selection(
                expert=job.expert,
                config_name=job.config_name,
                expert_id=job.expert_id,
            )
        except ExpertReferenceConflict as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc
        if expert_choice.kind == "bundled" and job.expert:
            # `expert` means "an entry from the catalogue", so a slug that is
            # not in it is a typo, not a deployment config. Refuse now: the
            # alternative is a job that provisions and only fails when the
            # agent cannot load its config. `config_name` keeps accepting
            # non-catalogue deployment configs, unvalidated, as it always did.
            global _experts_cache
            if _experts_cache is None:
                _experts_cache = _scan_experts()
            if not any(e.id == expert_choice.config_name for e in _experts_cache):
                raise HTTPException(
                    status_code=400,
                    detail=(
                        f"Unknown expert '{expert_choice.config_name}'. Use "
                        "list_experts (GET /api/experts) to see the selectable "
                        "experts; pass a bundled expert id or a DB expert UUID."
                    ),
                )
        explicit_expert_id = expert_choice.expert_id
        # Write boundary for the pod entrypoint's one caller-controlled word.
        # `config_name` still accepts non-catalogue deployment configs (the
        # branch above only vets `expert`), so this is the only charset check
        # a job's stored selector ever gets — and jobs.config_name is read back
        # by dispatch, resume, subjob grafting and every recovery path.
        config_name = canonical_config_name(
            _validated_config_name(expert_choice.config_name) or "worker_base"
        )
        # The resolver can never emit both halves; assert it rather than trust
        # it, because "a DB expert layered over someone else's bundled base"
        # is a config nobody reviewed.
        if explicit_expert_id and config_name != "worker_base":
            raise HTTPException(
                status_code=400,
                detail=(
                    "expert_id cannot be combined with a bundled worker "
                    "config_name; select one expert source"
                ),
            )
        request_config_override = job.config_override
        try:
            requested_workspace_backend = configured_workspace_backend(
                request_config_override
            )
        except WorkspaceContractError as exc:
            raise HTTPException(
                status_code=422,
                detail={"code": exc.code, "message": exc.detail},
            ) from exc
        project_default_override: dict[str, Any] | None = None
        if project_id:
            project = await postgres_db.get_project(project_id)
            if not project:
                raise HTTPException(
                    status_code=404, detail=f"Project '{project_id}' not found"
                )
            # Layer 2 of the archived-project refusal (§4.3 of
            # knowledge-base/knowledge/features/project_and_job_list_filtering.md).
            # It has to be HERE and not on the guard above: an X-Internal-Key
            # caller — all MCP traffic, all agent delegation, the bench
            # sweeper — skips require_project_member entirely, so the flag
            # would only ever cover the cockpit. This load is unconditional
            # across both paths. Critic/scholar/curator subjobs call
            # postgres_db.create_job directly and stay exempt by construction:
            # finishing in-flight work is not new work.
            if project_is_archived(project):
                raise HTTPException(status_code=409, detail=PROJECT_ARCHIVED_DETAIL)
            project_default_override = project.get("default_config_override")
            if project_default_override:
                # asyncpg may return JSONB as a string — parse it
                if isinstance(project_default_override, str):
                    project_default_override = json.loads(project_default_override)

        config_override = project_default_override
        resolved_expert_id = explicit_expert_id
        # A worker launched from an interactive thread is still a user-level
        # root job (the thread supplies scope/datasources, not a worker parent).
        # Only actual worker children/specialists carry parent_job_id.
        root_creation = not job.parent_job_id
        should_resolve_default = (
            root_creation
            and bool(effective_user_id)
            and config_name == "worker_base"
            and _is_experts_db_enabled()
            and await _user_experts_enabled()
        )
        should_validate_explicit = (
            bool(explicit_expert_id)
            and bool(effective_user_id)
            and _is_experts_db_enabled()
        )
        selection = None
        try:
            if should_resolve_default or should_validate_explicit:
                principal = internal_principal if internal_call else caller
                selection = await resolve_root_expert(
                    postgres_db,
                    expert_type="worker",
                    user_id=str(effective_user_id),
                    project_id=project_id,
                    explicit_expert_id=explicit_expert_id,
                    is_admin=bool((principal or {}).get("is_admin")),
                )
                resolved_expert_id = str(selection.expert["id"])
                config_name = "worker_base"
                if selection.project_override:
                    config_override = _deep_merge_dicts(
                        config_override or {}, selection.project_override
                    )
                context["expert_selection"] = {
                    "source": selection.source,
                    "expert_id": resolved_expert_id,
                }
            elif (
                root_creation
                and config_name == "worker_base"
                and project
                and project.get("default_config_name")
                and not _is_experts_db_enabled()
            ):
                # Emergency compatibility mode only.  In normal operation the
                # typed project_experts pointer supersedes this legacy slug.
                config_name = canonical_config_name(project["default_config_name"])
        except ExpertSelectionError as exc:
            raise HTTPException(status_code=422, detail=str(exc)) from exc
        except DefaultExpertUnavailable as exc:
            raise HTTPException(status_code=503, detail=str(exc)) from exc

        if selection is None and expert_choice.kind == "bundled":
            # Same field the DB path stamps, so "who did this dispatcher pick,
            # and did it pick at all?" has one answer whichever store the
            # expert lives in. Reading exactly this key across eight jobs is
            # how the two-path defect was diagnosed.
            context["expert_selection"] = {
                "source": "bundled",
                "expert": expert_choice.reference,
            }

        if request_config_override:
            config_override = _deep_merge_dicts(
                config_override or {}, request_config_override
            )

        # Officer admission preparation (BP-02/BP-03/BP-04). Expensive grant,
        # datasource and provisioning inputs are resolved after this snapshot
        # but before the authoritative transaction. The final INSERT below
        # locks project_officers -> current thread, revalidates this exact
        # incarnation/config/lineage, recomputes all-non-terminal capacity and
        # writes the job on that same connection. Ordinary sessions never take
        # the post lock.
        officer_slot_name: str | None = None
        officer_admission_preparation = None
        officer_ticket_ready_at: datetime | None = None
        _officer_admit_thread_id = (
            str(job.thread_id) if (job.thread_id and root_creation) else None
        )
        if _officer_admit_thread_id:
            try:
                _admit_thread = await postgres_db.get_thread(_officer_admit_thread_id)
            except Exception:
                _admit_thread = None
            officer_meta = _thread_officer_meta(_admit_thread or {})

            # Every ordinary session materializes officer.enabled=false, so
            # that flag alone cannot distinguish a retired officer from a
            # plain session. The durable post lineage can. Enabled orphan /
            # duplicate threads are also candidates so the authoritative
            # post check refuses them instead of letting them dispatch as an
            # ordinary session.
            _officer_lineage_member = False
            if project_id:
                try:
                    _officer_lineage_member = _officer_admit_thread_id in set(
                        await postgres_db.get_project_officer_lineage(project_id)
                    )
                except Exception:
                    _officer_lineage_member = False
            if _officer_meta_enabled(officer_meta) or _officer_lineage_member:
                from services.officer_admission import (
                    OfficerAdmissionConflict,
                    SlotAdmissionError,
                    apply_prepared_slot_config,
                    prepare_officer_admission,
                )

                if not project_id:
                    raise HTTPException(
                        status_code=409,
                        detail="Officer dispatch requires its durable project post.",
                    )
                requested_slot = context.get("officer_slot")
                try:
                    officer_admission_preparation = await prepare_officer_admission(
                        postgres_db,
                        project_id=project_id,
                        thread_id=_officer_admit_thread_id,
                        requested_slot=str(requested_slot) if requested_slot else None,
                        requested_config_override=request_config_override,
                    )
                except OfficerAdmissionConflict as exc:
                    raise HTTPException(
                        status_code=409,
                        detail={
                            "code": exc.code,
                            "message": exc.detail,
                            **exc.fields,
                        },
                    ) from exc
                except SlotAdmissionError as exc:
                    raise HTTPException(status_code=409, detail=str(exc)) from exc
                officer_slot_name = officer_admission_preparation.slot_name
                if officer_slot_name:
                    context["officer_slot"] = officer_slot_name
                config_override = apply_prepared_slot_config(
                    config_override, officer_admission_preparation
                )
                # One claim ledger for both dispatch paths. Without this the
                # officer manually working the top ready ticket races his own
                # tick into double-work on the very next cycle
                # (officer_backlog_pools.md §5.3).
                if job.ticket:
                    context["ticket_note_id"] = str(job.ticket)

                    # ``ticket=`` selects a current ready backlog note; it
                    # never supplies dispatch authority. Resolve the exact
                    # project-scoped row and its database-owned generation
                    # before the short app-Postgres transaction. The final
                    # post lock consumes this value atomically with the claim
                    # and job INSERTs. No ready_at field is model-selectable.
                    from services.project_backlog import (
                        BACKLOG_NOTE_TYPES,
                        fetch_ticket_state,
                    )
                    from services.work_categories import classify_ticket

                    try:
                        ticket_state = await fetch_ticket_state(
                            vector_db,
                            str(project_id),
                            str(job.ticket),
                        )
                    except Exception as exc:
                        raise HTTPException(
                            status_code=503,
                            detail=(
                                "Backlog ticket authority is unavailable; "
                                "no claim or job was created."
                            ),
                        ) from exc
                    if ticket_state is None:
                        raise HTTPException(
                            status_code=409,
                            detail=(
                                f"Backlog ticket '{job.ticket}' does not exist "
                                "in this Officer Post's project."
                            ),
                        )
                    if str(ticket_state.get("project_id") or "") != str(project_id):
                        raise HTTPException(
                            status_code=409,
                            detail="Backlog ticket belongs to a different project.",
                        )
                    if (
                        str(ticket_state.get("status") or "") != "active"
                        or str(ticket_state.get("note_type") or "")
                        not in BACKLOG_NOTE_TYPES
                    ):
                        raise HTTPException(
                            status_code=409,
                            detail=(
                                f"Backlog ticket '{job.ticket}' is not an "
                                "active backlog ticket."
                            ),
                        )
                    classification = classify_ticket(ticket_state.get("tags"))
                    if classification.problems:
                        raise HTTPException(
                            status_code=409,
                            detail=(
                                f"Backlog ticket '{job.ticket}' is ambiguous: "
                                + "; ".join(classification.problems)
                            ),
                        )
                    ready_value = ticket_state.get("ready_at")
                    if not classification.ready or not isinstance(
                        ready_value, datetime
                    ):
                        raise HTTPException(
                            status_code=409,
                            detail=(
                                f"Backlog ticket '{job.ticket}' is not ready "
                                "with trusted Officer provenance."
                            ),
                        )
                    officer_ticket_ready_at = (
                        ready_value
                        if ready_value.tzinfo
                        else ready_value.replace(tzinfo=timezone.utc)
                    )

                # Precedence law (§6): the SLOT's category decides the contract
                # this worker is held to. Explicit model/backend choices must
                # match the slot (validated above and again under the Post
                # lock); they are never silently replaced. A cross-category
                # dispatch — sending a slot into work its category does not
                # describe — remains warn-not-forbid and is named in the
                # kickoff instead.
                _slot_category = officer_admission_preparation.category
                if _slot_category:
                    context.setdefault("work_category", _slot_category)
                    context["kickoff_message"] = _compose_category_kickoff(
                        _slot_category,
                        context.get("kickoff_message"),
                        requested_category=job.work_category,
                        slot=officer_slot_name,
                        thread_id=_officer_admit_thread_id,
                    )

        if job.ticket and officer_admission_preparation is None:
            raise HTTPException(
                status_code=409,
                detail=(
                    "Backlog ticket claims require the exact current commissioned "
                    "Officer Post incarnation. Ad-hoc jobs must omit ticket."
                ),
            )

        # VM permission gate: refuse at submit time so the user gets a clear
        # 403 instead of a silent failure later in the dispatcher. The
        # dispatcher re-checks too (in case the grant is revoked after
        # submission) — defense in depth.
        needs_vm = _job_needs_vm(
            {"context": context, "config_override": config_override}
        )
        if needs_vm:
            creator = None
            if effective_user_id:
                try:
                    creator = await postgres_db.get_user(effective_user_id)
                except Exception:
                    creator = None
            await _check_vm_permission(creator, job_needs_vm=True)

        # Stateless worker admission is independently gated. Explicit requests
        # keep their fail-closed admission errors; an omitted root lane may try
        # the stateless default and silently fall back to pinned when any
        # capability is absent. Omitted children do not enter that default:
        # PostgresDB.create_job resolves them from the authoritative parent.
        needs_sandbox = _job_needs_sandbox(
            {"context": context, "config_override": config_override}
        )
        execution_lane = _resolve_requested_job_execution_lane(
            job.execution_lane,
            default_stateless=STATELESS_WORKER_DEFAULT_ENABLED and root_creation,
            needs_vm=needs_vm,
            needs_sandbox=needs_sandbox,
        )
        if (
            job.execution_lane is None
            and STATELESS_WORKER_DEFAULT_ENABLED
            and root_creation
        ):
            if execution_lane == "stateless":
                logger.info(
                    "Job create: worker execution lane defaulted to stateless "
                    "for a capable root job"
                )
            else:
                if needs_vm and not vm_workspaces_on_pod_network():
                    fallback_reason = "external VM jobs require pinned workers"
                elif not STATELESS_WORKER_ENABLED:
                    fallback_reason = "stateless worker admission is disabled"
                elif not container_provisioner.is_available:
                    fallback_reason = (
                        "the Kubernetes workspace provisioner is unavailable"
                    )
                elif not container_provisioner.in_cluster:
                    fallback_reason = "the workspace provisioner is not in-cluster"
                elif not needs_sandbox:
                    fallback_reason = "the job does not require a Kubernetes sandbox"
                else:
                    fallback_reason = "the worker capability check declined stateless"
                logger.debug(
                    "Job create: stateless worker lane default fell back to pinned (%s)",
                    fallback_reason,
                )
        if job.execution_lane == "stateless" and execution_lane == "pinned":
            logger.info(
                "Job create: external VM request keeps job on pinned lane "
                "(stateless worker opt-in ignored)"
            )

        # Capability PEP on the merged override — same fail-fast rationale as
        # the VM gate above, so an over-reaching override is refused here
        # instead of dying at dispatch. See the helper for what it deliberately
        # does not cover.
        await _enforce_job_create_grants(
            config_override,
            user_id=str(effective_user_id) if effective_user_id else None,
            project_ids=[project_id] if project_id else [],
        )

        # Resolve one complete attachment set before persistence. Presence —
        # not truthiness — distinguishes an explicit [] from omission.
        from services.datasource_policy import default_datasource_selection

        selection_actor = internal_principal if internal_call else caller
        target_project_ids = [project_id] if project_id else []
        lite_backend = _backend_from_override(config_override)
        selection_was_supplied = "datasource_ids" in job.model_fields_set
        trusted_system_origin = bool(
            internal_call and internal_origin_bound and selection_actor is None
        )
        # Inheritance is for DELEGATION; project defaults are for DISPATCH.
        #
        # A parented subjob (critic, curator, pre-job scholar, a legacy delegation child)
        # must never exceed its parent's connectors, so ``parent_job_id`` keeps
        # inheriting unconditionally. But a thread that *commissions* fresh
        # project work — an officer, a session — is not delegating its own
        # charge, and it only landed in the inheritance branch because it
        # happens to be a thread. That mis-classification made
        # ``use_datasource_defaults`` unreachable for every thread-originated
        # job: the branch below it was never evaluated, so the flag the client
        # already sends on omission (orch_surface/client.py) was silently
        # dropped.
        #
        # Cost of that, found live on Better Resavio 2026-08-15: the officer's
        # own thread had been created without a selection, which persists as
        # ``datasource_ids: []`` (origin ``omitted_compat``). Every job he
        # commissioned faithfully inherited the empty list, so his workers got
        # no KurortEngine checkout, could not clone/commit/push, and he
        # correctly refused to dispatch further against a candidate that could
        # never be produced — a full night idle on one absent field.
        wants_dispatch_defaults = bool(
            effective_user_id and job.use_datasource_defaults and not job.parent_job_id
        )

        if selection_was_supplied:
            selection_origin = "explicit"
            requested_datasource_ids = job.datasource_ids or []
            trusted_explicit_reuse = False
            if trusted_system_origin and effective_user_id is None:
                # An ownerless internal caller has no ambient connector
                # authority. It may narrow an authoritative thread/parent
                # selection, but it cannot turn the trusted-inheritance seam
                # into an arbitrary UUID capability.
                inherited_ids = await _inherit_parent_datasource_ids(
                    thread_id=job.thread_id,
                    parent_job_id=job.parent_job_id,
                )
                try:
                    requested_set = {
                        str(UUID(str(value))) for value in requested_datasource_ids
                    }
                    inherited_set = {str(UUID(str(value))) for value in inherited_ids}
                except (TypeError, ValueError) as exc:
                    raise HTTPException(
                        status_code=403,
                        detail="One or more selected connectors are unavailable",
                    ) from exc
                if not requested_set.issubset(inherited_set):
                    raise HTTPException(
                        status_code=403,
                        detail="One or more selected connectors are unavailable",
                    )
                trusted_explicit_reuse = True
            (
                selected_ds_ids,
                selected_ds_revisions,
            ) = await _authorize_thread_datasource_selection(
                selection_actor,
                requested_datasource_ids,
                workspace_backend=lite_backend,
                target_project_ids=target_project_ids,
                effective_work_owner_id=(
                    str(effective_user_id) if effective_user_id else None
                ),
                trusted_system_inheritance=trusted_explicit_reuse,
                legacy_job_id=str(job.parent_job_id) if job.parent_job_id else None,
            )
        elif (job.thread_id or job.parent_job_id) and not wants_dispatch_defaults:
            selection_origin = "inherited"
            inherited_ids = await _inherit_parent_datasource_ids(
                thread_id=job.thread_id, parent_job_id=job.parent_job_id
            )
            inherited_ids = await _filter_implicit_lite_datasource_ids(
                inherited_ids, lite_backend
            )
            (
                selected_ds_ids,
                selected_ds_revisions,
            ) = await _authorize_thread_datasource_selection(
                selection_actor,
                inherited_ids,
                workspace_backend=None,
                target_project_ids=target_project_ids,
                effective_work_owner_id=(
                    str(effective_user_id) if effective_user_id else None
                ),
                trusted_system_inheritance=trusted_system_origin,
                legacy_job_id=str(job.parent_job_id) if job.parent_job_id else None,
            )
        elif effective_user_id and (
            job.use_datasource_defaults or _datasource_defaults_on_omission()
        ):
            selection_origin = "default"
            try:
                (
                    selected_ds_ids,
                    selected_ds_revisions,
                ) = await default_datasource_selection(
                    postgres_db,
                    str(effective_user_id),
                    target_project_ids,
                    lite_backend,
                )
            except Exception as exc:
                from services.datasource_policy import DatasourceUnavailableError

                if isinstance(exc, DatasourceUnavailableError):
                    raise HTTPException(
                        status_code=403,
                        detail="One or more selected connectors are unavailable",
                    ) from exc
                raise
        else:
            selection_origin = "omitted_compat" if effective_user_id else "system_empty"
            selected_ds_ids = []
            selected_ds_revisions = {}

        selection_provenance = await _datasource_selection_provenance(
            datasource_ids=selected_ds_ids,
            policy_revisions=selected_ds_revisions,
            origin=selection_origin,
            effective_work_owner_id=(
                str(effective_user_id) if effective_user_id else None
            ),
            actor=selection_actor,
            project_ids=target_project_ids,
            creation_path="internal_rest" if internal_call else "user_rest",
        )

        # Bind the caller's semantic contract to the exact authorized
        # datasource set before insertion.  This is also where the historical
        # ``repos/<alias>/...`` form becomes a loud PR requirement: Pydantic
        # cannot do that because project/ticket/datasource authority has not
        # been resolved at that boundary.
        from services.deliverable_contracts import (
            DeliveryContractConflict,
            prepare_delivery_contract,
        )

        # Repository binding is needed only for a declared contract. Keep
        # jobs without deliverables on the historical creation path (and
        # avoid turning an optional connector read into a new admission
        # dependency for every job).
        selected_datasources = []
        if job.required_deliverables:
            selected_datasources = await postgres_db.resolve_datasources_for_thread(
                selected_ds_ids, target_project_ids
            )
        try:
            delivery_plan = prepare_delivery_contract(
                job.required_deliverables or [],
                datasources=selected_datasources,
            )
        except DeliveryContractConflict as exc:
            if (
                exc.code == "external_repository_requires_pr"
                and officer_admission_preparation is not None
                and job.ticket
                and officer_ticket_ready_at is not None
            ):
                from services.officer_admission import (
                    OfficerAdmissionConflict,
                    record_rejected_ticket_delivery_requirement,
                )

                try:
                    await record_rejected_ticket_delivery_requirement(
                        postgres_db,
                        preparation=officer_admission_preparation,
                        ticket_note_id=str(job.ticket),
                        ticket_ready_at=officer_ticket_ready_at,
                        required_pr_repositories=list(
                            exc.fields.get("required_pr_repositories") or []
                        ),
                    )
                except OfficerAdmissionConflict as admission_exc:
                    raise HTTPException(
                        status_code=409,
                        detail={
                            "code": admission_exc.code,
                            "message": admission_exc.detail,
                            **admission_exc.fields,
                        },
                    ) from admission_exc
            raise HTTPException(
                status_code=409,
                detail={"code": exc.code, "message": exc.message, **exc.fields},
            ) from exc

        if delivery_plan.deliverables:
            context["required_deliverables"] = list(delivery_plan.deliverables)
            delivery_contract_record = delivery_plan.as_database_record()
        else:
            context.pop("required_deliverables", None)
            delivery_contract_record = None

        # Session ↔ job backref. `job.thread_id` is authenticated on the
        # internal path (_resolve_internal_job_creation_scope 403s on a thread
        # that is missing or owned by someone else) and forced to None on the
        # public path by _strip_public_job_reserved_markers — so persisting it
        # here cannot be steered from a request body.
        #
        # Only ROOT creations carry the backref: a worker child (scholar,
        # critic, delegation subagent) inherits its thread scope for datasources
        # but its completion is the parent job's business, not the session's.
        # Waking the session per subjob would turn one delegation into a status
        # feed. (Those call sites hit postgres_db.create_job directly anyway and
        # simply never pass the kwarg.)
        #
        # wake_on_complete is set here, server-side, rather than being a
        # create_job parameter: an opt-in flag the model must remember
        # fails SILENTLY — it forgets, then never learns the job finished, which
        # is indistinguishable from having no wake feature at all. A surplus
        # wake costs one cheap turn the agent can go straight back to sleep
        # from. knowledge-base/knowledge/features/session_wake_on_job_completion.md.
        creating_thread_id = (
            str(job.thread_id) if (job.thread_id and root_creation) else None
        )

        create_kwargs = {
            "description": job.description,
            "document_path": job.document_path,
            "document_dir": job.document_dir,
            "config_name": config_name,
            "expert_id": resolved_expert_id,
            "config_override": config_override,
            "context": context if context else None,
            "user_id": effective_user_id,
            "project_id": project_id,
            "parent_job_id": job.parent_job_id,
            "priority": job.priority,
            "creation_order": job.creation_order,
            "worktree_path": job.worktree_path,
            "delegation_context": job.delegation_context,
            "created_by_thread_id": creating_thread_id,
            "wake_on_complete": bool(creating_thread_id),
            "datasource_ids": selected_ds_ids,
            "datasource_selection_provenance": selection_provenance,
            "datasource_policy_revisions": selected_ds_revisions,
            "authority_user_id": (
                str(effective_user_id) if effective_user_id else None
            ),
            "authority_project_ids": (
                target_project_ids if effective_user_id else None
            ),
            "execution_lane": execution_lane,
            "origin": _resolve_submitted_job_origin(
                context=context,
                parent_job_id=job.parent_job_id,
                thread_id=creating_thread_id,
            ),
            "requested_workspace_backend": requested_workspace_backend,
            "workspace_assignment_source": (
                "request"
                if requested_workspace_backend is not None
                else "resolved_config"
            ),
            "delivery_contract": delivery_contract_record,
        }
        if officer_admission_preparation is not None:
            from services.officer_admission import (
                OfficerAdmissionConflict,
                SlotAdmissionError,
                admit_and_create_job,
            )

            try:
                result = await admit_and_create_job(
                    postgres_db,
                    preparation=officer_admission_preparation,
                    job_kwargs=create_kwargs,
                    ticket_note_id=str(job.ticket) if job.ticket else None,
                    ticket_ready_at=officer_ticket_ready_at,
                    ticket_claim_source="manual",
                    strict_provisioning=True,
                )
            except OfficerAdmissionConflict as exc:
                raise HTTPException(
                    status_code=409,
                    detail={
                        "code": exc.code,
                        "message": exc.detail,
                        **exc.fields,
                    },
                ) from exc
            except SlotAdmissionError as exc:
                raise HTTPException(status_code=409, detail=str(exc)) from exc
        else:
            result = await postgres_db.create_job(**create_kwargs)

        officer_preflight_activated = True
        if officer_admission_preparation is not None:
            from services.officer_preflight import ensure_officer_job_activated

            preflight = await ensure_officer_job_activated(
                postgres_db,
                result,
                provision=_provision_officer_ticket_repo,
                category=officer_admission_preparation.category,
                trigger_dispatch=_trigger_dispatch,
            )
            officer_preflight_activated = preflight.activated
            result = await postgres_db.get_job(str(result["id"])) or result
            result["provisioning_preflight"] = {
                "state": preflight.state,
                "activated": preflight.activated,
                "retryable": preflight.retryable,
                "phase": preflight.phase,
                "error": preflight.error,
            }
        else:
            from services.job_provisioning import provision_job_repo

            await provision_job_repo(
                job_row=result,
                gitea_client=gitea_client,
                postgres_db=postgres_db,
                main_cloud_router=main_cloud_router,
            )

        # Spawn scholar subjob if enabled (root jobs only)
        if not job.parent_job_id and officer_preflight_activated:
            try:
                # Re-fetch the job so _spawn_scholar_subjob has repo_name etc.
                fresh_job = await postgres_db.get_job(str(result["id"]))
                if fresh_job:
                    scholar_result = await _spawn_scholar_subjob(
                        fresh_job,
                        config_name,
                        config_override,
                        context,
                    )
                    if scholar_result:
                        result["scholar_job_id"] = str(scholar_result["id"])
            except Exception as e:
                logger.warning(f"Failed to spawn scholar for job {result['id']}: {e}")

        # Trigger auto-assignment dispatcher (fire-and-forget)
        if officer_admission_preparation is None:
            _trigger_dispatch()

        return _redact_job_config_override(result)
    except DatasourceMaterializationAuthorizationError as exc:
        raise HTTPException(
            status_code=403,
            detail="Work owner is no longer authorized",
        ) from exc
    except DatasourcePolicyConflictError as exc:
        raise HTTPException(
            status_code=409,
            detail="Connector policy changed while creating work; retry the request",
        ) from exc
    except HTTPException:
        raise
    except Exception as e:
        logger.exception("Failed to create job: %s", e)
        raise HTTPException(status_code=500, detail=str(e)) from e


@app.delete("/api/jobs/{job_id}")
async def delete_job(request: Request, job_id: str) -> dict[str, Any]:
    """Delete a job and its requirements.

    P4c: destructive. Caller must own the job OR be project-owner OR admin.
    Plain project membership is not enough — mirrors G3 sudo-authority gate.
    """
    caller, job = await require_job_access(request, postgres_db, job_id)
    if not caller.get("is_admin"):
        is_job_owner = str(job.get("user_id") or "") == str(caller["id"])
        is_project_owner = False
        if not is_job_owner and job.get("project_id"):
            role = await postgres_db.get_user_role_in_project(
                str(job["project_id"]), str(caller["id"])
            )
            is_project_owner = role == "owner"
        if not (is_job_owner or is_project_owner):
            raise HTTPException(
                status_code=403,
                detail="Only the job owner, the project owner, or an admin may delete this job",
            )
    try:
        # A parent with surviving child rows can't be row-deleted anyway
        # (parent_job_id FK, no cascade) — fail fast BEFORE tearing down the
        # workspace, or the failed delete would leave the job alive with its
        # pod gone.
        if await postgres_db.has_child_jobs(job_id):
            raise HTTPException(
                status_code=409,
                detail="Job has child jobs; delete them first",
            )

        # A stateless saver is authorized by its run_queue generation, not by
        # the continued existence of the jobs row. Permanently fence that
        # generation and prove the canonical checkpoint thread empty before
        # workspace teardown; pruning after row deletion would let a live
        # predecessor recreate orphaned checkpoints.
        if job.get("execution_lane") == "stateless":
            prepared = await postgres_db.prepare_stateless_job_for_delete(job_id)
            if not prepared:
                raise HTTPException(
                    status_code=409,
                    detail="Stateless job changed while deletion was being prepared",
                )

        # Tear down workspace/VM resources while the row still exists — the
        # provisioners resolve them through the job's context, and once the
        # row is gone the lifecycle reconciler refuses to reap the pod
        # (no-bound-row is treated as in-flight provisioning; see
        # knowledge-history/done/deleted_job_orphans_workspace_pod.md).
        try:
            await _archive_and_cleanup_workspace(job_id)
        except Exception as exc:
            # Retain the owning row as the durable retry handle.  In
            # particular, a static Docker container may still hold a live
            # repo-scoped ssh-agent even after its lease is quarantined; and a
            # Pod/VM transport acknowledgement is not exact compute absence.
            # Deleting the row here would make either residue ownerless.
            logger.warning(
                "Workspace cleanup is incomplete for job %s: %s", job_id, exc
            )
            raise HTTPException(
                status_code=503,
                detail="Workspace authority retirement is incomplete",
            ) from exc
        # A deleted job can never be restored, so its S3 snapshots (including
        # the one release_workspace may have just captured) are garbage.
        if snapshot_service.is_available:
            try:
                await snapshot_service.delete_snapshot(job_id)
            except Exception as e:
                logger.warning(f"Snapshot cleanup failed for deleted job {job_id}: {e}")

        # Log-archive objects die with the job (retention:
        # knowledge-base/knowledge/features/job_log_archive.md). Re-fetch the row — keys may have
        # been stamped after this handler fetched it.
        if snapshot_service.is_available:
            try:
                fresh = await postgres_db.get_job(job_id) or {}
                ctx = fresh.get("context") or {}
                if isinstance(ctx, str):
                    ctx = json.loads(ctx)
                for key in ctx.get("log_archive_keys") or []:
                    await snapshot_service.delete_blob(str(key))
            except Exception as e:
                logger.warning(
                    f"Log archive cleanup failed for deleted job {job_id}: {e}"
                )

        # Clean up Gitea repo/branch. Root repository deletion is a security
        # boundary: if Gitea is unavailable, retain the job row as the durable
        # retry handle instead of orphaning a still-usable deploy key.
        repo_name = job.get("repo_name")
        branch_name = job.get("branch_name")
        isolated_repo_name = f"job-{str(job.get('id') or job_id)[:8]}"
        if repo_name or branch_name:
            if job.get("parent_job_id") and branch_name and repo_name:
                # Subjob: delete the branch (no-op if already merged and deleted)
                if gitea_client.is_initialized:
                    await gitea_client.delete_branch(repo_name, branch_name)
            elif repo_name == isolated_repo_name:
                # New root-job model: this repo belongs to exactly this job.
                if not await revoke_and_delete_managed_repository(
                    postgres_db, gitea_client, repo_name
                ):
                    raise HTTPException(
                        status_code=503,
                        detail="Repository credential revocation is retryable",
                    )
            elif job.get("project_id") and branch_name:
                # Legacy project job: the repo is shared. Never delete it from a
                # job endpoint, even when repo_name is stamped on the row (which
                # newer legacy rows are). Delete only this job's branch.
                legacy_repo_name = repo_name
                if not legacy_repo_name:
                    repos = await postgres_db.get_project_repositories(
                        str(job["project_id"]), role="jobs"
                    )
                    legacy_repo_name = repos[0]["name"] if repos else None
                if legacy_repo_name and branch_name != "main":
                    await gitea_client.delete_branch(legacy_repo_name, branch_name)
            elif repo_name and not job.get("project_id"):
                # Pre-migration loose root job: its non-project repo is private
                # to the job even if it predates the deterministic short name.
                if not await revoke_and_delete_managed_repository(
                    postgres_db, gitea_client, repo_name
                ):
                    raise HTTPException(
                        status_code=503,
                        detail="Repository credential revocation is retryable",
                    )
        # Clean up vector DB tables (no FK cascade across databases)
        try:
            async with vector_db.acquire() as conn:
                await conn.execute(
                    "DELETE FROM memories WHERE job_id = $1", UUID(job_id)
                )
                await conn.execute(
                    "DELETE FROM citations WHERE job_id = $1", UUID(job_id)
                )
                await conn.execute(
                    "DELETE FROM source_annotations WHERE job_id = $1", UUID(job_id)
                )
                await conn.execute(
                    "DELETE FROM source_tags WHERE job_id = $1", UUID(job_id)
                )
                await conn.execute(
                    "DELETE FROM source_embeddings WHERE job_id = $1", UUID(job_id)
                )
                await conn.execute(
                    "DELETE FROM job_sources WHERE job_id = $1", UUID(job_id)
                )
        except Exception as e:
            logger.warning(f"Failed to clean up vector DB tables for job {job_id}: {e}")

        if job.get("execution_lane") == "stateless":
            delete_result = await postgres_db.delete_job(
                job_id,
                prepared_stateless=True,
                deletion_actor_user_id=str(caller["id"]),
                deletion_reason="authorized_api_delete",
                return_claim_state=True,
            )
        else:
            # Pinned deletion keeps its historical collaborator signature and
            # behavior; only stateless checkpoints need the queue fence above.
            delete_result = await postgres_db.delete_job(
                job_id,
                deletion_actor_user_id=str(caller["id"]),
                deletion_reason="authorized_api_delete",
                return_claim_state=True,
            )
        # ``return_claim_state`` is implemented by PostgresDB. Tolerating the
        # historical boolean here keeps narrow test collaborators and rolling
        # application adapters safe, but only the mapping can assert a claim.
        if isinstance(delete_result, dict):
            success = bool(delete_result.get("deleted"))
            claim_retained = bool(delete_result.get("ticket_claim_retained"))
        else:
            success = bool(delete_result)
            claim_retained = False
        if not success:
            raise HTTPException(status_code=404, detail=f"Job '{job_id}' not found")
        await _resolve_job_notifications(job_id, user=caller, hook="delete")
        return {
            "status": "deleted",
            "ticket_claim_retained": claim_retained,
            "ticket_rearmed": False,
            "message": (
                "Job deleted. Its backlog-ticket claim remains durable; "
                "deletion does not re-arm the ticket."
                if claim_retained
                else "Job deleted. This job had no durable backlog-ticket claim."
            ),
        }
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e


@app.post("/api/jobs/{job_id}/subjob-merge")
async def subjob_merge(request: Request, job_id: str) -> dict[str, Any]:
    """Graft a completed subjob's output/ onto its parent's branch.
    **Internal** (P4b) — requires ``X-Internal-Key``. Ingress strips this
    path.

    Called by the agent after a subjob completes (autonomy=full auto-completion).
    Grafts the subjob's output/ onto the parent as a namespaced outputs/ folder.
    """
    await require_internal(request)
    try:
        job = await postgres_db.get_job(job_id)
        if not job:
            raise HTTPException(status_code=404, detail=f"Job '{job_id}' not found")

        if not job.get("parent_job_id"):
            raise HTTPException(
                status_code=400,
                detail="Only subjobs (with parent_job_id) can be grafted",
            )

        result = await _graft_subjob_output(job_id)
        if result is None:
            return {"status": "skipped", "reason": "no branch/repo configured"}

        return {"job_id": job_id, **result}

    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Squash merge failed for subjob {job_id}: {e}", exc_info=True)
        raise HTTPException(status_code=500, detail=str(e)) from e


async def _cascade_cancel_to_children(job_id: str) -> bool:
    """Cancel all non-terminal descendant jobs of a parent.

    Fetches the full descendant tree (recursive), signals processing agents
    to stop, cleans up VMs/containers, and bulk-updates DB status.
    """
    children = await postgres_db.get_descendant_jobs(job_id)
    if not children:
        return True

    # Signal processing agents concurrently
    async def _signal_cancel(child: dict) -> bool:
        child_id = str(child["id"])
        agent_id = child.get("assigned_agent_id")
        if child["status"] != "processing":
            return True
        if not agent_id:
            return False
        target = await _prepare_pinned_job_mutation_target(
            agent_id=str(agent_id),
            job_id=child_id,
            require_idle=False,
        )
        if target is None:
            return False
        agent_url = (
            f"http://{target.agent['pod_ip']}:{target.agent['pod_port']}/job/cancel"
        )
        try:
            async with httpx.AsyncClient(timeout=130.0) as client:
                response = await client.post(
                    agent_url,
                    json={
                        "reason": f"Parent job {job_id} cancelled",
                        "recipient": target.recipient.model_dump(mode="json"),
                    },
                )
            return response.status_code == 200
        except Exception as e:
            logger.warning(f"Could not reach agent to cancel child {child_id}: {e}")
            return False

    async def _cleanup_child(child: dict) -> bool:
        child_id = str(child["id"])
        try:
            await _archive_and_cleanup_workspace(child_id)
        except Exception as exc:
            logger.warning("Workspace cleanup failed for child %s: %s", child_id, exc)
            return False
        return True

    pinned_children = [c for c in children if c.get("execution_lane") != "stateless"]
    stateless_children = [c for c in children if c.get("execution_lane") == "stateless"]

    pinned_settled = True
    if COMPLETION_COMMANDS_ENABLED:

        async def _cancel_pinned_child(child: dict) -> bool:
            child_id = str(child["id"])
            won = await postgres_db.linearize_pinned_cancel(
                child_id,
                expected_status=str(child.get("status") or ""),
                completion_commands_enabled=True,
            )
            if not won:
                refreshed = await postgres_db.get_job(child_id)
                if not refreshed or refreshed.get("status") in (
                    "completed",
                    "failed",
                ):
                    return True
                if refreshed.get("status") != "cancelled":
                    return False
                # A previous caller may have committed cancellation and died
                # before external retirement.  The terminal row remains the
                # retry owner; never treat status alone as cleanup success.
                return await _cleanup_child(refreshed)
            signal_result, cleanup_result = await asyncio.gather(
                _signal_cancel(child),
                _cleanup_child(child),
                return_exceptions=True,
            )
            if isinstance(signal_result, BaseException):
                logger.warning(
                    "Cascade cancellation signal raised for child %s",
                    child_id,
                    exc_info=(
                        type(signal_result),
                        signal_result,
                        signal_result.__traceback__,
                    ),
                )
            return signal_result is True and cleanup_result is True

        pinned_results = await asyncio.gather(
            *[_cancel_pinned_child(c) for c in pinned_children],
            return_exceptions=True,
        )
        for child, result in zip(pinned_children, pinned_results, strict=True):
            if result is True:
                continue
            pinned_settled = False
            logger.error(
                "Cascade cancellation stood down for pinned child %s because "
                "another completion/control owner won",
                child.get("id"),
            )
    else:
        legacy_results = await asyncio.gather(
            *[_signal_cancel(c) for c in pinned_children],
            *[_cleanup_child(c) for c in pinned_children],
            return_exceptions=True,
        )
        signal_results = legacy_results[: len(pinned_children)]
        cleanup_results = legacy_results[len(pinned_children) :]
        pinned_settled = all(result is True for result in signal_results) and all(
            result is True for result in cleanup_results
        )

    async def _cancel_stateless_child(child: dict) -> bool:
        child_id = str(child["id"])
        cancelled, _queue_closed = await postgres_db.cancel_stateless_job(
            child_id, **_completion_dispatch_guard_kwargs()
        )
        if cancelled:
            return await _wait_for_stateless_cancel_settle(child_id)
        refreshed = await postgres_db.get_job(child_id)
        if not refreshed:
            return True
        if refreshed.get("status") in ("completed", "failed"):
            return True
        if refreshed.get("status") != "cancelled":
            return False
        refreshed_context = refreshed.get("context") or {}
        if isinstance(refreshed_context, str):
            try:
                refreshed_context = json.loads(refreshed_context)
            except (TypeError, ValueError):
                refreshed_context = {}
        if refreshed_context.get("_stateless_cancel_cleanup_pending") is True:
            return await _wait_for_stateless_cancel_settle(child_id)
        return True

    stateless_results = await asyncio.gather(
        *[_cancel_stateless_child(c) for c in stateless_children],
        return_exceptions=True,
    )
    stateless_settled = True
    for child, result in zip(stateless_children, stateless_results, strict=True):
        if result is True:
            continue
        stateless_settled = False
        if isinstance(result, BaseException):
            logger.error(
                "Cascade cancellation could not settle stateless child %s",
                child.get("id"),
                exc_info=(type(result), result, result.__traceback__),
            )
        else:
            logger.error(
                "Cascade cancellation timed out with stateless child %s still live",
                child.get("id"),
            )

    # Bulk cancel in DB
    pinned_ids = [str(c["id"]) for c in pinned_children]
    if pinned_ids and not COMPLETION_COMMANDS_ENABLED and pinned_settled:
        async with postgres_db.acquire() as conn:
            await conn.execute(
                """
                UPDATE jobs
                SET status = 'cancelled',
                    assigned_agent_id = NULL,
                    updated_at = CURRENT_TIMESTAMP
                WHERE id = ANY($1::uuid[])
                  AND status NOT IN ('completed', 'cancelled')
                """,
                pinned_ids,
            )

    logger.info(f"Cascade-cancelled {len(children)} descendant(s) of job {job_id}")
    return pinned_settled and stateless_settled


async def _cascade_pause_to_children(job_id: str) -> None:
    """Pause all processing descendant jobs of a parent.

    Only actively-processing children are signaled and paused in DB.
    Non-processing children (created, waiting) are implicitly held by
    the dispatcher's ancestor guard.
    """
    children = await postgres_db.get_descendant_jobs(job_id)
    processing = [c for c in children if c["status"] == "processing"]
    if not processing:
        return
    pinned_processing = [
        c for c in processing if c.get("execution_lane") != "stateless"
    ]
    stateless_processing = [
        c for c in processing if c.get("execution_lane") == "stateless"
    ]

    async def _signal_pause(
        child: dict,
        *,
        already_paused: bool = False,
        require_positive_quiescence: bool = False,
    ) -> bool:
        child_id = str(child["id"])
        agent_id = child.get("assigned_agent_id")
        if not agent_id and not require_positive_quiescence:
            return True
        if agent_id:
            target = await _prepare_pinned_job_mutation_target(
                agent_id=str(agent_id),
                job_id=child_id,
                require_idle=False,
            )
            if target is None:
                return False
            else:
                agent_url = (
                    f"http://{target.agent['pod_ip']}:{target.agent['pod_port']}"
                    "/job/pause"
                )
                try:
                    async with httpx.AsyncClient(timeout=130.0) as client:
                        response = await client.post(
                            agent_url,
                            json={
                                "recipient": target.recipient.model_dump(mode="json")
                            },
                        )
                except Exception as e:
                    logger.warning(
                        f"Could not reach agent to pause child {child_id}: {e}"
                    )
                    if require_positive_quiescence:
                        return False
                else:
                    if response.status_code != 200:
                        logger.warning(
                            "Cascade pause for child %s was not positively "
                            "acknowledged (%s)%s",
                            child_id,
                            response.status_code,
                            (
                                "; retaining bounded control hold"
                                if require_positive_quiescence
                                else ""
                            ),
                        )
                        if require_positive_quiescence:
                            return False

        if not already_paused:
            await postgres_db.pause_job(child_id)
        return True

    if COMPLETION_COMMANDS_ENABLED:

        async def _linearize_and_signal_pause(child: dict) -> None:
            child_id = str(child["id"])
            try:
                pause_claim = await _claim_completion_pause(
                    child_id,
                    source="cascade_pause",
                    expected_agent_id=(
                        str(child["assigned_agent_id"])
                        if child.get("assigned_agent_id")
                        else None
                    ),
                )
            except HTTPException:
                logger.info(
                    "Cascade pause: child %s changed or is controlled; "
                    "skipping external pause",
                    child_id,
                )
                return
            quiescent = await _signal_pause(
                child,
                already_paused=True,
                require_positive_quiescence=True,
            )
            if quiescent:
                await _abort_completion_control_claim(pause_claim)
            else:
                logger.warning(
                    "Cascade pause: retaining child %s control hold until "
                    "bounded expiry",
                    child_id,
                )

        await asyncio.gather(
            *[_linearize_and_signal_pause(c) for c in pinned_processing],
            return_exceptions=True,
        )
    else:
        await asyncio.gather(
            *[_signal_pause(c) for c in pinned_processing],
            return_exceptions=True,
        )
    for child in stateless_processing:
        await postgres_db.pause_stateless_job(
            str(child["id"]), **_completion_dispatch_guard_kwargs()
        )

    logger.info(
        f"Cascade-paused {len(processing)} processing descendant(s) of job {job_id}"
    )


async def _wait_for_stateless_cancel_settle(
    job_id: str,
    *,
    timeout_seconds: float = 130.0,
    poll_seconds: float = 0.5,
) -> bool:
    """Wait for a cancelled worker owner to teardown, then prune/archive.

    The status write is the preemption signal and must happen first. A live
    holder discovers it on renewal, tears down local/tmux ownership, then
    closes its exact queue lease. A killed holder is reclaimed within the
    queue TTL/reaper horizon. Only after that boundary is it safe to delete the
    shared checkpoint and workspace underneath the former owner.
    """
    deadline = asyncio.get_running_loop().time() + max(0.0, timeout_seconds)
    while True:
        try:
            async with postgres_db.stateless_cancel_cleanup_lock(
                job_id
            ) as cleanup_owner:
                if not cleanup_owner:
                    settled = False
                else:
                    cleanup_pending = (
                        await postgres_db.stateless_cancel_cleanup_pending(job_id)
                    )
                    if cleanup_pending is False:
                        # A prior owner already cleared the durable marker (or
                        # permanent DELETE removed the row). Never repeat the
                        # destructive workspace cleanup after Resume can run.
                        return True
                    if cleanup_pending is None:
                        settled = False
                    else:
                        settled = await postgres_db.finalize_cancelled_stateless_job(
                            job_id
                        )
                    if settled:
                        workspace_clean = True
                        try:
                            await _archive_and_cleanup_workspace(job_id)
                        except Exception as exc:
                            workspace_clean = False
                            logger.warning(
                                "Workspace cleanup failed for cancelled stateless "
                                "job %s: %s",
                                job_id,
                                exc,
                            )
                        if workspace_clean:
                            cleanup_completed = (
                                await postgres_db.complete_stateless_cancel_cleanup(
                                    job_id
                                )
                            )
                            if cleanup_completed:
                                return True
                            settled = False
                        else:
                            # Keep the durable Resume block until workspace teardown
                            # has actually returned successfully. Clearing it after an
                            # exception would let a new claim attach while cancellation's
                            # destructive cleanup is only half complete.
                            settled = False
        except Exception:
            logger.warning(
                "Stateless cancel settle check failed for job %s; retrying",
                job_id,
                exc_info=True,
            )
            settled = False

        remaining = deadline - asyncio.get_running_loop().time()
        if remaining <= 0:
            return False
        await asyncio.sleep(min(max(0.01, poll_seconds), remaining))


@app.put("/api/jobs/{job_id}/cancel")
async def cancel_job(request: Request, job_id: str) -> dict[str, str]:
    """Cancel a running job. **Dual-callable** (P4b): cockpit user with job
    access (``require_job_access``) OR agent with valid ``X-Internal-Key``
    (agent's `cancel_job` tool path).

    If the job is assigned to an agent, this will also send a cancel request
    to the agent pod.
    """
    _, job = await require_internal_or_job_access(request, postgres_db, job_id)
    early_pinned_cancel = False

    try:
        if job.get("execution_lane") == "stateless":
            success, _queue_closed = await postgres_db.cancel_stateless_job(
                job_id, **_completion_dispatch_guard_kwargs()
            )
            if not success:
                refreshed = await postgres_db.get_job(job_id)
                if refreshed and refreshed.get("execution_lane") == "pinned":
                    # The defensive VM repair may have won the queue lock and
                    # moved this legacy row after our initial lane read. Fall
                    # through to the established pinned cancellation path.
                    job = refreshed
                elif (
                    refreshed
                    and (refreshed.get("context") or {}).get(
                        "_stateless_delete_pending"
                    )
                    is True
                ):
                    raise HTTPException(
                        status_code=409,
                        detail="Job deletion is already in progress",
                    )
                elif (
                    refreshed
                    and refreshed.get("status") not in ("completed", "cancelled")
                    and _active_completion_control_claim(refreshed)
                ):
                    raise HTTPException(
                        status_code=409,
                        detail=_completion_control_claim_detail(refreshed),
                    )
                elif not refreshed or refreshed.get("status") != "cancelled":
                    raise HTTPException(
                        status_code=400,
                        detail=(
                            "Job cannot be cancelled (already completed or cancelled)"
                        ),
                    )

            if job.get("execution_lane") == "stateless":
                # Publish descendant cancellation before any root-workspace
                # teardown. Stateless children can share this exact parent pod;
                # waiting below must include their live holders or cleanup could
                # pull the workspace out from under a still-running critic/scholar.
                descendants_settled = await _cascade_cancel_to_children(job_id)

                if descendants_settled:
                    # The current token remains live so renewal can return the
                    # cancelled status. Wait through the same bounded cooperative
                    # stop horizon as the pinned cancel route, then clean up only
                    # after the exact holder has closed (or the reaper reconciled)
                    # the queue row.
                    settled = await _wait_for_stateless_cancel_settle(job_id)
                    if not settled:
                        logger.error(
                            "Stateless cancel cleanup timed out for job %s; terminal "
                            "workspace lifecycle remains the teardown backstop",
                            job_id,
                        )
                else:
                    logger.error(
                        "Stateless cancel left root workspace %s intact because a "
                        "descendant worker was not proven quiescent",
                        job_id,
                    )
                    raise HTTPException(
                        status_code=503,
                        detail=(
                            "Descendant workspace authority retirement is incomplete"
                        ),
                    )

                job["status"] = "cancelled"
                try:
                    await _handle_scholar_completion(job, [])
                except Exception as exc:
                    logger.warning(
                        "Error handling scholar cancellation for %s: %s", job_id, exc
                    )
                await maybe_wake_session(postgres_db, job_id, "cancelled")
                _kick_session_wake_drain(postgres_db)
                _trigger_dispatch()
                await _resolve_job_notifications(job_id, user=None, hook="cancel")
                return {"status": "cancelled"}

        if COMPLETION_COMMANDS_ENABLED and job.get("execution_lane") == "pinned":
            # Linearize the user's cancellation before agent/VM/workspace I/O.
            # The finalizer's expected-status CAS must observe this terminal
            # control even if external quiescence takes minutes.  Checkpoint
            # pruning stays after quiescence below.
            early_pinned_cancel = await postgres_db.linearize_pinned_cancel(
                job_id,
                expected_status=str(job.get("status") or ""),
                completion_commands_enabled=True,
            )
            if not early_pinned_cancel:
                refreshed = await postgres_db.get_job(job_id)
                if (
                    refreshed
                    and refreshed.get("status") not in ("completed", "cancelled")
                    and _active_completion_control_claim(refreshed)
                ):
                    raise HTTPException(
                        status_code=409,
                        detail=_completion_control_claim_detail(refreshed),
                    )
                if not refreshed or refreshed.get("status") != "cancelled":
                    raise HTTPException(
                        status_code=400,
                        detail="Job cannot be cancelled (already completed or cancelled)",
                    )

        # If job is assigned to an agent, send cancel request to agent pod
        assigned_agent_id = job.get("assigned_agent_id")
        if assigned_agent_id:
            target = await _prepare_pinned_job_mutation_target(
                agent_id=str(assigned_agent_id),
                job_id=job_id,
                require_idle=False,
            )
            if target is not None:
                agent_url = (
                    f"http://{target.agent['pod_ip']}:{target.agent['pod_port']}"
                    "/job/cancel"
                )
                try:
                    # 130s timeout: agent tries cooperative stop for up to 120s,
                    # then falls back to hard kill. We wait slightly longer.
                    async with httpx.AsyncClient(timeout=130.0) as client:
                        response = await client.post(
                            agent_url,
                            json={
                                "reason": "Cancelled via cockpit",
                                "recipient": target.recipient.model_dump(mode="json"),
                            },
                        )
                        if response.status_code == 200:
                            resp_data = response.json()
                            if resp_data.get("graceful", True):
                                logger.info(
                                    f"Agent confirmed graceful cancel for job {job_id}"
                                )
                            else:
                                logger.warning(
                                    f"Agent hard-killed job {job_id} after cooperative timeout"
                                )
                        elif response.status_code == 408:
                            logger.warning(
                                f"Agent cancel timed out for job {job_id} — may still stop after current node"
                            )
                        else:
                            logger.warning(
                                f"Agent cancel returned {response.status_code}: {response.text}"
                            )
                except Exception as e:
                    # Agent might be unreachable — still cancel in DB
                    logger.warning(f"Could not reach agent to cancel job {job_id}: {e}")

        # Descendants can share the root Pod/VM/Docker namespace. Quiesce and
        # terminalize every child before the root performs namespace-wide
        # repository-agent retirement or compute deletion.
        if not await _cascade_cancel_to_children(job_id):
            raise HTTPException(
                status_code=503,
                detail="Descendant workspace authority retirement is incomplete",
            )

        # Archive workspace (snapshot to S3) and clean up VM/container
        try:
            await _archive_and_cleanup_workspace(job_id)
        except Exception as exc:
            # ``linearize_pinned_cancel`` may already have published the
            # terminal status.  Keep the row as the durable retry owner and
            # make the caller retry cleanup; the Docker lifecycle sweep also
            # owns any exact static-workspace residue.
            logger.warning(
                "Workspace cleanup remains pending for cancelled job %s: %s",
                job_id,
                exc,
            )
            raise HTTPException(
                status_code=503,
                detail="Workspace authority retirement is incomplete",
            ) from exc

        success = await postgres_db.cancel_job(job_id)
        if not success:
            # Agent may have already set status to 'cancelled' before we got here
            refreshed = await postgres_db.get_job(job_id)
            if refreshed and refreshed.get("status") == "cancelled":
                logger.info(f"Job {job_id} already cancelled (agent beat us to it)")
            else:
                raise HTTPException(
                    status_code=400,
                    detail="Job cannot be cancelled (already completed or cancelled)",
                )
        if early_pinned_cancel:
            try:
                await postgres_db.delete_checkpoint_thread(job_id)
            except Exception as exc:
                logger.debug("checkpoint prune skipped for %s: %s", job_id, exc)

        # If this was a scholar, unblock the parent job
        job["status"] = "cancelled"
        try:
            await _handle_scholar_completion(job, [])
        except Exception as e:
            logger.warning(f"Error handling scholar cancellation for {job_id}: {e}")

        # A session cancelling its own job does not need telling — but a user
        # cancelling from the cockpit does, and the session can't distinguish
        # the two from a status column. One cheap turn either way; the cost of
        # NOT sending is a session that waits on a job that will never report.
        # (Cascade-cancelled children are never session-created — they carry a
        # parent_job_id, so create_job withholds the backref — which is why
        # _cascade_cancel_to_children needs no hook of its own.)
        await maybe_wake_session(postgres_db, job_id, "cancelled")
        _kick_session_wake_drain(postgres_db)

        # Agent is being freed — trigger dispatcher for queued jobs
        _trigger_dispatch()
        await _resolve_job_notifications(job_id, user=None, hook="cancel")

        return {"status": "cancelled"}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e


@app.put("/api/jobs/{job_id}/pause")
async def pause_job(request: Request, job_id: str) -> dict[str, str]:
    """Pause a running job. **Dual-callable** (P4b): cockpit user with
    job access OR agent with ``X-Internal-Key`` (`pause_job` tool).

    If the job is assigned to an agent, sends a graceful pause request
    to the agent pod. The agent finishes its current graph node, saves
    the checkpoint, and becomes available for new work.

    The paused job re-enters the dispatch queue and will be auto-resumed
    when an agent becomes available.
    """
    _, job = await require_internal_or_job_access(request, postgres_db, job_id)
    try:
        if job["status"] != "processing":
            raise HTTPException(
                status_code=400,
                detail=f"Job cannot be paused (status: {job['status']})",
            )

        if job.get("execution_lane") == "stateless":
            success = await postgres_db.pause_stateless_job(
                job_id, **_completion_dispatch_guard_kwargs()
            )
            if not success:
                refreshed = await postgres_db.get_job(job_id)
                if _active_completion_control_claim(refreshed):
                    raise HTTPException(
                        status_code=409,
                        detail=_completion_control_claim_detail(refreshed),
                    )
                raise HTTPException(
                    status_code=400,
                    detail="Job cannot be paused (status may have changed)",
                )
            await maybe_wake_session(postgres_db, job_id, "paused")
            await _cascade_pause_to_children(job_id)
            return {"status": "paused", "job_id": job_id}

        # Flag-on publishes paused + an exact marker before old-executor I/O.
        # The marker remains on ambiguous timeout/failure so no successor can
        # be dispatched into a still-running agent or stale VM freeze.
        pause_claim = (
            await _claim_completion_pause(
                job_id,
                source="public_pause",
                expected_agent_id=(
                    str(job["assigned_agent_id"])
                    if job.get("assigned_agent_id")
                    else None
                ),
            )
            if COMPLETION_COMMANDS_ENABLED
            else None
        )
        release_pause_claim = False
        try:
            assigned_agent_id = job.get("assigned_agent_id")
            agent_quiescent = not assigned_agent_id
            if assigned_agent_id:
                target = await _prepare_pinned_job_mutation_target(
                    agent_id=str(assigned_agent_id),
                    job_id=job_id,
                    require_idle=False,
                )
                if target is None:
                    agent_quiescent = False
                else:
                    agent_url = (
                        f"http://{target.agent['pod_ip']}:{target.agent['pod_port']}"
                        "/job/pause"
                    )
                    try:
                        async with httpx.AsyncClient(timeout=130.0) as client:
                            response = await client.post(
                                agent_url,
                                json={
                                    "recipient": target.recipient.model_dump(
                                        mode="json"
                                    )
                                },
                            )
                        if response.status_code == 200:
                            agent_quiescent = True
                            logger.info(f"Agent confirmed pause for job {job_id}")
                        elif response.status_code == 408:
                            logger.warning(
                                "Pause timed out for job %s; retaining control "
                                "hold until bounded expiry",
                                job_id,
                            )
                        else:
                            logger.warning(
                                f"Agent pause returned {response.status_code}: "
                                f"{response.text}"
                            )
                    except httpx.TimeoutException:
                        logger.warning(
                            f"Timeout sending pause to agent for job {job_id}"
                        )
                    except Exception as e:
                        logger.warning(
                            f"Could not reach agent to pause job {job_id}: {e}"
                        )

            if pause_claim is None:
                success = await postgres_db.pause_job(job_id)
                if not success:
                    raise HTTPException(
                        status_code=400,
                        detail="Job cannot be paused (status may have changed)",
                    )
            release_pause_claim = agent_quiescent
        finally:
            if pause_claim is not None and release_pause_claim:
                await _abort_completion_control_claim(pause_claim)
            elif pause_claim is not None:
                logger.warning(
                    "Pause control hold retained for job %s after ambiguous "
                    "quiescence; bounded expiry will release it",
                    job_id,
                )

        # 'paused' is officer-only inside maybe_wake_session — it never enters
        # the ordinary jobs outbox (risk 6), but a paused job is exactly what
        # the project's officer exists to notice.
        await maybe_wake_session(postgres_db, job_id, "paused")

        # Cascade pause to processing child/subjobs
        await _cascade_pause_to_children(job_id)

        return {"status": "paused", "job_id": job_id}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e


@app.put("/api/jobs/{job_id}/agent-release")
async def agent_release_job(
    request: Request,
    job_id: str,
    agent_id: str | None = None,
    lease_token: int | None = None,
) -> dict[str, str]:
    """Agent-initiated job release (no agent callback). **Internal** (P4b)
    — requires ``X-Internal-Key``. Ingress strips this path.

    Called by an agent that is shutting down or otherwise releasing a job
    it was working on. Unlike the regular pause endpoint, this does NOT try to
    contact the agent pod (since the caller *is* the agent). A leased pinned
    job is handed to the authoritative expiry sweep, which advances durable
    redispatch accounting; only a genuine pre-lease NULL-lease row is paused
    here directly. Stateless work retains its queue-token release contract.
    """
    await require_internal(request)
    try:
        job = await postgres_db.get_job(job_id)
        lease_recovery_pending = False
        if not job:
            success = False
        elif (
            job.get("execution_lane", "pinned") == "pinned"
            and job.get("lease_expires_at") is not None
        ):
            if COMPLETION_COMMANDS_ENABLED and agent_id is None:
                raise HTTPException(
                    status_code=409,
                    detail="Agent release does not identify the assigned agent",
                )
            success = await postgres_db.route_pinned_agent_release_to_lease_recovery(
                job_id,
                completion_commands_enabled=COMPLETION_COMMANDS_ENABLED,
                expected_agent_id=agent_id,
            )
            lease_recovery_pending = success
        elif not COMPLETION_COMMANDS_ENABLED:
            success = await postgres_db.pause_job(job_id)
        else:
            if job.get("execution_lane") == "stateless":
                if lease_token is None:
                    raise HTTPException(
                        status_code=409,
                        detail="Agent release does not hold the worker lease",
                    )
                success = await postgres_db.pause_stateless_job(
                    job_id,
                    completion_commands_enabled=True,
                    expected_lease_token=lease_token,
                )
            else:
                if agent_id is None:
                    raise HTTPException(
                        status_code=409,
                        detail="Agent release does not identify the assigned agent",
                    )
                success = await postgres_db.pause_job(
                    job_id,
                    completion_commands_enabled=True,
                    expected_agent_id=agent_id,
                )
        if not success:
            refreshed = (
                await postgres_db.get_job(job_id)
                if COMPLETION_COMMANDS_ENABLED
                else None
            )
            if _active_completion_control_claim(refreshed):
                raise HTTPException(
                    status_code=409,
                    detail=_completion_control_claim_detail(refreshed),
                )
            if (
                COMPLETION_COMMANDS_ENABLED
                and refreshed
                and refreshed.get("status") == "processing"
            ):
                raise HTTPException(
                    status_code=409,
                    detail="Job ownership changed before agent release",
                )
            raise HTTPException(
                status_code=400,
                detail="Job cannot be paused (not found or status changed)",
            )
        if lease_recovery_pending:
            logger.info(
                "Agent released leased job %s — lease expiry recovery pending",
                job_id,
            )
            return {"status": "lease_recovery_pending", "job_id": job_id}
        logger.info(f"Agent released job {job_id} — paused for reassignment")
        _trigger_dispatch()
        return {"status": "paused", "job_id": job_id}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e


# =============================================================================
# Agent Messaging Endpoints (Live Communication)
# =============================================================================


class MessageSendRequest(BaseModel):
    """Request body for agent-initiated message send."""

    to: str = Field(
        ...,
        description="Recipient: 'user' for job owner, or display name / email of a project member",
    )
    subject: str = Field(..., max_length=200, description="Subject line")
    message: str = Field(..., max_length=5000, description="Message body (markdown)")
    mode: str = Field("async", description="'async' or 'blocking'")
    thread_id: str | None = Field(
        None, description="Existing thread ID, or null for new thread"
    )
    project_id: str | None = Field(
        None, description="Project ID for member resolution (auto-filled from job)"
    )
    lease_token: int | None = Field(
        None,
        ge=1,
        description="Exact stateless worker lease; ignored for pinned jobs",
    )
    agent_id: str | None = Field(
        None,
        description="Exact pinned agent assignment; ignored for stateless jobs",
    )
    purpose: str | None = Field(
        None,
        description=(
            "Optional self-declared label (question|blocker|update). "
            "Presentation/coalescing only — routing never trusts it; "
            "mode='blocking' stays the mechanical signal."
        ),
    )
    routing_generation: UUID | None = Field(
        None,
        description=(
            "Internal idempotency identity for this logical send. It conveys no "
            "audience, quota, recipient, or routing authority."
        ),
    )


class MessageReplyRequest(BaseModel):
    """Request body for human reply to agent message."""

    message: str = Field(..., description="Reply body")
    urgent: bool = Field(False, description="Deliver as immediate interrupt")


def _mask_email(email: str) -> str:
    """Mask email for display: alice@example.com -> a***@example.com"""
    if not email or "@" not in email:
        return email or ""
    local, domain = email.rsplit("@", 1)
    return f"{local[0]}***@{domain}" if len(local) > 1 else f"*@{domain}"


_VALID_MESSAGE_PURPOSES = ("question", "blocker", "update")


async def _send_officer_routed_message(
    *,
    job: dict[str, Any],
    job_id: str,
    request: MessageSendRequest,
    routing: dict[str, Any],
    applied_policy: str,
    thread_id: str,
    sequence: int,
    user_id: str,
    recipient_email: str,
    recipient_name: str,
    purpose: str | None,
    routing_generation: str,
    quota_intent: dict[str, Any],
) -> dict[str, Any] | None:
    """Deliver one worker message through the officer chain (M2/M3).

    Returns the endpoint response dict on success. Returns None when the
    officer leg failed for infrastructure reasons — §5.1's immediate
    fallback: the caller re-runs the plain user_direct path, the job was NOT
    frozen (the routed transaction is all-or-nothing). Raises
    HTTPException(409) when the job's freeze guard/CAS lost — the job is no
    longer freezable and no fallback may freeze it either.
    """
    from services import message_routing as routing_svc

    officer_tid = str(routing["officer_thread_id"])
    incarnation = routing.get("officer_incarnation")
    minutes = int(
        routing.get("officer_response_minutes")
        or routing_svc.DEFAULT_OFFICER_RESPONSE_MINUTES
    )
    project_id = routing.get("project_id")
    now = datetime.now(timezone.utc)
    state = "pending_officer" if applied_policy == "officer_first" else "pending_both"
    blocking = request.mode == "blocking"
    # One server-owned generation is both the route identity and the quota
    # charge identity.  Retries can therefore recover the same durable intent
    # without inventing a second route or consuming a second bucket slot.
    route_id = routing_generation
    snapshot = routing_svc.snapshot_for_route(
        routing, applied=applied_policy, purpose=purpose
    )
    transitions = [
        routing_svc.build_transition(
            None,
            state,
            actor_kind="system",
            actor_id="send",
            officer_incarnation=incarnation,
            note=f"created ({applied_policy}, {'blocking' if blocking else 'async'})",
        )
    ]

    def _response(
        *,
        recipient: str,
        to_name: str,
        dispatch: dict[str, Any] | None,
        route_state: str,
    ) -> dict[str, Any]:
        return {
            "status": "sent",
            "thread_id": thread_id,
            "sequence": sequence,
            "file_path": f"messages/{thread_id}/{sequence:03d}_sent.md",
            "recipient": recipient,
            "to_name": to_name,
            "email_delivered": bool((dispatch or {}).get("email", False)),
            "channels": dispatch or {},
            "routing": {
                "policy": routing.get("requested"),
                "applied": applied_policy,
                "reason": routing.get("reason"),
                "route_id": route_id,
                "state": route_state,
                "officer_response_minutes": minutes,
            },
        }

    async def _dispatch_user_leg(
        *, message_log_id: str | None, blocking: bool
    ) -> dict[str, Any]:
        # The feed row is the user leg (D1); the ledger row id rides in the
        # payload so the (possibly deferred) email's Message-ID lands on
        # message_log for In-Reply-To routing.
        result = await notification_service.record_agent_message(
            user_id=user_id,
            job={
                **job,
                "config_name": canonical_config_name(
                    job.get("config_name") or "worker_base"
                ),
            },
            job_id=job_id,
            thread_id=thread_id,
            sequence=sequence,
            subject=request.subject,
            message_md=request.message,
            blocking=blocking,
            message_log_id=message_log_id,
            deliver_to=(recipient_email, recipient_name),
        )
        return result.as_dispatch()

    # Claim the non-idempotent side of this generation before creating a
    # route. A concurrent retry can reserve the same quota row, but cannot
    # create a second route or call a provider while this short attempt lease
    # is live. Sticky acceptance makes later request retries read-only.
    attempt = await routing_svc.begin_delivery_attempt(postgres_db, quota_intent)
    if not attempt.get("delivery_claimed"):
        if attempt.get("accepted"):
            existing = await postgres_db.get_message_route(route_id)
            return _response(
                recipient=(
                    "project officer"
                    if applied_policy == "officer_first"
                    else _mask_email(recipient_email)
                ),
                to_name=(
                    "Project officer"
                    if applied_policy == "officer_first"
                    else recipient_name
                ),
                dispatch=None,
                route_state=(str(existing.get("state")) if existing else state),
            )
        raise HTTPException(
            status_code=409,
            detail="This message generation already has a delivery attempt in progress",
        )

    if blocking:
        deadlines = routing_svc.route_deadlines(
            blocking=True,
            state=state,
            officer_response_minutes=minutes,
            timeout_hours=routing_svc.blocking_timeout_hours(job),
            now=now,
        )
        freeze_data = {
            "status": "waiting_for_reply",
            "freeze_type": "blocking_message",
            "thread_id": thread_id,
            "subject": request.subject,
            "timestamp": now.isoformat(),
            "job_id": job_id,
            # Route/freeze generation fence: the reconciler's resume matches
            # this against the route it timed out, so a job re-frozen by a
            # LATER message can never be resumed against an old route.
            "route_id": route_id,
            "routing": applied_policy,
        }
        label = purpose or "question"
        if state == "pending_officer":
            wake_summary = (
                f"BLOCKING worker {label} from job {job_id[:8]} (thread "
                f"{thread_id}): {request.subject!r} — the worker is frozen "
                f"waiting. Answer with reply_to_job_message or hand it to the "
                f"user with escalate_job_message; unanswered it escalates "
                f"automatically in {minutes} min."
            )
        else:
            wake_summary = (
                f"BLOCKING worker {label} from job {job_id[:8]} (thread "
                f"{thread_id}): {request.subject!r} — the user was notified "
                f"in parallel; the first valid answer resumes the worker."
            )
        route = {
            "route_id": route_id,
            "job_id": job_id,
            "project_id": project_id,
            "thread_id": thread_id,
            "policy_snapshot": snapshot,
            "state": state,
            "officer_thread_id": officer_tid,
            "officer_incarnation": incarnation,
            "officer_deadline": deadlines["officer_deadline"],
            "total_deadline": deadlines["total_deadline"],
            "transitions": transitions,
            "routing_generation": routing_generation,
            "effective_audience": (
                "officer" if state == "pending_officer" else "officer_and_user"
            ),
        }
        wake = {
            "thread_id": officer_tid,
            "source": "worker_message",
            "dedup_key": f"route:{route_id}",
            "payload": {
                "summary": wake_summary,
                "job_id": job_id,
                "thread_id": thread_id,
                "subject": request.subject,
                "blocking": True,
                "purpose": purpose,
                "route_id": route_id,
            },
        }
        message_entry = {
            "user_id": user_id,
            "recipient_email": recipient_email if state == "pending_both" else None,
            "subject": request.subject,
            "message": request.message,
            "status": "sent" if state == "pending_officer" else "pending",
        }
        lane = str(job.get("execution_lane") or "pinned")
        try:
            created = await postgres_db.create_routed_blocking_freeze(
                job_id,
                freeze_data,
                route=route,
                message_entry=message_entry,
                wake=wake,
                expected_lane=lane,
                lease_token=request.lease_token,
                agent_id=request.agent_id,
                completion_commands_enabled=COMPLETION_COMMANDS_ENABLED,
            )
        except Exception:
            await routing_svc.settle_delivery_attempt(
                postgres_db,
                quota_intent,
                attempt,
                accepted=False,
                failure_class="route_commit_failed",
            )
            logger.exception(
                "Officer-routed blocking send failed for job %s — falling "
                "back to direct user delivery (§5.1)",
                job_id[:8],
            )
            return None
        if created is None:
            await routing_svc.settle_delivery_attempt(
                postgres_db,
                quota_intent,
                attempt,
                accepted=False,
                failure_class="route_guard_lost",
            )
            raise HTTPException(
                status_code=409,
                detail="Job changed before blocking message was committed",
            )
        # Latency: the wake row is durable; this just delivers it now.
        _kick_officer_event_drain(postgres_db)

        if state == "pending_officer":
            await routing_svc.settle_delivery_attempt(
                postgres_db,
                quota_intent,
                attempt,
                accepted=True,
                detail="durable officer route and wake queued",
            )

        dispatch: dict[str, Any] | None = None
        if state == "pending_both":
            try:
                dispatch = await _dispatch_user_leg(
                    message_log_id=str(created["originating_message_id"]),
                    blocking=True,
                )
            except Exception:
                await routing_svc.settle_delivery_attempt(
                    postgres_db,
                    quota_intent,
                    attempt,
                    accepted=False,
                    failure_class="notifier_exception",
                )
                await postgres_db.settle_outbound_message_log(
                    created["originating_message_id"],
                    accepted=False,
                    error_message="notifier exception",
                )
                # user_delivery_at stays NULL — the reconciler redelivers.
                logger.warning(
                    "officer_and_user user leg failed for route %s "
                    "(reconciler will redeliver)",
                    route_id[:8],
                    exc_info=True,
                )
            else:
                outcome = routing_svc.classify_dispatch(dispatch)
                await routing_svc.settle_delivery_attempt(
                    postgres_db,
                    quota_intent,
                    attempt,
                    accepted=outcome.accepted,
                    failure_class=(None if outcome.accepted else "provider_rejected"),
                    detail=outcome.detail,
                )
                await postgres_db.settle_outbound_message_log(
                    created["originating_message_id"],
                    accepted=outcome.accepted,
                    error_message=outcome.detail,
                    email_message_id=dispatch.get("email_message_id"),
                )
                if outcome.accepted:
                    await postgres_db.mark_route_user_delivery(route_id)
        if state == "pending_officer":
            return _response(
                recipient="project officer",
                to_name="Project officer",
                dispatch=None,
                route_state=state,
            )
        return _response(
            recipient=_mask_email(recipient_email),
            to_name=recipient_name,
            dispatch=dispatch,
            route_state=state,
        )

    # ---- async modes: no freeze; the route row IS the durable inbox item.
    if applied_policy == "officer_first":
        # Officer only initially (§2 policy table) — no user notification.
        # No wake either: async items coalesce into the officer's next
        # inbox/SITREP section instead of costing a paid wake each.
        try:
            # notification-ledger: the officer-only leg's outbound record (no user notification by policy)
            log_row = await postgres_db.log_message(
                job_id=job_id,
                user_id=user_id,
                thread_id=thread_id,
                direction="outbound",
                recipient_email=None,
                subject=request.subject,
                message=request.message,
                mode="async",
                status="sent",
                routing_generation=routing_generation,
                effective_audience="officer",
            )
            created_route = await postgres_db.create_message_route(
                {
                    "route_id": route_id,
                    "job_id": job_id,
                    "project_id": project_id,
                    "thread_id": thread_id,
                    "originating_message_id": (log_row or {}).get("id"),
                    "policy_snapshot": snapshot,
                    "state": "pending_officer",
                    "blocking": False,
                    "officer_thread_id": officer_tid,
                    "officer_incarnation": incarnation,
                    "transitions": transitions,
                    "routing_generation": routing_generation,
                    "effective_audience": "officer",
                }
            )
            if not created_route:
                await routing_svc.settle_delivery_attempt(
                    postgres_db,
                    quota_intent,
                    attempt,
                    accepted=False,
                    failure_class="route_commit_failed",
                )
                return None
        except Exception:
            await routing_svc.settle_delivery_attempt(
                postgres_db,
                quota_intent,
                attempt,
                accepted=False,
                failure_class="route_commit_failed",
            )
            logger.exception(
                "Async officer_first route failed for job %s — falling back "
                "to direct user delivery",
                job_id[:8],
            )
            return None
        await routing_svc.settle_delivery_attempt(
            postgres_db,
            quota_intent,
            attempt,
            accepted=True,
            detail="durable officer route queued",
        )
        return _response(
            recipient="project officer",
            to_name="Project officer",
            dispatch=None,
            route_state="pending_officer",
        )

    # officer_and_user, async: immediate delivery to both (ratified) — the
    # user leg is the unchanged notification path; the officer sees the open
    # route in his next inbox/SITREP.
    # Persist the Officer inbox route before invoking the user notifier. The
    # reconciler can therefore repair a crash at every later fault point.
    # notification-ledger: prelogged before the feed row so its Message-ID can be stamped
    log_row = await postgres_db.log_message(
        job_id=job_id,
        user_id=user_id,
        thread_id=thread_id,
        direction="outbound",
        recipient_email=recipient_email,
        subject=request.subject,
        message=request.message,
        mode="async",
        status="pending",
        routing_generation=routing_generation,
        effective_audience="officer_and_user",
    )
    created_route = await postgres_db.create_message_route(
        {
            "route_id": route_id,
            "job_id": job_id,
            "project_id": project_id,
            "thread_id": thread_id,
            "originating_message_id": (log_row or {}).get("id"),
            "policy_snapshot": snapshot,
            "state": "pending_both",
            "blocking": False,
            "officer_thread_id": officer_tid,
            "officer_incarnation": incarnation,
            "transitions": transitions,
            "routing_generation": routing_generation,
            "effective_audience": "officer_and_user",
        }
    )
    if not created_route:
        await routing_svc.settle_delivery_attempt(
            postgres_db,
            quota_intent,
            attempt,
            accepted=False,
            failure_class="route_commit_failed",
        )
        return None
    try:
        dispatch = await _dispatch_user_leg(
            message_log_id=(str(log_row["id"]) if log_row else None), blocking=False
        )
    except Exception:
        await routing_svc.settle_delivery_attempt(
            postgres_db,
            quota_intent,
            attempt,
            accepted=False,
            failure_class="notifier_exception",
        )
        raise
    outcome = routing_svc.classify_dispatch(dispatch)
    await routing_svc.settle_delivery_attempt(
        postgres_db,
        quota_intent,
        attempt,
        accepted=outcome.accepted,
        failure_class=(None if outcome.accepted else "provider_rejected"),
        detail=outcome.detail,
    )
    if dispatch.get("email_message_id") and log_row:
        await postgres_db.settle_outbound_message_log(
            str(log_row["id"]),
            accepted=outcome.accepted,
            error_message=outcome.detail,
            email_message_id=dispatch.get("email_message_id"),
        )
    elif log_row:
        await postgres_db.settle_outbound_message_log(
            str(log_row["id"]),
            accepted=outcome.accepted,
            error_message=outcome.detail,
        )
    if outcome.accepted:
        await postgres_db.mark_route_user_delivery(route_id)
    return _response(
        recipient=_mask_email(recipient_email),
        to_name=recipient_name,
        dispatch=dispatch,
        route_state="pending_both",
    )


@app.post("/api/jobs/{job_id}/messages/send")
async def send_agent_message(
    req: Request,
    job_id: str,
    request: MessageSendRequest,
) -> dict[str, Any]:
    """Send a message from an agent to a human. **Internal** (P4b) —
    requires ``X-Internal-Key``. Ingress strips this path.

    The Pydantic body keeps its historical name ``request`` to avoid
    churning the body of this long handler; the FastAPI Request handle
    is named ``req`` for the gate call only.

    Resolves recipient from job ownership, checks rate limits, sends
    email, and logs to message_log.
    """
    await require_internal(req)
    try:
        # Validate job exists and has an owner
        job = await postgres_db.get_job(job_id)
        if not job:
            raise HTTPException(status_code=404, detail=f"Job '{job_id}' not found")

        user_id = str(job.get("user_id", "")) if job.get("user_id") else None
        if not user_id:
            raise HTTPException(
                status_code=404,
                detail="Job has no associated user. Cannot resolve recipient.",
            )

        # Resolve recipient
        if request.to == "user":
            # Job owner
            user = await postgres_db.get_user(user_id)
            if not user or not user.get("email"):
                raise HTTPException(
                    status_code=404,
                    detail="Job owner has no email address.",
                )
            recipient_email = user["email"]
            recipient_name = user.get("display_name", "User")
        else:
            # Multi-recipient: resolve from project members
            project_id = request.project_id or (
                str(job["project_id"]) if job.get("project_id") else None
            )
            if not project_id:
                raise HTTPException(
                    status_code=400,
                    detail=(
                        f"Cannot resolve recipient '{request.to}': "
                        "job has no project_id. Use to='user' for the job owner."
                    ),
                )
            members = await postgres_db.get_project_members(project_id)
            if not members:
                raise HTTPException(
                    status_code=404,
                    detail="No project members found.",
                )
            # Match by display_name or email (case-insensitive)
            to_lower = request.to.lower()
            match = None
            for m in members:
                if (
                    m.get("email", "").lower() == to_lower
                    or m.get("display_name", "").lower() == to_lower
                ):
                    match = m
                    break
            if not match:
                # Fallback: contacts registry (channel-aware; email path here)
                resolved = await postgres_db.resolve_contact(
                    project_id, request.to, "email"
                )
                if resolved["status"] == "ok":
                    recipient_email = resolved["address"]
                    recipient_name = resolved["display_name"]
                    # Contacts don't have a user_id — keep job owner's
                elif resolved["status"] == "no_channel_address":
                    raise HTTPException(
                        status_code=404,
                        detail=(
                            f"{resolved['display_name']} has no email address "
                            f"({', '.join(resolved['channels']) or 'no addresses'} only)."
                        ),
                    )
                elif resolved["status"] == "ambiguous":
                    cands = "; ".join(
                        f"{c['display_name']} <{', '.join(c['addresses'])}>"
                        for c in resolved["candidates"]
                    )
                    raise HTTPException(
                        status_code=404,
                        detail=(
                            f"Recipient '{request.to}' is ambiguous — specify an address. "
                            f"Candidates: {cands}"
                        ),
                    )
                else:
                    available = ", ".join(m.get("display_name", "?") for m in members)
                    contact_rows = await postgres_db.get_project_contacts(project_id)
                    if contact_rows:
                        names = ", ".join(
                            c.get("display_name", "?") for c in contact_rows
                        )
                        available += f" | Contacts: {names}"
                    raise HTTPException(
                        status_code=404,
                        detail=(
                            f"Recipient '{request.to}' not found among project members "
                            f"or contacts. Available: {available}"
                        ),
                    )
            else:
                recipient_email = match["email"]
                recipient_name = match.get("display_name", "User")
                user_id = str(match["user_id"])

        # Generate thread_id if not provided
        thread_id = request.thread_id or secrets.token_hex(3)

        # Get sequence number
        sequence = await postgres_db.get_message_sequence(job_id, thread_id)

        # M1 — resolve the project's worker-message routing policy for
        # owner-directed messages (officer_message_routing.md §2). Explicit
        # named recipients stay direct; any resolver failure degrades to
        # user_direct — the officer layer must never break plain messaging.
        purpose = (
            request.purpose if request.purpose in _VALID_MESSAGE_PURPOSES else None
        )
        routing: dict[str, Any] | None = None
        if request.to == "user":
            try:
                from services import message_routing as _routing_svc

                routing = await _routing_svc.resolve_effective_policy(postgres_db, job)
            except Exception:
                logger.exception(
                    "Worker-message policy resolution failed for job %s — "
                    "using user_direct",
                    job_id[:8],
                )
                routing = None

        applied_policy = routing["applied"] if routing else "user_direct"
        applied_reason = (
            routing["reason"]
            if routing
            else ("explicit_recipient" if request.to != "user" else "resolver_failed")
        )
        if (
            applied_policy == "officer_first"
            and request.mode == "blocking"
            and routing is not None
            and routing.get("officer_held")
        ):
            # §5.1: a held officer is unavailable for the blocking SLA —
            # the question goes to the user immediately. Async officer_first
            # keeps its route and queues behind the hold.
            applied_policy = "user_direct"
            applied_reason = "officer_held"

        # OC-07: quota follows the server-resolved durable audience.  The
        # generation is opaque idempotency only; it conveys no routing or
        # quota authority and all audience selection above is server-owned.
        from services import message_routing as _routing_svc

        routing_generation = str(request.routing_generation or uuid4())
        route_project_id = str(job["project_id"]) if job.get("project_id") else None

        async def _reserve_delivery(
            bucket: str,
            audience: str,
            reason: str,
        ) -> dict[str, Any] | JSONResponse:
            intent = await _routing_svc.reserve_quota_intent(
                postgres_db,
                routing_generation=routing_generation,
                route_id=routing_generation,
                bucket=bucket,
                effective_audience=audience,
                job_id=job_id,
                project_id=route_project_id,
                user_id=user_id if bucket == "human" else None,
                reason=reason,
            )
            if intent.get("allowed"):
                return intent
            limit_name = str(intent.get("limit") or "message_quota")
            retry_after = int(intent.get("retry_after_seconds") or 3600)
            # notification-ledger: durable intent row logged before any provider I/O
            await postgres_db.log_message(
                job_id=job_id,
                thread_id=thread_id,
                direction="outbound",
                subject=request.subject,
                message=request.message,
                status="rate_limited",
                user_id=user_id,
                mode=request.mode,
                error_message=f"Rate limit: {limit_name}",
                routing_generation=routing_generation,
                effective_audience=audience,
            )
            return JSONResponse(
                status_code=429,
                content={
                    "status": "rate_limited",
                    "error": f"Rate limit exceeded: {limit_name}",
                    "bucket": bucket,
                    "retry_after_seconds": retry_after,
                },
            )

        if applied_policy in ("officer_first", "officer_and_user"):
            audience = (
                "officer" if applied_policy == "officer_first" else "officer_and_user"
            )
            quota_intent = await _reserve_delivery(
                "officer_internal" if applied_policy == "officer_first" else "human",
                audience,
                applied_reason,
            )
            if isinstance(quota_intent, JSONResponse):
                return quota_intent
            officer_result = await _send_officer_routed_message(
                job=job,
                job_id=job_id,
                request=request,
                routing=routing,
                applied_policy=applied_policy,
                thread_id=thread_id,
                sequence=sequence,
                user_id=user_id,
                recipient_email=recipient_email,
                recipient_name=recipient_name,
                purpose=purpose,
                routing_generation=routing_generation,
                quota_intent=quota_intent,
            )
            if officer_result is not None:
                return officer_result
            # §5.1 immediate fallback: the officer leg failed without
            # freezing the job — deliver directly to the user instead.
            applied_policy = "user_direct"
            applied_reason = "officer_route_failed"

        direct_audience = "human" if request.to == "user" else "explicit_recipient"
        direct_intent = await _reserve_delivery(
            "human", direct_audience, applied_reason
        )
        if isinstance(direct_intent, JSONResponse):
            return direct_intent

        direct_attempt = await _routing_svc.begin_delivery_attempt(
            postgres_db, direct_intent
        )
        if not direct_attempt.get("delivery_claimed"):
            if direct_attempt.get("accepted"):
                return {
                    "status": "sent",
                    "thread_id": thread_id,
                    "sequence": sequence,
                    "file_path": f"messages/{thread_id}/{sequence:03d}_sent.md",
                    "recipient": _mask_email(recipient_email),
                    "to_name": recipient_name,
                    "email_delivered": False,
                    "channels": {},
                    "routing": {
                        "policy": (
                            routing.get("requested") if routing else "user_direct"
                        ),
                        "applied": "user_direct",
                        "reason": "idempotent_replay",
                        "route_id": (
                            routing_generation if request.mode == "blocking" else None
                        ),
                        "state": (
                            "user_direct" if request.mode == "blocking" else None
                        ),
                    },
                }
            raise HTTPException(
                status_code=409,
                detail=(
                    "This message generation already has a delivery attempt in progress"
                ),
            )

        route_id: str | None = None
        freeze_data: dict[str, Any] | None = None
        direct_message_id: str | None = None
        if request.mode == "blocking":
            route_id = routing_generation
            freeze_data = {
                "status": "waiting_for_reply",
                "freeze_type": "blocking_message",
                "thread_id": thread_id,
                "subject": request.subject,
                "timestamp": datetime.now(timezone.utc).isoformat(),
                "job_id": job_id,
                "route_id": route_id,
                "routing": "user_direct",
            }
            # ONE transaction: the logical message, the route, and the job's
            # waiting_for_reply flip on the same route generation (audit
            # OC-01). This used to be a freeze followed by best-effort route
            # bookkeeping, so a crash between them left a job waiting forever
            # with nothing for the total-timeout reconciler to claim —
            # and user_direct is the DEFAULT policy, so that was the common
            # path. Under backlog pools such a job also held its one-shot
            # ticket claim and pool capacity indefinitely.
            #
            # External delivery happens AFTER this commits. If the commit
            # fails, nothing is written and the job stays runnable; there is
            # no compensating "unfreeze" to get wrong.
            from services import message_routing as _routing_svc

            _snapshot = (
                _routing_svc.snapshot_for_route(
                    routing,
                    applied="user_direct",
                    reason=applied_reason,
                    purpose=purpose,
                )
                if routing
                else {
                    "worker_messages": "user_direct",
                    "applied": "user_direct",
                    "reason": applied_reason,
                    "resolved_at": datetime.now(timezone.utc).isoformat(),
                }
            )
            _deadlines = _routing_svc.route_deadlines(
                blocking=True,
                state="user_direct",
                officer_response_minutes=0,
                timeout_hours=_routing_svc.blocking_timeout_hours(job),
            )
            _direct_route = {
                "route_id": route_id,
                "job_id": job_id,
                "project_id": (
                    str(job["project_id"]) if job.get("project_id") else None
                ),
                "thread_id": thread_id,
                "policy_snapshot": _snapshot,
                "state": "user_direct",
                "blocking": True,
                "total_deadline": _deadlines["total_deadline"],
                "transitions": [
                    _routing_svc.build_transition(
                        None,
                        "user_direct",
                        actor_kind="system",
                        actor_id="send",
                        note=f"created (user_direct: {applied_reason})",
                    )
                ],
                "routing_generation": routing_generation,
                "effective_audience": direct_audience,
            }
            try:
                direct_committed = await postgres_db.create_routed_blocking_freeze(
                    job_id,
                    freeze_data,
                    route=_direct_route,
                    message_entry={
                        "user_id": user_id,
                        "recipient_email": recipient_email,
                        "subject": request.subject,
                        "message": request.message,
                        "status": "pending",
                    },
                    wake=None,
                    expected_lane=str(job.get("execution_lane") or "pinned"),
                    lease_token=request.lease_token,
                    agent_id=request.agent_id,
                    completion_commands_enabled=COMPLETION_COMMANDS_ENABLED,
                )
            except Exception:
                await _routing_svc.settle_delivery_attempt(
                    postgres_db,
                    direct_intent,
                    direct_attempt,
                    accepted=False,
                    failure_class="route_commit_failed",
                )
                raise
            if direct_committed is None:
                await _routing_svc.settle_delivery_attempt(
                    postgres_db,
                    direct_intent,
                    direct_attempt,
                    accepted=False,
                    failure_class="route_guard_lost",
                )
                raise HTTPException(
                    status_code=409,
                    detail="Job changed before blocking message was committed",
                )
            direct_message_id = str(direct_committed["originating_message_id"])
        else:
            # Async direct delivery has the same write-before-side-effect law as
            # the blocking route transaction.  In particular, a provider that
            # accepts the notification immediately before this process dies
            # must not leave the durable ledger as the only operator-visible
            # account of what was sent.
            # notification-ledger: prelogged before the feed row so its Message-ID can be stamped
            direct_message = await postgres_db.log_message(
                job_id=job_id,
                user_id=user_id,
                thread_id=thread_id,
                direction="outbound",
                recipient_email=recipient_email,
                subject=request.subject,
                message=request.message,
                mode=request.mode,
                status="pending",
                routing_generation=routing_generation,
                effective_audience=direct_audience,
            )
            if not direct_message or not direct_message.get("id"):
                await _routing_svc.settle_delivery_attempt(
                    postgres_db,
                    direct_intent,
                    direct_attempt,
                    accepted=False,
                    failure_class="message_log_failed",
                )
                raise HTTPException(
                    status_code=503,
                    detail="Message delivery could not be durably recorded",
                )
            direct_message_id = str(direct_message["id"])

        # Dispatch only after the durable intent (and, for blocking sends,
        # the route/freeze unit) exists.  Attempt and settlement are separate
        # durable facts so provider failure never masquerades as acceptance.
        try:
            record_result = await notification_service.record_agent_message(
                user_id=user_id,
                job={
                    **job,
                    "config_name": canonical_config_name(
                        job.get("config_name") or "worker_base"
                    ),
                },
                job_id=job_id,
                thread_id=thread_id,
                sequence=sequence,
                subject=request.subject,
                message_md=request.message,
                blocking=request.mode == "blocking",
                message_log_id=direct_message_id,
                # A named contact (no user row) still gets the mail; the feed
                # row belongs to the owner, who is the party with the stake.
                deliver_to=(recipient_email, recipient_name),
            )
            dispatch_results = record_result.as_dispatch()
        except Exception:
            await _routing_svc.settle_delivery_attempt(
                postgres_db,
                direct_intent,
                direct_attempt,
                accepted=False,
                failure_class="notifier_exception",
            )
            if direct_message_id is not None:
                await postgres_db.settle_outbound_message_log(
                    direct_message_id,
                    accepted=False,
                    error_message="notification provider raised an exception",
                )
            raise

        dispatch_outcome = _routing_svc.classify_dispatch(dispatch_results)
        await _routing_svc.settle_delivery_attempt(
            postgres_db,
            direct_intent,
            direct_attempt,
            accepted=dispatch_outcome.accepted,
            failure_class=(None if dispatch_outcome.accepted else "provider_rejected"),
            detail=dispatch_outcome.detail,
        )

        email_sent = dispatch_results.get("email", False)
        email_msg_id = dispatch_results.get("email_message_id")

        # Both modes prelogged exactly one row before provider I/O. Settle that
        # row instead of appending a second, outcome-only message.
        if direct_message_id is not None:
            await postgres_db.settle_outbound_message_log(
                direct_message_id,
                accepted=dispatch_outcome.accepted,
                error_message=dispatch_outcome.detail,
                email_message_id=email_msg_id,
            )
        if request.mode == "blocking":
            if dispatch_outcome.accepted:
                await postgres_db.mark_route_user_delivery(str(route_id))

        file_path = f"messages/{thread_id}/{sequence:03d}_sent.md"

        response: dict[str, Any] = {
            "status": "sent",
            "thread_id": thread_id,
            "sequence": sequence,
            "file_path": file_path,
            "recipient": _mask_email(recipient_email),
            "to_name": recipient_name,
            "email_delivered": email_sent,
            "channels": dispatch_results,
        }
        if request.to == "user":
            response["routing"] = {
                "policy": routing.get("requested") if routing else "user_direct",
                "applied": "user_direct",
                "reason": applied_reason,
                "route_id": route_id,
                "state": "user_direct" if route_id else None,
            }
        return response

    except HTTPException:
        raise
    except Exception as e:
        logger.exception(f"Failed to send agent message for job {job_id}: {e}")
        raise HTTPException(status_code=500, detail=str(e)) from e


def _format_freeze_notification(
    freeze_type: str,
    freeze_data: dict[str, Any],
    job_id: str,
    config_name: str,
    description: str,
) -> tuple[str, str]:
    """Format notification subject and body for a freeze event."""
    short_id = job_id[:8]

    if freeze_type == "vm_upgrade_required":
        command = freeze_data.get("command", "unknown")
        subject = f"Job {short_id} needs VM upgrade (sudo detected)"
        message_md = (
            f"**Job `{short_id}`** (`{config_name}`) attempted a sudo command "
            f"and needs approval to continue.\n\n"
            f"**Command:** `{command}`\n\n"
            f"**Description:** {description}\n\n"
            f"Approve a VM upgrade or reject to keep the job paused."
        )

    elif freeze_type == "job_complete":
        summary = freeze_data.get("summary", "No summary provided")
        confidence = freeze_data.get("confidence", 0)
        deliverables = freeze_data.get("deliverables", [])
        confidence_str = (
            f"{confidence:.0%}"
            if isinstance(confidence, (int, float))
            else str(confidence)
        )
        deliverables_str = (
            "\n".join(f"- `{d}`" for d in deliverables)
            if deliverables
            else "*(none listed)*"
        )
        subject = f"Job {short_id} completed — review required"
        message_md = (
            f"**Job `{short_id}`** (`{config_name}`) has completed and is awaiting review.\n\n"
            f"**Summary:** {summary}\n\n"
            f"**Confidence:** {confidence_str}\n\n"
            f"**Deliverables:**\n{deliverables_str}"
        )

    elif freeze_type == "budget_exceeded":
        phase_number = freeze_data.get("phase_number", "?")
        reason = freeze_data.get("reason", "Tool call budget exceeded")
        tool_calls = freeze_data.get("tool_calls_this_phase", "?")
        subject = f"Job {short_id} frozen — budget exceeded (phase {phase_number})"
        message_md = (
            f"**Job `{short_id}`** (`{config_name}`) has been frozen because "
            f"the tool call budget was exceeded.\n\n"
            f"**Phase:** #{phase_number}\n"
            f"**Tool calls this phase:** {tool_calls}\n"
            f"**Reason:** {reason}\n\n"
            f"**Description:** {description}"
        )

    elif freeze_type == "llm_unavailable":
        classification = freeze_data.get("classification", "unknown")
        model = freeze_data.get("model", "?")
        summary = freeze_data.get("error_summary") or "LLM endpoint unavailable"
        attempt = freeze_data.get("attempt", "?")
        subject = f"Job {short_id} FAILED — LLM endpoint unavailable (gave up)"
        message_md = (
            f"**Job `{short_id}`** (`{config_name}`) was paused and retried on a "
            f"backoff while the LLM endpoint was unavailable, but hit the give-up "
            f"ceiling and has **failed**.\n\n"
            f"**Model:** `{model}`\n"
            f"**Classification:** `{classification}`\n"
            f"**Attempts:** {attempt}\n"
            f"**Last error:** {str(summary)[:300]}\n\n"
            f"**Description:** {description}\n\n"
            f"Check the model endpoint/provider (Admin → Models), then re-run."
        )

    else:
        subject = f"Job {short_id} frozen — {freeze_type}"
        message_md = (
            f"**Job `{short_id}`** (`{config_name}`) has frozen with type "
            f"`{freeze_type}` and requires attention.\n\n"
            f"**Description:** {description}"
        )

    return subject, message_md


# freeze_type → feed category. Anything unlisted is an incident: it reached a
# human because something went wrong, not because a decision is queued.
_FREEZE_CATEGORY = {
    "job_complete": "review_queue",
    "vm_upgrade_required": "vm_upgrade",
    "budget_exceeded": "budget_exceeded",
    "llm_unavailable": "incident",
}


async def _resolve_job_notifications(
    job_id: str, *, user: dict[str, Any] | None, hook: str
) -> None:
    """The job left its frozen/pending state — settle every feed row about it,
    whoever it belongs to (unified notification system, D6). Best-effort."""
    resolved_by = f"user:{user['id']}" if user and user.get("id") else f"system:{hook}"
    await notification_service.resolve_source(
        "job", str(job_id), resolved_by=resolved_by
    )


async def _notify_operator_freeze(
    job: dict[str, Any],
    job_id: str,
    freeze_type: str,
    freeze_data: dict[str, Any],
    sudo_request_id: str | None = None,
    *,
    dedup_key: str,
) -> RecordResult | None:
    """Record the operator-facing notification for a freeze event.

    ``dedup_key`` is the caller's idempotency key — inside a completion effect
    that is the command id, so a journal replay lands on the same feed row and
    sends nothing twice. Delivery (email, webhooks, later the escalation
    ladder) is the notification system's business, not this function's.
    """
    user_id = str(job["user_id"]) if job.get("user_id") else None
    if not user_id:
        logger.debug(f"Job {job_id} has no user_id — skipping freeze notification")
        return None

    config_name = canonical_config_name(job.get("config_name") or "worker_base")
    description = (job.get("description") or "")[:100]
    subject, message_md = _format_freeze_notification(
        freeze_type=freeze_type,
        freeze_data=freeze_data,
        job_id=job_id,
        config_name=config_name,
        description=description,
    )

    category = _FREEZE_CATEGORY.get(freeze_type, "incident")
    if category == "vm_upgrade" and sudo_request_id:
        source_kind, source_id = "sudo_request", str(sudo_request_id)
    else:
        source_kind, source_id = "job", str(job_id)
    action_params: dict[str, Any] = {"job_id": str(job_id)}
    if sudo_request_id:
        action_params["request_id"] = str(sudo_request_id)

    result = await notification_service.record(
        recipient_id=user_id,
        category=category,
        dedup_key=dedup_key,
        subject=subject,
        body=message_md,
        source_kind=source_kind,
        source_id=source_id,
        action_params=action_params,
        payload={
            "job_id": str(job_id),
            "config_name": config_name,
            "job_description": description,
            "freeze_type": freeze_type,
            "phase_number": (freeze_data or {}).get("phase_number"),
            "sudo_request_id": str(sudo_request_id) if sudo_request_id else None,
        },
    )
    logger.info(
        "Freeze notification %s for job %s (%s → %s)",
        "recorded" if result.inserted else "replayed",
        job_id,
        freeze_type,
        category,
    )
    return result


# Fallback reason for interrupt-style replies that could not ride the
# guidance lane (job not processing → resumed instead). Rendered verbatim
# in the worker's [FEEDBACK_RESUME] banner.
_URGENT_RESUME_REASON = (
    "An urgent operator message arrived while this job was not running; "
    "the job was resumed to deliver it."
)


async def _queue_supervisor_guidance(
    job: dict[str, Any], thread_id: str, message: str
) -> str | None:
    """Non-destructive urgent steer (P1-A): append to ``context.pending_guidance``.

    The entry rides the agent-heartbeat response into the worker's next LLM
    turn as a transient [SUPERVISOR GUIDANCE] block — no pause, no pod
    replacement, no context compaction, no forced re-plan (the old urgent arm
    was a hidden resume-with-feedback that destroyed the worker's in-flight
    tactical context). Worst-case delivery: one heartbeat interval (currently
    60s) + the time to the worker's next LLM turn. The agent acks via
    ``POST /api/jobs/{id}/guidance/ack``, which moves the entry to
    ``context.consumed_replies`` — senders confirm delivery there.

    Returns:
        The delivery strategy, or None when there is no live run to deliver
        into (job not ``processing``, or the row vanished) — callers fall
        back to the resume path.
    """
    if job.get("status") != "processing":
        return None
    entry = {
        "id": str(uuid4()),
        "text": message,
        "source": thread_id,
        "created_at": datetime.now(timezone.utc).isoformat(),
    }
    if not await postgres_db.append_pending_guidance(
        str(job["id"]), entry, **_completion_dispatch_guard_kwargs()
    ):
        return None
    logger.info(
        "Queued supervisor guidance %s for job %s (thread %s)",
        entry["id"][:8],
        str(job["id"])[:8],
        thread_id,
    )
    return "guidance_next_turn"


async def _find_thread_route(job_id: str, thread_id: str) -> dict[str, Any] | None:
    """Best-effort newest route row for a (job, thread). Never raises."""
    try:
        return await postgres_db.find_message_route_for_thread(job_id, thread_id)
    except Exception:
        logger.debug(
            "route lookup failed for job %s thread %s",
            job_id[:8],
            thread_id,
            exc_info=True,
        )
        return None


async def _record_route_reply_resolution(
    job_id: str,
    thread_id: str,
    *,
    actor_kind: str,
    actor_id: str | None = None,
    note: str | None = None,
) -> None:
    """Best-effort CAS of the thread's open route to its resolved state.

    The job-status CAS is what unblocks exactly once; this records WHO
    answered on the route ledger. A lost CAS (reconciler deadline or the
    other audience won) is a silent no-op by design.
    """
    try:
        from services import message_routing as routing_svc

        await routing_svc.record_reply_resolution(
            postgres_db,
            job_id,
            thread_id,
            actor_kind=actor_kind,
            actor_id=actor_id,
            note=note,
        )
    except Exception:
        logger.debug(
            "route resolution recording failed for job %s thread %s",
            job_id[:8],
            thread_id,
            exc_info=True,
        )


async def _route_inbound_reply(
    job_id: str,
    thread_id: str,
    message: str,
    sender_email: str | None = None,
    email_message_id: str | None = None,
    urgent: bool = False,
    resolver_kind: str = "user",
    resolver_id: str | None = None,
) -> tuple[str, int]:
    """Route an inbound reply to the correct job/thread.

    Shared by the cockpit reply endpoint, the IMAP poller, and the officer
    reply lane (M3 — which passes ``resolver_kind='officer'`` so the route
    ledger records the right actor).

    Args:
        job_id: Target job UUID
        thread_id: Target thread ID
        message: Reply body
        sender_email: Sender's email (for user resolution, IMAP only)
        email_message_id: RFC822 Message-ID for dedup (IMAP only)
        urgent: Deliver into the worker's next LLM turn via the guidance
            lane (non-destructive). Only when the job has no live run does
            urgent fall back to a resume-with-feedback.
        resolver_kind: 'user' (default) or 'officer' — recorded on a
            matching route's resolution transition.
        resolver_id: Actor id for the route audit (user id / officer thread).

    Returns:
        Tuple of (delivery_strategy, sequence_number).

    Raises:
        ValueError: If the job is not found.
    """
    job = await postgres_db.get_job(job_id)
    if not job:
        raise ValueError(f"Job '{job_id}' not found")
    await _guard_completion_control(job_id, source="inbound_reply")
    # Any answer — cockpit, mail, officer — settles the thread's feed rows
    # (D6): the deferred "nobody answered" mail must never go out after this.
    await notification_service.resolve_source(
        "message_thread",
        thread_id,
        resolved_by=(
            f"{resolver_kind}:{resolver_id}"
            if resolver_id
            else f"{resolver_kind}:reply"
        ),
    )

    async def _resume_reply_or_conflict(
        *, reason: str, route_id: str | None = None
    ) -> None:
        resumed = await _internal_resume_job(
            job_id,
            feedback=message,
            reason=reason,
            expected_status=str(job.get("status") or ""),
            # OC-04: reply and timeout race for the same freeze. Both now CAS
            # on the route generation, so exactly one wins and a delayed actor
            # for an OLD route cannot resume a job that has since refrozen on
            # a new one. None (an unrouted freeze) keeps the status-only CAS.
            expected_route_id=route_id,
        )
        if resumed:
            return
        # Distinguish a command winner when possible, but never report an
        # immediate delivery that did not win its status/queue mutation.
        await _guard_completion_control(job_id, source="inbound_reply")
        refreshed = await postgres_db.get_job(job_id)
        raise HTTPException(
            status_code=409,
            detail=(
                "Job changed while the inbound reply was being delivered"
                + (f" (status: {refreshed.get('status')})" if refreshed else "")
            ),
        )

    # Resolve user_id from sender email or job owner
    user_id = None
    if sender_email:
        async with postgres_db.acquire() as conn:
            user_row = await conn.fetchrow(
                "SELECT id FROM users WHERE email = $1",
                sender_email,
            )
        if user_row:
            user_id = str(user_row["id"])
    if not user_id:
        user_id = str(job.get("user_id", "")) if job.get("user_id") else None

    # Get sequence number
    sequence = await postgres_db.get_message_sequence(job_id, thread_id)

    async def _delivered(strategy: str) -> tuple[str, int]:
        # Record "delivered" only after the selected context/resume mutation
        # won its command-aware CAS. A losing control remains a clean 409.
        await postgres_db.log_message(
            job_id=job_id,
            user_id=user_id,
            thread_id=thread_id,
            direction="inbound",
            subject="(reply)",
            message=message,
            status="delivered",
            email_message_id=email_message_id,
        )
        return strategy, sequence

    # Check if job is waiting for a reply on this thread
    job_status = job.get("status", "")
    freeze_data = job.get("freeze_data")
    if isinstance(freeze_data, str):
        try:
            freeze_data = json.loads(freeze_data)
        except json.JSONDecodeError:
            freeze_data = None

    is_blocking_reply = (
        job_status == "waiting_for_reply"
        and freeze_data
        and freeze_data.get("thread_id") == thread_id
    )

    if is_blocking_reply:
        await _resume_reply_or_conflict(
            reason=(
                "This job froze waiting for a reply to its outbound message; "
                "the reply below answers it."
            ),
            route_id=(freeze_data or {}).get("route_id"),
        )
        # The resume CAS won — record who answered on the route ledger
        # (officer_message_routing.md §3). Best-effort: the worker is
        # already unblocked either way.
        await _record_route_reply_resolution(
            job_id,
            thread_id,
            actor_kind=resolver_kind,
            actor_id=resolver_id or user_id,
        )
        return await _delivered("immediate_resume")

    # Officer-aware follow-ups (officer_message_routing.md §5.3): consult the
    # thread's route ONCE. Threads without a route (all pre-officer traffic)
    # skip this entirely — behavior below stays byte-compatible for them.
    thread_route = await _find_thread_route(job_id, thread_id)
    if thread_route is not None:
        route_state = str(thread_route.get("state") or "")
        if job_status in ("completed", "failed", "cancelled"):
            # After disposition: the reply is recorded and wakes the officer
            # rather than pretending a finished job can resume.
            if resolver_kind == "user" and thread_route.get("project_id"):
                try:
                    from services.session_wake import notify_officer

                    await notify_officer(
                        postgres_db,
                        str(thread_route["project_id"]),
                        source="worker_message",
                        dedup_key=(
                            f"late-reply:{thread_route.get('route_id')}:{sequence}"
                        ),
                        payload={
                            "summary": (
                                f"The user replied on thread {thread_id} of job "
                                f"{job_id[:8]} after it reached {job_status}: "
                                f"{message[:200]}"
                            ),
                            "job_id": job_id,
                            "thread_id": thread_id,
                        },
                    )
                    _kick_officer_event_drain(postgres_db)
                except Exception:
                    logger.warning(
                        "late-reply officer wake failed for job %s",
                        job_id[:8],
                        exc_info=True,
                    )
            return await _delivered("recorded_after_disposition")
        if (
            resolver_kind == "user"
            and route_state == "resolved_by_officer"
            and job_status == "processing"
        ):
            # §5.3: the officer answered first; the later user reply is
            # higher authority — deliver it as a sourced steer through the
            # P1-A guidance lane instead of parking it for a phase boundary.
            strategy = await _queue_supervisor_guidance(
                job,
                thread_id,
                (
                    f"[Reply from the job owner on thread {thread_id} — it "
                    "supersedes the project officer's earlier answer on this "
                    f"thread]\n{message}"
                ),
            )
            if strategy:
                return await _delivered(strategy)
        elif resolver_kind == "user" and route_state in (
            "pending_officer",
            "pending_both",
            "escalated_to_user",
            "delivery_failed",
        ):
            # A user answer on a still-open (async) route closes it.
            await _record_route_reply_resolution(
                job_id,
                thread_id,
                actor_kind="user",
                actor_id=resolver_id or user_id,
                note="user replied on open route",
            )

    # Look up user delivery preferences
    user_prefs = {}
    if user_id:
        try:
            user_settings = await postgres_db.get_user_settings(user_id)
            user_prefs = (
                (user_settings or {}).get("communication", {}).get("delivery", {})
            )
        except Exception:
            pass  # Non-critical — fall back to defaults

    # Check urgent flag (explicit from cockpit, or user preference).
    # Urgent ≠ resume anymore (P1-A): a live run gets the message as
    # next-turn guidance; only a job with no live run is resumed to
    # deliver it.
    urgent_override = user_prefs.get("urgent_override", True)
    if urgent and urgent_override:
        strategy = await _queue_supervisor_guidance(job, thread_id, message)
        if strategy:
            return await _delivered(strategy)
        await _resume_reply_or_conflict(reason=_URGENT_RESUME_REASON)
        return await _delivered("immediate_interrupt")

    # Check user's async reply preference (same semantics as urgent above)
    async_pref = user_prefs.get("async_reply", "next_strategic_phase")
    if async_pref == "immediate_interrupt":
        strategy = await _queue_supervisor_guidance(job, thread_id, message)
        if strategy:
            return await _delivered(strategy)
        await _resume_reply_or_conflict(reason=_URGENT_RESUME_REASON)
        return await _delivered("immediate_interrupt")

    # LLM triage: let auxiliary model decide guidance-now vs queue
    if async_pref == "llm_triage" and job.get("status") == "processing":
        try:
            from services.message_triage import triage_message

            decision = await triage_message(
                message=message,
                job_status=job.get("status", ""),
                job_description=job.get("description", ""),
                phase_number=job.get("phase_number"),
                db=postgres_db,
            )
            if decision.get("action") == "interrupt":
                strategy = await _queue_supervisor_guidance(job, thread_id, message)
                if strategy:
                    logger.info(
                        "LLM triage: next-turn guidance for job %s — %s",
                        job_id[:8],
                        decision.get("reason", ""),
                    )
                    return await _delivered("llm_triage_guidance")
                # No live run after all — fall through to the queued lane.
        except Exception as e:
            logger.warning("LLM triage failed, falling through to queue: %s", e)

    # Default: queue for next strategic phase. Atomic array append so two
    # concurrent inbound replies both land — the old read-modify-write full-dict
    # rewrite lost one of a racing pair (its RMW window spans the LLM triage
    # call above).
    queued_reply = await postgres_db.append_queued_reply(
        job_id,
        {
            "id": str(uuid4()),
            "thread_id": thread_id,
            "message": message,
            "timestamp": datetime.now(timezone.utc).isoformat(),
        },
        **_completion_dispatch_guard_kwargs(),
    )
    if not queued_reply:
        await _guard_completion_control(job_id, source="inbound_reply")
        raise HTTPException(
            status_code=409,
            detail="Job changed while the inbound reply was being queued",
        )

    # Broadcast reply_delivered to cockpit SSE
    try:
        from services.notification_feed import notification_feed

        job_owner_id = str(job.get("user_id", "")) if job.get("user_id") else None
        if job_owner_id:
            notification_feed.broadcast(
                user_id=job_owner_id,
                event_type="reply_delivered",
                data={"job_id": job_id, "thread_id": thread_id},
            )
    except Exception:
        pass  # Non-critical

    return await _delivered("next_strategic_phase")


@app.post("/api/jobs/{job_id}/messages/{thread_id}/reply")
async def reply_to_agent_message(
    request: Request,
    job_id: str,
    thread_id: str,
    body: MessageReplyRequest,
) -> dict[str, Any]:
    """Reply to an agent's message (cockpit UI or IMAP).

    If the job is in 'waiting_for_reply' status and the thread matches,
    resumes the job with the reply as feedback. ``urgent`` (and the
    immediate-interrupt user preference) delivers into the worker's next
    LLM turn via the non-destructive guidance lane
    (``delivery_strategy="guidance_next_turn"``); only a job with no live
    run is resumed to deliver an urgent message. Otherwise the reply is
    queued and injected at the next tactical→strategic phase boundary.
    """
    await require_job_access(request, postgres_db, job_id)
    try:
        delivery_strategy, sequence = await _route_inbound_reply(
            job_id=job_id,
            thread_id=thread_id,
            message=body.message,
            urgent=body.urgent,
        )

        file_path = f"messages/{thread_id}/{sequence:03d}_received.md"

        return {
            "status": "delivered",
            "sequence": sequence,
            "file_path": file_path,
            "delivery_strategy": delivery_strategy,
        }

    except ValueError as e:
        raise HTTPException(status_code=404, detail=str(e)) from e
    except HTTPException:
        raise
    except Exception as e:
        logger.exception(
            f"Failed to deliver reply for job {job_id} thread {thread_id}: {e}"
        )
        raise HTTPException(status_code=500, detail=str(e)) from e


# =============================================================================
# Officer message actions (officer_message_routing.md §4 — M3)
# =============================================================================


class RuntimeActorAuthorizationRequest(BaseModel):
    """Target of a sensitive knowledge write; identity stays in the header."""

    action: Literal["machine_tags", "charter"]
    project_id: str


@app.post("/api/runtime-actors/authorize")
async def authorize_runtime_actor(
    request: Request, body: RuntimeActorAuthorizationRequest
) -> dict[str, Any]:
    """Authorize a hidden runtime actor against current server-side state."""

    await require_internal(request)
    actor = await authorize_runtime_actor_request(
        postgres_db,
        request,
        action=body.action,
        project_id=body.project_id,
    )
    return {
        "authorized": True,
        "code": "authorized",
        "action": body.action,
        "actor": actor.audit_payload(),
        "message": "Runtime actor is authorized.",
    }


@app.post("/api/runtime-actors/refresh")
async def refresh_runtime_actor(request: Request) -> dict[str, Any]:
    """Refresh a short-lived actor access token after revalidating identity."""

    await require_internal(request)
    exchange = await refresh_runtime_actor_exchange(
        postgres_db,
        request,
        verification_enabled=OFFICER_RUNTIME_VERIFICATION_ENABLED,
    )
    if exchange.retryable_failure_code or exchange.response_lost:
        # The authoritative refresh transaction has either been deliberately
        # refused before mutation or committed with its credential payload
        # intentionally withheld. Never echo plan/binding/credential details
        # onto the runtime transport.
        raise HTTPException(
            status_code=503,
            detail={
                "code": "runtime_maintenance_unavailable",
                "retryable": True,
            },
        )
    actor = exchange.actor
    if actor is None:  # defensive: every non-fault exchange carries an actor
        raise HTTPException(status_code=503, detail="Runtime maintenance unavailable")
    if actor.caller_kind == "officer":
        _kick_officer_event_drain(postgres_db)
    return {"runtime_actor": actor.to_payload()}


class OfficerRuntimeVerificationPlanRequest(BaseModel):
    """Bounded admin-only runtime verification parameters."""

    idempotency_key: UUID
    exercise: Literal["longevity", "response_loss", "maintenance_failure"]
    expires_in_seconds: int = Field(default=900, ge=120, le=3600)
    logical_window_seconds: int | None = Field(default=None, ge=30, le=600)
    response_losses: int | None = Field(default=None, ge=1, le=2)
    response_loss_gap_seconds: int | None = Field(default=None, ge=0, le=300)


def _runtime_verification_http_error(
    exc: RuntimeVerificationPlanError,
) -> HTTPException:
    return HTTPException(
        status_code=exc.status_code,
        detail={"code": exc.code, "message": exc.message},
    )


async def _audit_runtime_verification_action(
    *,
    request: Request,
    admin: dict[str, Any],
    project_id: str,
    plan: dict[str, Any],
    action: Literal["create", "recover", "disarm"],
) -> None:
    """Record a successful secret-free admin verification action."""

    event_type = {
        "create": "officer_runtime_verification_created",
        "recover": "officer_runtime_verification_recovery_requested",
        "disarm": "officer_runtime_verification_disarmed",
    }[action]
    await log_security_event(
        postgres_db,
        event_type=event_type,
        user=admin,
        resource_type="officer_runtime_verification",
        resource_id=str(plan.get("plan_id") or ""),
        detail=(
            f"project_id={project_id} plan_id={plan.get('plan_id')} "
            f"exercise={plan.get('exercise')} action={action} "
            f"replayed={str(bool(plan.get('replayed'))).lower()}"
        ),
        request=request,
    )


@app.post("/api/admin/projects/{project_id}/officer/runtime-verification")
async def create_officer_runtime_verification(
    project_id: str,
    body: OfficerRuntimeVerificationPlanRequest,
    request: Request,
) -> dict[str, Any]:
    """Arm one exact commissioned-Officer verification plan (admin only)."""

    admin = await _require_admin(request)
    try:
        plan = await create_runtime_verification_plan(
            postgres_db,
            enabled=OFFICER_RUNTIME_VERIFICATION_ENABLED,
            project_id=project_id,
            idempotency_key=str(body.idempotency_key),
            exercise=body.exercise,
            created_by=str(admin["id"]),
            expires_in_seconds=body.expires_in_seconds,
            logical_window_seconds=body.logical_window_seconds,
            response_losses=body.response_losses,
            response_loss_gap_seconds=body.response_loss_gap_seconds,
        )
    except RuntimeVerificationPlanError as exc:
        raise _runtime_verification_http_error(exc) from exc
    await _audit_runtime_verification_action(
        request=request,
        admin=admin,
        project_id=project_id,
        plan=plan,
        action="create",
    )
    return {"enabled": True, "plan": plan}


@app.get("/api/admin/projects/{project_id}/officer/runtime-verification")
async def read_officer_runtime_verification(
    project_id: str, request: Request
) -> dict[str, Any]:
    """Read the secret-free durable plan projection (admin only)."""

    await _require_admin(request)
    try:
        plan = await get_runtime_verification_plan(
            postgres_db,
            enabled=OFFICER_RUNTIME_VERIFICATION_ENABLED,
            project_id=project_id,
        )
    except RuntimeVerificationPlanError as exc:
        raise _runtime_verification_http_error(exc) from exc
    return {"enabled": True, "plan": plan}


@app.post(
    "/api/admin/projects/{project_id}/officer/runtime-verification/{plan_id}/{action}"
)
async def transition_officer_runtime_verification(
    project_id: str,
    plan_id: str,
    action: Literal["recover", "disarm"],
    request: Request,
) -> dict[str, Any]:
    """Recover or disarm the exact plan; neither operation carries identity."""

    admin = await _require_admin(request)
    try:
        plan = await transition_runtime_verification_plan(
            postgres_db,
            enabled=OFFICER_RUNTIME_VERIFICATION_ENABLED,
            project_id=project_id,
            plan_id=plan_id,
            action=action,
            actor_id=str(admin["id"]),
        )
    except RuntimeVerificationPlanError as exc:
        raise _runtime_verification_http_error(exc) from exc
    await _audit_runtime_verification_action(
        request=request,
        admin=admin,
        project_id=project_id,
        plan=plan,
        action=action,
    )
    return {"enabled": True, "plan": plan}


class OfficerMessageReplyRequest(BaseModel):
    """Body for the officer's reply on a worker message thread."""

    message: str = Field(..., max_length=5000, description="Answer for the worker")


class OfficerMessageEscalateRequest(BaseModel):
    """Body for escalating a worker message thread to the user."""

    context: str | None = Field(
        None,
        max_length=5000,
        description="Officer context delivered (clearly delimited) with the "
        "original worker message",
    )


class OfficerMessageAckRequest(BaseModel):
    """Body for acknowledging (closing) an async worker message route."""

    note: str | None = Field(None, max_length=1000, description="Optional note")


async def _require_officer_route_actor(
    request: Request, job_id: str
) -> tuple[dict[str, Any], dict[str, Any], int | None]:
    """Derive and authorize the current officer from hidden runtime identity."""
    await require_internal(request)
    job = await postgres_db.get_job(job_id)
    if not job:
        raise HTTPException(status_code=404, detail=f"Job '{job_id}' not found")
    project_id = str(job["project_id"]) if job.get("project_id") else None
    if not project_id:
        raise HTTPException(
            status_code=403,
            detail="Job has no project — there is no officer chain of command.",
        )
    actor = await authorize_runtime_actor_request(
        postgres_db,
        request,
        action="officer_message",
        project_id=project_id,
    )
    # Downstream route-transition code consumes the historical row-shaped
    # ``{"id": thread_id}`` value.  The id now comes only from the verified
    # runtime actor, never from a public request body.
    officer = {"id": actor.thread_id}
    return job, officer, actor.officer_incarnation


async def _officer_route_for_action(
    job_id: str, thread_id: str, officer_thread_id: str
) -> dict[str, Any]:
    """The open route an officer action targets, or a 409 explaining why not.

    The incarnation fence: a route addressed to a PREVIOUS officer thread is
    never adoptable by the current one (§5.1) — the drain already handed it
    to the user.
    """
    route = await postgres_db.find_message_route_for_thread(
        job_id, thread_id, open_only=True
    )
    if not route:
        raise HTTPException(
            status_code=409,
            detail=(
                "No open worker-message route on this thread (it may already "
                "be resolved or timed out). For plain guidance use "
                "send_message_to_job."
            ),
        )
    if str(route.get("officer_thread_id") or "") != str(officer_thread_id):
        raise HTTPException(
            status_code=409,
            detail=(
                "This route is not addressed to the current officer "
                "incarnation (it predates this commission or is user-direct); "
                "it is not adoptable. For plain guidance use "
                "send_message_to_job."
            ),
        )
    return route


@app.post("/api/jobs/{job_id}/messages/{thread_id}/officer-reply")
async def officer_reply_to_worker_message(
    request: Request,
    job_id: str,
    thread_id: str,
    body: OfficerMessageReplyRequest,
) -> dict[str, Any]:
    """Answer a worker message as the commissioned officer. **Internal** —
    requires ``X-Internal-Key``; the caller must BE the project's officer.

    Delivers through the existing reply lane [A-reply] — a blocking route's
    worker resumes exactly once (job-status CAS) — and CAS-records
    ``resolved_by_officer`` on the route. The reply is guidance, never
    authorization: no approval/ready/claim side effects, and the original
    message is never erased.
    """
    job, officer, incarnation = await _require_officer_route_actor(request, job_id)
    message = (body.message or "").strip()
    if not message:
        raise HTTPException(status_code=400, detail="message must not be empty")
    route = await _officer_route_for_action(job_id, thread_id, str(officer["id"]))

    try:
        delivery_strategy, sequence = await _route_inbound_reply(
            job_id=job_id,
            thread_id=thread_id,
            message=f"[Answered by the project officer]\n\n{message}",
            resolver_kind="officer",
            resolver_id=str(officer["id"]),
        )
    except ValueError as e:
        raise HTTPException(status_code=404, detail=str(e)) from e

    # The blocking branch already recorded; this covers async routes (the
    # reply took a queued/guidance lane). CAS — a second record is a no-op.
    await _record_route_reply_resolution(
        job_id,
        thread_id,
        actor_kind="officer",
        actor_id=str(officer["id"]),
        note="officer replied",
    )
    refreshed = await postgres_db.get_message_route(str(route["route_id"]))
    return {
        "status": "replied",
        "delivery_strategy": delivery_strategy,
        "sequence": sequence,
        "route_id": str(route["route_id"]),
        "route_state": (refreshed or route).get("state"),
    }


@app.post("/api/jobs/{job_id}/messages/{thread_id}/officer-escalate")
async def officer_escalate_worker_message(
    request: Request,
    job_id: str,
    thread_id: str,
    body: OfficerMessageEscalateRequest,
) -> dict[str, Any]:
    """Escalate a worker message thread to the user with officer context.
    **Internal** — requires ``X-Internal-Key``; caller must BE the officer.

    Same ``thread_id`` keeps the reply/resume path: the user's answer
    resumes the worker directly. The original worker text and the officer's
    context are delivered clearly delimited (§7).
    """
    job, officer, incarnation = await _require_officer_route_actor(request, job_id)
    route = await _officer_route_for_action(job_id, thread_id, str(officer["id"]))
    if route.get("state") not in ("pending_officer", "pending_both"):
        raise HTTPException(
            status_code=409,
            detail=(f"Route is already {route.get('state')} — nothing to escalate."),
        )

    from services import message_routing as routing_svc

    outcome = await routing_svc.escalate_route(
        postgres_db,
        route,
        reason="officer_escalated",
        actor_kind="officer",
        actor_id=str(officer["id"]),
        officer_context=body.context,
        expected_states=("pending_officer", "pending_both"),
        notifier=notification_service,
    )
    if not outcome["escalated"]:
        refreshed = await postgres_db.get_message_route(str(route["route_id"]))
        state = (refreshed or {}).get("state")
        if state == "escalated_to_user":
            # The SLA reconciler won the CAS a moment earlier — the thread is
            # with the user either way.
            return {
                "status": "escalated",
                "delivered": bool((refreshed or {}).get("user_delivery_at")),
                "route_id": str(route["route_id"]),
                "note": "already escalated (officer SLA expired first)",
            }
        raise HTTPException(
            status_code=409,
            detail=f"Route changed before escalation (now: {state}).",
        )
    return {
        "status": "escalated",
        "delivered": outcome["delivered"],
        "route_id": str(route["route_id"]),
    }


@app.post("/api/jobs/{job_id}/messages/{thread_id}/officer-ack")
async def officer_acknowledge_worker_message(
    request: Request,
    job_id: str,
    thread_id: str,
    body: OfficerMessageAckRequest,
) -> dict[str, Any]:
    """Close an ASYNC worker message route without a reply. **Internal** —
    requires ``X-Internal-Key``; caller must BE the officer.

    Refused for blocking routes: a frozen worker needs an answer or an
    escalation, never a silent ack pretending nobody waited.
    """
    job, officer, incarnation = await _require_officer_route_actor(request, job_id)
    route = await _officer_route_for_action(job_id, thread_id, str(officer["id"]))
    if route.get("blocking"):
        raise HTTPException(
            status_code=400,
            detail=(
                "This worker is frozen waiting for an answer — use "
                "reply_to_job_message or escalate_job_message. Acknowledge is "
                "for async items only."
            ),
        )
    note = (body.note or "").strip()
    updated = await postgres_db.transition_message_route(
        str(route["route_id"]),
        to_state="resolved_by_officer",
        expected_states=["pending_officer", "pending_both", "delivery_failed"],
        actor_kind="officer",
        actor_id=str(officer["id"]),
        officer_thread_id=str(officer["id"]),
        officer_incarnation=incarnation,
        note=f"acknowledged{': ' + note if note else ''}",
    )
    if not updated:
        refreshed = await postgres_db.get_message_route(str(route["route_id"]))
        raise HTTPException(
            status_code=409,
            detail=(
                "Route changed before acknowledge "
                f"(now: {(refreshed or {}).get('state')})."
            ),
        )
    return {
        "status": "acknowledged",
        "route_id": str(route["route_id"]),
        "route_state": updated.get("state"),
    }


class GuidanceAckRequest(BaseModel):
    """Body for the agent's guidance-delivery ack (P1-A)."""

    guidance_ids: list[str] = Field(
        default_factory=list,
        description="context.pending_guidance entry ids rendered into the "
        "worker's LLM context",
    )
    reply_threads: list[str] = Field(
        default_factory=list,
        description="thread ids whose context.queued_replies were drained "
        "at a phase boundary",
    )
    reply_keys: list[str] = Field(
        default_factory=list,
        description="exact durable identities of queued replies absorbed by "
        "a stateless-worker checkpoint",
    )
    feedback_keys: list[str] = Field(
        default_factory=list,
        description="exact generations of queued feedback absorbed by a "
        "stateless-worker checkpoint",
    )
    delegation_keys: list[str] = Field(
        default_factory=list,
        description="exact generations of delegation results absorbed by a "
        "stateless-worker checkpoint",
    )
    checkpoint_id: str | None = Field(
        default=None,
        description="durable LangGraph checkpoint proving stateless delivery",
    )


@app.post("/api/jobs/{job_id}/guidance/ack")
async def ack_job_guidance(
    request: Request, job_id: str, body: GuidanceAckRequest
) -> dict[str, Any]:
    """Ack delivered supervisor guidance / drained queued replies.
    **Internal** (P4b) — requires ``X-Internal-Key``.

    The pinned agent calls this after entries reached LLM-visible context. A
    stateless worker calls it only after the checkpoint that absorbed those
    entries committed; ``checkpoint_id`` is verified before anything moves.
    Entries move atomically ``context.pending_guidance`` (by id) /
    ``context.queued_replies`` (by exact key for stateless workers, legacy
    thread id for pinned workers) → ``context.consumed_replies``
    with a ``consumed_at`` stamp — which stops heartbeat redelivery /
    boundary re-materialization, and lets the sender confirm delivery by
    reading job context. At-least-once by design: a lost ack just means
    the worker sees the same guidance for one more turn. Idempotent.
    """
    await require_internal(request)
    try:
        moved = await postgres_db.consume_job_guidance(
            job_id,
            guidance_ids=body.guidance_ids,
            reply_threads=body.reply_threads,
            reply_keys=body.reply_keys,
            feedback_keys=body.feedback_keys,
            delegation_keys=body.delegation_keys,
            checkpoint_id=body.checkpoint_id,
        )
    except HTTPException:
        raise
    except ValueError as e:
        raise HTTPException(status_code=409, detail=str(e)) from e
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e
    if moved is None:
        raise HTTPException(status_code=404, detail=f"Job '{job_id}' not found")
    return {"status": "ok", "consumed": moved}


@app.get("/api/jobs/{job_id}/messages")
async def list_message_threads(request: Request, job_id: str) -> dict[str, Any]:
    """List message threads for a job."""
    _, job = await require_job_access(request, postgres_db, job_id)
    try:
        threads = await postgres_db.get_message_threads(job_id)

        # Enrich with job freeze status
        freeze_data = job.get("freeze_data")
        if isinstance(freeze_data, str):
            try:
                freeze_data = json.loads(freeze_data)
            except json.JSONDecodeError:
                freeze_data = None

        waiting_thread = None
        if job.get("status") == "waiting_for_reply" and freeze_data:
            waiting_thread = freeze_data.get("thread_id")

        for thread in threads:
            thread["status"] = (
                "waiting_for_reply"
                if thread["thread_id"] == waiting_thread
                else "active"
            )

        return {"threads": threads}

    except HTTPException:
        raise
    except Exception as e:
        logger.exception(f"Failed to list message threads for job {job_id}: {e}")
        raise HTTPException(status_code=500, detail=str(e)) from e


