@app.get("/api/jobs/{job_id}/repo/commits")
async def list_repo_commits(
    request: Request,
    job_id: str,
    sha: str = Query(
        default="main", description="Branch, tag, or commit SHA to list from"
    ),
    since_ref: str | None = Query(
        default=None, description="Only show commits after this ref"
    ),
    page: int = Query(default=1, ge=1, description="Page number"),
    limit: int = Query(default=20, ge=1, le=100, description="Max commits per page"),
) -> dict[str, Any]:
    """List git commits for a job's repository.

    If since_ref is provided, returns only commits between since_ref and sha
    using git compare. Otherwise lists commits from sha.

    Returns:
        Dict with commits list and total count
    """
    await require_job_access(request, postgres_db, job_id)
    if not gitea_client.is_initialized:
        raise HTTPException(status_code=503, detail="Gitea not available")

    repo_name, job_branch = await resolve_job_repo(job_id)
    effective_sha = sha if sha != "main" else (job_branch or sha)

    if since_ref:
        # Commits-endpoint pagination with a client-side cut, not the compare
        # API: Gitea 1.22 compare 404s on SHA bases and always pays a
        # per-commit `git diff` server-side (ignores `stat=false`).
        compare = await gitea_client.get_commits_between(
            repo_name, since_ref, effective_sha
        )
        if compare is None:
            raise HTTPException(
                status_code=404,
                detail=f"Could not compare {since_ref}...{effective_sha} in repo for job '{job_id}'",
            )
        return compare
    else:
        commits = await gitea_client.get_commits(
            repo_name, sha=effective_sha, page=page, limit=limit
        )
        if commits is None:
            raise HTTPException(
                status_code=404,
                detail=f"No commits found in repo for job '{job_id}'",
            )
        return {"total_commits": len(commits), "commits": commits}


@app.get("/api/jobs/{job_id}/repo/diff")
async def get_repo_diff(
    request: Request,
    job_id: str,
    base: str = Query(..., description="Base ref (commit SHA, tag, or branch)"),
    head: str = Query(default="HEAD", description="Head ref"),
) -> dict[str, str]:
    """Get unified diff between two refs in a job's repository.

    Returns:
        Dict with base, head, and diff text
    """
    await require_job_access(request, postgres_db, job_id)
    if not gitea_client.is_initialized:
        raise HTTPException(status_code=503, detail="Gitea not available")

    repo_name, _job_branch = await resolve_job_repo(job_id)
    diff_text = await gitea_client.get_diff(repo_name, base, head)

    if diff_text is None:
        raise HTTPException(
            status_code=404,
            detail=f"Could not get diff {base}...{head} in repo for job '{job_id}'",
        )

    return {"base": base, "head": head, "diff": diff_text}


@app.get("/api/jobs/{job_id}/repo/tags")
async def list_repo_tags(
    request: Request, job_id: str, all_jobs: bool = False
) -> list[dict[str, Any]]:
    """List tags in a job's repository.

    By default, only returns tags for the specified job (namespaced by
    job short ID prefix). Set all_jobs=True to return all tags in the repo.

    Returns:
        List of tags with name, sha, and message
    """
    await require_job_access(request, postgres_db, job_id)
    if not gitea_client.is_initialized:
        raise HTTPException(status_code=503, detail="Gitea not available")

    repo_name, _job_branch = await resolve_job_repo(job_id)
    tags = await gitea_client.get_tags(repo_name)

    if tags is None:
        raise HTTPException(
            status_code=404,
            detail=f"No tags found in repo for job '{job_id}'",
        )

    # Filter to this job's tags unless all_jobs requested
    if not all_jobs:
        short_id = job_id[:8]
        tags = [t for t in tags if t["name"].startswith(f"{short_id}-")]

    return tags


# NOTE: the former GET/PUT /api/jobs/{id}/workspace* routes were removed.
# They read the orchestrator-local WorkspaceService disk (a dev-era relic
# with no job dimension — on k8s that PVC only ever holds uploads/), so
# every read 404'd and any hit was a cross-job leak by construction. Job
# files are served from Gitea via /api/jobs/{id}/repo/* above. See
# knowledge-base/knowledge/issues/officer_blind_reads_and_worker_bureaucracy.md §4 P0-B.


@app.get("/api/jobs/{job_id}/diff")
async def get_job_diff(request: Request, job_id: str) -> dict[str, Any]:
    """Mode A diff summary for a project-attached job.

    Returns ``{baseline_commit, head_commit, files: [{path, status}]}``
    where each ``status`` is ``added`` / ``modified`` / ``deleted``.
    Per-file diff content is served separately via the sibling
    ``/diff/{path}`` endpoint.

    Returns 404 when the job has no baseline (loose job, or a pre-Mode-A
    project job). Empty ``files`` list means no changes under
    ``projects/<slug>/`` — the agent didn't touch the mounted folder.

    See knowledge-history/done/job_cloud_export.md §5.
    """
    _, job = await require_job_access(request, postgres_db, job_id)
    if not job.get("cloud_diff_baseline_commit"):
        raise HTTPException(
            status_code=404,
            detail="Job has no Mode A diff baseline.",
        )

    if not gitea_client.is_initialized:
        raise HTTPException(status_code=503, detail="Gitea not available.")
    from services.diff_source import GiteaDiffSource

    diff_source = GiteaDiffSource(job=job, gitea_client=gitea_client)
    summary = await diff_source.summary()
    if summary is None:
        raise HTTPException(
            status_code=404,
            detail="Diff unavailable (no repo or no head).",
        )
    return {
        "job_id": job_id,
        "diff_status": job.get("diff_status"),
        "baseline_commit": summary.meta["baseline_commit"],
        "head_commit": summary.meta["head_commit"],
        "files": [{"path": f.path, "status": f.status} for f in summary.files],
    }


@app.get("/api/jobs/{job_id}/diff/{file_path:path}")
async def get_job_diff_file(
    request: Request, job_id: str, file_path: str
) -> dict[str, Any]:
    """Mode A per-file diff content.

    Returns ``{path, status, old_content, new_content}`` for one file in
    the diff. ``old_content`` is read from the baseline commit;
    ``new_content`` from the head of the job's branch. Either side can
    be ``None`` (added → no old, deleted → no new).

    Only files under ``projects/`` are accepted — the Mode A diff is
    scoped to the project-folder mount.
    """
    _, job = await require_job_access(request, postgres_db, job_id)
    baseline = job.get("cloud_diff_baseline_commit")
    if not baseline:
        raise HTTPException(
            status_code=404,
            detail="Job has no Mode A diff baseline.",
        )
    if not file_path.startswith("projects/"):
        raise HTTPException(
            status_code=400,
            detail="Per-file diff is scoped to projects/<slug>/* paths.",
        )
    if not gitea_client.is_initialized:
        raise HTTPException(status_code=503, detail="Gitea not available.")
    repo_name = job.get("repo_name")
    if not repo_name:
        raise HTTPException(status_code=404, detail="Job repo not found.")

    from services.diff_source import GiteaDiffSource

    diff_source = GiteaDiffSource(job=job, gitea_client=gitea_client)

    # Pull the diff summary to learn the file's status (added/modified/deleted).
    summary = await diff_source.summary()
    if summary is None:
        raise HTTPException(status_code=404, detail="Diff unavailable for this job.")
    file_entry = next(
        (f for f in summary.files if f.path == file_path),
        None,
    )
    if file_entry is None:
        raise HTTPException(
            status_code=404,
            detail=f"Path '{file_path}' is not in the diff.",
        )

    content = await diff_source.file(file_path)
    if content is None:
        raise HTTPException(
            status_code=404,
            detail=f"Path '{file_path}' is not in the diff.",
        )
    return {
        "job_id": job_id,
        "path": file_path,
        "status": content.status,
        "old_content": content.old_content,
        "new_content": content.new_content,
    }


@app.post("/api/jobs/{job_id}/accept")
async def accept_job_diff(request: Request, job_id: str) -> dict[str, Any]:
    """Mode A accept: apply the job's diff back to the project's cloud folder.

    Gates:

    * Job is ``pending_review`` and project-attached.
    * ``diff_status`` is ``pending`` (the diff capture flagged changes).
    * Backend + Gitea are reachable.
    * No external modifications to the cloud folder since seed
      (etag map captured at seed time vs. fresh PROPFIND at accept). On
      divergence, returns 409 with the diverging path list — user must
      resolve manually and re-accept.

    On success, writes/deletes each diff path back via the cloud
    backend, then transitions ``diff_status='accepted'`` and
    ``status='completed'``.

    See knowledge-history/done/job_cloud_export.md §3.5.
    """
    _, job = await require_job_access(request, postgres_db, job_id)
    await _guard_completion_control(job_id, source="mode_a_accept")

    # --- Gates -------------------------------------------------------
    if job.get("status") != "pending_review":
        raise HTTPException(
            status_code=409,
            detail=(
                f"Job is in status '{job.get('status')}'; "
                "only pending_review jobs can be accepted."
            ),
        )
    if not job.get("project_id"):
        raise HTTPException(
            status_code=409,
            detail="Job has no project attached; nothing to write back to.",
        )
    if job.get("diff_status") != "pending":
        raise HTTPException(
            status_code=409,
            detail=(
                f"Job diff_status is '{job.get('diff_status')}'; "
                "only pending diffs can be accepted."
            ),
        )

    if not job.get("cloud_diff_baseline_commit"):
        raise HTTPException(
            status_code=409,
            detail="Job has no Mode A baseline; nothing to compare against.",
        )

    if not gitea_client.is_initialized:
        raise HTTPException(status_code=503, detail="Gitea not available.")

    project = await postgres_db.get_project(str(job["project_id"]))
    if not project:
        raise HTTPException(status_code=404, detail="Project not found.")
    if not project.get("main_cloud_folder_handle"):
        raise HTTPException(
            status_code=409,
            detail="Project has no cloud folder; cannot apply diff.",
        )
    backend_id = project.get("main_cloud_backend")
    if not backend_id:
        raise HTTPException(
            status_code=409,
            detail="Project has no cloud backend; cannot apply diff.",
        )
    try:
        backend = main_cloud_router.for_project(project)
    except Exception as e:
        raise HTTPException(
            status_code=503,
            detail=f"Cloud backend '{backend_id}' unavailable: {e}",
        ) from e
    if not backend.is_initialized:
        raise HTTPException(status_code=503, detail="Cloud backend not initialized.")

    control_claim = await _claim_completion_control(
        {**job, "id": job_id}, source="mode_a_accept"
    )

    # --- External-modification gate ---------------------------------
    from services.job_cloud_baseline import (
        apply_diff_to_cloud,
        detect_external_mods,
        get_diff_summary,
        project_folder_slug,
    )

    try:
        diff_summary = await (
            asyncio.wait_for(
                get_diff_summary(job=job, gitea_client=gitea_client),
                timeout=120.0,
            )
            if control_claim is not None
            else get_diff_summary(job=job, gitea_client=gitea_client)
        )
    except Exception:
        await _abort_completion_control_claim(control_claim)
        raise
    slug = project_folder_slug(job, project)
    prefix = f"projects/{slug}/"
    affected_paths = {
        str(entry.get("path"))[len(prefix) :]
        for entry in ((diff_summary or {}).get("files") or [])
        if str(entry.get("path") or "").startswith(prefix)
    }
    try:
        detect_call = detect_external_mods(
            job=job,
            project=project,
            main_cloud_router=main_cloud_router,
            scope_paths=affected_paths,
        )
        diverged = await (
            asyncio.wait_for(detect_call, timeout=180.0)
            if control_claim is not None
            else detect_call
        )
    except Exception:
        await _abort_completion_control_claim(control_claim)
        raise
    if diverged:
        await _abort_completion_control_claim(control_claim)
        raise HTTPException(
            status_code=409,
            detail={
                "code": "external_modifications_detected",
                "message": (
                    "Cloud folder was modified externally since the job "
                    "started. Resolve manually before accepting."
                ),
                "diverged": diverged,
            },
        )

    # --- Apply -------------------------------------------------------
    try:
        apply_call = apply_diff_to_cloud(
            job=job,
            project=project,
            gitea_client=gitea_client,
            main_cloud_router=main_cloud_router,
        )
        result = await (
            asyncio.wait_for(apply_call, timeout=20 * 60.0)
            if control_claim is not None
            else apply_call
        )
    except Exception:
        await _abort_completion_control_claim(control_claim)
        raise
    if result.get("errors"):
        # Partial failure: cloud is now in a mixed state. Surface the
        # errors so the user can see what missed; don't transition the
        # job — user can retry.
        await _abort_completion_control_claim(control_claim)
        raise HTTPException(
            status_code=502,
            detail={
                "code": "partial_write_failure",
                "applied": result.get("applied", 0),
                "deleted": result.get("deleted", 0),
                "errors": result.get("errors"),
            },
        )

    # --- Status transition ------------------------------------------
    delivery = {
        "delivery_status": "cloud-applied",
        "needs_review": False,
        "delivery_sha": (diff_summary or {}).get("head_commit"),
        "notes": [],
        "applied": int(result.get("applied") or 0),
        "deleted": int(result.get("deleted") or 0),
    }
    if control_claim is not None:
        from services.completion_control import CompletionControlClaimConflict

        try:
            async with _get_completion_control().finish_claim(control_claim) as (
                conn,
                _locked_job,
            ):
                updated = await conn.fetchrow(
                    """
                    UPDATE jobs
                    SET diff_status='accepted', merge_status='cloud-applied',
                        status='completed', assigned_agent_id=NULL,
                        completed_at=COALESCE(completed_at, CURRENT_TIMESTAMP),
                        context=COALESCE(context, '{}'::jsonb) || $2::jsonb,
                        updated_at=CURRENT_TIMESTAMP
                    WHERE id=$1::uuid
                      AND status='pending_review'
                      AND diff_status='pending'
                      AND execution_lane=$3::text
                    RETURNING id
                    """,
                    job_id,
                    json.dumps({"loop_cloud_delivery": delivery}),
                    str(job.get("execution_lane") or "pinned"),
                )
                if updated is None:
                    raise CompletionControlClaimConflict(
                        "job changed while Mode A accept was being committed"
                    )
        except CompletionControlClaimConflict as exc:
            await _abort_completion_control_claim(control_claim)
            raise HTTPException(status_code=409, detail=str(exc)) from exc
    else:
        await postgres_db.update_job_cloud_diff(job_id, diff_status="accepted")
        await postgres_db.update_job_merge_status(job_id, merge_status="cloud-applied")
        await postgres_db.update_job_status(job_id, status="completed")
        await postgres_db.merge_job_context(job_id, {"loop_cloud_delivery": delivery})
    job["status"] = "completed"
    job["diff_status"] = "accepted"
    job["merge_status"] = "cloud-applied"
    _accept_ctx = job.get("context") or {}
    if isinstance(_accept_ctx, str):
        try:
            _accept_ctx = json.loads(_accept_ctx)
        except (json.JSONDecodeError, TypeError):
            _accept_ctx = {}
    if not isinstance(_accept_ctx, dict):
        _accept_ctx = {}
    _accept_ctx["loop_cloud_delivery"] = delivery
    job["context"] = _accept_ctx

    terminal_actions: list[str] = []
    from services.project_loops import job_loop_id

    if job_loop_id(job):
        await _advance_project_loop(job, {}, terminal_actions)
    else:
        from services.completion import apply_terminal_job_side_effects

        side_effects = await apply_terminal_job_side_effects(
            job,
            "completed",
            gitea=gitea_client,
            db=postgres_db,
            vector_db=vector_db,
        )
        terminal_actions.extend(side_effects["actions"])
    logger.info(
        "Mode A: job %s — diff accepted (%d applied, %d deleted)",
        job_id,
        result.get("applied", 0),
        result.get("deleted", 0),
    )
    return {
        "job_id": job_id,
        "diff_status": "accepted",
        "status": "completed",
        "applied": result.get("applied", 0),
        "deleted": result.get("deleted", 0),
        "actions": terminal_actions,
    }


@app.post("/api/jobs/{job_id}/reject")
async def reject_job_diff(request: Request, job_id: str) -> dict[str, Any]:
    """Mode A reject: discard the job's diff, no cloud write.

    Stamps ``diff_status='rejected'`` and ``status='completed'``. The
    Gitea commits stay around as the audit trail of what the agent
    tried to do (cheap; see §3.6).

    See knowledge-history/done/job_cloud_export.md §3.6.
    """
    _, job = await require_job_access(request, postgres_db, job_id)
    await _guard_completion_control(job_id, source="mode_a_reject")

    if job.get("status") != "pending_review":
        raise HTTPException(
            status_code=409,
            detail=(
                f"Job is in status '{job.get('status')}'; "
                "only pending_review jobs can be rejected."
            ),
        )
    if not job.get("project_id"):
        raise HTTPException(
            status_code=409,
            detail="Job has no project attached; no diff to reject.",
        )
    if job.get("diff_status") != "pending":
        raise HTTPException(
            status_code=409,
            detail=(
                f"Job diff_status is '{job.get('diff_status')}'; "
                "only pending diffs can be rejected."
            ),
        )

    control_claim = await _claim_completion_control(
        {**job, "id": job_id}, source="mode_a_reject"
    )
    delivery = {
        "delivery_status": "cloud-rejected",
        "needs_review": False,
        "delivery_sha": None,
        "notes": ["project-file diff rejected; cloud folder left unchanged"],
    }
    if control_claim is not None:
        from services.completion_control import CompletionControlClaimConflict

        try:
            async with _get_completion_control().finish_claim(control_claim) as (
                conn,
                _locked_job,
            ):
                updated = await conn.fetchrow(
                    """
                    UPDATE jobs
                    SET diff_status='rejected', merge_status='cloud-rejected',
                        status='completed', assigned_agent_id=NULL,
                        completed_at=COALESCE(completed_at, CURRENT_TIMESTAMP),
                        context=COALESCE(context, '{}'::jsonb) || $2::jsonb,
                        updated_at=CURRENT_TIMESTAMP
                    WHERE id=$1::uuid
                      AND status='pending_review'
                      AND diff_status='pending'
                      AND execution_lane=$3::text
                    RETURNING id
                    """,
                    job_id,
                    json.dumps({"loop_cloud_delivery": delivery}),
                    str(job.get("execution_lane") or "pinned"),
                )
                if updated is None:
                    raise CompletionControlClaimConflict(
                        "job changed while Mode A reject was being committed"
                    )
        except CompletionControlClaimConflict as exc:
            await _abort_completion_control_claim(control_claim)
            raise HTTPException(status_code=409, detail=str(exc)) from exc
    else:
        await postgres_db.update_job_cloud_diff(job_id, diff_status="rejected")
        await postgres_db.update_job_merge_status(job_id, merge_status="cloud-rejected")
        await postgres_db.update_job_status(job_id, status="completed")
        await postgres_db.merge_job_context(job_id, {"loop_cloud_delivery": delivery})
    job["status"] = "completed"
    job["diff_status"] = "rejected"
    job["merge_status"] = "cloud-rejected"
    _reject_ctx = job.get("context") or {}
    if isinstance(_reject_ctx, str):
        try:
            _reject_ctx = json.loads(_reject_ctx)
        except (json.JSONDecodeError, TypeError):
            _reject_ctx = {}
    if not isinstance(_reject_ctx, dict):
        _reject_ctx = {}
    _reject_ctx["loop_cloud_delivery"] = delivery
    job["context"] = _reject_ctx

    terminal_actions: list[str] = []
    from services.project_loops import job_loop_id

    if job_loop_id(job):
        await _advance_project_loop(job, {}, terminal_actions)
    else:
        from services.completion import apply_terminal_job_side_effects

        side_effects = await apply_terminal_job_side_effects(
            job,
            "completed",
            gitea=gitea_client,
            db=postgres_db,
            vector_db=vector_db,
        )
        terminal_actions.extend(side_effects["actions"])
    logger.info("Mode A: job %s — diff rejected", job_id)
    return {
        "job_id": job_id,
        "diff_status": "rejected",
        "status": "completed",
        "actions": terminal_actions,
    }


_EXPORT_SLUG_STRIP = re.compile(r"[^a-z0-9]+")
_EXPORT_SLUG_MAX = 40


def _job_export_folder_name(job_id: str, description: str | None) -> str:
    """Human-readable, stable folder name for a job's Mode B export.

    A cloud root full of ``job-a6fa6f2a9101`` folders is unnavigable after a
    handful of exports, so lead with a slug of the job's prompt and keep a short
    id suffix for uniqueness (two jobs can share a description) — e.g.
    ``you-maintain-a-daily-digest-a6fa6f2a``.

    Must stay **deterministic**: the endpoint is re-syncable and re-derives this
    name to find the folder again. ``description`` is fixed at job creation, so
    the same job always maps to the same name. Output is restricted to
    ``[a-z0-9-]``, which is a safe single path segment for every backend
    (both build ``sessions/<name>`` over WebDAV).
    """
    short = job_id.replace("-", "")
    # splitlines() on a blank string yields [], so index defensively.
    lines = (description or "").strip().splitlines()
    first_line = lines[0] if lines else ""
    # Fold accents so "Führe" slugs to "fuhre", not "f-hre".
    folded = (
        unicodedata.normalize("NFKD", first_line)
        .encode("ascii", "ignore")
        .decode("ascii")
    )
    slug = _EXPORT_SLUG_STRIP.sub("-", folded.lower()).strip("-")
    if len(slug) > _EXPORT_SLUG_MAX:
        slug = slug[:_EXPORT_SLUG_MAX].rsplit("-", 1)[0].strip("-")
    if not slug:
        # Descriptions are NOT NULL but can be punctuation-only in theory.
        return f"job-{short[:12]}"
    return f"{slug}-{short[:8]}"


def _common_dir_prefix(paths: list[str]) -> str:
    """Longest whole-segment directory prefix shared by every path.

    ``["output/digest.md"]`` -> ``"output"``;
    ``["repo/src/a.py", "repo/tests/b.py"]`` -> ``"repo"``;
    ``["spec.yaml", "repo/a.py"]`` -> ``""``.

    Segment-wise, so ``["out/a.md", "output/b.md"]`` shares nothing rather than
    the string prefix ``"out"``. The last component of each path is the
    filename and never counts.
    """
    if not paths:
        return ""
    common = paths[0].split("/")[:-1]
    for path in paths[1:]:
        segments = path.split("/")[:-1]
        keep = 0
        while (
            keep < len(common)
            and keep < len(segments)
            and common[keep] == segments[keep]
        ):
            keep += 1
        common = common[:keep]
        if not common:
            break
    return "/".join(common)


@app.post("/api/jobs/{job_id}/export-to-shared-folder")
async def export_job_to_shared_folder(request: Request, job_id: str) -> dict[str, Any]:
    """Mode B of the job cloud workflow — copy a job's deliverables into a
    shared cloud folder ("Open cloud folder") and return its browser URL.

    Valid for ``completed`` or ``pending_review`` jobs whose project has **no**
    main-cloud folder (loose jobs and default-project / no-cloud-folder jobs);
    jobs whose project *does* have a cloud folder go through the Mode A
    diff-review flow instead. Copies the agent's declared deliverables (from
    ``freeze_data.deliverables``; falls back to ``output/`` for jobs without a
    deliverables list) into a per-job session-style cloud folder shared with the
    calling user. Workspace-relative paths are kept **except** for the leading
    directories every deliverable shares, which are collapsed
    (``_common_dir_prefix``) so a lone ``output/digest.md`` opens as
    ``digest.md`` instead of hiding a level down.

    Re-syncable: a repeat call overwrites the same folder and re-stamps
    ``exported_at`` as "last synced at" (e.g. after resume-with-feedback). The
    folder name is derived deterministically from the job, and a job that has
    been exported before reuses its stored handle. v1 overwrites in place and
    does not prune files removed between syncs — note that a re-sync after the
    deliverable set changes can therefore leave files from the previous shape
    behind, since the collapsed prefix is recomputed per call.

    See knowledge-history/done/job_cloud_export.md §3.2.
    """
    user, job = await require_job_access(request, postgres_db, job_id)

    # Status gate — completed or in-review. In-review (pending_review) export
    # lets the user preview the deliverables in the cloud before approving;
    # failed/cancelled/in-flight jobs have no stable output to copy.
    if job.get("status") not in ("completed", "pending_review"):
        raise HTTPException(
            status_code=409,
            detail=(
                f"Job is in status '{job.get('status')}'; "
                "only completed or in-review jobs can be exported."
            ),
        )

    # Routing gate — only jobs whose project has a main-cloud folder use the
    # Mode A diff flow. Loose jobs AND default-project / no-cloud-folder jobs
    # fall through to Mode B here (mirrors the seed gate in
    # services/job_cloud_baseline.py). ``project_has_cloud_folder`` is computed
    # by the projects LEFT JOIN in postgres.get_job.
    if job.get("project_has_cloud_folder"):
        raise HTTPException(
            status_code=409,
            detail=(
                "Job's project has a cloud folder — use the diff-review "
                "(accept/reject) flow instead of shared-folder export."
            ),
        )

    # No idempotency refusal: this endpoint is re-syncable. The folder id is
    # derived deterministically from the job id below, so a repeat call
    # overwrites the same folder (e.g. after resume-with-feedback) and
    # re-stamps ``exported_at`` as "last synced at".

    # Fresh loose-job export folder — no project/thread row to pin to yet,
    # so resolve via the owner seam (returns the active backend today;
    # per-org under multi-tenancy). Issue 16, knowledge-base/knowledge/issues/main_cloud.md.
    backend = main_cloud_router.for_owner(user)
    if not backend.is_initialized:
        raise HTTPException(status_code=503, detail="Cloud backend not available.")
    if not gitea_client.is_initialized:
        raise HTTPException(status_code=503, detail="Gitea not available.")

    repo_name, branch = await resolve_job_repo(job_id)

    # 1) Provision shared folder. A job that has been exported before keeps the
    #    folder it already has — re-deriving the name would strand the old
    #    folder (and its share) whenever the naming scheme changes, which it did
    #    once already when these went from `job-<uuid>` to slugged names.
    previous_handle = job.get("exported_folder_handle")
    if previous_handle:
        folder_session_id = (
            SessionFolderHandle.from_db(previous_handle, backend=backend.backend_id)
            .native_id.rstrip("/")
            .split("/")[-1]
        )
    else:
        folder_session_id = _job_export_folder_name(job_id, job.get("description"))
    try:
        folder_handle = await backend.ensure_session_folder(
            session_id=folder_session_id
        )
        resolved_user_id = await backend.ensure_user(
            sub=user.get("keycloak_sub") or "",
            issuer=getattr(backend, "_keycloak_issuer", "") or "",
            email=user.get("email"),
            display_name=user.get("display_name"),
            preferred_username=user.get("preferred_username"),
        )
        if resolved_user_id:
            await backend.share_session_folder(folder_handle, resolved_user_id)
        else:
            # Not fatal — the files still land in the agent's cloud home and a
            # later re-sync shares them once the account exists. But it IS the
            # difference between "the folder opens" and "the folder 404s", so
            # say so loudly here and hand the caller a `shared: false` it can
            # surface. Backends that cannot provision accounts themselves
            # (Nextcloud: user_oidc materialises the account on the user's
            # first browser login) resolve to None until the user has signed
            # in to the cloud at least once.
            logger.warning(
                "Mode B export: no %s account for user %s (email=%r) — folder "
                "%s created but NOT shared; the user must sign in to the cloud "
                "once before it becomes visible to them",
                backend.backend_id,
                user.get("id"),
                user.get("email"),
                folder_session_id,
            )
    except CloudBackendError as e:
        logger.exception("Mode B export: folder provisioning failed for job %s", job_id)
        raise HTTPException(
            status_code=502,
            detail=f"Cloud folder provisioning failed: {e}",
        ) from e

    # 2) Copy the job's deliverables from Gitea → cloud, bytes-faithful via
    #    get_file_bytes so binary outputs (PDFs, images) survive the round trip
    #    and the declared workspace-relative paths are preserved. The agent's
    #    declared deliverables (validated non-empty at freeze time) are the
    #    curated result set — for code jobs they live under ``repo/`` and the
    #    workspace root, not ``output/``. Jobs without a deliverables list
    #    (older jobs) fall back to copying ``output/`` wholesale. Per-file read
    #    failures in the deliverables path are logged and skipped (fail-soft) so
    #    one missing artifact doesn't sink the whole export; ``files_copied``
    #    reflects what actually landed.
    files_copied = 0

    # Declared deliverables from freeze_data (JSONB may arrive as a str).
    freeze_data = job.get("freeze_data")
    if isinstance(freeze_data, str):
        try:
            freeze_data = json.loads(freeze_data)
        except (json.JSONDecodeError, TypeError):
            freeze_data = None
    deliverables: list[str] = []
    if isinstance(freeze_data, dict) and isinstance(
        freeze_data.get("deliverables"), list
    ):
        deliverables = [
            str(p).strip() for p in freeze_data["deliverables"] if str(p).strip()
        ]

    async def _list_tree(src_dir: str) -> list[str]:
        """Repo-relative paths of every file under ``src_dir``, recursively."""
        found: list[str] = []
        entries = await gitea_client.list_contents(repo_name, src_dir, ref=branch)
        for entry in entries or []:
            entry_type = entry.get("type")
            if entry_type == "dir":
                found.extend(await _list_tree(entry["path"]))
            elif entry_type == "file":
                found.append(entry["path"])
        return found

    async def _copy(rel: str, dest: str, *, required: bool) -> None:
        nonlocal files_copied
        file_bytes = await gitea_client.get_file_bytes(repo_name, rel, ref=branch)
        if file_bytes is None:
            if required:
                raise HTTPException(
                    status_code=502,
                    detail=f"Failed to read '{rel}' from Gitea.",
                )
            # Declared but absent from the repo (e.g. a directory entry or a
            # workspace-only artifact). Skip fail-soft rather than 502.
            logger.warning(
                "Mode B export: deliverable %r not found in repo %s; skipping",
                rel,
                repo_name,
            )
            return
        await backend.put_session_file(folder_handle, path=dest, content=file_bytes)
        files_copied += 1

    try:
        if deliverables:
            # Declared paths are workspace-root-relative, matching the job's
            # Gitea repo layout. Reject path escapes defensively.
            sources: list[str] = []
            for declared in deliverables:
                rel = declared.lstrip("/")
                if not rel or ".." in rel.split("/"):
                    logger.warning(
                        "Mode B export: skipping unsafe deliverable path %r", declared
                    )
                    continue
                sources.append(rel)
            # A declared-but-missing deliverable is not fatal (see _copy).
            required = False
        else:
            # No declared deliverables (older jobs) — copy output/ wholesale.
            sources = await _list_tree("output")
            required = True

        # Collapse the wrapper directories every file shares, so a job whose one
        # deliverable is output/digest.md lands as digest.md at the folder root
        # rather than behind two clicks. Structure that actually distinguishes
        # files survives — repo/src/a.py + repo/tests/b.py only lose `repo/`.
        prefix = _common_dir_prefix(sources)
        for rel in sources:
            await _copy(
                rel,
                rel[len(prefix) + 1 :] if prefix else rel,
                required=required,
            )
    except HTTPException:
        raise
    except CloudBackendError as e:
        logger.exception(
            "Mode B export: cloud upload failed for job %s (copied %d)",
            job_id,
            files_copied,
        )
        raise HTTPException(
            status_code=502,
            detail=f"File copy to cloud failed after {files_copied} files: {e}",
        ) from e
    except Exception as e:
        logger.exception("Mode B export: unexpected failure for job %s", job_id)
        raise HTTPException(
            status_code=502,
            detail=f"Export failed: {e}",
        ) from e

    # 3) Stamp the job — only on success so retries are safe.
    await postgres_db.update_job_exported_folder(job_id, handle=folder_handle.to_db())

    return {
        "job_id": job_id,
        "files_copied": files_copied,
        # False = copied, but the folder is not visible to the caller yet (see
        # the ensure_user miss above). The cockpit turns this into a distinct
        # toast instead of claiming an unqualified success.
        "shared": bool(resolved_user_id),
        "folder": {
            "name": folder_session_id,
            # Where the caller will actually find it: the share lands at the
            # root of their own cloud drive, so the folder name IS the path.
            # Sent explicitly so the cockpit doesn't have to assume that.
            "path": f"/{folder_session_id}",
            "browser_url": backend.get_session_folder_browser_url(folder_handle),
            "webdav_url": backend.get_session_folder_webdav_url(folder_handle),
        },
    }


@app.get("/api/jobs/{job_id}/todos")
async def get_job_todos(request: Request, job_id: str) -> dict[str, Any]:
    """Get all todos for a job (current + archives) from its Gitea repo.

    Reads the committed state as of the worker's last phase-boundary push:
    ``todos.yaml`` at the job branch head plus ``archive/todos_*.md`` phase
    archives.

    Gracefully degrades — Gitea unavailable or repo/files missing yields the
    empty shape instead of an error, because the cockpit todo view renders
    this response directly.

    Returns:
        Dict with:
        - job_id: Job UUID
        - current: Current todos from todos.yaml (if the worker pushed one)
        - archives: List of archived todo files
        - has_workspace: Whether the job's Gitea repo was reachable
    """
    await require_job_access(request, postgres_db, job_id)

    current: dict[str, Any] | None = None
    archives: list[dict[str, Any]] = []
    has_workspace = False

    if gitea_client.is_initialized:
        repo_name, job_branch = await resolve_job_repo(job_id)
        root_entries = await gitea_client.list_contents(repo_name, "", ref=job_branch)
        if root_entries is not None:
            has_workspace = True
            content = await gitea_client.get_file_content(
                repo_name, "todos.yaml", ref=job_branch
            )
            if content is not None:
                current = parse_current_todos(content)
            archive_entries = await gitea_client.list_contents(
                repo_name, "archive", ref=job_branch
            )
            archives = build_archive_listing(archive_entries)

    return {
        "job_id": job_id,
        "current": current,
        "archives": archives,
        "has_workspace": has_workspace,
    }


@app.get("/api/jobs/{job_id}/todos/current")
async def get_current_todos(request: Request, job_id: str) -> dict[str, Any]:
    """Get current active todos from todos.yaml in the job's Gitea repo.

    Committed state as of the worker's last phase-boundary push.

    Returns:
        Dict with todos list and metadata, or 404 if not found
    """
    await require_job_access(request, postgres_db, job_id)
    result: dict[str, Any] | None = None
    if gitea_client.is_initialized:
        repo_name, job_branch = await resolve_job_repo(job_id)
        content = await gitea_client.get_file_content(
            repo_name, "todos.yaml", ref=job_branch
        )
        if content is not None:
            result = parse_current_todos(content)
    if result is None:
        raise HTTPException(
            status_code=404, detail=f"No current todos found for job '{job_id}'"
        )
    return result


@app.get("/api/jobs/{job_id}/todos/archives")
async def list_todo_archives(request: Request, job_id: str) -> list[dict[str, Any]]:
    """List archived todo files from the job repo's ``archive/`` directory.

    Committed state as of the worker's last phase-boundary push. Empty list
    when Gitea is unavailable or the repo has no archives yet.

    Returns:
        List of archive metadata (filename, phase_name, timestamp)
    """
    await require_job_access(request, postgres_db, job_id)
    if not gitea_client.is_initialized:
        return []
    repo_name, job_branch = await resolve_job_repo(job_id)
    entries = await gitea_client.list_contents(repo_name, "archive", ref=job_branch)
    return build_archive_listing(entries)


@app.get("/api/jobs/{job_id}/todos/archives/{filename}")
async def get_archived_todos(
    request: Request, job_id: str, filename: str
) -> dict[str, Any]:
    """Get parsed content of an archived todo file from the job's Gitea repo.

    Committed state as of the worker's last phase-boundary push.

    Args:
        job_id: Job UUID
        filename: Archive filename (e.g., "todos_phase1_20260124_183618.md")

    Returns:
        Dict with parsed todos, summary, and metadata
    """
    await require_job_access(request, postgres_db, job_id)
    result: dict[str, Any] | None = None
    # Security: same filename sanitation the local-disk route enforced
    safe = not (".." in filename or "/" in filename or "\\" in filename)
    if safe and gitea_client.is_initialized:
        repo_name, job_branch = await resolve_job_repo(job_id)
        content = await gitea_client.get_file_content(
            repo_name, f"archive/{filename}", ref=job_branch
        )
        if content is not None:
            result = parse_archived_todos(content, filename)
    if result is None:
        raise HTTPException(
            status_code=404, detail=f"Archive '{filename}' not found for job '{job_id}'"
        )
    return result


