def _build_datasource_tool_override(
    datasources: list[dict[str, Any]], config_override: dict[str, Any] | None
) -> dict[str, Any]:
    """Inject/strip database tool categories based on attached datasources.

    For each known datasource type, if a datasource is attached, the corresponding
    tool category is injected. If not attached, the category is set to an empty list.
    This ensures the agent only has database tools for databases that are actually
    connected.

    Args:
        datasources: List of resolved datasource dicts (from resolve_datasources_for_job)
        config_override: Existing config override dict (may be None)

    Returns:
        Updated config override dict with tool categories adjusted
    """
    override = dict(config_override or {})
    tools_override = dict(override.get("tools", {}))
    # Shared single source of truth with the agent's session attach path
    # (they previously disagreed on read-write managed connectors). Email is
    # tier-keyed inside the shared map (EMAIL_TIER_TOOLS keyed by
    # config.access, clamped by project_read_only) — no extra handling here.
    enabled_datasources = [
        datasource
        for datasource in datasources
        if _mcp_datasource_runtime_allowed(datasource)
    ]
    tools_override.update(datasource_tool_categories(enabled_datasources))
    override["tools"] = tools_override
    return override


def _apply_cloud_storage_override(
    resolved_ds: list[dict[str, Any]], job_context: dict[str, Any]
) -> None:
    """Apply job-level cloud_storage_read_only override to WebDAV datasources.

    If the job's context contains cloud_storage_read_only, it overrides the
    project-level read_only setting on any webdav datasource in the resolved list.
    Mutates resolved_ds in place.
    """
    override = job_context.get("cloud_storage_read_only")
    if override is None:
        return
    for ds in resolved_ds:
        if ds["type"] == "webdav":
            ds["project_read_only"] = bool(override)


def _build_datasources_payload(
    resolved_ds: list[dict[str, Any]],
) -> list[dict[str, Any]] | None:
    """Build the datasources payload for sending to the agent.

    Strips internal fields (id, job_id, created_at, updated_at) that the
    agent doesn't need. For read-only managed connectors, credentials are
    withheld (tools hold them internally).

    Args:
        resolved_ds: List of resolved datasource dicts from the database

    Returns:
        List of datasource dicts for the agent, or None if empty
    """
    if not resolved_ds:
        return None

    managed_types = {"postgresql", "neo4j", "mongodb", "webdav", "email"}
    payload = []
    email_forwarded = False
    for ds in resolved_ds:
        creds = ds.get("credentials") or {}
        if isinstance(creds, str):
            import json as json_module

            try:
                creds = json_module.loads(creds)
            except (json.JSONDecodeError, ValueError):
                creds = {}

        is_read_only = ds.get("project_read_only", False)
        ds_type = ds["type"]
        if not _mcp_datasource_runtime_allowed(ds):
            continue

        # Read-only managed connectors: withhold credentials (tools hold them).
        # Email is exempt — its tools need a live IMAP login at every tier;
        # read-only is expressed as the access floor on entry['config'] instead.
        if ds_type in managed_types and is_read_only and ds_type != "email":
            creds = {}

        # External OKF KBs are centrally indexed and read-only in Slice 4 v1.
        # The agent needs the stable index id + display metadata, never the
        # remote URL or repository credentials.
        if ds_type == "kb":
            creds = {}
            is_read_only = True

        entry = {
            "type": ds_type,
            "name": ds["name"],
            "description": ds.get("description"),
            "connection_url": None if ds_type == "kb" else ds.get("connection_url"),
            "credentials": creds,
            "project_read_only": is_read_only,
        }
        if ds_type == "kb":
            entry["datasource_id"] = str(ds["id"])
            # stored=True keeps the native-project marker in the payload: the
            # agent's binding builder needs it to collapse a project's own KB
            # row into the writable native binding instead of adding a second,
            # read-only binding for the same notes.
            entry["config"] = _normalize_kb_config(ds.get("config"), stored=True)
        if ds_type == "repository":
            # Repository identity is server-owned runtime authority.  Keep the
            # raw database ``id`` out of the payload, but carry its exact value
            # under the dedicated internal key consumed by the clone/tool
            # binding.  ``resolved_ds`` comes from the authorization query;
            # callers and models never select this field.
            datasource_id = ds.get("id")
            if datasource_id is not None:
                entry["datasource_id"] = str(datasource_id)
            # The clone reads config["forge"] to resolve the forge API base;
            # without it every repository records forge="" and repo_open_pr
            # can never be used. _datasource_row_to_dict already parsed the
            # JSONB, so this is a real dict. No secrets live in config —
            # credentials travel in `creds`.
            entry["config"] = ds.get("config") or {}
        if ds_type == "email":
            # v1: one mailbox per job/session — the agent keys connections by
            # type, so a second email datasource would silently shadow the
            # first (knowledge-base/knowledge/features/email_datasource.md, open questions).
            if email_forwarded:
                logger.warning(
                    "Skipping additional email datasource %r: only one email "
                    "datasource per job/session is supported",
                    ds.get("name"),
                )
                continue
            email_forwarded = True
            entry["config"] = email_dispatch_config(
                ds.get("config"),
                project_read_only=bool(is_read_only),
                owner_can_autonomous_send=bool(
                    ds.get("_owner_can_autonomous_send", False)
                ),
            )
        if ds.get("cli_hint"):
            entry["cli_hint"] = ds["cli_hint"]
        if ds.get("default_branch"):
            entry["default_branch"] = ds["default_branch"]
        if ds_type == "repository" and ds.get("require_default_branch") is True:
            entry["require_default_branch"] = True

        payload.append(entry)

    return payload or None


def _mcp_datasource_runtime_allowed(datasource: dict[str, Any]) -> bool:
    """Apply deployment gates to a resolved datasource without exposing secrets."""
    if datasource.get("type") != "mcp":
        return True
    if not _mcp_datasources_enabled():
        return False
    credentials = datasource.get("credentials") or {}
    if isinstance(credentials, str):
        try:
            credentials = json.loads(credentials)
        except (json.JSONDecodeError, ValueError):
            credentials = {}
    transport = (
        credentials.get("transport", "http")
        if isinstance(credentials, dict)
        else "http"
    )
    return str(transport).lower() != "stdio" or _mcp_stdio_enabled()


@app.post("/api/jobs/{job_id}/assign/{agent_id}")
async def assign_job_to_agent(
    request: Request, job_id: str, agent_id: str
) -> dict[str, str]:
    """Administrative scheduling override for a job.

    **Admin only** (P4c). Normal callers should rely on automatic dispatch.
    If the managed workspace is not live, this endpoint sheds stale workspace
    state and queues normal provisioning instead of dispatching an incomplete
    SSH configuration. The requested agent is not reserved in that case.

    With a live workspace, validates the agent and delegates to the shared
    start/resume helper. Accepts 'created', 'failed', or 'paused' jobs.
    """
    await _require_admin(request)
    try:
        job = await postgres_db.get_job(job_id)
        if not job:
            raise HTTPException(status_code=404, detail=f"Job '{job_id}' not found")

        if job.get("execution_lane", "pinned") != "pinned":
            raise HTTPException(
                status_code=409,
                detail=(
                    "Stateless jobs are claimed from the run queue and cannot "
                    "be assigned directly to a registered agent"
                ),
            )

        if job["status"] not in ("created", "failed", "paused"):
            raise HTTPException(
                status_code=400,
                detail=f"Job cannot be assigned (status: {job['status']})",
            )

        await _guard_completion_control(job_id, source="manual_assign")

        workspace_action, job, workspace_reason = await _prepare_job_workspace_runtime(
            job
        )
        if workspace_action != "proceed":
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "workspace_runtime_adoption_pending",
                    "message": (
                        "Live Kubernetes workspace authority is not yet available; "
                        "no agent was reserved"
                    ),
                    "retryable": workspace_action == "wait",
                    "failure": workspace_reason,
                },
            )

        workspace_decision = resolve_workspace_runtime(job, vm_mode=vm_provisioner.mode)
        if workspace_decision.contract is None or workspace_decision.state == "invalid":
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "workspace_contract_invalid",
                    "message": (
                        "Job workspace authority is ambiguous; no agent was reserved"
                    ),
                    "state": workspace_decision.state,
                    "failure": workspace_decision.reason,
                },
            )

        missing_workspace = _resume_missing_workspace(job)
        if missing_workspace:
            if COMPLETION_COMMANDS_ENABLED:
                control_claim = await _claim_completion_control(
                    {**job, "id": job_id}, source="manual_assign_workspace"
                )
                try:
                    queued = await postgres_db.prepare_pinned_job_for_workspace_resume(
                        job_id,
                        _WORKSPACE_CONTEXT_KEYS[missing_workspace],
                        expected_status=str(job["status"]),
                        completion_control_claim_id=str(control_claim.claim_id),
                    )
                except Exception:
                    await _abort_completion_control_claim(control_claim)
                    raise
                if not queued:
                    await _abort_completion_control_claim(control_claim)
                    raise HTTPException(
                        status_code=409,
                        detail="Job changed while it was being queued for provisioning",
                    )
            else:
                await postgres_db.shed_workspace_context(
                    job_id, _WORKSPACE_CONTEXT_KEYS[missing_workspace]
                )
            if job["status"] != "created" and not COMPLETION_COMMANDS_ENABLED:
                queued = await postgres_db.queue_job_for_resume(
                    job_id,
                    **_completion_resume_guard_kwargs(),
                )
                if not queued:
                    raise HTTPException(
                        status_code=409,
                        detail="Job changed while it was being queued for provisioning",
                    )
            _trigger_dispatch()
            return {
                "status": "queued",
                "job_id": job_id,
                "message": (
                    f"No live {missing_workspace} workspace; queued for automatic "
                    "provisioning and assignment. The requested agent was not reserved."
                ),
            }

        agent = await postgres_db.get_agent(agent_id)
        if not agent:
            raise HTTPException(status_code=404, detail=f"Agent '{agent_id}' not found")

        if agent["status"] != "ready":
            raise HTTPException(
                status_code=400,
                detail=f"Agent is not ready (status: {agent['status']})",
            )

        if not agent.get("pod_ip"):
            raise HTTPException(
                status_code=400,
                detail="Agent has no pod IP configured",
            )

        if not await _prepare_job_repository_before_claim(job):
            raise HTTPException(
                status_code=409,
                detail="Job repository authority is not ready",
            )
        if not await postgres_db.claim_job_for_agent(
            job_id,
            agent_id,
            completion_commands_enabled=COMPLETION_COMMANDS_ENABLED,
            allow_failed=True,
        ):
            raise HTTPException(
                status_code=409,
                detail="Job changed while it was being assigned",
            )

        # Use resume path for paused jobs that actually ran, start path for
        # new/failed — and for paused-but-never-started jobs, whose resume
        # would skip task-brief seeding (fresh_job_dispatched_as_resume_
        # skips_seeding.md).
        if resume_lane_applies(
            job, has_checkpoint=await postgres_db.job_has_checkpoint(job_id)
        ):
            success = await _resume_job_on_agent(job, agent)
        else:
            if job["status"] == "paused":
                logger.info(
                    "Assign: job %s is paused with no checkpoint to resume "
                    "from (never started, or pruned at a terminal state) — "
                    "dispatching via the fresh /job/start lane",
                    job_id,
                )
            success = await _dispatch_job_to_agent(job, agent)

        if not success:
            raise HTTPException(
                status_code=502,
                detail="Failed to dispatch job to agent",
            )

        return {"status": "assigned", "agent_id": agent_id, "job_id": job_id}

    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e


# =============================================================================
# Datasource Endpoints
# =============================================================================


def _normalize_datasource_credentials(
    credentials: dict[str, Any] | None,
) -> dict[str, Any] | None:
    """Validate and normalize secret fields in a datasource credentials dict.

    Currently this means: if an ``ssh_key`` is present, run it through
    :func:`validate_private_key`, which trims surrounding whitespace,
    normalizes line endings, and ensures the single trailing newline that
    OpenSSL/libcrypto requires. Raises ``HTTPException(400)`` if the key
    fails structural validation.
    """
    if not credentials:
        return credentials
    ssh_key = credentials.get("ssh_key")
    if ssh_key is None:
        return credentials
    try:
        credentials["ssh_key"] = _validate_ssh_private_key(ssh_key)
    except InvalidSSHKeyError as exc:
        raise HTTPException(status_code=400, detail=f"Invalid ssh_key: {exc}") from exc
    return credentials


def _normalize_kb_config(
    config: dict[str, Any] | None, *, stored: bool = False
) -> dict[str, Any]:
    """Validate the non-secret v1 config for an OKF KB datasource.

    ``root_path`` is relative to the configured repository root. Keep the
    accepted shape intentionally small so misspelled future-looking keys do not
    silently change indexing behavior.

    ``stored=True`` normalizes a config read back out of the database and
    carries the server-owned ``native_project_id`` marker through. User input
    is always normalized without it, so the marker cannot be hand-forged onto
    an external connector to steer it out of the sweep — and, read the other
    way, cannot be stripped off a project's own KB by editing its root path
    (that would drop the vault straight back into the external sweep and
    double-index it; knowledge-base/knowledge/features/knowledge_base_repo_separation.md §6).
    """
    from services.kb_datasources import NATIVE_PROJECT_CONFIG_KEY

    raw = dict(config or {})
    native_project = raw.pop(NATIVE_PROJECT_CONFIG_KEY, None) if stored else None
    unknown = sorted(set(raw) - {"root_path", "forge"})
    if unknown:
        raise HTTPException(
            status_code=400,
            detail=f"Unknown KB config field(s): {', '.join(unknown)}",
        )

    value = raw.get("root_path", "")
    if value is None:
        value = ""
    if not isinstance(value, str):
        raise HTTPException(status_code=400, detail="KB root_path must be a string")
    if "\x00" in value:
        raise HTTPException(status_code=400, detail="KB root_path contains NUL")

    normalized = value.strip().replace("\\", "/")
    if normalized.startswith("/") or urlparse(normalized).scheme:
        raise HTTPException(
            status_code=400,
            detail="KB root_path must be a relative repository path",
        )

    parts: list[str] = []
    for part in normalized.split("/"):
        if part in ("", "."):
            continue
        if part == "..":
            raise HTTPException(
                status_code=400,
                detail="KB root_path must not contain '..'",
            )
        parts.append(part)
    normalized_config = {"root_path": "/".join(parts)}
    forge = raw.get("forge")
    if forge is not None:
        if not isinstance(forge, str):
            raise HTTPException(status_code=400, detail="KB forge must be a string")
        from src.services.forge import SUPPORTED_FORGES

        normalized_forge = forge.strip().lower()
        if normalized_forge not in SUPPORTED_FORGES:
            raise HTTPException(
                status_code=400,
                detail=(
                    f"Unsupported KB forge {normalized_forge!r}; expected one of "
                    f"{sorted(SUPPORTED_FORGES)}"
                ),
            )
        normalized_config["forge"] = normalized_forge
    if native_project:
        normalized_config[NATIVE_PROJECT_CONFIG_KEY] = str(native_project)
    return normalized_config


def _normalize_repository_config(
    config: dict[str, Any] | None, connection_url: str | None
) -> dict[str, Any]:
    """Validate and default the ``forge`` field on a repository datasource.

    Host inference only covers the two SaaS hosts. A self-hosted Gitea and a
    self-hosted GitLab are indistinguishable by URL, so those must declare
    ``forge`` explicitly rather than be guessed at.
    """
    from src.services.forge import SUPPORTED_FORGES  # noqa: PLC0415

    out = dict(config or {})
    forge = str(out.get("forge") or "").strip().lower()

    if not forge:
        host = (urlparse(connection_url or "").hostname or "").lower()
        if host in ("github.com", "www.github.com"):
            forge = "github"
        elif host in ("gitlab.com", "www.gitlab.com"):
            forge = "gitlab"
        else:
            raise HTTPException(
                status_code=400,
                detail=(
                    "Repository connectors on a self-hosted host must declare "
                    f"'forge' explicitly (one of {sorted(SUPPORTED_FORGES)}) — "
                    "a self-hosted Gitea and GitLab cannot be told apart by URL"
                ),
            )

    if forge not in SUPPORTED_FORGES:
        raise HTTPException(
            status_code=400,
            detail=f"Unsupported forge {forge!r}; expected one of {sorted(SUPPORTED_FORGES)}",
        )

    out["forge"] = forge
    return out


def _validate_kb_repository_url(connection_url: str | None) -> str:
    """Require a safe network Git URL with no embedded credentials."""
    value = (connection_url or "").strip()
    if not value:
        raise HTTPException(
            status_code=400,
            detail="OKF Knowledge Base connectors require a repository URL",
        )
    from services.kb_git_source import validate_git_remote_url

    try:
        return validate_git_remote_url(value, allow_local=False)
    except ValueError as exc:
        raise HTTPException(
            status_code=400,
            detail=str(exc),
        ) from exc


def _validate_kb_repository_auth(
    connection_url: str,
    credentials: dict[str, Any] | None,
) -> None:
    """Reject unsafe OKF repository transport/auth combinations pre-persist."""
    from services.kb_git_source import validate_git_auth_configuration

    try:
        validate_git_auth_configuration(
            connection_url,
            credentials,
            allow_local=False,
        )
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc


@app.post(
    "/api/datasources/ssh-keys/generate",
    response_model=SSHKeyGenerateResponse,
)
async def generate_datasource_ssh_key(
    request: Request,
    body: SSHKeyGenerateRequest | None = None,
) -> SSHKeyGenerateResponse:
    """Generate a fresh ed25519 SSH keypair for the user to paste into the form.

    **P4e** — gated to approved users. The keypair is ephemeral (no DB
    write); the gate just blocks anonymous CPU-burn from key generation.

    The private half is returned in OpenSSH PEM format (already normalized
    with a trailing newline so it round-trips through validation) and the
    public half is returned in the single-line authorized_keys format the
    user pastes into their provider's deploy-keys UI. The server does not
    persist the keypair — storage happens when the user submits the
    datasource form, which re-validates the private key via the same
    ssh_key path as a hand-pasted key.
    """
    await require_approved_user(request, postgres_db)
    comment = (body.comment if body else None) or ""
    keypair = _generate_ed25519_keypair(comment=comment)
    return SSHKeyGenerateResponse(
        private_key=keypair.private_key,
        public_key=keypair.public_key,
    )


@app.get("/api/datasources")
async def list_datasources(
    request: Request,
    job_id: str | None = Query(
        default=None, description="Filter by job ID (use 'global' for global-only)"
    ),
    type: str | None = Query(
        default=None, description="Filter by type (postgresql, neo4j, mongodb)"
    ),
    limit: int = Query(default=100, ge=1, le=500),
) -> list[dict[str, Any]]:
    """List connectors visible to the caller.

    F3: each row is scoped (admin / creator / project member) and the
    `credentials` field is stripped from every row.
    """
    user = await require_approved_user(request, postgres_db)
    try:
        rows = await postgres_db.list_datasources(
            job_id=job_id, ds_type=type, limit=limit
        )
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e
    # Batch the visibility filter: one project-link fetch + one membership
    # resolution for the whole page (was a per-row N x (1 + M) fan-out).
    visible = await filter_visible_datasources(user, postgres_db, rows)
    return redact_datasources(visible)


@app.get("/api/datasources/catalog")
async def list_datasource_catalog(
    request: Request,
    q: str | None = Query(default=None, max_length=200),
    type: str | None = Query(default=None),
    project_id: str | None = Query(default=None),
    scope_mode: str | None = Query(default=None),
    auto_attach: bool | None = Query(default=None),
    visibility: str | None = Query(default=None),
    ownership: str | None = Query(default=None),
    availability: str | None = Query(default=None),
    limit: int = Query(default=50, ge=1, le=100),
    cursor: str | None = Query(default=None),
) -> dict[str, Any]:
    """Cursor-paginated connector management catalog.

    Authorization and every filter are applied before the stable cursor/limit;
    this avoids the legacy newest-100 raw-row cap hiding older owned rows.
    """
    user = await require_approved_user(request, postgres_db)
    scope_project_id = mcp_scope_project_id(user)
    if project_id:
        await require_project_member(request, postgres_db, project_id)
    if scope_project_id and project_id and str(project_id) != str(scope_project_id):
        raise HTTPException(status_code=403, detail="Access denied by MCP token scope")

    visible = await user_visible_project_ids(user, postgres_db)
    visible_project_ids = [] if visible == "all" else [str(value) for value in visible]
    if scope_project_id:
        visible_project_ids = [str(scope_project_id)]
    try:
        result = await postgres_db.list_datasource_catalog(
            str(user["id"]),
            visible_project_ids,
            is_admin=bool(user.get("is_admin")),
            restrict_to_projects=bool(scope_project_id),
            q=q,
            ds_type=type,
            project_id=project_id,
            scope_mode=scope_mode,
            auto_attach=auto_attach,
            visibility=visibility,
            ownership=ownership,
            availability=availability,
            limit=limit,
            cursor=cursor,
        )
    except (DatasourcePolicyValidationError, DatasourceCatalogCursorError) as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    result["items"] = redact_datasources(result.get("items") or [])
    return result


@app.get("/api/projects/linkable-datasource-targets")
async def list_linkable_datasource_targets(
    request: Request,
    datasource_id: str | None = Query(default=None),
    q: str | None = Query(default=None, max_length=200),
    limit: int = Query(default=50, ge=1, le=100),
    cursor: str | None = Query(default=None),
) -> dict[str, Any]:
    """Projects addable to a connector policy, plus retained current links."""
    user = await require_approved_user(request, postgres_db)
    if datasource_id:
        await require_datasource_owner(request, postgres_db, datasource_id)
    try:
        result = await postgres_db.list_linkable_datasource_targets(
            str(user["id"]),
            datasource_id=datasource_id,
            is_admin=bool(user.get("is_admin")),
            restrict_project_id=(
                str(mcp_scope_project_id(user)) if mcp_scope_project_id(user) else None
            ),
            q=q,
            limit=limit,
            cursor=cursor,
        )
    except DatasourceCatalogCursorError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc

    return result


@app.get("/api/datasources/eligible")
async def list_eligible_datasources(
    request: Request,
    project_id: list[str] | None = Query(
        default=None,
        description="Project(s) to include linked connectors for (repeatable)",
    ),
) -> list[dict[str, Any]]:
    """Connectors the caller may pre-select for a job/session (the picker
    source of truth).

    Returns the union of: connectors the caller created, public connectors,
    and connectors linked to any supplied project. Credentials are stripped.
    Membership is required for each supplied project (403 otherwise). Used to
    seed the create-job / create-session connector picker; with explicit-only
    resolution the picker is the only way a job gets connectors.
    """
    user = await require_approved_user(request, postgres_db)
    project_ids = list(dict.fromkeys(str(value) for value in (project_id or [])))
    scope_project_id = mcp_scope_project_id(user)
    if scope_project_id is not None:
        scoped_id = str(scope_project_id)
        if project_ids and project_ids != [scoped_id]:
            raise HTTPException(
                status_code=403,
                detail="Access denied by MCP token scope",
            )
        # Omission never widens a project-scoped principal to the projectless
        # catalog: the token's project is the authoritative target context.
        project_ids = [scoped_id]
    for pid in project_ids:
        await require_project_member(request, postgres_db, pid)
    try:
        rows = await postgres_db.list_eligible_datasources(
            str(user["id"]),
            project_ids,
            is_admin=bool(user.get("is_admin")),
        )
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e
    return redact_datasources(rows)


@app.get("/api/datasources/{datasource_id}")
async def get_datasource(request: Request, datasource_id: str) -> dict[str, Any]:
    """Get a single connector by ID. F3: gated + credentials redacted."""
    user, ds = await require_datasource_access(request, postgres_db, datasource_id)
    if user.get("is_admin") or str(ds.get("created_by") or "") == str(user["id"]):
        project_ids = await postgres_db.list_datasource_projects(datasource_id)
        scope_project_id = mcp_scope_project_id(user)
        ds["project_ids"] = (
            [str(scope_project_id)]
            if scope_project_id
            and str(scope_project_id) in {str(value) for value in project_ids}
            else ([] if scope_project_id else project_ids)
        )
    return redact_datasource(ds)


async def _require_scoped_datasource_mutation(
    user: dict[str, Any], datasource: dict[str, Any], datasource_id: str
) -> set[str]:
    """Keep a project-scoped token from mutating a cross-scope connector."""
    scope_project_id = mcp_scope_project_id(user)
    if scope_project_id is None:
        return set()
    project_ids = {
        str(value)
        for value in await postgres_db.list_datasource_projects(datasource_id)
    }
    if datasource.get("scope_mode") != "projects" or project_ids != {
        str(scope_project_id)
    }:
        raise HTTPException(
            status_code=403,
            detail="Access denied by MCP token scope",
        )
    return project_ids


@app.post("/api/datasources")
async def create_datasource(body: DatasourceCreate, request: Request) -> dict[str, Any]:
    """Create a new connector owned by the current user."""
    valid_types = DATASOURCE_TYPES
    if body.type not in valid_types:
        raise HTTPException(
            status_code=400,
            detail=f"Invalid type '{body.type}'. Must be one of: {', '.join(sorted(valid_types))}",
        )
    if body.job_id is not None:
        raise HTTPException(
            status_code=400,
            detail=(
                "New connectors cannot set job_id; attach them through the "
                "job's explicit connector selection"
            ),
        )
    if body.type == "mcp":
        if not _mcp_datasources_enabled():
            raise HTTPException(
                status_code=403,
                detail="MCP connectors are disabled on this deployment",
            )
        _validate_mcp_datasource(body.connection_url, body.credentials or {})

    user = await require_approved_user(request, postgres_db)
    user_id = str(user["id"])

    # Project scope is an execution boundary, so UUID knowledge or ordinary
    # membership is insufficient to add a link. Creation needs management
    # authority for every selected target before the datasource transaction.
    project_ids = list(dict.fromkeys(str(value) for value in body.project_ids or []))
    scope_project_id = mcp_scope_project_id(user)
    if scope_project_id and (
        body.scope_mode != "projects" or set(project_ids) != {str(scope_project_id)}
    ):
        raise HTTPException(
            status_code=403,
            detail="Access denied by MCP token scope",
        )
    for project_id in project_ids:
        await require_project_owner(
            request, postgres_db, project_id, allow_archived=False
        )

    # Publish gate — is_global hands the publisher's stored credentials to
    # every user's agents (knowledge-base/knowledge/features/public_datasources.md).
    if body.is_global and not await postgres_db.user_can_publish_datasource(user):
        raise HTTPException(
            status_code=403,
            detail=(
                "Publishing public connectors requires the "
                "'public_datasources' capability"
            ),
        )
    # Mailboxes are never published — a public email datasource would hand the
    # owner's IMAP/SMTP credentials to every user's agents, so no capability
    # can allow it (knowledge-base/knowledge/features/email_datasource.md).
    if body.type == "email" and body.is_global:
        raise HTTPException(
            status_code=400,
            detail="Email connectors cannot be published (is_global)",
        )
    read_only = body.read_only
    if body.type == "kb":
        if read_only is False:
            raise HTTPException(
                status_code=400,
                detail="Knowledge-base connectors are always read-only",
            )
        if body.is_global:
            read_only = True
    elif body.is_global and read_only is None:
        read_only = True  # invariant: public ⇒ read_only set (RO default)

    connection_url = body.connection_url
    if body.type == "kb":
        connection_url = _validate_kb_repository_url(connection_url)
        datasource_config = _normalize_kb_config(body.config)
    elif body.type == "email":
        # The grant is only consulted when unattended_send is requested, so
        # the common draft-tier create skips the grant-resolution round-trip.
        wants_unattended = bool((body.config or {}).get("unattended_send"))
        owner_has_send_grant = (
            await postgres_db.user_can_autonomous_send(user)
            if wants_unattended
            else False
        )
        try:
            datasource_config = validate_email_config(body.config, owner_has_send_grant)
        except ValueError as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc
    elif body.type == "mcp":
        if (body.credentials or {}).get("transport", "http").lower() == "stdio":
            connection_url = None
        if body.config:
            raise HTTPException(
                status_code=400,
                detail="Connector config is not supported for MCP connectors",
            )
        datasource_config = {}
    elif body.type == "repository":
        datasource_config = _normalize_repository_config(
            body.config, body.connection_url
        )
    else:
        if body.config:
            raise HTTPException(
                status_code=400,
                detail=(
                    "Connector config is only supported for OKF Knowledge "
                    "Bases and email connectors"
                ),
            )
        datasource_config = dict(body.config or {})

    credentials = _normalize_datasource_credentials(body.credentials)
    try:
        credentials = normalize_credential_files(body.type, body.name, credentials)
    except CredentialFileValidationError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    if body.type == "kb":
        _validate_kb_repository_auth(connection_url, credentials)
    if body.type == "email":
        # Shape check runs BEFORE encryption at rest (create_datasource
        # encrypts transparently); smtp block required only for access='send'.
        try:
            credentials = validate_email_credentials(
                credentials, access=datasource_config["access"]
            )
        except ValueError as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc

    try:
        created = await postgres_db.create_datasource(
            name=body.name,
            ds_type=body.type,
            connection_url=connection_url,
            description=body.description,
            credentials=credentials,
            job_id=body.job_id,
            cli_hint=body.cli_hint,
            default_branch=body.default_branch,
            config=datasource_config,
            created_by=user_id,
            is_global=body.is_global,
            read_only=read_only,
            scope_mode=body.scope_mode,
            auto_attach=body.auto_attach,
            project_ids=project_ids,
            authority_user_id=user_id,
            authority_is_admin=bool(user.get("is_admin")),
        )
    except DatasourceProjectAuthorizationError as exc:
        raise HTTPException(
            status_code=403,
            detail="Not authorized to add one or more project links",
        ) from exc
    except DatasourcePolicyValidationError as exc:
        raise HTTPException(status_code=422, detail=str(exc)) from exc
    except HTTPException:
        raise
    except Exception as e:
        error_msg = str(e)
        if "unique" in error_msg.lower() or "duplicate" in error_msg.lower():
            raise HTTPException(
                status_code=409,
                detail=f"A connector named '{body.name}' of type '{body.type}' already exists",
            ) from e
        raise HTTPException(status_code=500, detail=error_msg) from e
    created["project_ids"] = project_ids

    if body.type == "kb":
        await _mark_kb_datasource_pending(str(created["id"]))
        _schedule_kb_datasource_reindex(str(created["id"]), force_full=True)
    return redact_datasource(created)


@app.put("/api/datasources/{datasource_id}")
async def update_datasource(
    request: Request, datasource_id: str, body: DatasourceUpdate
) -> dict[str, Any]:
    """Update a connector. F3: creator/admin only; credentials are preserved."""
    user, existing_ds = await require_datasource_owner(
        request, postgres_db, datasource_id
    )
    scope_project_id = mcp_scope_project_id(user)
    scoped_current_project_ids = await _require_scoped_datasource_mutation(
        user, existing_ds, datasource_id
    )
    if existing_ds.get("type") == "mcp" and not _mcp_datasources_enabled():
        raise HTTPException(
            status_code=403,
            detail="MCP connectors are disabled on this deployment",
        )
    # Publish gate (spec: knowledge-base/knowledge/features/public_datasources.md). Only the
    # false→true transition needs the capability; unpublishing must always
    # work for creator/admin (a revoked grant must not trap a public row).
    if body.is_global is True and not existing_ds.get("is_global"):
        if not await postgres_db.user_can_publish_datasource(user):
            raise HTTPException(
                status_code=403,
                detail=(
                    "Publishing public connectors requires the "
                    "'public_datasources' capability"
                ),
            )
    # Mailboxes are never published — a public email datasource would hand the
    # owner's IMAP/SMTP credentials to every user's agents, so no capability
    # can allow it (knowledge-base/knowledge/features/email_datasource.md).
    if existing_ds.get("type") == "email" and body.is_global is True:
        raise HTTPException(
            status_code=400,
            detail="Email connectors cannot be published (is_global)",
        )
    read_only = body.read_only
    if existing_ds.get("type") == "kb" and read_only is False:
        raise HTTPException(
            status_code=400,
            detail="Knowledge-base connectors are always read-only",
        )
    effective_global = (
        body.is_global
        if body.is_global is not None
        else bool(existing_ds.get("is_global"))
    )
    if effective_global and read_only is None and existing_ds.get("read_only") is None:
        read_only = True  # invariant: public ⇒ read_only set
    # F3: if body.credentials is None or {}, do NOT touch the stored value.
    # The cockpit's edit form sends an empty creds dict when the user
    # didn't re-enter; passing that through would clobber the secret.
    raw_creds = _normalize_datasource_credentials(body.credentials)
    credentials = raw_creds if raw_creds else None
    if credentials is not None and existing_ds.get("type") in CREDENTIAL_FILE_TYPES:
        try:
            credentials = normalize_credential_files(
                existing_ds["type"],
                body.name or existing_ds.get("name", ""),
                credentials,
            )
        except CredentialFileValidationError as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc

    from services.kb_datasources import (
        NATIVE_PROJECT_CONFIG_KEY,
        native_kb_project_id,
    )

    connection_url = body.connection_url
    datasource_config = body.config
    mcp_connection_url_set = False
    reindex_required = False
    native_project = native_kb_project_id(existing_ds)
    policy_fields = {"scope_mode", "project_ids", "auto_attach"}
    policy_changed = bool(policy_fields.intersection(body.model_fields_set))
    if native_project and policy_changed:
        raise HTTPException(
            status_code=409,
            detail="The native project knowledge connector policy is managed by its project",
        )

    # A connector-owner may always revoke an existing link, but every newly
    # added target requires current project-owner authority. This check is
    # deliberately based on the desired-set diff: retained-only projects can
    # survive an edit without being re-authorized or losing their overrides.
    existing_project_ids: set[str] = set()
    if policy_changed:
        existing_project_ids = (
            scoped_current_project_ids
            if scope_project_id
            else set(await postgres_db.list_datasource_projects(datasource_id))
        )
    if "project_ids" in body.model_fields_set:
        desired_project_ids = set(str(value) for value in body.project_ids or [])
        if scope_project_id and desired_project_ids != {str(scope_project_id)}:
            raise HTTPException(
                status_code=403,
                detail="Access denied by MCP token scope",
            )
        for project_id in sorted(desired_project_ids - existing_project_ids):
            await require_project_owner(
                request, postgres_db, project_id, allow_archived=False
            )
    if (
        scope_project_id
        and "scope_mode" in body.model_fields_set
        and body.scope_mode != "projects"
    ):
        raise HTTPException(
            status_code=403,
            detail="Access denied by MCP token scope",
        )
    if existing_ds.get("type") == "kb" and native_project:
        # A project's own KB row is a management surface, not a remote source:
        # it has no repository URL or credentials to validate, and it is never
        # indexed under its datasource id, so no edit here can require a
        # rebuild. Config still goes through the normalizer (unknown keys stay
        # rejected) and the server-owned marker is re-attached, so editing the
        # root path cannot quietly promote the vault into the external sweep
        # and index every note a second time.
        if datasource_config is not None:
            datasource_config = _normalize_kb_config(datasource_config)
            datasource_config[NATIVE_PROJECT_CONFIG_KEY] = native_project
        connection_url = None  # nothing to point at; leave the column alone
    elif existing_ds.get("type") == "kb":
        if connection_url is not None:
            connection_url = _validate_kb_repository_url(connection_url)
            reindex_required = (
                connection_url != str(existing_ds.get("connection_url") or "").strip()
            )
        if datasource_config is not None:
            datasource_config = _normalize_kb_config(datasource_config)
            existing_config = _normalize_kb_config(existing_ds.get("config"))
            reindex_required = reindex_required or (
                datasource_config != existing_config
            )
        if credentials is not None:
            reindex_required = reindex_required or (
                credentials != (existing_ds.get("credentials") or {})
            )
        if body.default_branch is not None:
            reindex_required = reindex_required or (
                (body.default_branch or None)
                != (existing_ds.get("default_branch") or None)
            )
        effective_url = connection_url or str(existing_ds.get("connection_url") or "")
        effective_credentials = (
            credentials
            if credentials is not None
            else (existing_ds.get("credentials") or {})
        )
        _validate_kb_repository_auth(effective_url, effective_credentials)
    elif existing_ds.get("type") == "email":
        if datasource_config is not None:
            wants_unattended = bool(datasource_config.get("unattended_send"))
            owner_has_send_grant = (
                await postgres_db.user_can_autonomous_send(user)
                if wants_unattended
                else False
            )
            try:
                datasource_config = validate_email_config(
                    datasource_config, owner_has_send_grant
                )
            except ValueError as exc:
                raise HTTPException(status_code=400, detail=str(exc)) from exc
        # Validate the EFFECTIVE credential shape against the EFFECTIVE access
        # tier (e.g. flipping access to 'send' without a stored smtp block must
        # 400 here, not fail at first use). Runs BEFORE encryption at rest;
        # preserved (None) credentials are checked but not rewritten.
        effective_email_conf = (
            datasource_config
            if datasource_config is not None
            else (existing_ds.get("config") or {})
        )
        effective_credentials = (
            credentials
            if credentials is not None
            else (existing_ds.get("credentials") or {})
        )
        try:
            checked_credentials = validate_email_credentials(
                effective_credentials,
                access=effective_email_conf.get("access", "draft"),
            )
        except ValueError as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc
        if credentials is not None:
            credentials = checked_credentials
    elif existing_ds.get("type") == "mcp":
        if datasource_config:
            raise HTTPException(
                status_code=400,
                detail="Connector config is not supported for MCP connectors",
            )
        effective_credentials = (
            credentials
            if credentials is not None
            else (existing_ds.get("credentials") or {})
        )
        url_was_supplied = "connection_url" in body.model_fields_set
        effective_url = (
            body.connection_url
            if url_was_supplied
            else existing_ds.get("connection_url")
        )
        _validate_mcp_datasource(effective_url, effective_credentials)
        transport = (effective_credentials.get("transport") or "http").lower()
        if transport == "stdio":
            connection_url = None
            mcp_connection_url_set = bool(
                url_was_supplied or existing_ds.get("connection_url") is not None
            )
    elif (existing_ds.get("type") or "") == "repository":
        if datasource_config is not None:
            effective_url = body.connection_url or existing_ds.get("connection_url")
            datasource_config = _normalize_repository_config(
                datasource_config, effective_url
            )
    elif datasource_config:
        raise HTTPException(
            status_code=400,
            detail=(
                "Connector config is only supported for OKF Knowledge Bases "
                "and email connectors"
            ),
        )
    try:
        policy_result: dict[str, Any] | None = None
        content_fields = {
            "name",
            "description",
            "connection_url",
            "credentials",
            "cli_hint",
            "default_branch",
            "config",
            "is_global",
            "read_only",
        }
        content_changed = bool(content_fields.intersection(body.model_fields_set))
        if policy_changed:
            policy_result = await postgres_db.update_datasource_with_policy(
                datasource_id,
                expected_policy_revision=int(body.policy_revision or 0),
                scope_mode=(
                    body.scope_mode if "scope_mode" in body.model_fields_set else None
                ),
                auto_attach=(
                    body.auto_attach if "auto_attach" in body.model_fields_set else None
                ),
                project_ids=(
                    body.project_ids if "project_ids" in body.model_fields_set else None
                ),
                name=body.name,
                description=body.description,
                connection_url=connection_url,
                credentials=credentials,
                cli_hint=body.cli_hint,
                default_branch=body.default_branch,
                config=datasource_config,
                is_global=body.is_global,
                read_only=read_only,
                connection_url_set=mcp_connection_url_set,
                authority_user_id=str(user["id"]),
                authority_is_admin=bool(user.get("is_admin")),
                authority_project_scope_id=(
                    str(scope_project_id) if scope_project_id else None
                ),
            )
            if policy_result is None:
                raise HTTPException(
                    status_code=404, detail=f"Connector '{datasource_id}' not found"
                )

        if content_changed and not policy_changed:
            update_kwargs = dict(
                datasource_id=datasource_id,
                name=body.name,
                description=body.description,
                connection_url=connection_url,
                credentials=credentials,
                cli_hint=body.cli_hint,
                default_branch=body.default_branch,
                config=datasource_config,
                is_global=body.is_global,
                read_only=read_only,
            )
            if mcp_connection_url_set:
                update_kwargs["connection_url_set"] = True
            if scope_project_id:
                update_kwargs["authority_project_scope_id"] = str(scope_project_id)
            success = await postgres_db.update_datasource(**update_kwargs)
            if not success:
                raise HTTPException(
                    status_code=404, detail=f"Connector '{datasource_id}' not found"
                )

        if existing_ds.get("type") == "kb" and reindex_required:
            await _mark_kb_datasource_pending(datasource_id)
            _schedule_kb_datasource_reindex(datasource_id, force_full=True)

        updated_ds = await postgres_db.get_datasource(datasource_id)
        if not updated_ds:
            raise HTTPException(
                status_code=404, detail=f"Connector '{datasource_id}' not found"
            )
        updated_project_ids = (
            policy_result.get("project_ids", [])
            if policy_result is not None
            else await postgres_db.list_datasource_projects(datasource_id)
        )
        updated_ds["project_ids"] = (
            [str(scope_project_id)]
            if scope_project_id
            and str(scope_project_id) in {str(value) for value in updated_project_ids}
            else ([] if scope_project_id else updated_project_ids)
        )
        if policy_result is not None:
            await log_security_event(
                postgres_db,
                resource_type="datasource",
                event_type="datasource_policy_updated",
                user=user,
                resource_id=datasource_id,
                detail=(
                    f"scope={existing_ds.get('scope_mode', 'all')}->"
                    f"{updated_ds.get('scope_mode', 'all')} "
                    f"auto={bool(existing_ds.get('auto_attach', False))}->"
                    f"{bool(updated_ds.get('auto_attach', False))} "
                    f"projects={len(existing_project_ids)}->"
                    f"{len(updated_ds['project_ids'])} "
                    f"revision={updated_ds.get('policy_revision')}"
                ),
                request=request,
            )
        return redact_datasource(updated_ds)
    except DatasourceScopeAuthorizationError as exc:
        raise HTTPException(
            status_code=403,
            detail="Access denied by MCP token scope",
        ) from exc
    except DatasourceProjectAuthorizationError as exc:
        raise HTTPException(
            status_code=403,
            detail="Not authorized to add one or more project links",
        ) from exc
    except DatasourcePolicyConflictError as exc:
        raise HTTPException(status_code=409, detail=str(exc)) from exc
    except DatasourcePolicyValidationError as exc:
        raise HTTPException(status_code=422, detail=str(exc)) from exc
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e


@app.delete("/api/datasources/{datasource_id}")
async def delete_datasource(request: Request, datasource_id: str) -> dict[str, str]:
    """Delete a connector. F3: creator/admin only."""
    user, datasource = await require_datasource_owner(
        request, postgres_db, datasource_id
    )
    from services.kb_datasources import native_kb_project_id

    if native_kb_project_id(datasource):
        raise HTTPException(
            status_code=409,
            detail="The project knowledge connector is managed by its project",
        )
    await _require_scoped_datasource_mutation(user, datasource, datasource_id)
    scope_project_id = mcp_scope_project_id(user)
    try:
        if datasource.get("type") == "kb":
            success = await _delete_kb_datasource_with_index(
                datasource_id,
                authority_project_scope_id=(
                    str(scope_project_id) if scope_project_id else None
                ),
                deleted_by=str(user["id"]),
            )
        else:
            success = await postgres_db.delete_datasource(
                datasource_id,
                authority_project_scope_id=(
                    str(scope_project_id) if scope_project_id else None
                ),
                deleted_by=str(user["id"]),
            )
        if not success:
            raise HTTPException(
                status_code=404, detail=f"Connector '{datasource_id}' not found"
            )
        return {"status": "deleted"}
    except HTTPException:
        raise
    except DatasourceScopeAuthorizationError as exc:
        raise HTTPException(
            status_code=403,
            detail="Access denied by MCP token scope",
        ) from exc
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e


@app.get("/api/jobs/{job_id}/datasources")
async def get_job_datasources(request: Request, job_id: str) -> list[dict[str, Any]]:
    """Get resolved connectors for a job.

    F3: gated by `require_job_access`; credentials redacted in the
    response (the agent process gets them via internal dispatch, not via
    this endpoint).
    """
    await require_job_access(request, postgres_db, job_id)
    try:
        rows = await postgres_db.resolve_datasources_for_job(job_id)
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e
    return redact_datasources(rows)


@app.get("/api/jobs/{job_id}/pull-request")
async def get_job_pull_request_status(request: Request, job_id: str) -> dict[str, Any]:
    """Read the live state of the PR recorded by ``repo_open_pr``.

    The caller supplies only a job id. The server resolves both the persisted
    PR identity and its credential-bearing repository connector after the
    ordinary job-access check; connector credentials never cross REST.
    """
    _, job = await require_job_access(request, postgres_db, job_id)
    from services.job_delivery import (
        find_pull_request_repository,
        forge_repo_from_datasource,
        parse_job_pull_request,
    )
    from src.services.forge import ForgeError, get_pull_request_status

    pull_request = parse_job_pull_request(job.get("context"))
    if pull_request is None:
        raise HTTPException(
            status_code=404, detail="This job has no recorded pull request"
        )

    try:
        datasources = await postgres_db.resolve_datasources_for_job(job_id)
    except Exception as exc:
        logger.warning(
            "Could not resolve repository connector for job PR status: %s",
            type(exc).__name__,
        )
        raise HTTPException(
            status_code=500, detail="Could not resolve this job's repository"
        ) from exc
    datasource = find_pull_request_repository(pull_request, datasources)
    if datasource is None:
        raise HTTPException(
            status_code=409,
            detail="The recorded pull request's repository is no longer attached",
        )

    try:
        target = forge_repo_from_datasource(datasource)
        status = await get_pull_request_status(target, pull_request.number)
    except ForgeError as exc:
        logger.warning(
            "Live pull request status failed for job %s: %s",
            job_id,
            type(exc).__name__,
        )
        raise HTTPException(
            status_code=502, detail="Live pull request status is unavailable"
        ) from exc

    return {
        "forge": pull_request.forge,
        "repo": pull_request.repo,
        **status,
        # A forge response may omit these display fields; the record written at
        # creation is still authoritative for the delivery identity.
        "url": status.get("url") or pull_request.url,
        "head": status.get("head") or pull_request.head,
        "base": status.get("base") or pull_request.base,
    }


def _review_session_config_values(
    job: dict[str, Any],
) -> tuple[str | None, float | None, list[str]]:
    """Extract only fields supported by the ordinary session-create surface."""
    from services.job_delivery import parse_json_object

    override = parse_json_object(job.get("config_override")) or {}
    resolved = parse_json_object(job.get("resolved_config")) or {}
    resolved_agent = parse_json_object(resolved.get("agent")) or {}
    resolved_llm = parse_json_object(resolved_agent.get("llm")) or {}
    override_llm = parse_json_object(override.get("llm")) or {}

    raw_model = resolved_llm.get("model", override_llm.get("model"))
    model = (
        raw_model.strip() if isinstance(raw_model, str) and raw_model.strip() else None
    )

    raw_temperature = resolved_llm.get("temperature", override_llm.get("temperature"))
    temperature = (
        float(raw_temperature)
        if isinstance(raw_temperature, (int, float))
        and not isinstance(raw_temperature, bool)
        else None
    )

    dropped: list[str] = []
    for key, value in override.items():
        if key == "llm" and isinstance(value, dict):
            dropped.extend(
                f"llm.{subkey}"
                for subkey in value
                if subkey not in {"model", "temperature"}
            )
        elif key == "interactive" and isinstance(value, dict):
            dropped.extend(f"interactive.{subkey}" for subkey in value)
        elif key not in {"llm", "interactive"}:
            # State only the key, never its value: unsupported job config can
            # contain environment/credential material that must not enter the
            # transcript.
            dropped.append(str(key))
    return model, temperature, dropped


def _review_session_config_name(job: dict[str, Any]) -> str:
    """Keep a session profile when one is already present; map workers safely."""
    source = canonical_config_name(str(job.get("config_name") or "worker_base"))
    if source == "session_base":
        return source
    # Bundled expert type is inferred from its declared base by the existing
    # catalogue reader. Arbitrary paths and worker experts deliberately fall
    # back to the session base; worker/session schemas are not interchangeable.
    bundle = _bundled_expert_bundle(source)
    if bundle and bundle.get("expert_type") == "session":
        return source
    return "session_base"


def _brief_text(value: Any, *, limit: int) -> str:
    """Bound one untrusted job string for a plain-text opening event."""
    if not isinstance(value, str):
        return ""
    return " ".join(value.split())[:limit]


def _review_session_opening_event(
    job: dict[str, Any],
    *,
    pull_request: Any,
    session_config_name: str,
    dropped_settings: list[str],
) -> str:
    """Render the durable, non-user-bubble context for a review thread."""
    from services.job_delivery import parse_json_object

    context = parse_json_object(job.get("context")) or {}
    freeze = parse_json_object(job.get("freeze_data")) or {}
    deliverables = context.get("required_deliverables")
    if not isinstance(deliverables, list):
        deliverables = freeze.get("deliverables")
    safe_deliverables = [
        text
        for item in (deliverables if isinstance(deliverables, list) else [])[:50]
        if (text := _brief_text(item, limit=250))
    ]

    source_config = canonical_config_name(str(job.get("config_name") or "worker_base"))
    source_label = _brief_text(source_config, limit=200)
    session_label = _brief_text(session_config_name, limit=200)
    repository = _brief_text(pull_request.repo, limit=500)
    delivered_branch = _brief_text(pull_request.head, limit=500)
    pull_request_url = _brief_text(pull_request.url, limit=2_000)
    base_branch = _brief_text(pull_request.base, limit=500)
    lines = [
        "[Server-derived job review context]",
        f"Job: {job['id']}",
        f"Task: {_brief_text(job.get('description'), limit=2_000)}",
        f"Source repository: {repository}",
        f"Delivered branch: {delivered_branch}",
        f"Pull request: #{pull_request.number} ({pull_request_url})",
        f"Base branch: {base_branch}",
        (
            "Workspace: fresh sandbox checkout through the job's repository "
            "connector; the scratch job workspace is not reused."
        ),
        (
            "Permission mode: supervised for review; the worker's automation "
            "mode is not inherited."
        ),
    ]
    summary = _brief_text(freeze.get("summary"), limit=2_000)
    if summary:
        lines.append(f"Completion summary: {summary}")
    if safe_deliverables:
        lines.append("Declared deliverables:")
        lines.extend(f"- {item}" for item in safe_deliverables)
    if source_config != session_config_name:
        lines.append(
            f"Session profile: {session_label}; worker profile "
            f"{source_label} is not copied because worker and session "
            "profiles have different schemas."
        )
    if dropped_settings:
        safe_dropped = [
            text
            for setting in dropped_settings[:100]
            if (text := _brief_text(setting, limit=200))
        ]
        lines.append(
            "Job-only settings not inherited: " + ", ".join(safe_dropped) + "."
        )
    rendered = "\n".join(lines)
    if len(rendered) > 19_500:
        return rendered[:19_499].rstrip() + "…"
    return rendered


@app.post("/api/jobs/{job_id}/review-session")
async def create_job_review_session(request: Request, job_id: str) -> dict[str, Any]:
    """Create a fresh interactive review from an access-checked job id.

    There is intentionally no request body. Model, scope, connectors and the
    delivered branch are all derived from stored server state; the MCP session
    tool remains unchanged and has no route to ``config_override``.
    """
    _, job = await require_job_access(request, postgres_db, job_id)
    from services.job_delivery import (
        find_pull_request_repository,
        parse_job_pull_request,
        repository_host,
    )

    pull_request = parse_job_pull_request(job.get("context"))
    if pull_request is None:
        raise HTTPException(
            status_code=409,
            detail="This job has no recorded delivered branch to review",
        )

    try:
        datasources = await postgres_db.resolve_datasources_for_job(job_id)
    except Exception as exc:
        logger.warning(
            "Could not resolve connectors for job review session %s: %s",
            job_id,
            type(exc).__name__,
        )
        raise HTTPException(
            status_code=500,
            detail="Could not resolve this job's connectors",
        ) from exc

    source = find_pull_request_repository(pull_request, datasources)
    if source is None or not source.get("id"):
        raise HTTPException(
            status_code=409,
            detail="The delivered repository is no longer attached to this job",
        )
    if any(not datasource.get("id") for datasource in datasources):
        raise HTTPException(
            status_code=500,
            detail="Could not resolve this job's connectors",
        )

    model, temperature, dropped = _review_session_config_values(job)
    session_config_name = _review_session_config_name(job)
    title_description = _brief_text(job.get("description"), limit=80)
    title = f"Review job {str(job['id'])[:8]}"
    if title_description:
        title = f"{title}: {title_description}"

    review_delivery = {
        "job_id": str(job["id"]),
        "datasource_id": str(source["id"]),
        "forge": pull_request.forge,
        "repository_host": repository_host(str(source["connection_url"])),
        "repo": pull_request.repo,
        "branch": pull_request.head,
        "base": pull_request.base,
        "pull_request": {
            "number": pull_request.number,
            "url": pull_request.url,
        },
    }
    body = ThreadCreateRequest(
        title=title,
        config_name=session_config_name,
        project_ids=[str(job["project_id"])] if job.get("project_id") else None,
        datasource_ids=[str(datasource["id"]) for datasource in datasources],
        model=model,
        temperature=temperature,
        permission_mode="supervised",
        # A clone-based repository requires a shell workspace. This is a fixed
        # property of the review workflow, not a copied or caller-supplied job
        # override (the job's vm/virtual choice is deliberately ignored).
        config_override={"workspace": {"backend": "sandbox"}},
    )
    body._trusted_seed = TrustedThreadSeed(
        metadata={"review_delivery": review_delivery},
        opening_event=_review_session_opening_event(
            job,
            pull_request=pull_request,
            session_config_name=session_config_name,
            dropped_settings=dropped,
        ),
    )
    created = await create_thread(body, request)
    return {
        "job_id": str(job["id"]),
        "thread_id": created["thread_id"],
        "status": created.get("status", "created"),
    }


@app.get("/api/datasources/{datasource_id}/index-status")
async def get_datasource_index_status(
    request: Request, datasource_id: str
) -> dict[str, Any]:
    """Return credential-free indexing state for an OKF KB connector."""
