@app.get("/api/stats/agents")
async def get_agent_statistics(request: Request) -> dict[str, Any]:
    """Get agent workforce summary. **Admin only** (G5) — counts the
    fleet by status, which is infra-level data tied to ``/api/agents``."""
    await _require_admin(request)
    try:
        agents = await postgres_db.list_agents(limit=500)

        # Count by status
        status_counts = {
            "total": len(agents),
            "booting": 0,
            "ready": 0,
            "working": 0,
            "completed": 0,
            "failed": 0,
            "offline": 0,
        }

        for agent in agents:
            status = agent.get("status", "unknown")
            if status in status_counts:
                status_counts[status] += 1

        return status_counts
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e


@app.get("/api/stats/stuck")
async def get_stuck_jobs(
    request: Request,
    threshold_minutes: int | None = Query(default=None, ge=1, le=1440),
) -> dict[str, Any]:
    """Get jobs suspected stuck, scoped to the caller's visibility (G5).

    E3 (officer_supervision_surface §5): stuckness comes from the one shared
    liveness computation — audit movement first, then agent heartbeat —
    never from ``jobs.updated_at`` (display metadata poisoned by trigger
    cascades). Rows carry the liveness state and reasons. Jobs whose
    activity evidence is unreachable are returned with
    ``state='unavailable'`` — surfaced uncertainty, not a fabricated
    stuck fact. Admins see the full fleet; non-admins see only jobs they
    own or are project members of.
    """
    user = await require_approved_user(request, postgres_db)
    vis = await _visibility_kwargs_for_stats(user)
    from services.job_liveness import compute_jobs_liveness, get_liveness_policy

    try:
        policy = get_liveness_policy(stall_override_minutes=threshold_minutes)
        processing = await postgres_db.get_processing_jobs(**vis)
        liveness_by_id = await compute_jobs_liveness(
            processing,
            audit_reader=audit_reader,
            db=postgres_db,
            policy=policy,
        )
        stuck: list[dict[str, Any]] = []
        for job in processing:
            liveness = liveness_by_id.get(str(job["id"]))
            if not liveness or liveness["state"] not in (
                "suspected_stuck",
                "unavailable",
            ):
                continue
            row = dict(job)
            row.update(liveness)
            # Legacy shape kept for existing consumers.
            row["stuck_reason"] = "; ".join(liveness.get("reasons") or []) or (
                "No recent activity"
            )
            row["stuck_component"] = "liveness"
            stuck.append(row)
        return {
            "jobs": stuck,
            **policy.stall.as_dict(),
        }
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e


def _parse_utc_date(s: str) -> datetime:
    """Parse an ISO date/datetime as tz-aware UTC (naive → assumed UTC)."""
    d = datetime.fromisoformat(s)
    return (
        d.replace(tzinfo=timezone.utc)
        if d.tzinfo is None
        else d.astimezone(timezone.utc)
    )


def _verification_rounds(job: dict[str, Any] | None) -> list[dict[str, Any]]:
    """Read ``context.verification_rounds`` from a job row.

    asyncpg returns JSONB as a string on the app pool (no codec registered), so
    the context must be coerced at every read. This is the single coercion
    point for the ledger — see
    knowledge-base/knowledge/issues/jsonb_isinstance_guard_without_parse_silent_dead_paths.md.
    """
    if not job:
        return []
    ctx = job.get("context")
    if isinstance(ctx, str):
        try:
            ctx = json.loads(ctx)
        except (json.JSONDecodeError, ValueError):
            return []
    if not isinstance(ctx, dict):
        return []
    rounds = ctx.get("verification_rounds")
    return rounds if isinstance(rounds, list) else []


def _fold_breakdown(rows: list[dict[str, Any]]) -> dict[str, dict[str, Any]]:
    """Fold flat (key, unit) aggregate rows into one object per key.

    Each key carries a ``units`` map plus key-level ``events``/``cost_usd`` totals.
    Order-preserving on first appearance of a key.
    """
    out: dict[str, dict[str, Any]] = {}
    for r in rows:
        k = r["key"]
        o = out.setdefault(k, {"key": k, "units": {}, "events": 0, "cost_usd": 0.0})
        o["units"][r["unit"]] = {
            "quantity": r["quantity"],
            "cost_usd": r["cost_usd"],
            "events": r["events"],
        }
        o["events"] += r["events"]
        o["cost_usd"] += r["cost_usd"]
    for o in out.values():
        unit_rows = [
            {"category": "llm", "unit": unit, "quantity": agg["quantity"]}
            for unit, agg in o["units"].items()
        ]
        o["cache_hit_ratio"] = cache_hit_ratio_from_rows(unit_rows)
    return out


def _merge_labels(
    folded: dict[str, dict[str, Any]], labels: dict[str, dict[str, Any]]
) -> list[dict[str, Any]]:
    """Attach a display label (+ optional is_admin) to each folded key.

    Unknown keys (deleted/aged-out referents — the ledger has no FKs) fall back to
    the raw key as the label. Sorted by total events desc (the leaderboard order).
    """
    out: list[dict[str, Any]] = []
    for k, o in folded.items():
        meta = labels.get(k, {})
        out.append(
            {**o, "label": meta.get("label", k), "is_admin": meta.get("is_admin")}
        )
    out.sort(key=lambda r: r["events"], reverse=True)
    return out


async def _usage_labels(group_by: str, keys: list[str]) -> dict[str, dict[str, Any]]:
    """Resolve display labels for breakdown keys via an app-DB lookup (cross-DB).

    user → users.display_name (+ is_admin); project → projects.name; model → none
    (the key IS the label). Robust to the audit/app DB split — a separate query,
    merged in Python, NOT a SQL join.
    """
    if not keys or group_by == "model":
        return {}
    uids = [UUID(k) for k in keys]
    if group_by == "user":
        rows = await postgres_db.fetch(
            "SELECT id, display_name, is_admin FROM users WHERE id = ANY($1::uuid[])",
            uids,
        )
        return {
            str(r["id"]): {"label": r["display_name"], "is_admin": r["is_admin"]}
            for r in rows
        }
    rows = await postgres_db.fetch(
        "SELECT id, name FROM projects WHERE id = ANY($1::uuid[])", uids
    )
    return {str(r["id"]): {"label": r["name"]} for r in rows}


def _build_timeseries(
    rows: list[dict[str, Any]], labels: dict[str, dict[str, Any]]
) -> dict[str, Any]:
    """Pivot flat (day, key, metrics) rows into a day axis + per-key series.

    ``days`` is the sorted union of all buckets; each series carries only the days
    it has activity (sparse — the client zero-fills gaps). Series are ordered by
    total events desc so the busiest key stacks first and leads the legend, matching
    ``_merge_labels``. Unknown keys fall back to the raw key as their label.
    """
    days = sorted({r["day"] for r in rows})
    series: dict[str, dict[str, Any]] = {}
    for r in rows:
        k = r["key"]
        s = series.setdefault(
            k,
            {
                "key": k,
                "label": labels.get(k, {}).get("label", k),
                "is_admin": labels.get(k, {}).get("is_admin"),
                "events": 0,
                "points": [],
            },
        )
        s["points"].append(
            {
                "day": r["day"],
                "tokens": r["tokens"],
                "cost_usd": r["cost_usd"],
                "events": r["events"],
            }
        )
        s["events"] += r["events"]
    ordered = sorted(series.values(), key=lambda s: s["events"], reverse=True)
    return {"days": days, "series": ordered}


async def _dispatch_infrastructure_ingestion(
    operation: Literal[
        "ticket",
        "snapshot_begin",
        "snapshot_items",
        "snapshot_finalize",
        "watch_apply",
        "watch_finish",
    ],
    request: Request,
) -> dict[str, Any]:
    try:
        return await dispatch_ingestion_request(
            infrastructure_ingestion_service,
            operation,
            request,
        )
    except IngestionRequestError as exc:
        headers = {"Retry-After": "1"} if exc.status_code in {409, 503} else None
        raise HTTPException(
            status_code=exc.status_code,
            detail=exc.code,
            headers=headers,
        ) from exc


