@app.get("/api/usage/v2", response_model=UsageSummaryV2)
async def get_usage_v2(
    request: Request,
    days: int = Query(default=30, ge=1, le=365),
    from_date: str | None = Query(
        default=None, description="ISO date/datetime (UTC); overrides `days`"
    ),
    to_date: str | None = Query(
        default=None, description="ISO date/datetime (UTC), exclusive"
    ),
    ref_id: str | None = Query(default=None, description="Filter to one job/thread id"),
    include_non_customer: bool = Query(
        default=False,
        description="Fleet admins only: include shared-platform and unknown rows",
    ),
) -> UsageSummaryV2:
    """Dimensionally typed usage summary with a gated source-aware handoff.

    The default path reads finalized ledger rows with Decimal-safe string
    quantities. Once the independent source-aware gate is enabled after the
    durable cutover, the same route combines sealed daily rows, verified audit
    fragments, and confirmed provisional interval tails.
    """
    if not infrastructure_metering_settings.v2_reads_enabled:
        raise HTTPException(status_code=404, detail="Usage API v2 is not enabled")
    user = await require_approved_user(request, postgres_db)
    fleet_admin = bool(user.get("is_admin")) and mcp_scope_project_id(user) is None
    if include_non_customer and not fleet_admin:
        raise HTTPException(status_code=403, detail="Fleet admin access required")
    if ref_id is not None:
        try:
            UUID(ref_id)
        except ValueError as exc:
            raise HTTPException(status_code=400, detail="invalid ref_id") from exc
        if not await user_can_access_job_or_thread(user, postgres_db, ref_id):
            # Do not turn a guessed ledger reference into a presence oracle.
            raise HTTPException(status_code=404, detail="Usage reference not found")
    if infrastructure_usage_v2 is None or not infrastructure_usage_v2.is_available:
        raise HTTPException(status_code=503, detail="Usage API v2 schema unavailable")
    if infrastructure_usage_rollup is None:
        raise HTTPException(
            status_code=503, detail="Usage API v2 bootstrap unavailable"
        )
    try:
        bootstrap = await infrastructure_usage_rollup.bootstrap_state()
    except Exception as exc:
        logger.warning("Usage API v2 bootstrap readiness check failed", exc_info=True)
        raise HTTPException(
            status_code=503, detail="Usage API v2 bootstrap unavailable"
        ) from exc
    if not bootstrap.read_ready:
        raise HTTPException(status_code=503, detail="Usage API v2 bootstrap incomplete")
    now = datetime.now(timezone.utc)
    try:
        to_ts = _parse_utc_date(to_date) if to_date else now
        from_ts = (
            _parse_utc_date(from_date) if from_date else (to_ts - timedelta(days=days))
        )
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=f"invalid date: {exc}") from exc
    if to_ts <= from_ts:
        raise HTTPException(
            status_code=400, detail="usage window end must be after its start"
        )
    try:
        visibility = _usage_v2_visibility(
            await _visibility_kwargs_for_stats(user),
            include_non_customer=include_non_customer,
        )
        return await infrastructure_usage_v2.summary(
            from_ts=from_ts,
            to_ts=to_ts,
            visibility=visibility,
            ref_id=ref_id,
            as_of=now,
        )
    except HTTPException:
        raise
    except UsageReadCutoverInactive as exc:
        raise HTTPException(
            status_code=503,
            detail="Infrastructure usage cutover is not active",
        ) from exc
    except Exception as exc:
        logger.exception("Usage API v2 query failed")
        raise HTTPException(
            status_code=500, detail="Usage API v2 query failed"
        ) from exc


@app.get("/api/usage")
async def get_usage(
    request: Request,
    days: int = Query(default=30, ge=1, le=365),
    from_date: str | None = Query(
        default=None, description="ISO date/datetime (UTC); overrides `days`"
    ),
    to_date: str | None = Query(
        default=None, description="ISO date/datetime (UTC), exclusive"
    ),
    ref_id: str | None = Query(default=None, description="Filter to one job/thread id"),
) -> dict[str, Any]:
    """Aggregate usage (LLM tokens + workspace compute) for the caller (G5).

    Reads the ``usage_events`` ledger (Slice 4). Window defaults to the last
    ``days``; ``from_date``/``to_date`` override it. Admins see the full fleet
    (optionally narrowed by an MCP ``project:`` scope); non-admins see only rows
    they own or can see via project membership. Returns sums by (category, unit),
    the canonical ``total_cost_usd``, provider-list-price ``cloud_estimates``, and
    ``cache_hit_ratio`` for LLM prompt cache reads. Cloud estimates reprice the
    measured quantities at read time and never mutate the ledger. ``available=false``
    means the audit tier is off — metering disabled.
    """
    user = await require_approved_user(request, postgres_db)
    if usage_ledger is None or not usage_ledger.is_available:
        return {
            "by_category": [],
            "total_cost_usd": 0.0,
            "cache_hit_ratio": 0.0,
            "cloud_estimates": [],
            "available": False,
        }
    try:
        now = datetime.now(timezone.utc)
        to_ts = _parse_utc_date(to_date) if to_date else now
        from_ts = (
            _parse_utc_date(from_date) if from_date else (to_ts - timedelta(days=days))
        )
    except ValueError as e:
        raise HTTPException(status_code=400, detail=f"invalid date: {e}") from e
    vis = await _visibility_kwargs_for_stats(user)
    try:
        # Read through the rollup (closed days from usage_daily, raw for the open
        # tail); ref_id per-job cost is not a rollup dim → it goes straight to raw
        # inside usage_rollup.usage. Fall back to the raw ledger if the rollup
        # singleton is absent (test/degraded).
        if usage_rollup is not None:
            result = await usage_rollup.usage(
                from_ts=from_ts,
                to_ts=to_ts,
                owner_user_id=vis.get("owner_user_id"),
                visible_project_ids=vis.get("visible_project_ids"),
                scope_project_id=vis.get("scope_project_id"),
                ref_id=ref_id,
            )
        else:
            result = await usage_ledger.query_usage(
                from_ts=from_ts,
                to_ts=to_ts,
                owner_user_id=vis.get("owner_user_id"),
                visible_project_ids=vis.get("visible_project_ids"),
                scope_project_id=vis.get("scope_project_id"),
                ref_id=ref_id,
            )
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e
    if usage_cloud_estimator is not None:
        try:
            result["cloud_estimates"] = await usage_cloud_estimator.estimate(
                result.get("by_category") or []
            )
        except Exception:
            # Planning estimates are strictly non-load-bearing. The measured
            # quantities and canonical LLM cost remain useful on their own.
            logger.warning(
                "cloud-equivalent usage estimate failed (non-fatal)",
                exc_info=True,
            )
            result["cloud_estimates"] = []
    else:
        result["cloud_estimates"] = []
    result["available"] = True
    result["from"] = from_ts.isoformat()
    result["to"] = to_ts.isoformat()
    return result


@app.get("/api/usage/breakdown")
async def get_usage_breakdown(
    request: Request,
    group_by: str = Query(..., description="user | model | project"),
    days: int = Query(default=30, ge=1, le=365),
    from_date: str | None = Query(default=None),
    to_date: str | None = Query(default=None),
) -> dict[str, Any]:
    """Per-(user|model|project) usage breakdown over a window (G5-scoped).

    Quantities by unit + key-level event/cost totals, labels enriched from the app
    DB. Non-admins are strictly self-scoped (see query_grouped). ``available=false``
    when the audit tier is off.
    """
    user = await require_approved_user(request, postgres_db)
    if group_by not in ("user", "model", "project"):
        raise HTTPException(status_code=400, detail=f"bad group_by: {group_by}")
    if usage_ledger is None or not usage_ledger.is_available:
        return {"available": False, "group_by": group_by, "rows": []}
    try:
        now = datetime.now(timezone.utc)
        to_ts = _parse_utc_date(to_date) if to_date else now
        from_ts = (
            _parse_utc_date(from_date) if from_date else (to_ts - timedelta(days=days))
        )
    except ValueError as e:
        raise HTTPException(status_code=400, detail=f"invalid date: {e}") from e
    vis = await _visibility_kwargs_for_stats(user)
    try:
        reader = (
            usage_rollup.breakdown
            if usage_rollup is not None
            else (usage_ledger.query_grouped)
        )
        rows = await reader(
            from_ts=from_ts,
            to_ts=to_ts,
            group_by=group_by,
            owner_user_id=vis.get("owner_user_id"),
            visible_project_ids=vis.get("visible_project_ids"),
            scope_project_id=vis.get("scope_project_id"),
        )
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e
    folded = _fold_breakdown(rows)
    labels = await _usage_labels(group_by, list(folded.keys()))
    return {
        "available": True,
        "group_by": group_by,
        "from": from_ts.isoformat(),
        "to": to_ts.isoformat(),
        "rows": _merge_labels(folded, labels),
    }


@app.get("/api/usage/timeseries")
async def get_usage_timeseries(
    request: Request,
    group_by: str = Query(..., description="user | model | project"),
    days: int = Query(default=30, ge=1, le=365),
    from_date: str | None = Query(default=None),
    to_date: str | None = Query(default=None),
) -> dict[str, Any]:
    """Daily-bucketed usage time series grouped by user|model|project (G5-scoped).

    Powers the dashboard's stacked usage-over-time chart. Returns a sorted ``days``
    axis and one ``series`` per key, each carrying per-day {day, tokens, cost_usd,
    events} points (days a key had no activity are omitted, not zero-filled — the
    client fills gaps). Labels are enriched from the app DB; non-admins are strictly
    self-scoped (see query_timeseries). ``available=false`` when metering is off.
    """
    user = await require_approved_user(request, postgres_db)
    if group_by not in ("user", "model", "project"):
        raise HTTPException(status_code=400, detail=f"bad group_by: {group_by}")
    if usage_ledger is None or not usage_ledger.is_available:
        return {"available": False, "group_by": group_by, "days": [], "series": []}
    try:
        now = datetime.now(timezone.utc)
        to_ts = _parse_utc_date(to_date) if to_date else now
        from_ts = (
            _parse_utc_date(from_date) if from_date else (to_ts - timedelta(days=days))
        )
    except ValueError as e:
        raise HTTPException(status_code=400, detail=f"invalid date: {e}") from e
    vis = await _visibility_kwargs_for_stats(user)
    try:
        reader = (
            usage_rollup.timeseries
            if usage_rollup is not None
            else (usage_ledger.query_timeseries)
        )
        rows = await reader(
            from_ts=from_ts,
            to_ts=to_ts,
            group_by=group_by,
            owner_user_id=vis.get("owner_user_id"),
            visible_project_ids=vis.get("visible_project_ids"),
            scope_project_id=vis.get("scope_project_id"),
        )
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e
    labels = await _usage_labels(group_by, sorted({r["key"] for r in rows}))
    return {
        "available": True,
        "group_by": group_by,
        "from": from_ts.isoformat(),
        "to": to_ts.isoformat(),
        **_build_timeseries(rows, labels),
    }


