# Citation & Source Library Endpoints
# =============================================================================


@app.get("/api/sources")
async def list_sources(
    request: Request,
    job_id: str | None = Query(default=None, description="Filter by job ID"),
    type: str | None = Query(default=None, description="Filter by source type"),
    limit: int = Query(default=50, ge=1, le=500),
    offset: int = Query(default=0, ge=0),
) -> dict[str, Any]:
    """List sources, optionally filtered by job and/or type.

    Visibility model (G3):
        * With ``?job_id=``: gate on ``require_job_access``. The job's
          sources are returned (visible if the caller can access the job).
        * Without ``?job_id=``: admin-only. Non-admins must filter by a
          specific job they can access. (Cross-job source enumeration
          would require a vector_db ⇆ postgres_db JOIN we deliberately
          don't do; the per-job path covers the legitimate cockpit use
          case without that complexity.)
    """
    if job_id:
        await require_job_access(request, postgres_db, job_id)
    else:
        caller = await require_approved_user(request, postgres_db)
        if not caller.get("is_admin"):
            raise HTTPException(
                status_code=403,
                detail="Cross-job source listing requires admin role; "
                "non-admins must pass ?job_id=",
            )
    try:
        async with vector_db.acquire() as conn:
            conditions = []
            params: list[Any] = []
            idx = 1

            if job_id:
                conditions.append(
                    f"s.id IN (SELECT source_id FROM job_sources WHERE job_id = ${idx}::uuid)"
                )
                params.append(job_id)
                idx += 1
            if type:
                conditions.append(f"s.type::text = ${idx}")
                params.append(type)
                idx += 1

            where = f"WHERE {' AND '.join(conditions)}" if conditions else ""

            # Count total
            count_row = await conn.fetchrow(
                f"SELECT COUNT(*) as total FROM sources s {where}", *params
            )
            total = count_row["total"] if count_row else 0

            # Fetch sources
            params.append(limit)
            params.append(offset)
            rows = await conn.fetch(
                f"""SELECT s.id, s.type::text as type, s.identifier, s.name,
                       s.version, s.content_hash,
                       LEFT(s.content, 200) as content_preview,
                       s.metadata, s.created_at
                FROM sources s {where}
                ORDER BY s.created_at DESC
                LIMIT ${idx} OFFSET ${idx + 1}""",
                *params,
            )

            sources = [dict(r) for r in rows]

            # If querying across jobs, include job IDs for each source
            if not job_id:
                for src in sources:
                    job_rows = await conn.fetch(
                        "SELECT job_id FROM job_sources WHERE source_id = $1",
                        src["id"],
                    )
                    src["job_ids"] = [str(r["job_id"]) for r in job_rows]

            return {"sources": sources, "total": total}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e


@app.get("/api/sources/{source_id}")
async def get_source_detail(
    request: Request,
    source_id: int,
    content_limit: int = Query(default=2000, ge=0, le=100000),
) -> dict[str, Any]:
    """Get full detail for a single source.

    Visibility (G3): the source is visible if the caller can access at
    least one job linked to it via ``job_sources``. Admins (without an
    MCP project: scope) bypass without enumerating links.
    """
    caller = await require_approved_user(request, postgres_db)
    try:
        async with vector_db.acquire() as conn:
            if content_limit > 0:
                row = await conn.fetchrow(
                    """SELECT id, type::text as type, identifier, name, version,
                          LEFT(content, $2) as content, content_hash, metadata, created_at,
                          LENGTH(content) as full_content_length
                    FROM sources WHERE id = $1""",
                    source_id,
                    content_limit,
                )
            else:
                row = await conn.fetchrow(
                    """SELECT id, type::text as type, identifier, name, version,
                          content, content_hash, metadata, created_at,
                          LENGTH(content) as full_content_length
                    FROM sources WHERE id = $1""",
                    source_id,
                )

            if not row:
                raise HTTPException(
                    status_code=404, detail=f"Source {source_id} not found"
                )

            result = dict(row)
            result["content_truncated"] = (
                content_limit > 0
                and result.get("full_content_length", 0) > content_limit
            )

            # Include linked job IDs
            job_rows = await conn.fetch(
                "SELECT job_id FROM job_sources WHERE source_id = $1", source_id
            )
            result["job_ids"] = [str(r["job_id"]) for r in job_rows]

            # G3 visibility: caller must be able to access at least one
            # linked job. Admins with no MCP project: scope skip the loop.
            if not await user_can_access_any_job(
                caller, postgres_db, result["job_ids"]
            ):
                raise HTTPException(
                    status_code=403, detail="Not authorized to access this source"
                )

            return result
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e


class RemoteImageRequest(BaseModel):
    """An exact external image URL the Cockpit user chose to load once."""

    url: str = Field(min_length=1, max_length=MAX_REMOTE_IMAGE_URL_CHARS)


@app.post("/api/media/remote-image")
async def load_remote_image(
    request: Request,
    body: RemoteImageRequest,
) -> Response:
    """Fetch one user-reviewed public raster image through a safe boundary.

    The approved-user and CSRF gates apply before any outbound network work.
    The fetcher pins public DNS results, revalidates redirects, strips browser
    identity, and bounds/validates the bytes. URLs and image bytes are neither
    logged here nor persisted.
    """

    await require_approved_user(request, postgres_db)
    try:
        image = await fetch_remote_image(body.url)
    except RemoteImageError as exc:
        raise HTTPException(
            status_code=exc.status_code,
            detail={"code": exc.code, "message": exc.message},
        ) from exc

    extension = {
        "image/png": "png",
        "image/jpeg": "jpg",
        "image/gif": "gif",
        "image/webp": "webp",
    }[image.media_type]
    return Response(
        content=image.content,
        media_type=image.media_type,
        headers={
            "Cache-Control": "private, no-store",
            "Content-Disposition": f'inline; filename="remote-image.{extension}"',
            "Content-Security-Policy": "default-src 'none'; sandbox",
            "Cross-Origin-Resource-Policy": "same-origin",
            "Referrer-Policy": "no-referrer",
            "X-Content-Type-Options": "nosniff",
        },
    )


@app.get("/api/jobs/{job_id}/citations")
async def list_job_citations(
    request: Request,
    job_id: str,
    source_id: int | None = Query(default=None),
    status: str | None = Query(
        default=None, description="Filter by verification_status"
    ),
    limit: int = Query(default=50, ge=1, le=500),
    offset: int = Query(default=0, ge=0),
) -> dict[str, Any]:
    """List citations for a job with optional filters."""
    await require_job_access(request, postgres_db, job_id)
    try:
        async with vector_db.acquire() as conn:
            conditions = ["c.job_id = $1::uuid"]
            params: list[Any] = [job_id]
            idx = 2

            if source_id is not None:
                conditions.append(f"c.source_id = ${idx}")
                params.append(source_id)
                idx += 1
            if status:
                conditions.append(f"c.verification_status::text = ${idx}")
                params.append(status)
                idx += 1

            where = "WHERE " + " AND ".join(conditions)

            count_row = await conn.fetchrow(
                f"SELECT COUNT(*) as total FROM citations c {where}", *params
            )
            total = count_row["total"] if count_row else 0

            params.append(limit)
            params.append(offset)
            rows = await conn.fetch(
                f"""SELECT c.id, LEFT(c.claim, 200) as claim, c.source_id,
                       s.name as source_name, s.type::text as source_type,
                       c.verification_status::text as verification_status,
                       c.confidence::text as confidence,
                       c.extraction_method::text as extraction_method,
                       c.similarity_score, c.created_at
                FROM citations c
                JOIN sources s ON c.source_id = s.id
                {where}
                ORDER BY c.created_at DESC
                LIMIT ${idx} OFFSET ${idx + 1}""",
                *params,
            )

            return {"citations": [dict(r) for r in rows], "total": total}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e


@app.post("/api/citations/snapshot")
async def store_citation_snapshot(request: Request) -> dict[str, Any]:
    """Persist the original bytes of a cited cloud document (Phase 3, D7).

    **Internal** (P4b) — requires ``X-Internal-Key``; the agent calls this at
    cite-time because it has no S3 credentials of its own. The request body is
    the raw file bytes; ``content_type`` is an optional query param used when
    the blob is later served back. Returns a content-addressed
    ``snapshot_blob_key`` the agent records onto the citation source's
    ``metadata.cloud`` so the original can be retrieved on view.
    """
    await require_internal(request)
    if not snapshot_service.is_available:
        raise HTTPException(status_code=503, detail="Snapshot store unavailable")
    data = await request.body()
    if not data:
        raise HTTPException(status_code=400, detail="Empty body")
    content_type = (
        request.query_params.get("content_type") or "application/octet-stream"
    )
    key = await snapshot_service.save_blob(
        data, prefix="citations", content_type=content_type
    )
    if not key:
        raise HTTPException(status_code=500, detail="Snapshot store write failed")
    return {"snapshot_blob_key": key, "size_bytes": len(data)}


# Bounded verdict-submission retries per critic: each 409 tells the model to
# "correct and resubmit", and a critic that cannot render a valid verdict
# resubmits forever (189 iterations / 105 min in the live incident) while its
# parent sits wedged in 'reviewing'. A fresh critic is spawned every round, so
# the per-critic count naturally resets each round.
# knowledge-history/done/rejected_verdict_livelocks_critic_and_wedges_parent.md
_MAX_VERDICT_REJECTIONS = 3


async def _record_verification_round_impl(
    *,
    postgres_db: Any,
    target_job_id: str,
    critic_job_id: str,
    asserted_verdict: str,
    opened: list[dict[str, Any]],
    dispositions: list[dict[str, Any]],
    head_commit: str | None,
    content_tree: str | None = None,
) -> dict[str, Any]:
    """Validate, compute, and durably append one verification round.

    Split out of the route so the gate logic is testable without HTTP. Raises
    HTTPException(409) with the model-facing errors on invalid input,
    HTTPException(400) if ``critic_job_id`` is missing, HTTPException(403) if
    the critic was not spawned for this target, or HTTPException(404) if the
    target does not exist.
    """
    from services.completion import _parse_freeze_data
    from services.verification_ledger import (
        assign_ids,
        compute_verdict,
        fold_open_findings,
        validate_dispositions,
        validate_verdict_call,
    )

    if not critic_job_id:
        # append_verification_round's dedup guard keys on critic_job_id
        # (`@> {"critic_job_id": ...}`). A falsy value here would make every
        # caller that omits it collide with every other on this target — both
        # at the DB-level dedup (silently dropping a genuinely distinct round
        # as a "duplicate") and at the idempotent-retry short-circuit below
        # (returning a stranger's stored verdict for a request that never ran).
        raise HTTPException(status_code=400, detail="critic_job_id is required")

    target = await postgres_db.get_job(target_job_id)
    if not target:
        raise HTTPException(status_code=404, detail=f"Job {target_job_id} not found")

    # The target comes from the URL but is chosen by the MODEL —
    # ``approve_job_verdict(job_id=...)`` flows straight through to it, and the route
    # is authenticated only by the shared internal key, which every agent pod
    # holds. A confused critic writing to the wrong job's ledger is fail-closed
    # for its REAL target (which then escalates for lack of a verdict), but it
    # pollutes an unrelated job's ledger with phantom findings that get
    # injected into that job's next critic brief and can force its cap /
    # no-progress escalation. Same principle as the rest of this design: never
    # trust the model's assertion about what it is judging.
    critic = await postgres_db.get_job(critic_job_id)
    critic_ctx = (critic or {}).get("context")
    if isinstance(critic_ctx, str):
        # asyncpg returns JSONB as a string on the app pool (no codec
        # registered); an isinstance-only check here would reject every real
        # critic. See knowledge-base/knowledge/issues/
        # jsonb_isinstance_guard_without_parse_silent_dead_paths.md.
        try:
            critic_ctx = json.loads(critic_ctx)
        except (json.JSONDecodeError, ValueError):
            critic_ctx = {}
    if not isinstance(critic_ctx, dict):
        critic_ctx = {}
    claimed_target = critic_ctx.get("verification_target")
    if not critic or str(claimed_target or "") != str(target_job_id):
        logger.warning(
            "Rejected verification round: critic %s is not the critic for target "
            "%s (its verification_target is %r)",
            critic_job_id,
            target_job_id,
            claimed_target,
        )
        raise HTTPException(
            status_code=403,
            detail=(
                f"Job {critic_job_id} is not the verification critic for "
                f"{target_job_id}. Record your verdict against the job you were "
                f"asked to review."
            ),
        )

    # Both progress markers are server-authoritative from the TARGET's own
    # completion freeze, not the caller-supplied values — the critic runs on
    # its own ``subjob/<id>/critic`` branch, so ITS workspace is a different
    # thing from the target's, and comparing it against the previous round's
    # (the no-progress check in _verification_gate_decision) would be
    # meaningless. Each falls back to the caller-supplied value only when the
    # target's freeze has none (e.g. an older freeze predating the field).
    # ``content_tree`` is the ONLY one the gate compares. ``head_commit`` is
    # recorded purely for diagnostics — it is unusable as a progress signal
    # (see _verification_gate_decision) and nothing reads it back.
    target_freeze = _parse_freeze_data(target) or {}
    head_commit = target_freeze.get("head_commit") or head_commit
    content_tree = target_freeze.get("content_tree") or content_tree

    rounds = _verification_rounds(target)

    # Idempotent retry: this critic_job_id already has a durable round on the
    # ledger. Short-circuit to the stored result BEFORE validating — the
    # retried round's own findings are now part of `rounds` (they were
    # appended by the original attempt), so validating this call against them
    # would wrongly demand the retry disposition the findings it itself just
    # opened. Checked ahead of the atomic-append dedup below so a same-input
    # retry never re-derives (and can't diverge from) the stored verdict.
    for existing in rounds:
        if existing.get("critic_job_id") == critic_job_id:
            return {
                "verdict": existing.get("verdict"),
                "round": existing.get("round"),
                "assigned": existing.get("opened", []),
                "open_findings": fold_open_findings(rounds),
            }

    open_before = fold_open_findings(rounds)

    errors = validate_verdict_call(asserted_verdict, opened, open_before)
    errors += validate_dispositions(dispositions, open_before)
    if errors:
        rejections = await postgres_db.increment_verdict_rejections(critic_job_id)
        if rejections >= _MAX_VERDICT_REJECTIONS:
            reason = (
                f"Critic {critic_job_id} failed to render a valid verdict "
                f"after {rejections} rejected submissions; sent to manual "
                f"review. Last rejection: " + "; ".join(errors)
            )
            await _escalate_target(target_job_id, target, reason)
            # `escalated` tells the agent-side client to stop the critic's
            # resubmit loop (its retry instruction becomes a stop order).
            raise HTTPException(
                status_code=409, detail={"errors": errors, "escalated": True}
            )
        raise HTTPException(status_code=409, detail={"errors": errors})

    assigned = assign_ids(opened, rounds)
    record = {
        "round": len(rounds) + 1,
        "critic_job_id": critic_job_id,
        "head_commit": head_commit,
        "content_tree": content_tree,
        "asserted_verdict": str(asserted_verdict).lower(),
        "opened": assigned,
        "dispositions": dispositions,
        "ts": datetime.now(timezone.utc).isoformat(),
    }
    open_after = fold_open_findings(rounds + [record])
    record["verdict"] = compute_verdict(record["asserted_verdict"], open_after)

    if record["verdict"] != record["asserted_verdict"]:
        # Free, direct measure of critic quality: how often a critic tries to
        # approve over its own open findings. Previously unobservable.
        logger.warning(
            "Verification verdict divergence for target %s (critic %s): "
            "model asserted %r, computed %r from %d open finding(s)",
            target_job_id,
            critic_job_id,
            record["asserted_verdict"],
            record["verdict"],
            len(open_after),
        )

    appended = await postgres_db.append_verification_round(target_job_id, record)
    if appended == 0:
        # Duplicate (retried /complete) — return the stored verdict, idempotent.
        stored = await postgres_db.get_job(target_job_id)
        for existing in _verification_rounds(stored):
            if existing.get("critic_job_id") == critic_job_id:
                return {
                    "verdict": existing.get("verdict"),
                    "round": existing.get("round"),
                    "assigned": existing.get("opened", []),
                    "open_findings": fold_open_findings(_verification_rounds(stored)),
                }
        raise HTTPException(status_code=500, detail="Ledger append failed")

    return {
        "verdict": record["verdict"],
        "round": record["round"],
        "assigned": assigned,
        "open_findings": open_after,
    }


@app.post("/api/jobs/{target_job_id}/verification/rounds")
async def record_verification_round(
    request: Request, target_job_id: str
) -> dict[str, Any]:
    """Record one verification round on the TARGET job's durable ledger.

    **Internal** (P4b) — requires ``X-Internal-Key``. Ingress strips this path.
    Called by the critic's verdict tools BEFORE they return, so the verdict is
    durable before anything observes it (journal-before-observe). The verdict in
    the response is COMPUTED from the open findings, not taken from the caller.
    """
    await require_internal(request)
    body = await request.json()
    return await _record_verification_round_impl(
        postgres_db=postgres_db,
        target_job_id=target_job_id,
        critic_job_id=str(body.get("critic_job_id") or ""),
        asserted_verdict=str(body.get("asserted_verdict") or ""),
        opened=body.get("opened") or [],
        dispositions=body.get("dispositions") or [],
        head_commit=body.get("head_commit"),
        content_tree=body.get("content_tree"),
    )


def _parse_completion_decision(job: dict[str, Any] | None) -> dict[str, Any] | None:
    """Extract ``context.completion_decision`` with the defensive JSONB parse.

    asyncpg returns JSONB as a string on the app pool (no codec registered) —
    same trap as ``_record_verification_round_impl``'s critic context parse.
    """
    ctx = (job or {}).get("context")
    if isinstance(ctx, str):
        try:
            ctx = json.loads(ctx)
        except (json.JSONDecodeError, ValueError):
            ctx = {}
    if not isinstance(ctx, dict):
        return None
    decision = ctx.get("completion_decision")
    return decision if isinstance(decision, dict) else None


async def _record_completion_decision_impl(
    *,
    postgres_db: Any,
    job_id: str,
    tool_call_id: str,
    summary: str,
    deliverables: list[Any],
    confidence: float,
    notes: str | None,
) -> dict[str, Any]:
    """Validate and durably journal one job_complete decision.

    Journal-before-observe (knowledge-base/knowledge/issues/
    job_finalization_decisions_held_only_in_process_memory.md): the agent's
    ``job_complete`` tool must not return to the model until the decision is
    committed here. Idempotency key is ``(job_id, tool_call_id)`` — a replay
    of the same tool call (ToolNode re-execution after a checkpoint gap)
    short-circuits to the stored record; a NEW tool_call_id (a genuine later
    decision, e.g. round 2 after a critic return) overwrites. Split out of
    the route so the logic is testable without HTTP.
    """
    if not tool_call_id:
        raise HTTPException(status_code=400, detail="tool_call_id is required")

    job = await postgres_db.get_job(job_id)
    if not job:
        raise HTTPException(status_code=404, detail=f"Job {job_id} not found")

    if job.get("status") in ("completed", "failed", "cancelled"):
        raise HTTPException(
            status_code=409,
            detail=(
                f"Job {job_id} is already terminal "
                f"({job.get('status')}); refusing to journal a completion "
                f"decision for it."
            ),
        )

    existing = _parse_completion_decision(job)
    if existing and existing.get("tool_call_id") == tool_call_id:
        # Same tool call re-executed after a crash — the journal already has
        # this decision; replay is a no-op.
        return {"recorded": True, "replay": True, "decision": existing}

    decision = {
        "tool_call_id": tool_call_id,
        "summary": str(summary or ""),
        "deliverables": [str(d) for d in (deliverables or [])],
        "confidence": max(0.0, min(1.0, float(confidence))),
        "recorded_at": datetime.now(timezone.utc).isoformat(),
        "job_id": str(job_id),
    }
    if notes:
        decision["notes"] = str(notes)

    try:
        journaled = await postgres_db.set_completion_decision(job_id, decision)
    except CompletionDecisionBlocked as exc:
        raise HTTPException(status_code=409, detail=exc.detail()) from exc
    if not journaled:
        # The CAS lost: the job vanished or flipped terminal under us.
        raise HTTPException(
            status_code=409,
            detail=f"Job {job_id} changed state while journaling the decision",
        )

    logger.info(
        f"Journaled completion decision for job {job_id} "
        f"(tool_call_id={tool_call_id}, confidence={decision['confidence']}, "
        f"{len(decision['deliverables'])} deliverable(s))"
    )
    return {"recorded": True, "replay": False, "decision": decision}


@app.post("/api/jobs/{job_id}/completion-decision")
async def record_completion_decision(request: Request, job_id: str) -> dict[str, Any]:
    """Durably journal the agent's job_complete decision on the job row.

    **Internal** (P4b) — requires ``X-Internal-Key``. Ingress strips this path.
    Called by the worker's ``job_complete`` tool BEFORE it returns, so the
    decision survives any agent restart (journal-before-observe — the sibling
    of ``/verification/rounds`` for the worker's own terminating decision).
    """
    await require_internal(request)
    body = await request.json()
    try:
        confidence = float(body.get("confidence", 1.0))
    except (TypeError, ValueError):
        confidence = 1.0
    return await _record_completion_decision_impl(
        postgres_db=postgres_db,
        job_id=job_id,
        tool_call_id=str(body.get("tool_call_id") or ""),
        summary=str(body.get("summary") or ""),
        deliverables=body.get("deliverables") or [],
        confidence=confidence,
        notes=body.get("notes"),
    )


@app.get("/api/jobs/{job_id}/completion-decision")
async def get_completion_decision(request: Request, job_id: str) -> dict[str, Any]:
    """Read back the journaled job_complete decision (or null).

    **Internal** (P4b) — requires ``X-Internal-Key``. Used by the agent's
    resume hydration so a restarted process re-seeds its in-memory cache from
    the durable record instead of treating "I decided" as "no decision".
    """
    await require_internal(request)
    job = await postgres_db.get_job(job_id)
    if not job:
        raise HTTPException(status_code=404, detail=f"Job {job_id} not found")
    return {"decision": _parse_completion_decision(job)}


@app.get("/api/citations/{citation_id}")
async def get_citation_detail(request: Request, citation_id: int) -> dict[str, Any]:
    """Get full citation record with source info and verification details.

    **P4e** — visible if the caller can access the citation's linked job
    (mirrors G3's ``get_source_detail`` pattern). Admins without an MCP
    ``project:<uuid>`` scope bypass. Missing/unauthorized → 404 to avoid
    leaking citation existence via probe.
    """
    caller = await require_approved_user(request, postgres_db)
    try:
        async with vector_db.acquire() as conn:
            row = await conn.fetchrow(
                """SELECT c.id, c.job_id, c.claim, c.verbatim_quote, c.quote_context,
                      c.quote_language, c.relevance_reasoning,
                      c.confidence::text as confidence,
                      c.extraction_method::text as extraction_method,
                      c.source_id, s.name as source_name, s.type::text as source_type,
                      s.identifier as source_identifier,
                      c.locator, c.verification_status::text as verification_status,
                      c.verification_notes, c.similarity_score, c.matched_location,
                      c.created_at, c.created_by
                FROM citations c
                JOIN sources s ON c.source_id = s.id
                WHERE c.id = $1""",
                citation_id,
            )

            if not row:
                raise HTTPException(
                    status_code=404, detail=f"Citation {citation_id} not found"
                )

            result = dict(row)
            job_id = result.get("job_id")
            if not await user_can_access_job_or_thread(
                caller, postgres_db, str(job_id) if job_id else None
            ):
                # 404 instead of 403 — don't leak that the citation exists.
                raise HTTPException(
                    status_code=404, detail=f"Citation {citation_id} not found"
                )

            return result
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e


def _source_cloud_meta(metadata: Any) -> dict[str, Any]:
    """Extract the ``metadata.cloud`` block from a ``sources.metadata`` value.

    The vector pool may hand back JSONB as a dict (codec) or a JSON string;
    coerce both, and return ``{}`` when there's no cloud snapshot-anchor.
    """
    if isinstance(metadata, (str, bytes)):
        try:
            metadata = json.loads(metadata)
        except (ValueError, TypeError):
            return {}
    if not isinstance(metadata, dict):
        return {}
    cloud = metadata.get("cloud")
    return cloud if isinstance(cloud, dict) else {}


def _home_relative_path(anchor_webdav_url: str, home_webdav_url: str) -> Optional[str]:
    """Path of a cited file relative to the viewing user's home, if it's under it.

    Phase 3c (D7) only re-fetches a cited cloud file for the drift check when it
    is provably inside the *viewing user's own* cloud home — i.e. the anchor's
    WebDAV URL starts with the user's home WebDAV URL. Returns the home-relative
    path (no leading slash) in that case, else ``None`` (→ ``live_state =
    unreachable``: an external datasource or a different cloud the orchestrator
    can't fetch on the user's behalf). This both guards against comparing a
    same-named-but-different file and yields the path for
    ``get_project_folder_file_bytes``.
    """
    if not anchor_webdav_url or not home_webdav_url:
        return None
    base = home_webdav_url.rstrip("/")
    if not anchor_webdav_url.startswith(base):
        return None
    return anchor_webdav_url[len(base) :].lstrip("/") or None


@app.get("/api/citations/{citation_id}/snapshot")
async def get_citation_snapshot(request: Request, citation_id: int) -> Response:
    """Serve the backed-up original bytes of a cited cloud document (Phase 3c, D7).

    Viewing-user auth (same gate as ``get_citation_detail``). Returns the copy
    SRW stored at cite-time (``metadata.cloud.snapshot_blob_key``) so a citation
    can show the exact version cited even when the live source changed or is
    unreachable. 404 if the citation is unknown/unauthorized or has no snapshot
    (404 over 403 so citation existence isn't leaked by probing).
    """
    caller = await require_approved_user(request, postgres_db)
    try:
        async with vector_db.acquire() as conn:
            row = await conn.fetchrow(
                """SELECT c.job_id, s.name AS source_name, s.metadata
                   FROM citations c JOIN sources s ON c.source_id = s.id
                   WHERE c.id = $1""",
                citation_id,
            )
        if not row:
            raise HTTPException(
                status_code=404, detail=f"Citation {citation_id} not found"
            )
        job_id = row["job_id"]
        if not await user_can_access_job_or_thread(
            caller, postgres_db, str(job_id) if job_id else None
        ):
            raise HTTPException(
                status_code=404, detail=f"Citation {citation_id} not found"
            )

        cloud = _source_cloud_meta(row["metadata"])
        key = cloud.get("snapshot_blob_key")
        if not key:
            raise HTTPException(
                status_code=404, detail="No snapshot stored for this citation"
            )
        data = await snapshot_service.get_blob(key)
        if data is None:
            raise HTTPException(status_code=404, detail="Snapshot blob not found")

        media_type = cloud.get("content_type") or "application/octet-stream"
        filename = (row["source_name"] or f"citation-{citation_id}").replace('"', "")
        return Response(
            content=data,
            media_type=media_type,
            headers={"Content-Disposition": f'inline; filename="{filename}"'},
        )
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e


@app.get("/api/citations/{citation_id}/drift")
async def get_citation_drift(request: Request, citation_id: int) -> dict[str, Any]:
    """On-view drift check for a cited cloud document (Phase 3c, D7).

    Viewing-user auth. Compares the live source against what was cited. A
    best-effort re-fetch runs **only** when the cited file is provably inside the
    viewing user's own cloud home (so the credentials are the user's, never the
    agent's expired ones, and we never compare a same-named different file).
    Returns:

    - ``live_state``: ``unchanged`` | ``changed`` | ``unreachable`` | ``unknown``
    - ``snapshot_available``: whether ``/snapshot`` can serve the backed-up copy
    - ``cited``: the drift fingerprint captured at cite-time

    ``unreachable`` (external datasource / different cloud / no access) is the
    spec's "fall back to the snapshot" branch.
    """
    caller = await require_approved_user(request, postgres_db)
    try:
        async with vector_db.acquire() as conn:
            row = await conn.fetchrow(
                """SELECT c.job_id, s.metadata
                   FROM citations c JOIN sources s ON c.source_id = s.id
                   WHERE c.id = $1""",
                citation_id,
            )
        if not row:
            raise HTTPException(
                status_code=404, detail=f"Citation {citation_id} not found"
            )
        job_id = row["job_id"]
        if not await user_can_access_job_or_thread(
            caller, postgres_db, str(job_id) if job_id else None
        ):
            raise HTTPException(
                status_code=404, detail=f"Citation {citation_id} not found"
            )

        cloud = _source_cloud_meta(row["metadata"])
        if not cloud:
            raise HTTPException(
                status_code=400, detail="Citation has no cloud source to drift-check"
            )

        cited_sha = cloud.get("file_sha256")
        result: dict[str, Any] = {
            "citation_id": citation_id,
            "live_state": "unknown",
            "snapshot_available": bool(cloud.get("snapshot_blob_key")),
            "cited": {
                "etag": cloud.get("etag"),
                "file_sha256": cited_sha,
                "captured_at": cloud.get("captured_at"),
                "webdav_url": cloud.get("webdav_url"),
                "backend": cloud.get("backend"),
            },
        }

        # Best-effort live re-fetch via the viewing user's own cloud home.
        try:
            backend = main_cloud_router.for_owner(caller)
            user_id = await resolve_user_identity_cached(postgres_db, caller, backend)
            home = await backend.get_user_home(user_id) if user_id else None
            rel = (
                _home_relative_path(
                    cloud.get("webdav_url") or "", home.webdav_url or ""
                )
                if home and home.webdav_url
                else None
            )
            if rel is None:
                result["live_state"] = "unreachable"
                result["reason"] = "live source not reachable from your account"
                return result
            live_bytes = await backend.get_project_folder_file_bytes(
                home.handle, path=rel
            )
            live_sha = hashlib.sha256(live_bytes).hexdigest()
            result["live"] = {"file_sha256": live_sha, "size_bytes": len(live_bytes)}
            result["live_state"] = (
                "unchanged" if cited_sha and live_sha == cited_sha else "changed"
            )
            return result
        except Exception as e:
            logger.info("Citation %s drift live-fetch unreachable: %s", citation_id, e)
            result["live_state"] = "unreachable"
            result["reason"] = "live source could not be fetched"
            return result
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e


