# =============================================================================
# MCP Token Endpoints
# =============================================================================

# Note: ``MCP_INTERNAL_KEY`` is read in ``security/access.py`` (helpers
# ``require_internal`` / ``is_internal_call``) and used by every Track B
# (P4b) endpoint. This module-level constant is no longer needed here.


@app.post("/api/mcp-tokens")
async def create_mcp_token(request: Request, body: McpTokenCreate) -> dict[str, Any]:
    """Generate a new MCP API token. Returns the plaintext token once."""
    user = await require_approved_user(request, postgres_db)

    # Validate scope
    scope = body.scope.strip()
    if scope not in ("user", "all") and not scope.startswith("project:"):
        raise HTTPException(
            status_code=400,
            detail="Invalid scope. Use 'user', 'all', or 'project:<uuid>'",
        )
    if scope == "all" and not user.get("real_is_admin", False):
        raise HTTPException(
            status_code=403, detail="Only admins can create full-access tokens"
        )
    if scope.startswith("project:"):
        project_id = scope.split(":", 1)[1]
        members = await postgres_db.get_project_members(project_id)
        if not any(str(m["user_id"]) == str(user["id"]) for m in members):
            raise HTTPException(status_code=403, detail="Not a member of this project")

    # Generate token
    token = "srw_" + secrets.token_urlsafe(32)
    token_hash = hashlib.sha256(token.encode()).hexdigest()
    token_prefix = token[:12]

    # Expiration
    expires_at = None
    if body.expires_in_days:
        from datetime import timedelta

        expires_at = datetime.now(timezone.utc) + timedelta(days=body.expires_in_days)

    row = await postgres_db.create_mcp_token(
        user_id=str(user["id"]),
        name=body.name,
        token_hash=token_hash,
        token_prefix=token_prefix,
        scope=scope,
        expires_at=expires_at,
    )

    result = {
        k: str(v) if isinstance(v, (UUID, datetime)) else v for k, v in row.items()
    }
    result["token"] = token  # Plaintext returned once only
    return result


@app.get("/api/mcp-tokens")
async def list_mcp_tokens(request: Request) -> list[dict[str, Any]]:
    """List the current user's MCP tokens (no plaintext or hashes)."""
    user = await require_approved_user(request, postgres_db)
    rows = await postgres_db.list_mcp_tokens(str(user["id"]))
    return [
        {k: str(v) if isinstance(v, (UUID, datetime)) else v for k, v in r.items()}
        for r in rows
    ]


@app.delete("/api/mcp-tokens/{token_id}")
async def revoke_mcp_token(request: Request, token_id: str) -> dict[str, str]:
    """Revoke an MCP token (soft delete)."""
    user = await require_approved_user(request, postgres_db)
    revoked = await postgres_db.revoke_mcp_token(token_id, str(user["id"]))
    if not revoked:
        raise HTTPException(
            status_code=404, detail="Token not found or already revoked"
        )
    return {"status": "revoked"}


@app.post("/api/internal/mcp-token-verify")
async def internal_mcp_token_verify(
    request: Request, body: McpTokenVerifyRequest
) -> dict[str, Any]:
    """Internal endpoint for MCP server to verify a token hash.
    **Internal** (P4b) — requires ``X-Internal-Key``. Ingress strips
    this path.
    """
    await require_internal(request)
    token_data = await postgres_db.get_mcp_token_by_hash(body.token_hash)
    if not token_data:
        raise HTTPException(status_code=401, detail="Invalid or expired token")

    # Update last used
    await postgres_db.update_mcp_token_last_used(body.token_hash)

    return {
        "user_id": str(token_data["user_id"]),
        "scope": token_data["scope"],
        "display_name": token_data["display_name"],
    }


@app.post("/api/internal/mcp-token-create")
async def internal_mcp_token_create(
    request: Request, body: McpTokenCreateInternal
) -> dict[str, Any]:
    """Internal endpoint for OAuth bridge to create an srw_* token.
    **Internal** (P4b) — requires ``X-Internal-Key``. Ingress strips
    this path.

    Looks up the user by Keycloak subject (JIT-creates if needed),
    then creates a token with the given hash, scope, and origin.
    """
    await require_internal(request)
    # Look up or JIT-create user by Keycloak sub
    user = await postgres_db.get_user_by_keycloak_sub(body.user_sub)
    if not user:
        # JIT-create via upsert (same as cockpit OIDC login)
        user = await postgres_db.upsert_user_from_oidc(
            sub=body.user_sub,
            email=body.user_email,
            display_name=body.user_email.split("@")[0]
            if body.user_email
            else "OAuth User",
        )
    if not user:
        raise HTTPException(status_code=400, detail="Could not resolve user")

    # Parse expiry
    expires_at = None
    if body.expires_at:
        expires_at = datetime.fromisoformat(body.expires_at)

    row = await postgres_db.create_mcp_token(
        user_id=str(user["id"]),
        name=body.name,
        token_hash=body.token_hash,
        token_prefix=body.token_prefix,
        scope=body.scope,
        expires_at=expires_at,
        origin=body.origin,
    )

    result = {
        k: str(v) if isinstance(v, (UUID, datetime)) else v for k, v in row.items()
    }
    return result


# =============================================================================
# Personal Access Token (PAT) Endpoints — see auth_bff_and_api_tokens.md §3
# =============================================================================
#
# PATs live in the consolidated `auth_tokens` table with kind='api'. The
# legacy MCP-token endpoints (above) keep working unchanged on the same
# table with kind='mcp'. Validator path is shared (see security.auth
# `_resolve_pat`, `_resolve_legacy_mcp_token`).


def _serialize_api_key_row(row: dict[str, Any]) -> dict[str, Any]:
    """Coerce UUID / datetime values to strings so they JSON-serialise."""
    return {k: str(v) if isinstance(v, (UUID, datetime)) else v for k, v in row.items()}


@app.post("/api/api-keys")
async def create_api_key(request: Request, body: ApiKeyCreate) -> dict[str, Any]:
    """Generate a new Personal Access Token. Plaintext returned once."""
    user = await require_approved_user(request, postgres_db)

    # Validate scope set. `admin` is gated on the user's admin flag.
    requested = set(body.scopes)
    if not requested:
        raise HTTPException(status_code=400, detail="At least one scope required")
    bad = requested - VALID_PAT_SCOPES
    if bad:
        raise HTTPException(
            status_code=400,
            detail=f"Unknown scopes: {sorted(bad)}",
        )
    if "admin" in requested and not user.get("real_is_admin", False):
        raise HTTPException(
            status_code=403, detail="Only admins can issue admin-scoped tokens"
        )

    token = "ak_" + secrets.token_urlsafe(32)
    token_hash = hashlib.sha256(token.encode("ascii")).hexdigest()
    token_prefix = token[:12]
    last_four = token[-4:]

    expires_at = None
    if body.expires_in_days:
        expires_at = datetime.now(timezone.utc) + timedelta(days=body.expires_in_days)

    row = await postgres_db.create_api_key(
        user_id=str(user["id"]),
        name=body.name,
        token_hash=token_hash,
        token_prefix=token_prefix,
        last_four=last_four,
        scopes=sorted(requested),
        expires_at=expires_at,
    )
    result = _serialize_api_key_row(row)
    result["token"] = token  # Plaintext — caller must store immediately
    return result


@app.get("/api/api-keys")
async def list_api_keys(request: Request) -> list[dict[str, Any]]:
    """List the current user's PATs (no hashes, no plaintext)."""
    user = await require_approved_user(request, postgres_db)
    rows = await postgres_db.list_api_keys(str(user["id"]))
    return [_serialize_api_key_row(r) for r in rows]


@app.delete("/api/api-keys/{token_id}")
async def revoke_api_key(request: Request, token_id: str) -> dict[str, str]:
    """Soft-revoke a PAT."""
    user = await require_approved_user(request, postgres_db)
    revoked = await postgres_db.revoke_api_key(token_id, str(user["id"]))
    if not revoked:
        raise HTTPException(
            status_code=404, detail="Token not found or already revoked"
        )
    return {"status": "revoked"}


@app.post("/api/api-keys/{token_id}/rotate")
async def rotate_api_key(request: Request, token_id: str) -> dict[str, Any]:
    """Issue a successor PAT.

    Same name + scopes + expiry as the source token. The old row stays
    valid for 24h (cleanup loop revokes it) so an automation can roll
    over without an outage.
    """
    user = await require_approved_user(request, postgres_db)
    token = "ak_" + secrets.token_urlsafe(32)
    token_hash = hashlib.sha256(token.encode("ascii")).hexdigest()
    token_prefix = token[:12]
    last_four = token[-4:]

    row = await postgres_db.rotate_api_key(
        old_id=token_id,
        user_id=str(user["id"]),
        token_hash=token_hash,
        token_prefix=token_prefix,
        last_four=last_four,
    )
    if not row:
        raise HTTPException(
            status_code=404,
            detail="Token not found, already revoked, or not yours",
        )
    result = _serialize_api_key_row(row)
    result["token"] = token
    return result


# =============================================================================
# SSH Key Endpoints — possession-verified public key registration
# =============================================================================
#
# Registration requires proving possession: without it, anyone could claim a
# public key they merely read (e.g. published at github.com/<user>.keys), and
# because fingerprints are globally unique that would deny the rightful owner
# the ability to register their own key.
#
# The possession challenge is a STATELESS, HMAC-signed token, not a lookup in
# an in-process dict. The orchestrator runs multiple replicas behind one
# Service with no session affinity (deployment/values-experimental.yaml
# `orchestrator.replicas: 2` on dev, deliberately — it's where the HA posture
# gets exercised), so the pod that issues a challenge is frequently not the
# pod that redeems it. An in-process store would reject roughly half of all
# registrations with "unknown challenge" — a coin flip, not a rare race. See
# ruling F24 in
# .superpowers/sdd/2026-08-28-workspace-ssh-access-foundation/progress.md.


class SshKeyCreate(BaseModel):
    name: str = Field(..., min_length=1, max_length=100, description="Display name")
    public_key: str = Field(..., min_length=1, max_length=8192)
    # Capped like its siblings: `challenge` is the field that reaches hmac.new()
    # over the full head and .encode("utf-8"). A minted token is ~120 bytes.
    challenge: str = Field(..., min_length=1, max_length=1024)
    signature: str = Field(..., min_length=1, max_length=8192)


_SSH_CHALLENGE_TTL_SECONDS = 300
_SSH_CHALLENGE_VERSION = "srw-ssh1"


_SSH_CHALLENGE_IDENTITY_MAX_LEN = 255


def _mint_ssh_key_challenge(
    user_id: str, identity: str | None = None, *, now: float | None = None
) -> tuple[str, float]:
    """Mint a possession challenge bound to ``user_id``.

    Returns ``(token, expires_at_unix_ts)``. The token is the exact string
    the caller signs with ``ssh-keygen -Y sign``, so its wire format —
    version tag, nonce, user id, expiry, a human-readable identity label and
    an HMAC-SHA256 signature, colon-joined — is deliberately restricted to
    printable ASCII with no whitespace. The separator is ``:``, not ``.``:
    emails contain dots, and a dot-separated identity would make the field
    split in ``_verify_ssh_key_challenge`` ambiguous. ``identity`` may itself
    contain colons (an email never does, but nothing here depends on that);
    parsing uses ``rsplit``/``split`` with explicit counts so the identity
    field absorbs anything after its position instead of being cut short.

    ``identity`` (pass ``preferred_username`` or ``email``; the caller
    chooses) exists so a signer who actually reads what ``ssh-keygen -Y
    sign`` is about to sign can see whose account the token binds — a bare
    UUID gives a phishing target no such visibility (Mallory mints a
    challenge for her own account, gets Victoria to sign *that* token via a
    page imitating the registration flow, then posts Victoria's public key
    with her own token and Victoria's signature: every check passes and the
    row lands on Mallory's account). The label is covered by the HMAC below
    (so it can't be swapped after minting without invalidating the token)
    but is DISPLAY-ONLY: authorization in ``_verify_ssh_key_challenge`` is
    decided entirely by ``user_id``, never by ``identity`` — flipping the
    label to name a different account does not move who the token
    authenticates as. Sanitized here — non-empty, ASCII, no whitespace,
    bounded length — with a fall back to the raw user id, since a
    malicious or malformed label must not be able to break the token's
    single-line-printable-ASCII contract (that contract is what lets
    ``_verify_ssh_key_challenge`` use ``str.isascii()`` as its first,
    cheap line of defense).

    **The label's anti-phishing property has one undocumented dependency:
    ``preferred_username`` and ``email`` are unique per Keycloak realm.** The
    mitigation is "the signer recognises the name as their own and not
    someone else's", which only works while a label names exactly one
    account. A deployment that ever admits duplicate usernames — a second
    identity provider federated in, a realm merge, a source change to a
    non-unique field like ``display_name`` — reverts this to a bare UUID's
    worth of protection, silently: no test here can see it, because every
    test constructs its own label. If the label source changes, re-derive
    that uniqueness claim first.

    Not single-use, deliberately (ruling F24). A nonce store would give
    literal single-use, but that isn't the property this token needs:
    binding it to the caller's user id is what carries the actual security
    guarantee. The attack single-use would prevent is replaying a captured
    (challenge, signature) pair to register someone else's public key under
    the attacker's account — the lockout risk this whole possession check
    exists to prevent, since SSH key fingerprints are globally unique. A
    token minted for user A can never redeem for user B (checked in
    ``_verify_ssh_key_challenge``), and a user replaying their own token just
    re-registers their own key, which the fingerprint's uniqueness
    constraint already rejects (409, see ``create_ssh_key``). Do not "fix"
    this back into a stateful nonce store: every orchestrator replica shares
    SESSION_JWT_SECRET via one Kubernetes Secret, but replicas do not share
    memory, which is the whole reason this token is stateless.

    Fails closed: raises if SESSION_JWT_SECRET is empty rather than signing
    with a well-known-empty key. Both HTTP callers in this file already
    guard this before calling in (and keep their own 503), but the
    precondition lives here too, on the reusable unit itself, since the
    ssh-gateway is expected to call this directly, outside any HTTP
    request/response cycle where a 503 would even make sense.
    """
    if not _session_jwt_secret:
        raise RuntimeError(
            "SESSION_JWT_SECRET is empty; refusing to mint a forgeable SSH "
            "possession challenge."
        )
    if now is None:
        now = time.time()
    label = (identity or "").strip()
    if (
        not label
        or len(label) > _SSH_CHALLENGE_IDENTITY_MAX_LEN
        or not label.isascii()
        or not label.isprintable()
        or any(ch.isspace() for ch in label)
    ):
        label = user_id
    expires_at = now + _SSH_CHALLENGE_TTL_SECONDS
    nonce = secrets.token_urlsafe(24)
    head = f"{_SSH_CHALLENGE_VERSION}:{nonce}:{user_id}:{int(expires_at)}:{label}"
    signature = hmac.new(
        _session_jwt_secret.encode("utf-8"),
        head.encode("utf-8"),
        hashlib.sha256,
    ).hexdigest()
    return f"{head}:{signature}", expires_at


def _verify_ssh_key_challenge(
    token: str, user_id: str, *, now: float | None = None
) -> bool:
    """True iff ``token`` was minted by us, for ``user_id``, and is unexpired.

    Check order is deliberate and load-bearing:

    1. ``token.isascii()``. ``hmac.compare_digest`` raises ``TypeError`` on
       a non-ASCII ``str`` argument — reachable pre-authentication, since
       the raw signature field is compared before its validity is known —
       so a body like ``{"challenge": "srw-ssh1:...:é", ...}`` would
       otherwise turn a 400 into an unhandled 500 an authenticated caller
       could loop. A lone UTF-16 surrogate (reachable via ``json.loads`` on
       a hostile body) isn't even ``str``-comparable by ``compare_digest``
       and raises ``UnicodeEncodeError`` on ``.encode()`` instead, so this
       must be a rejection, not a switch to byte comparison.
    2. SESSION_JWT_SECRET must be configured — verifying against an empty
       key would accept a forgery anyone can compute.
    3. The token parses into the expected fields at all.
    4. The HMAC, via ``hmac.compare_digest``, before any field the token
       carries (expiry, embedded user id, identity) is trusted — until the
       MAC checks out those fields are attacker-controlled input, not fact.
    5. Expiry.
    6. The embedded user id against the authenticated caller, also via
       ``hmac.compare_digest``. The identity label is parsed out (it has to
       be, to locate the other fields) but never compared against
       anything: it is a MAC-covered, display-only annotation, not an
       authorization input — only ``user_id`` decides who a token is for.
    """
    if not token.isascii():
        return False
    if not _session_jwt_secret:
        return False
    if now is None:
        now = time.time()
    try:
        head, signature = token.rsplit(":", 1)
        version, nonce, token_user_id, expires_at_raw, _identity = head.split(":", 4)
    except ValueError:
        return False
    if version != _SSH_CHALLENGE_VERSION:
        return False
    expected_signature = hmac.new(
        _session_jwt_secret.encode("utf-8"),
        head.encode("utf-8"),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        return False
    try:
        expires_at = float(expires_at_raw)
    except ValueError:
        return False
    if expires_at <= now:
        return False
    return hmac.compare_digest(token_user_id, str(user_id))


def _serialize_ssh_key_row(row: dict[str, Any]) -> dict[str, Any]:
    return {
        "id": str(row["id"]),
        "name": row["name"],
        "key_type": row["key_type"],
        "fingerprint": row["fingerprint_sha256"],
        "created_at": row["created_at"].isoformat() if row.get("created_at") else None,
        "last_used_at": (
            row["last_used_at"].isoformat() if row.get("last_used_at") else None
        ),
        "disabled": row.get("disabled_at") is not None,
    }


@app.post("/api/ssh-keys/challenge")
async def create_ssh_key_challenge(request: Request) -> dict[str, Any]:
    """Issue a nonce the caller must sign with the private half of the key they
    are registering.

    Without proof of possession, anyone could claim a public key they merely
    read — and since fingerprints are globally unique, that denies the
    rightful owner the ability to register their own key.
    """
    user = await require_approved_user(request, postgres_db)
    if not _session_jwt_secret:
        # Fail closed: an empty secret is a well-known HMAC key, so every
        # replica would sign forgeable tokens. main.py:1403 only logs a
        # warning for this today — do not rely on that here.
        raise HTTPException(
            status_code=503,
            detail="SSH key registration is temporarily unavailable.",
        )
    identity = user.get("preferred_username") or user.get("email")
    token, expires_at = _mint_ssh_key_challenge(str(user["id"]), identity)
    return {
        "challenge": token,
        "namespace": SIGNATURE_NAMESPACE,
        "expires_at": datetime.fromtimestamp(expires_at, tz=timezone.utc).isoformat(),
    }


@app.post("/api/ssh-keys")
async def create_ssh_key(request: Request, body: SshKeyCreate) -> dict[str, Any]:
    """Register an SSH public key after verifying possession.

    Scope-gated: a ``project:<uuid>``-scoped MCP token is refused here even
    though it authenticates a real, approved user. That token is already
    denied every thread by ``user_can_access_job_or_thread`` — the IDE
    included — but an SSH key authenticates by fingerprint, so resolution
    never sees the token that registered it. Without this gate the token
    could mint a credential opening a shell on every session its owner has,
    and one that outlives the token: revoking the PAT does not revoke the key.
    """
    user = await require_approved_user(request, postgres_db)
    await require_personal_scope(request, postgres_db, user, resource_type="ssh_key")

    if not _session_jwt_secret:
        raise HTTPException(
            status_code=503,
            detail="SSH key registration is temporarily unavailable.",
        )
    if not _verify_ssh_key_challenge(body.challenge, str(user["id"])):
        raise HTTPException(
            status_code=400,
            detail=(
                "Challenge is unknown, expired, or was issued to a "
                "different account. Request a new one."
            ),
        )

    try:
        parsed = parse_public_key(body.public_key)
    except SshKeyRejected as exc:
        raise HTTPException(status_code=400, detail=exc.reason) from exc

    if not verify_possession(
        parsed.public_key,
        SIGNATURE_NAMESPACE,
        body.challenge.encode("utf-8"),
        body.signature,
    ):
        raise HTTPException(
            status_code=400,
            detail=(
                "Could not verify possession of this key. Sign the challenge "
                "with the matching private key and paste the signature."
            ),
        )

    name = body.name.strip()
    if not name:
        raise HTTPException(status_code=400, detail="Give the key a name.")

    try:
        row = await postgres_db.create_user_ssh_key(
            user_id=str(user["id"]),
            name=name,
            key_type=parsed.key_type,
            public_key=parsed.public_key,
            fingerprint_sha256=parsed.fingerprint_sha256,
        )
    except SshKeyAlreadyRegistered as exc:
        raise HTTPException(
            status_code=409,
            detail=(
                "This key is already registered, possibly on another account. "
                "Register a different key, or contact support to have the "
                "existing registration released."
            ),
        ) from exc
    except SshKeyLimitReached as exc:
        # Also 409, but a different recovery path from the duplicate above:
        # this one you can fix yourself. Name the cap — a refusal that does
        # not say what the limit is reads as a bug.
        raise HTTPException(
            status_code=409,
            detail=(
                f"You already have the maximum of {exc.limit} registered SSH "
                "keys. Delete one before adding another."
            ),
        ) from exc

    # Account-security signal (workspace_ssh_access.md §6.3): a key added by
    # someone else — a stolen session, a shared account — must stay visible
    # to its owner, the same reason a "new sign-in" mail is loud. Best-effort
    # and non-fatal, like every other notify-after-write call site in this
    # file: the key is already durably registered, so a feed-write hiccup
    # must never turn into a failed registration.
    try:
        await notification_service.record(
            recipient_id=str(user["id"]),
            category="ssh_key_added",
            # Per-key, not per-user-per-day: a replayed request must collapse
            # onto the same row, but a second, distinct key added minutes
            # later is its own event.
            dedup_key=f"ssh_key_added:{row['id']}",
            subject=f"New SSH key added: {name}",
            body=(
                f"The SSH key **{name}** ({parsed.key_type}, "
                f"`{parsed.fingerprint_sha256}`) was added to your account. "
                "If this wasn't you, remove it from Settings → SSH Keys "
                "immediately and rotate anything it may have reached."
            ),
            source_kind="ssh_key",
            source_id=str(row["id"]),
            payload={
                "ssh_key_id": str(row["id"]),
                "name": name,
                "fingerprint": parsed.fingerprint_sha256,
                "key_type": parsed.key_type,
            },
        )
    except Exception:
        logger.warning(
            "ssh_key_added notification for key %s failed (non-fatal)",
            str(row["id"])[:8],
            exc_info=True,
        )
    return _serialize_ssh_key_row(row)


@app.get("/api/ssh-keys")
async def list_ssh_keys(request: Request) -> list[dict[str, Any]]:
    """The current user's registered SSH public keys.

    Scope-gated like its create/delete siblings. The delta a project-scoped
    MCP token gains here is only read access — names, fingerprints and
    last_used_at, with no id it can act on, since delete is gated too. It is
    gated anyway because ``_scope_permits_personal`` says such a token
    "shouldn't be able to read or mutate" a personal resource, and
    ``user_can_access_job_or_thread`` enforces exactly that for reads. Leaving
    one of the three open would make this helper's own call sites disagree
    with the contract they cite.
    """
    user = await require_approved_user(request, postgres_db)
    await require_personal_scope(
        request, postgres_db, user, resource_type="ssh_key", resource_id=None
    )
    rows = await postgres_db.list_user_ssh_keys(str(user["id"]))
    return [_serialize_ssh_key_row(r) for r in rows]


@app.delete("/api/ssh-keys/{key_id}")
async def delete_ssh_key(request: Request, key_id: str) -> dict[str, str]:
    """Remove one of the current user's keys.

    Scope-gated for the same reason as ``create_ssh_key``: a project-scoped
    MCP token has no business reaching a personal credential, in either
    direction. Revocation is the only control a user has over a key (there is
    no disable endpoint), so leaving delete open while gating create would let
    a project-scoped token strip its owner's access.
    """
    user = await require_approved_user(request, postgres_db)
    await require_personal_scope(
        request, postgres_db, user, resource_type="ssh_key", resource_id=key_id
    )
    try:
        deleted = await postgres_db.delete_user_ssh_key(key_id, str(user["id"]))
    except ValueError:
        # key_id isn't a well-formed UUID — the store's UUID(key_id) raises.
        # Same "no such key" outcome as a well-formed id matching no row;
        # not a 500.
        deleted = False
    if not deleted:
        raise HTTPException(status_code=404, detail="Key not found")
    return {"status": "deleted"}


@app.post("/api/ssh/attach-token")
async def create_ssh_attach_token(request: Request) -> dict[str, Any]:
    """Mint the short-lived credential the SSH gateway's WSS front door wants.

    This is the ONLY thing a user should ever present to
    ``wss://.../api/ssh/attach``. It is emphatically not ``MCP_INTERNAL_KEY``:
    that value is the platform's service-to-service credential, guarding ~50
    ``require_internal`` endpoints, and an earlier draft of the gateway
    compared the user's bearer token against it — which would have put the
    master key in every SSH user's ``~/.config/srw/token`` (ruling G38; see
    ``services/ssh_gateway_token.py`` for the full account).

    Stateless and user-bound, the same shape as the SSH-key registration
    challenge above and for the same reason: the gateway is a separate
    Deployment from this one, and this one runs ``replicas: 2`` with no
    session affinity, so there is nowhere to keep a nonce that both sides can
    see. The two tokens are minted with the same secret and kept apart by a
    version clause inside the MAC.

    Scope-gated like ``create_ssh_key``: a ``project:<uuid>``-scoped MCP token
    is refused. The token opens a transport into every workspace its holder's
    registered keys can reach, and by the time the SSH layer authorizes (by
    key fingerprint) the MCP token's scope no longer exists to check.
    """
    user = await require_approved_user(request, postgres_db)
    await require_personal_scope(
        request, postgres_db, user, resource_type="ssh_attach_token"
    )
    if not _session_jwt_secret:
        raise HTTPException(
            status_code=503,
            detail="SSH access is temporarily unavailable.",
        )
    token, expires_at = mint_attach_token(str(user["id"]), _session_jwt_secret)
    return {
        "token": token,
        "expires_at": datetime.fromtimestamp(expires_at, tz=timezone.utc).isoformat(),
    }


class _PartialHostKeyRead(Exception):
    """Carries a partial host-key read past ``functools.lru_cache``.

    ``lru_cache`` does not memoize calls that raise, which is exactly the
    behavior wanted here: see ``_load_ssh_gateway_host_keys``.
    """

    def __init__(self, entries: tuple[dict[str, str], ...]) -> None:
        super().__init__("one or more ssh gateway host key paths were unreadable")
        self.entries = entries


# Cap on how much of an operator-supplied path is read. A public key file is
# a few hundred bytes; anything larger is a mis-pointed path, and there is no
# reason to slurp it into memory to fail parsing it.
_SSH_HOST_KEY_READ_LIMIT = 65536


def _parse_ssh_gateway_host_keys(
    paths_value: str,
) -> tuple[tuple[dict[str, str], ...], bool]:
    """Read and fingerprint every path in ``paths_value`` (uncached).

    Returns ``(entries, complete)``. ``complete`` is False when any configured
    path failed to read or parse. A bad entry is skipped rather than raising —
    one typo in the list must not take down discovery for the rest — but the
    caller needs to know it happened so it does not memoize a partial answer.
    """
    import asyncssh

    entries: list[dict[str, str]] = []
    complete = True
    for path in (p.strip() for p in paths_value.split(",")):
        if not path:
            continue
        try:
            with open(path, "r", encoding="utf-8") as handle:
                raw = handle.read(_SSH_HOST_KEY_READ_LIMIT)
            key = asyncssh.import_public_key(raw)
        except Exception:
            logger.warning("ssh gateway host key unreadable at %s", path)
            complete = False
            continue
        entries.append(
            {
                "type": key.get_algorithm(),
                "public_key": key.export_public_key().decode().strip(),
                "fingerprint": key.get_fingerprint("sha256"),
            }
        )
    return tuple(entries), complete


@functools.lru_cache(maxsize=8)
def _memoized_ssh_gateway_host_keys(paths_value: str) -> tuple[dict[str, str], ...]:
    """Memoize a *complete* parse only; raise on a partial one.

    ``functools.lru_cache`` never caches a call that raises, so signalling a
    partial read with ``_PartialHostKeyRead`` is what makes the next request
    retry instead of inheriting the failure.
    """
    entries, complete = _parse_ssh_gateway_host_keys(paths_value)
    if not complete:
        raise _PartialHostKeyRead(entries)
    return entries


def _load_ssh_gateway_host_keys(paths_value: str) -> tuple[dict[str, str], ...]:
    """Parse and fingerprint the gateway's public host keys.

    A fully-successful parse is cached on ``paths_value`` itself — the raw
    ``SSH_GATEWAY_PUBLIC_HOST_KEYS`` string, not on nothing.
    ``get_ssh_host_keys`` below is unauthenticated by design, so without that
    cache every anonymous request would drive a fresh blocking ``open()`` plus
    asyncssh parse per configured key, on the event loop, with no rate limit
    in front of it. Keying on the env value (rather than calling with no
    arguments) means a changed value — a real config update, or a different
    value monkeypatched in per-test — gets a fresh parse instead of a stale
    hit.

    A partial or failed read is deliberately *not* cached. These files arrive
    on a projected Secret volume, so contrary to what one might assume they
    very much can be absent or in flux while the pod runs: the volume may not
    be projected yet when the first request lands, and a read can fall in the
    window where kubelet swaps the ``..data`` symlink during a Secret update.
    Memoizing that outcome would publish ``host_keys: []`` — a hard stop for a
    pinning client — until the pod restarted. Retrying costs one re-read per
    request, and only for as long as the underlying problem lasts.
    """
    try:
        return _memoized_ssh_gateway_host_keys(paths_value)
    except _PartialHostKeyRead as partial:
        return partial.entries


# nosec: public ssh-host-key-pinning (host keys are public material; client needs them before it can authenticate anything)
@app.get("/api/ssh/host-keys")
async def get_ssh_host_keys(request: Request) -> dict[str, Any]:
    """Publish the SSH gateway's host keys so client tooling can pin them
    without a human comparing fingerprints by eye (Gitpod's
    ``/_ssh/host_keys``, Tailscale's control-plane distribution).

    Deliberately unauthenticated: host keys are public, and the client needs
    this response before it has anything to authenticate against yet. This
    runs in the orchestrator, not the gateway process — it reads
    ``SSH_GATEWAY_PUBLIC_HOST_KEYS`` (comma-separated public-key file paths)
    and ``SSH_GATEWAY_HOSTNAME`` from its own environment, which the gateway
    Deployment's operator is responsible for keeping in sync with the
    gateway's actual ``SSH_GATEWAY_HOST_KEYS`` (private-key) configuration.

    A path that doesn't parse as a key (missing, unreadable, garbage) is
    logged and skipped rather than raising — one bad entry in the list
    should not take down discovery for the rest. Pointing an entry at a
    private key instead of its ``.pub`` file does not raise either: asyncssh
    parses OpenSSH private-key material leniently and returns only its
    public component (verified by reading ``asyncssh.public_key._decode_public``,
    not assumed) — so this is not a rejection path, it is quietly correct.
    Either way, only ``export_public_key()`` output ever reaches the
    response; nothing here ever calls an export-private path.

    Returns ``{"host_keys": [], "hostname": ...}`` when unconfigured, never
    an error — an SSH client probing this before any gateway exists is a
    normal, not exceptional, state.
    """
    entries = _load_ssh_gateway_host_keys(
        os.environ.get("SSH_GATEWAY_PUBLIC_HOST_KEYS") or ""
    )
    return {
        "host_keys": [dict(entry) for entry in entries],
        "hostname": os.environ.get("SSH_GATEWAY_HOSTNAME", ""),
    }


def _ssh_target_response(
    thread_id: str,
    user: dict[str, Any],
    state: str,
    target: RemoteWorkspaceTarget | None = None,
) -> dict[str, Any]:
    """The one response shape every ``get_ssh_target`` branch returns, so a
    new field can't be added to three branches out of four.

    ``pod_ip`` is a misnomer kept on purpose. The value is
    ``RemoteWorkspaceTarget.host``, which comes from ``workspace_container.
    ssh_host`` — a Kubernetes Service DNS name, not a pod IP. Dialing a pod IP
    was an explicitly rejected earlier design (it breaks the moment the pod is
    recreated, and the provisioner's attested identity is bound to the
    Service). The name stays because the gateway plan already reads this
    field by it; do not "fix" it into something that suggests the gateway
    should resolve or trust an IP.

    ``ssh_key_id`` comes from ``user`` because ``resolve_user_by_ssh_
    fingerprint`` already resolves it (it's the matched ``user_ssh_keys.id``,
    joined in for exactly this reason). ``.get`` rather than a required key:
    every real caller passes the dict that resolver returns, but tests and
    any future caller that only has a plain ``{"id": ...}`` must not crash
    this helper for it.

    NOT load-bearing for ``POST /api/internal/ssh-attachments``: that
    endpoint re-resolves ``ssh_key_id`` server-side itself rather than
    trusting a value the gateway echoes back (fix round 1, Important 1 —
    accepting it from the caller would be exactly the "internal key plus an
    asserted identity" this module's own docstring rules out). This field
    stays because it is already built and tested, leaks nothing beyond the
    ``user_id`` already on this response, and is useful for gateway-side
    logging — but nothing should come to depend on it for anything other
    than display/logging.
    """
    ssh_key_id = user.get("ssh_key_id")
    return {
        "thread_id": thread_id,
        "user_id": str(user["id"]),
        "ssh_key_id": str(ssh_key_id) if ssh_key_id else None,
        "pod_ip": target.host if target else None,
        "pod_port": target.port if target else None,
        "host_key_fingerprint": target.fingerprint if target else None,
        "state": state,
    }


@app.get("/api/internal/ssh-targets/{handle}")
async def get_ssh_target(
    request: Request, handle: str, fingerprint: str | None = None
) -> dict[str, Any]:
    """Resolve an SSH handle plus a presented key fingerprint to a workspace
    target. **Internal** — requires ``X-Internal-Key``.

    The gateway sends the FINGERPRINT, never a user id: it holds no database
    credentials, and this codebase does not accept an internal key plus an
    asserted user identity. Key-to-user mapping stays here so disabled_at and
    approval are enforced server-side.

    **Resolution here is not proof of possession**, so this endpoint must
    never call ``mark_ssh_key_used``: the caller has offered a fingerprint,
    not a signature. Every agent pod holds ``X-Internal-Key``, and
    fingerprints are derivable from published public keys, so a write on this
    path would be attacker-controlled. The gateway bumps ``last_used_at``
    itself, after ``key.verify`` succeeds.

    Unknown handle, unknown key and unauthorized all return an identical 404.
    A resolvable-but-not-live workspace returns 200 with a non-live ``state``
    and ``pod_ip: None``, so the gateway can print a readable reason.

    ``fingerprint`` is Optional so a request that omits it still reaches
    ``require_internal`` first: a required query param would make FastAPI
    422 before any auth check runs, disclosing the route and its parameter
    name to an unauthenticated caller.
    """
    await require_internal(request)

    opaque = HTTPException(status_code=404, detail="No such workspace")

    if not fingerprint or not is_valid_handle(handle):
        raise opaque

    # Both lookups run unconditionally, even when the handle is already
    # known to be unknown. The original reason — resolve_user_by_ssh_
    # fingerprint bumped user_ssh_keys.last_used_at, which the caller could
    # read back through GET /api/ssh-keys, turning "did my key's last_used_at
    # just move?" into a confirmation oracle — is gone: that resolver is now a
    # pure read (see its docstring). Keep the unconditional call anyway. It
    # costs one indexed lookup on an already-failing request, it keeps the two
    # 404 paths issuing the same number of round trips, and it means
    # re-introducing any write inside the resolver cannot silently re-open the
    # oracle from here. Pinned by test_unknown_handle_still_reaches_the_
    # fingerprint_resolver.
    #
    # Note the timing argument is a bonus, not the boundary: the not-yours
    # path still does more work (get_thread plus user_can_access_ide_entity's
    # own get_job/get_thread) than the unknown-handle path.
    thread_id = await postgres_db.get_thread_id_by_ssh_handle(handle)
    user = await postgres_db.resolve_user_by_ssh_fingerprint(fingerprint)
    if not thread_id or not user:
        raise opaque
    if not await user_can_access_ide_entity(user, postgres_db, thread_id):
        raise opaque

    thread = await postgres_db.get_thread(thread_id)
    if not thread:
        raise opaque
    metadata = thread_metadata_object(thread)

    ws_ctx = metadata.get("workspace_container") or {}
    vm_ctx = metadata.get("vm") or {}
    if _thread_is_vm_tier(metadata, ws_ctx, vm_ctx):
        return _ssh_target_response(thread_id, user, STATE_VM_UNSUPPORTED)

    state = resolve_workspace_state(thread, metadata)
    if state != STATE_LIVE:
        return _ssh_target_response(thread_id, user, state)

    try:
        target = resolve_remote_workspace_target(
            thread, bound_workspace_generation(thread)
        )
    except CanvasSSHError as exc:
        # workspace_container.status IS "ready" here — resolve_workspace_
        # state already proved that via STATE_LIVE above — so this is a
        # provisioned workspace with an unusable SSH attestation (missing/
        # stale _workspace_binding, bad host key), not an absent workspace.
        # STATE_STALE_BINDING says so; folding it into STATE_NEVER_
        # PROVISIONED would send an operator after the wrong problem.
        logger.info("ssh-target unresolvable for %s: %s", thread_id, exc)
        return _ssh_target_response(thread_id, user, STATE_STALE_BINDING)

    # The guard above and the resolver disagree about what "VM tier" means,
    # and the disagreement hands out the wrong host. _thread_is_vm_tier reads
    # the DECLARED backend once a container status is present, while
    # resolve_remote_workspace_target prefers metadata.vm whenever its status
    # is "ready" regardless of workspace_container. Upgrade-to-VM writes
    # metadata.vm without rewriting config_override.workspace.backend (that
    # method's own docstring says so), so a thread with both contexts ready
    # and a stale non-VM backend passes the guard and is then handed the VM's
    # host and port — which v1 must refuse. Ask the resolver's own question,
    # after the fact, rather than re-deriving the tier a third way.
    if remote_target_is_vm_backed(thread):
        return _ssh_target_response(thread_id, user, STATE_VM_UNSUPPORTED)

    return _ssh_target_response(thread_id, user, STATE_LIVE, target)


class SshKeyUsedRequest(BaseModel):
    """Body for the gateway's post-authentication ``last_used_at`` bump.

    ``fingerprint`` is capped: it flows straight into a SQL predicate
    (``resolve_user_by_ssh_fingerprint``, then ``mark_ssh_key_used``'s
    second WHERE clause) with no length check downstream, so an unbounded
    body would let any ``X-Internal-Key`` holder push an arbitrarily large
    value into that query. A SHA256 fingerprint is ``"SHA256:"`` plus 43
    base64 characters (50 total); 128 is headroom, not a tight fit.
    """

    fingerprint: str = Field(..., min_length=1, max_length=128)


@app.post("/api/internal/ssh-keys/used")
async def internal_mark_ssh_key_used(
    request: Request, body: SshKeyUsedRequest
) -> dict[str, str]:
    """Stamp ``last_used_at`` on the key behind a presented fingerprint.
    **Internal** — requires ``X-Internal-Key``.

    Keyed by FINGERPRINT, not ``key_id``, and that is not arbitrary: the
    gateway calls this from asyncssh's ``auth_completed()``, which fires
    immediately after ``key.verify`` succeeds — but the gateway resolves its
    target (and therefore a key id) lazily, at first channel open. At the
    only moment this call may legitimately fire, it holds a fingerprint and
    nothing else. An endpoint taking ``key_id`` would be uncallable then.

    Resolution happens server-side via ``resolve_user_by_ssh_fingerprint``
    (the same pure-read resolver ``get_ssh_target`` uses) so the actual
    write goes through ``mark_ssh_key_used``, which additionally requires
    the fingerprint to match the row being stamped — see that method's
    docstring for why this endpoint is safe to call with only a fingerprint
    even though ``get_ssh_target`` itself must never call it.

    An unknown fingerprint is a quiet no-op success, not a 404: the caller
    has already authenticated against *some* key by the time this fires, and
    a 404 here would turn this endpoint into an existence oracle for
    registered keys (identical reasoning to ``get_ssh_target``'s opaque
    404s).
    """
    await require_internal(request)
    user = await postgres_db.resolve_user_by_ssh_fingerprint(body.fingerprint)
    key_id = user.get("ssh_key_id") if user else None
    if key_id:
        try:
            await postgres_db.mark_ssh_key_used(str(key_id), body.fingerprint)
        except Exception:
            # mark_ssh_key_used's own docstring: "a failed bump must not
            # discard an authentication that already succeeded." The
            # gateway calls this after key.verify has already passed, so a
            # transient DB hiccup on the bump itself must not turn into a
            # 500 for what is, from the caller's side, a fire-and-forget
            # bookkeeping call.
            logger.warning(
                "mark_ssh_key_used failed for a resolved key; last_used_at not bumped",
                exc_info=True,
            )
    return {"status": "ok"}


class SshAttachmentCreate(BaseModel):
    """Body for opening an SSH-attachment audit row.

    Deliberately does NOT carry ``thread_id``/``user_id``/``ssh_key_id``.
    ``get_ssh_target``'s docstring states the invariant this body must not
    violate: "this codebase does not accept an internal key plus an
    asserted user identity." An earlier draft of this endpoint took those
    three as asserted fields — any ``X-Internal-Key`` holder (every agent
    pod) could then write an audit row attributing an SSH attach to any
    user on any thread. That the value is only ever recorded, never used
    for an authorization decision, is a mitigation, not a justification —
    the audit table's whole purpose is a trustworthy record of who reached
    a workspace over SSH, and a forgeable one is worth less than it looks.

    ``thread_id``, ``user_id`` and ``ssh_key_id`` are resolved server-side
    instead, by ``internal_create_ssh_attachment``, from ``fingerprint`` and
    ``handle`` — the same two values ``get_ssh_target`` resolves identity
    from.

    ``fingerprint`` is capped for the same reason as
    ``SshKeyUsedRequest.fingerprint``.
    """

    fingerprint: str = Field(..., min_length=1, max_length=128)
    handle: str
    client_ip: str | None = None


@app.post("/api/internal/ssh-attachments")
async def internal_create_ssh_attachment(
    request: Request, body: SshAttachmentCreate
) -> dict[str, str]:
    """Open an SSH-attachment audit row. **Internal** — requires
    ``X-Internal-Key``.

    Resolves ``thread_id``, ``user_id`` and ``ssh_key_id`` server-side from
    ``fingerprint`` and ``handle`` — see ``SshAttachmentCreate`` for why an
    asserted identity is never accepted here. The resolution is the
    identical lookup ``get_ssh_target`` performs (``get_thread_id_by_ssh_
    handle`` + ``resolve_user_by_ssh_fingerprint``, gated by
    ``user_can_access_ide_entity``), reusing that endpoint's opaque 404 for
    every failure mode — unknown handle, unknown/unapproved key, and "not
    your thread" all come back identical, so this endpoint cannot be used
    to probe for handle or key existence either. In real operation this is
    not expected to fail: the gateway only calls this after ``get_ssh_
    target`` already resolved the same handle/fingerprint pair to open the
    SSH session in the first place.

    A foreign-key violation on the insert (thread, user or key deleted
    between the resolution above and the write below — a real race, e.g. a
    thread torn down mid-session, not just a probe) and a malformed
    ``handle`` surfacing from ``record_ssh_attachment`` both map to 400
    rather than an unhandled 500.
    """
    await require_internal(request)

    opaque = HTTPException(status_code=404, detail="No such workspace")
    if not is_valid_handle(body.handle):
        raise opaque

    thread_id = await postgres_db.get_thread_id_by_ssh_handle(body.handle)
    user = await postgres_db.resolve_user_by_ssh_fingerprint(body.fingerprint)
    if not thread_id or not user:
        raise opaque
    if not await user_can_access_ide_entity(user, postgres_db, thread_id):
        raise opaque

    ssh_key_id = user.get("ssh_key_id")
    try:
        attachment_id = await postgres_db.record_ssh_attachment(
            thread_id,
            str(user["id"]),
            str(ssh_key_id) if ssh_key_id else None,
            body.client_ip,
            body.handle,
        )
    except (ValueError, asyncpg.ForeignKeyViolationError) as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    return {"attachment_id": attachment_id}


class SshAttachmentClose(BaseModel):
    """Body for closing an SSH-attachment audit row.

    ``fingerprint`` (fix round 2): before this field existed, any
    ``X-Internal-Key`` holder (every agent pod) could close ANY attachment
    row it could name — there was no identity in this body at all, only an
    opaque path-param UUID. Unlike ``SshAttachmentCreate`` there was no
    identity to *forge*, so the risk isn't access escalation, but a
    forensics table any internal-key holder can silently corrupt (mark
    detached, stamp fabricated ``channels``) is weaker evidence, and being
    evidence is this table's whole purpose. ``internal_close_ssh_attachment``
    resolves this fingerprint to a user and checks that user against the
    NAMED attachment's own thread — see that function's docstring. Capped
    for the same reason as the other two fingerprint fields.

    ``channels`` is capped in both count and per-entry length: it is written
    straight into a ``text[]`` column (migration 0204) with no size limit of
    its own, so an unbounded body would let any ``X-Internal-Key`` holder
    inflate an audit row arbitrarily. Two channel types exist today
    ("session", "sftp"), so 8 entries of up to 32 characters each is
    generous headroom, not a tight fit.
    """

    fingerprint: str = Field(..., min_length=1, max_length=128)
    channels: list[str] = Field(default_factory=list, max_length=8)

    @field_validator("channels")
    @classmethod
    def _cap_channel_name_length(cls, value: list[str]) -> list[str]:
        for channel in value:
            if len(channel) > 32:
                raise ValueError(f"channel name too long: {channel[:40]!r}...")
        return value


@app.post("/api/internal/ssh-attachments/{attachment_id}/close")
async def internal_close_ssh_attachment(
    request: Request, attachment_id: str, body: SshAttachmentClose
) -> dict[str, int]:
    """Stamp detach time on an SSH-attachment row. **Internal** — requires
    ``X-Internal-Key``.

    Authorizes the close server-side rather than trusting the path-param
    UUID alone: resolves ``attachment_id`` to the thread it was opened
    against (``get_ssh_attachment_thread_id``), resolves ``body.fingerprint``
    to a user (``resolve_user_by_ssh_fingerprint``), and requires
    ``user_can_access_ide_entity`` to hold between them — the identical two
    building blocks ``internal_create_ssh_attachment`` composes, reused
    rather than re-invented. Both lookups run unconditionally regardless of
    whether the first already failed, mirroring ``get_ssh_target``'s own
    comment on why: skipping the fingerprint resolution whenever
    ``attachment_id`` is already known-bad would make "was the id real" a
    timing oracle.

    Every authorization failure — unknown id, a thread whose FK already went
    NULL (``get_ssh_attachment_thread_id``'s docstring), unresolvable
    fingerprint, and "not your thread" — collapses into the SAME
    ``{"closed": 0}`` the pre-existing "unknown or already-closed id" case
    returns, deliberately: a caller must not be able to distinguish "no such
    attachment" from "not yours" (opaque, matching create's contract), and
    the gateway already treats ``{"closed": 0}`` as a normal best-effort
    outcome, so this changes no caller's error handling. ``close_ssh_
    attachment`` itself is never reached in any of these cases.

    A malformed ``attachment_id`` is a distinct, earlier failure: it 400s
    (via ``get_ssh_attachment_thread_id``'s own ``UUID()`` parse, before any
    connection is acquired) rather than folding into the opaque envelope
    above, because the caller already knows whether the string it sent is a
    syntactically valid UUID — that check discloses nothing about which real
    ids exist.
    """
    await require_internal(request)

    try:
        thread_id = await postgres_db.get_ssh_attachment_thread_id(attachment_id)
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc

    user = await postgres_db.resolve_user_by_ssh_fingerprint(body.fingerprint)

    if (
        thread_id is not None
        and user is not None
        and await user_can_access_ide_entity(user, postgres_db, thread_id)
    ):
        try:
            closed = await postgres_db.close_ssh_attachment(
                attachment_id, body.channels
            )
        except ValueError as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc
        return {"closed": closed}

    return {"closed": 0}


# =============================================================================
# User Settings & API Key Endpoints
# =============================================================================


@app.get("/api/settings/api-keys")
async def list_user_api_keys(request: Request) -> list[dict[str, Any]]:
    """List the current user's API keys (prefix only, no full keys)."""
    user = await require_approved_user(request, postgres_db)
    rows = await postgres_db.list_user_api_keys(str(user["id"]))
    return [
        {k: str(v) if isinstance(v, (UUID, datetime)) else v for k, v in r.items()}
        for r in rows
    ]


@app.put("/api/settings/api-keys/{provider}")
async def set_user_api_key(
    request: Request, provider: str, body: ApiKeySet
) -> dict[str, Any]:
    """Set (create or replace) an API key for a provider."""
    user = await require_approved_user(request, postgres_db)
    if provider not in VALID_API_KEY_PROVIDERS:
        raise HTTPException(
            status_code=400,
            detail=f"Invalid provider '{provider}'. Valid: {sorted(VALID_API_KEY_PROVIDERS)}",
        )

    key_prefix = body.api_key[:8]
    row = await postgres_db.upsert_user_api_key(
        user_id=str(user["id"]),
        provider=provider,
        api_key=body.api_key,
        key_prefix=key_prefix,
        label=body.label,
    )
    return {k: str(v) if isinstance(v, (UUID, datetime)) else v for k, v in row.items()}


@app.delete("/api/settings/api-keys/{provider}")
async def delete_user_api_key(request: Request, provider: str) -> dict[str, str]:
    """Delete the current user's API key for a provider."""
    user = await require_approved_user(request, postgres_db)
    deleted = await postgres_db.delete_user_api_key(str(user["id"]), provider)
    if not deleted:
        raise HTTPException(
            status_code=404, detail=f"No API key for provider '{provider}'"
        )
    return {"status": "deleted"}


# =============================================================================
# LLM endpoint helpers
# Shared URL validation + response shaping for the admin provider-endpoint
# routes below. The former user-facing Settings → LLM Endpoints CRUD was
# removed: user-scoped endpoints were never resolvable at dispatch (the
# per-user/system resolver hooks are unregistered and the catalog resolver
# only joins system-scoped rows), so custom endpoints are admin-only now via
# Admin → Providers + Admin → Models.
# =============================================================================


def _validate_llm_endpoint_url(base_url: str, allow_insecure: bool) -> str:
    """Basic URL sanity check. Raises HTTPException(400) on malformed input.

    Rejects non-http(s) schemes (file://, javascript:), empty hosts, and
    http:// URLs unless the caller explicitly opts in via allow_insecure.
    """
    from urllib.parse import urlparse

    try:
        parsed = urlparse(base_url.strip())
    except Exception:
        raise HTTPException(status_code=400, detail="Malformed base_url")

    if parsed.scheme not in ("http", "https"):
        raise HTTPException(
            status_code=400,
            detail=f"base_url scheme must be http or https, got {parsed.scheme!r}",
        )
    if not parsed.netloc:
        raise HTTPException(status_code=400, detail="base_url must include a host")
    if parsed.scheme == "http" and not allow_insecure:
        raise HTTPException(
            status_code=400,
            detail=(
                "base_url uses http:// — set allow_insecure=true to override "
                "(not recommended outside local development)."
            ),
        )
    return parsed.geturl()


def _serialize_endpoint(row: dict[str, Any]) -> dict[str, Any]:
    """Shape an endpoint row for the API response (key_prefix only, no full key).

    The ``models`` key is kept on the response shape for Cockpit
    compatibility but is always empty after the catalog flip — model
    offerings live in the admin-curated ``models`` table now.
    """
    return {
        "id": str(row["id"]),
        "label": row["label"],
        "base_url": row["base_url"],
        "key_prefix": row.get("key_prefix"),
        "created_at": row["created_at"].isoformat() if row.get("created_at") else None,
        "updated_at": row["updated_at"].isoformat() if row.get("updated_at") else None,
        "models": [],
    }


# =============================================================================
# Admin Provider Endpoints
# System-scoped provider keys, LLM endpoints, and default-model settings.
# Gated by the srw-admin role via _require_admin.
# =============================================================================


def _serialize_system_api_key(row: dict[str, Any]) -> dict[str, Any]:
    """Shape a system_api_keys row for API responses (prefix only)."""
    return {
        "id": str(row["id"]),
        "provider": row["provider"],
        "key_prefix": row.get("key_prefix"),
        "label": row.get("label"),
        "seeded_from": row.get("seeded_from"),
        "created_at": row["created_at"].isoformat() if row.get("created_at") else None,
        "updated_at": row["updated_at"].isoformat() if row.get("updated_at") else None,
    }


@app.get("/api/admin/providers/keys")
async def admin_list_provider_keys(request: Request) -> list[dict[str, Any]]:
    """List system-scoped provider API keys (prefix only, no full keys)."""
    await _require_admin(request)
    rows = await postgres_db.list_system_api_keys()
    return [_serialize_system_api_key(r) for r in rows]


@app.put("/api/admin/providers/keys/{provider}")
async def admin_set_provider_key(
    request: Request, provider: str, body: ApiKeySet
) -> dict[str, Any]:
    """Set or rotate the system-level API key for a provider.

    On success, schedules a non-blocking discovery probe for providers
    we know how to enumerate (see ``discovery_service.DISCOVERABLE_PROVIDERS``).
    The discovery cache is cleared inline before the probe fires so the
    cockpit never shows stale candidates from a previous key. When the
    ``admin.discovery_enabled`` flag is set to ``false``, no probe runs.
    """
    await _require_admin(request)
    if provider not in VALID_SYSTEM_API_KEY_PROVIDERS:
        raise HTTPException(
            status_code=400,
            detail=(
                f"Invalid provider '{provider}'. Valid: "
                f"{sorted(VALID_SYSTEM_API_KEY_PROVIDERS)}"
            ),
        )
    row = await postgres_db.upsert_system_api_key(
        provider=provider,
        api_key=body.api_key,
        key_prefix=body.api_key[:8],
        label=body.label,
    )
    await _maybe_schedule_discovery(provider, body.api_key)
    return _serialize_system_api_key(row)


@app.delete("/api/admin/providers/keys/{provider}")
async def admin_delete_provider_key(request: Request, provider: str) -> dict[str, str]:
    """Remove the system-level key for a provider."""
    await _require_admin(request)
    deleted = await postgres_db.delete_system_api_key(provider)
    if not deleted:
        raise HTTPException(
            status_code=404, detail=f"No system key for provider '{provider}'"
        )
    return {"status": "deleted"}


@app.get("/api/admin/providers/keys/{provider}/discovery")
async def admin_get_provider_discovery(
    request: Request, provider: str
) -> dict[str, Any]:
    """Return the cached discovery payload for a provider key.

    Powers the post-save confirmation dialog on Admin → Providers. The
    response is ``{ready, fresh, payload, cached_at}``:

    - ``ready=False`` when no probe has completed yet (e.g. the async
      probe scheduled by the PUT side-effect is still running).
    - ``fresh`` reflects the 24h TTL — the cockpit can prompt for an
      explicit rediscover when stale.
    - ``payload`` is the cockpit-ready candidate list shaped by
      :func:`discovery_service.build_cache_payload`.
    """
    await _require_admin(request)
    if provider not in VALID_SYSTEM_API_KEY_PROVIDERS:
        raise HTTPException(
            status_code=400,
            detail=(
                f"Invalid provider '{provider}'. Valid: "
                f"{sorted(VALID_SYSTEM_API_KEY_PROVIDERS)}"
            ),
        )
    cached = await postgres_db.get_system_api_key_discovery_cache(provider)
    if cached is None:
        return {"ready": False, "fresh": False, "payload": None, "cached_at": None}
    cached_at_dt = (
        datetime.fromisoformat(cached["cached_at"]) if cached.get("cached_at") else None
    )
    return {
        "ready": True,
        "fresh": discovery_service.is_discovery_cache_fresh(cached_at_dt),
        "payload": cached.get("payload"),
        "cached_at": cached.get("cached_at"),
    }


@app.post("/api/admin/providers/keys/{provider}/rediscover")
async def admin_rediscover_provider_models(
    request: Request, provider: str
) -> dict[str, Any]:
    """Force-refresh the discovery cache for a provider key.

    Useful when the provider released new models since the cache was
    populated, or when the admin wants to retry after a transient probe
    failure. Returns the freshly-cached payload (synchronous probe — the
    button blocks until results come back, like an explicit "test" click).
    """
    await _require_admin(request)
    if provider not in VALID_SYSTEM_API_KEY_PROVIDERS:
        raise HTTPException(
            status_code=400,
            detail=(
                f"Invalid provider '{provider}'. Valid: "
                f"{sorted(VALID_SYSTEM_API_KEY_PROVIDERS)}"
            ),
        )
    if provider not in discovery_service.DISCOVERABLE_PROVIDERS:
        raise HTTPException(
            status_code=400,
            detail=(
                f"Provider '{provider}' has no discovery source. "
                "Add models manually via Admin → Models."
            ),
        )
    if not await _discovery_enabled():
        raise HTTPException(
            status_code=409,
            detail=(
                "Auto-discovery is disabled "
                "(admin.discovery_enabled = false in system_settings)."
            ),
        )
    api_key = await postgres_db.get_system_api_key(provider)
    if not api_key:
        raise HTTPException(
            status_code=404, detail=f"No system key for provider '{provider}'"
        )
    candidates = await discovery_service.discover_models(provider, api_key)
    payload = discovery_service.build_cache_payload(provider, candidates)
    await postgres_db.set_system_api_key_discovery_cache(provider, payload)
    return {
        "ready": True,
        "fresh": True,
        "payload": payload,
        "cached_at": payload["fetched_at"],
    }


async def _discovery_enabled() -> bool:
    """Return whether admin auto-discovery is enabled (system setting,
    default True). Operators flip this off when they want catalog growth
    to be a deliberate manual action."""
    row = await postgres_db.get_system_setting("admin.discovery_enabled")
    if row is None:
        return True
    value = row.get("value")
    if isinstance(value, dict):
        return bool(value.get("enabled", True))
    return bool(value)


async def _maybe_schedule_discovery(provider: str, api_key: str) -> None:
    """Clear the cache for a key and fire an async probe if applicable.

    The probe runs as a fire-and-forget task so the PUT route returns as
    quickly as today; the cockpit polls ``GET .../discovery`` to render
    the confirmation dialog when results land. Errors are swallowed by
    ``discover_models`` so a failed probe never blocks key-save.
    """
    if provider not in discovery_service.DISCOVERABLE_PROVIDERS:
        return
    if not await _discovery_enabled():
        return
    await postgres_db.set_system_api_key_discovery_cache(provider, None)

    async def _probe() -> None:
        candidates = await discovery_service.discover_models(provider, api_key)
        payload = discovery_service.build_cache_payload(provider, candidates)
        await postgres_db.set_system_api_key_discovery_cache(provider, payload)

    asyncio.create_task(_probe())


# =============================================================================
# Admin -> Prompts (DB-backed prompt overrides, v1)
# =============================================================================


def load_config_catalog() -> list[dict[str, Any]]:
    """Human-facing descriptions for editable prompt keys.

    Read from config/prompts/catalog.yaml (shipped with the image). Missing
    file -> empty list.
    """
    import yaml

    from src.core.loader import get_project_root

    path = get_project_root() / "config" / "prompts" / "catalog.yaml"
    if not path.exists():
        return []
    return yaml.safe_load(path.read_text()) or []


def _config_catalog_entry(kind: str, name: str) -> dict[str, Any] | None:
    for entry in load_config_catalog():
        if entry.get("kind") == kind and entry.get("name") == name:
            return entry
    return None


def validate_override_value(kind: str, name: str, value: Any) -> None:
    """Validate a structured (settings/guardrails) override value against the
    catalog. Raises HTTPException(422) on unknown key, wrong type, or out-of-bounds.

    Text kinds are validated by the Pydantic model (min_length) and are a no-op
    here. Fail-closed on write; reads stay fail-open (see the loader).
    """
    if kind not in ("settings", "guardrails"):
        return
    entry = _config_catalog_entry(kind, name)
    if entry is None:
        raise HTTPException(status_code=422, detail=f"unknown {kind} key: {name!r}")
    vtype = entry.get("type")
    if vtype in ("number", "integer"):
        # bool is a subclass of int — reject it for numeric leaves.
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise HTTPException(status_code=422, detail=f"{name} must be a {vtype}")
        if vtype == "integer" and isinstance(value, float) and not value.is_integer():
            raise HTTPException(status_code=422, detail=f"{name} must be an integer")
        lo, hi = entry.get("min"), entry.get("max")
        if lo is not None and value < lo:
            raise HTTPException(status_code=422, detail=f"{name} must be >= {lo}")
        if hi is not None and value > hi:
            raise HTTPException(status_code=422, detail=f"{name} must be <= {hi}")
    elif vtype == "boolean":
        if not isinstance(value, bool):
            raise HTTPException(status_code=422, detail=f"{name} must be a boolean")
    elif vtype == "enum":
        choices = entry.get("enum", [])
        if value not in choices:
            raise HTTPException(
                status_code=422, detail=f"{name} must be one of {choices}"
            )
    elif vtype == "json":
        if not isinstance(value, dict):
            raise HTTPException(status_code=422, detail=f"{name} must be a JSON object")
    # Unknown/absent type -> accept (forward-compatible with new catalog types).


def read_bundled_config(kind: str, family: str | None, name: str) -> Any:
    """Read the shipped (bundled) value for (kind, family, name), bypassing overrides.

    Returns text for prompts/instructions; the file-resolved value for settings
    (a single leaf) and guardrails (the {tool_examples, nudges} dict).
    """
    from src.core.loader import (
        InstructionMatrixResolver,
        PromptMatrixResolver,
        bundled_guardrails_for_family,
        bundled_settings_for_family,
    )

    if kind == "settings":
        return bundled_settings_for_family(family or "default", name)
    if kind == "guardrails":
        return bundled_guardrails_for_family(family or "default")

    resolver_cls = {
        "prompts": PromptMatrixResolver,
        "instructions": InstructionMatrixResolver,
    }.get(kind)
    if resolver_cls is None:
        raise HTTPException(status_code=400, detail=f"unknown kind: {kind!r}")
    resolver = resolver_cls(None, family or "default")
    try:
        return resolver.load(name, bundled_only=True)
    except FileNotFoundError:
        raise HTTPException(status_code=404, detail="no bundled default for that key")


