# Provider → env var mapping for system-level key detection
_PROVIDER_ENV_KEYS: dict[str, list[str]] = {
    "openai": ["OPENAI_API_KEY"],
    "anthropic": ["ANTHROPIC_API_KEY"],
    "google": ["GOOGLE_API_KEY"],
    "groq": ["GROQ_API_KEY"],
    "openrouter": ["OPENROUTER_API_KEY"],
    "mistral": ["MISTRAL_API_KEY"],
    "codex": ["CODEX_API_KEY"],
}


def _get_system_providers() -> set[str]:
    """Detect which providers have API keys set via environment variables."""
    providers: set[str] = set()
    for provider, env_vars in _PROVIDER_ENV_KEYS.items():
        if any(os.getenv(var) for var in env_vars):
            providers.add(provider)
    return providers


# Well-known label for the seeded codex-proxy llm_endpoints row. Kept in sync
# with orchestrator.init._seed_codex_proxy_endpoint — duplicated here to avoid
# importing init at runtime.
CODEX_PROXY_ENDPOINT_LABEL = "codex-proxy"


async def _get_codex_subscription_models() -> set[str]:
    """Fetch model IDs available through the Codex proxy subscription.

    Returns an empty set if the proxy is unreachable or has no active account.
    Uses a short timeout to avoid slowing down /api/models.
    """
    proxy_url = os.getenv("CODEX_PROXY_URL", "http://localhost:8317")
    try:
        async with httpx.AsyncClient(timeout=2.0) as client:
            resp = await client.get(f"{proxy_url}/v1/models")
        if resp.status_code == 200:
            data = resp.json()
            return {m["id"] if isinstance(m, dict) else m for m in data.get("data", [])}
    except Exception:
        pass
    return set()


@app.get("/api/models")
async def list_available_models(
    request: Request,
    project_id: str | None = None,
) -> dict[str, Any]:
    """List all models from the admin-curated catalog.

    Returns catalog rows grouped by provider/capability:

    - ``groups`` (chat-capability rows, grouped by provider)
    - ``auxiliary_models`` / ``vision_models`` / ``embedding_models`` /
      ``whisper_models`` / ``tts_models`` / ``search_models`` /
      ``fetch_models`` (one helper list per capability)

    Every row carries ``configured: true`` because the catalog only
    contains rows whose transport (system_api_keys row or system endpoint)
    is admin-managed. The legacy strategic+tactical preset bundle was
    removed in chunk 7 of the models_yaml_removal work — the job-create
    UX picks strategic and tactical models individually now.

    Query params:
        project_id: kept for backward compatibility — no longer affects the
            response shape now that the catalog is the source of truth.
    """
    await require_approved_user(request, postgres_db)
    _ = project_id  # accepted but unused post-flip

    # Catalog rows joined to transport (only enabled rows surface).
    catalog_rows = await postgres_db.list_models(enabled_only=True)
    system_endpoints = await postgres_db.list_system_llm_endpoints()
    endpoint_label_by_id: dict[str, str] = {
        str(e["id"]): e["label"] for e in system_endpoints
    }

    # Build (provider_kind, provider_ref) → group payload.
    groups_by_key: dict[tuple[str, str], dict[str, Any]] = {}
    auxiliary: list[dict[str, Any]] = []
    vision: list[dict[str, Any]] = []
    embedding: list[dict[str, Any]] = []
    whisper: list[dict[str, Any]] = []
    tts: list[dict[str, Any]] = []
    search: list[dict[str, Any]] = []
    fetch: list[dict[str, Any]] = []

    configured_providers: set[str] = set()

    for row in catalog_rows:
        kind = row["provider_kind"]
        ref = row["provider_ref"]
        # Fan-out: under the array model one row contributes to every
        # capability bucket it claims. A multimodal chat row registered as
        # ['chat','auxiliary','vision'] surfaces in the chat groups AND
        # auxiliary_models AND vision_models simultaneously — which is
        # exactly the operator intent (one physical model serves all three).
        capabilities_set = set(row.get("capabilities") or [])
        helper_entry = {
            "id": row["model_id"],
            "label": row["display_label"],
            "configured": True,
        }
        if "auxiliary" in capabilities_set:
            auxiliary.append(helper_entry)
        if "vision" in capabilities_set:
            vision.append(helper_entry)
        if "embedding" in capabilities_set:
            embedding.append(helper_entry)
        if "whisper" in capabilities_set:
            whisper.append(helper_entry)
        if "tts" in capabilities_set:
            tts.append(helper_entry)
        if "search" in capabilities_set:
            search.append(helper_entry)
        if "fetch" in capabilities_set:
            fetch.append(helper_entry)
        # Chat-only path: register the row in its provider group. Embedding-/
        # whisper-/tts-only rows skip this path so the chat dropdowns don't
        # show non-chat models.
        if "chat" not in capabilities_set:
            continue
        key = (kind, ref)
        group = groups_by_key.get(key)
        if group is None:
            if kind == "system":
                group_name = ref.title() if ref.islower() else ref
                provider_tag = ref
                configured_providers.add(ref)
                group = {
                    "group": group_name,
                    "provider": provider_tag,
                    "configured": True,
                    "models": [],
                }
            else:  # endpoint
                label = endpoint_label_by_id.get(ref, f"endpoint:{ref[:8]}")
                group = {
                    "group": f"System: {label}",
                    "provider": "system",
                    "endpoint_id": ref,
                    "configured": True,
                    "models": [],
                }
            groups_by_key[key] = group
        group["models"].append(row["model_id"])

    groups = list(groups_by_key.values())

    # Per-model reasoning capability (family-derived) so the Cockpit reasoning
    # control is driven by the catalog instead of hardcoded client logic. The
    # single source of truth is config/model_config_matrix.yaml's `reasoning`
    # block per family. See knowledge-base/knowledge/features/family_centered_reasoning.md.
    from src.core.loader import reasoning_capability

    reasoning_by_model: dict[str, dict[str, Any]] = {}
    for group in groups:
        for mid in group["models"]:
            if mid in reasoning_by_model:
                continue
            cap = reasoning_capability(mid)
            reasoning_by_model[mid] = {
                "method": cap.get("method", "none"),
                "default": cap.get("default"),
                "options": list(cap.get("options") or []),
            }

    return {
        "groups": groups,
        "auxiliary_models": auxiliary,
        "vision_models": vision,
        "whisper_models": whisper,
        "tts_models": tts,
        "search_models": search,
        "fetch_models": fetch,
        "embedding_models": embedding,
        "configured_providers": sorted(configured_providers),
        "reasoning_by_model": reasoning_by_model,
    }


@app.post("/api/models/reload")
async def reload_model_catalog(request: Request) -> dict[str, str]:
    """No-op kept for backward compat with cockpit clients that still POST.

    Catalog rows live in the DB and ``/api/models`` queries them fresh on
    every call — there is no cache to invalidate. The YAML fallback
    registry that this endpoint used to bounce was deleted in chunk 6;
    the legacy YAML projection cache it then bounced was deleted in
    chunk 7.
    """
    await _require_admin(request)
    return {"status": "reloaded"}


# =============================================================================
# Codex Proxy Management Endpoints (Admin-only)
# =============================================================================


async def _require_admin(request: Request) -> dict[str, Any]:
    """Require authenticated admin user.

    Checks ``real_is_admin`` (the un-shadowed privilege flag set by
    ``require_approved_user``) so admin-only endpoints stay reachable when
    the caller is in "view as user" mode. ``is_admin`` on the returned
    dict still reflects the shadow, so any downstream visibility check
    on the returned user dict honours the toggle.
    """
    user = await require_approved_user(request, postgres_db)
    if not user.get("real_is_admin", False):
        # A non-admin reaching an admin endpoint is the strongest single
        # probe signal we have — always leaves a security_events row.
        await log_security_event(
            postgres_db,
            event_type="admin_denied",
            user=user,
            resource_type="admin_endpoint",
            resource_id=getattr(getattr(request, "url", None), "path", None),
            detail="Admin access required",
            request=request,
        )
        raise HTTPException(status_code=403, detail="Admin access required")
    return user


async def _codex_proxy_request(
    method: str,
    path: str,
    **kwargs: Any,
) -> httpx.Response:
    """Make a request to the CLIProxyAPI management API.

    Reads CODEX_PROXY_URL and CODEX_MANAGEMENT_KEY from environment.
    Raises HTTPException on connection or upstream errors.
    """
    proxy_url = os.getenv("CODEX_PROXY_URL", "http://localhost:8317")
    mgmt_key = os.getenv("CODEX_MANAGEMENT_KEY", "")

    headers = kwargs.pop("headers", {})
    if mgmt_key:
        headers["Authorization"] = f"Bearer {mgmt_key}"

    timeout = kwargs.pop("timeout", 10.0)

    try:
        async with httpx.AsyncClient(timeout=timeout) as client:
            response = await client.request(
                method,
                f"{proxy_url}{path}",
                headers=headers,
                **kwargs,
            )
        if response.status_code >= 400:
            raise HTTPException(
                status_code=502,
                detail=f"Codex proxy returned {response.status_code}: {response.text[:200]}",
            )
        return response
    except HTTPException:
        raise
    except httpx.RequestError as e:
        raise HTTPException(
            status_code=502,
            detail=f"Codex proxy unreachable at {proxy_url}: {e}",
        ) from e


@app.get("/api/codex/status")
async def codex_status(request: Request) -> dict[str, Any]:
    """Get Codex proxy health and authentication status (admin-only)."""
    await _require_admin(request)

    try:
        auth_resp = await _codex_proxy_request("GET", "/v0/management/auth-files")
        auth_files = auth_resp.json()
    except HTTPException:
        # Proxy unreachable — the codex-proxy deployment is disabled or down.
        # `reachable: False` lets the cockpit show an "enable it" disclaimer
        # instead of a Connect button that would 502 on /api/codex/login.
        return {
            "connected": False,
            "reachable": False,
            "accounts": [],
            "model_count": 0,
        }

    # Normalize: auth-files may return a list or a dict with a key
    accounts = (
        auth_files if isinstance(auth_files, list) else auth_files.get("files", [])
    )
    active = [a for a in accounts if not a.get("disabled") and not a.get("unavailable")]

    model_count = 0
    try:
        models_resp = await _codex_proxy_request("GET", "/v1/models")
        models_data = models_resp.json()
        model_count = len(models_data.get("data", []))
    except HTTPException:
        pass

    # Wire-up after a local login: the proxy's callback runs on localhost:1455
    # so the orchestrator never sees /api/codex/callback for this flow. The
    # cockpit hits /api/codex/status as soon as polling reports success, so
    # ensure the transport row here when we see ≥1 active subscription.
    if len(active) > 0:
        try:
            await ensure_codex_proxy_endpoint(postgres_db)
        except Exception:
            logger.warning(
                "codex_status: ensure_codex_proxy_endpoint failed", exc_info=True
            )

    return {
        "connected": len(active) > 0,
        "reachable": True,
        "accounts": [
            {
                "name": a.get("name", "unknown"),
                "status": a.get("status", "unknown"),
                "status_message": a.get("status_message"),
            }
            for a in accounts
        ],
        "model_count": model_count,
    }


@app.get("/api/codex/models")
async def codex_models(request: Request) -> dict[str, Any]:
    """List models available through the Codex proxy (admin-only)."""
    await _require_admin(request)

    resp = await _codex_proxy_request("GET", "/v1/models")
    data = resp.json()
    models = [m.get("id", m) for m in data.get("data", [])]
    return {"models": models}


# ChatGPT backend usage endpoint — the authoritative Codex subscription
# rate-limit windows (5h + weekly), the same source the codex CLI's /status
# polls. Not exposed by the proxy (it 404s /wham/usage), so the orchestrator
# fetches it directly with the account's OAuth token.
CODEX_WHAM_USAGE_URL = "https://chatgpt.com/backend-api/wham/usage"


def _decode_jwt_claims(token: str) -> dict[str, Any]:
    """Best-effort decode of a JWT payload (no signature check — we only read
    the non-secret account-scoping claim from a token we already hold)."""
    import base64

    try:
        payload = token.split(".")[1]
        payload += "=" * (-len(payload) % 4)
        return json.loads(base64.urlsafe_b64decode(payload))
    except Exception:
        return {}


def _chatgpt_account_id(auth_file: dict[str, Any]) -> Optional[str]:
    """Pull the ChatGPT account id from a downloaded codex auth file's id_token
    (``https://api.openai.com/auth.chatgpt_account_id``). wham/usage wants it in
    the ``ChatGPT-Account-Id`` header."""
    claims = _decode_jwt_claims(auth_file.get("id_token", "") or "")
    auth = claims.get("https://api.openai.com/auth", {}) or {}
    return auth.get("chatgpt_account_id") or claims.get("chatgpt_account_id")


def _codex_usage_window(w: Any) -> Optional[dict[str, Any]]:
    """Normalize a wham/usage rate-limit window to the cockpit's shape."""
    if not isinstance(w, dict):
        return None
    return {
        "used_percent": w.get("used_percent"),
        "window_seconds": w.get("limit_window_seconds"),
        "reset_after_seconds": w.get("reset_after_seconds"),
        "reset_at": w.get("reset_at"),
    }


async def _fetch_codex_usage() -> Optional[dict[str, Any]]:
    """Fetch Codex subscription rate-limit windows from the ChatGPT backend.

    Path: management API ``auth-files`` → pick the active account → download its
    token → call ChatGPT ``wham/usage`` with ``Bearer`` + ``ChatGPT-Account-Id``.
    The OAuth token never leaves the orchestrator (only the aggregate percentages
    reach the UI). Returns ``None`` (→ endpoint degrades to ``available: false``)
    when the proxy is unreachable, no account is active, or the backend call
    fails — including the case where the orchestrator lacks chatgpt.com egress.
    """
    try:
        auth_resp = await _codex_proxy_request("GET", "/v0/management/auth-files")
        files = auth_resp.json()
    except HTTPException:
        return None
    accounts = files if isinstance(files, list) else files.get("files", [])
    active = next(
        (
            a
            for a in accounts
            if str(a.get("disabled")).lower() != "true"
            and str(a.get("unavailable")).lower() != "true"
        ),
        None,
    )
    name = (active or {}).get("name") or (active or {}).get("id")
    if not name:
        return None

    try:
        dl = await _codex_proxy_request(
            "GET", "/v0/management/auth-files/download", params={"name": name}
        )
        token_file = dl.json()
    except HTTPException:
        return None
    access_token = token_file.get("access_token")
    if not access_token:
        return None
    account_id = _chatgpt_account_id(token_file)

    headers = {
        "Authorization": f"Bearer {access_token}",
        "User-Agent": "srw-codex-usage/1.0",
    }
    if account_id:
        headers["ChatGPT-Account-Id"] = account_id
    try:
        async with httpx.AsyncClient(timeout=10.0) as client:
            resp = await client.get(CODEX_WHAM_USAGE_URL, headers=headers)
        if resp.status_code >= 400:
            logger.warning("codex wham/usage returned HTTP %s", resp.status_code)
            return None
        data = resp.json()
    except Exception:
        logger.warning("codex wham/usage fetch failed (non-fatal)", exc_info=True)
        return None

    rl = data.get("rate_limit") or {}
    per_model = [
        {
            "name": extra.get("limit_name"),
            "primary": _codex_usage_window(
                (extra.get("rate_limit") or {}).get("primary_window")
            ),
            "secondary": _codex_usage_window(
                (extra.get("rate_limit") or {}).get("secondary_window")
            ),
        }
        for extra in (data.get("additional_rate_limits") or [])
    ]
    credits = data.get("credits") or {}
    return {
        "account": data.get("email"),
        "plan_type": data.get("plan_type"),
        "limit_reached": bool(rl.get("limit_reached")),
        "primary": _codex_usage_window(rl.get("primary_window")),
        "secondary": _codex_usage_window(rl.get("secondary_window")),
        "per_model": per_model,
        "credits": {
            "has_credits": bool(credits.get("has_credits")),
            "unlimited": bool(credits.get("unlimited")),
            "balance": credits.get("balance"),
        }
        if credits
        else None,
    }


@app.get("/api/codex/usage")
async def codex_usage(request: Request) -> dict[str, Any]:
    """Codex subscription usage/limits (admin-only): the ChatGPT 5-hour + weekly
    rate-limit windows behind the codex proxy, for the cockpit capacity bars.

    Non-fatal: returns ``{"available": false}`` when the proxy is disabled/down,
    no account is connected, or the ChatGPT backend call fails.
    """
    await _require_admin(request)
    usage = await _fetch_codex_usage()
    if usage is None:
        return {"available": False}
    return {"available": True, **usage}


@app.post("/api/codex/login")
async def codex_login(request: Request) -> dict[str, Any]:
    """Initiate Codex OAuth login flow (admin-only).

    Returns an auth URL to open in the browser and a state token for polling.
    """
    await _require_admin(request)

    resp = await _codex_proxy_request(
        "GET",
        "/v0/management/codex-auth-url",
        params={"is_webui": "true"},
        timeout=15.0,
    )
    data = resp.json()
    # Proxy returns "url"; cockpit expects "auth_url"
    if "url" in data and "auth_url" not in data:
        data["auth_url"] = data.pop("url")
    return data


@app.get("/api/codex/login/poll")
async def codex_login_poll(request: Request, state: str) -> dict[str, Any]:
    """Poll Codex OAuth login status (admin-only)."""
    await _require_admin(request)

    resp = await _codex_proxy_request(
        "GET",
        "/v0/management/get-auth-status",
        params={"state": state},
    )
    return resp.json()


@app.post("/api/codex/callback")
async def codex_callback(
    body: CodexCallbackRequest, request: Request
) -> dict[str, Any]:
    """Relay an OAuth callback to the Codex proxy (admin-only).

    Accepts the full localhost callback URL (or explicit code+state).
    Parses the authorization code and state, then relays the callback
    to the proxy internally so no port-forward is needed.
    """
    await _require_admin(request)

    code = body.code
    state = body.state

    if body.url:
        parsed = urlparse(body.url)
        qs = parse_qs(parsed.query)
        code = code or (qs.get("code", [None])[0])
        state = state or (qs.get("state", [None])[0])

    if not code or not state:
        raise HTTPException(
            status_code=422,
            detail="Could not extract 'code' and 'state' from the provided URL. "
            "Please paste the complete URL from your browser address bar.",
        )

    resp = await _codex_proxy_request(
        "GET",
        "/codex/callback",
        params={"code": code, "state": state},
        timeout=15.0,
    )

    # OAuth completed — wire the codex-proxy as a system endpoint so the
    # subscription is immediately selectable in Admin → Models. Idempotent;
    # best-effort: a wiring failure must not block the callback response.
    try:
        await ensure_codex_proxy_endpoint(postgres_db)
    except Exception:
        logger.warning(
            "codex_callback: ensure_codex_proxy_endpoint failed", exc_info=True
        )

    if resp.content:
        return resp.json()
    return {"status": "ok"}


@app.delete("/api/codex/credentials/{name}")
async def codex_delete_credential(name: str, request: Request) -> dict[str, str]:
    """Remove a Codex proxy credential file (admin-only)."""
    await _require_admin(request)

    await _codex_proxy_request(
        "DELETE",
        "/v0/management/auth-files",
        params={"name": name},
    )
    return {"status": "deleted"}


# =============================================================================
# System Settings — Main Cloud (Phase 4, Admin-only)
# =============================================================================
# These endpoints drive the cockpit admin "Cloud Storage" panel. GETs
# return the current immutable instance snapshot with secrets stripped, PUT
# remotely attests and CAS-activates a new instance, and POST /test does a
# dry-run connection check without persisting.
#
# Secret handling: non-secret fields (URLs, usernames, quota) are stored
# in the `value` JSONB column. Secret fields (passwords, client secrets)
# are referenced via `credentials_ref` — a pointer like
# `env:OPENCLOUD_KEYCLOAK_CLIENT_SECRET` that the loader resolves against
# the orchestrator's own environment. This keeps secrets in Vault/ESO/.env
# and lets the UI manage only the non-secret knobs.

_MAIN_CLOUD_NONSECRET_FIELDS_BY_BACKEND: dict[str, list[str]] = {
    "nextcloud": [
        "base_url",
        "public_url",
        "admin_user",
        "agent_user",
    ],
    "opencloud": [
        "base_url",
        "public_url",
        "keycloak_issuer",
        "keycloak_client_id",
        "admin_role_claim_value",
        "default_quota_bytes",
    ],
}

_MAIN_CLOUD_SECRET_FIELDS_BY_BACKEND: dict[str, list[str]] = {
    "nextcloud": ["admin_password", "agent_password", "oidc_client_secret"],
    "opencloud": ["keycloak_client_secret"],
}

_MAIN_CLOUD_ALLOWED_BACKENDS = {"nextcloud", "opencloud"}


def _sanitize_main_cloud_value(
    backend_id: str, raw_value: dict[str, Any]
) -> dict[str, Any]:
    """Strip unknown keys + secret fields from an incoming overlay body.

    Secrets are never stored in JSONB — they always come from env vars
    resolved via `credentials_ref`. The sanitizer drops any secret-field
    key from the incoming dict so a careless UI PUT cannot accidentally
    persist a client secret into `system_settings.value`.
    """
    nonsecret = _MAIN_CLOUD_NONSECRET_FIELDS_BY_BACKEND.get(backend_id, [])
    secret = set(_MAIN_CLOUD_SECRET_FIELDS_BY_BACKEND.get(backend_id, []))
    clean: dict[str, Any] = {"backend_id": backend_id}
    for key in nonsecret:
        if key in raw_value and raw_value[key] not in (None, ""):
            clean[key] = raw_value[key]
    # Record which fields are secret-credential-sourced so the loader
    # knows to resolve them via credentials_ref at read time.
    if secret:
        clean["__secret_fields__"] = sorted(secret)
    return clean


def _current_effective_config() -> dict[str, Any]:
    """Read the active backend's current config shape for GET responses."""
    active = main_cloud_router.active
    backend_id = active.backend_id
    result: dict[str, Any] = {
        "backend_id": backend_id,
        "backend_instance_id": active.backend_instance_id,
        "is_initialized": active.is_initialized,
        "is_configured": active.is_configured,
    }

    # Non-secret fields come directly from the backend's settings where
    # possible. NextcloudBackend reads env vars into private attrs;
    # OpenCloudBackend holds a full settings dataclass.
    if backend_id == "nextcloud":
        # Attributes follow the adapter's internal names.
        result.update(
            {
                "base_url": getattr(active, "_base_url", None),
                "public_url": getattr(active, "_public_url", None),
                "admin_user": getattr(active, "_admin_user", None),
                "agent_user": getattr(active, "_agent_user", None),
            }
        )
    elif backend_id == "opencloud":
        settings = getattr(active, "_settings", None)
        if settings is not None:
            result.update(
                {
                    "base_url": str(settings.base_url),
                    "public_url": str(settings.public_url),
                    "keycloak_issuer": str(settings.keycloak_issuer),
                    "keycloak_client_id": settings.keycloak_client_id,
                    "admin_role_claim_value": settings.admin_role_claim_value,
                    "default_quota_bytes": settings.default_quota_bytes,
                }
            )
    return result


def _env_var_provenance(env_name: str) -> dict[str, Any]:
    """Report whether a secret env var is set, without leaking its value."""
    val = os.getenv(env_name)
    return {
        "env_var": env_name,
        "set": bool(val),
    }


@app.get("/api/admin/system-settings/main_cloud")
async def get_main_cloud_settings(request: Request) -> dict[str, Any]:
    """Return the current effective main-cloud config + persisted overlay.

    Admin-only. The response is safe to log: every secret field is
    replaced with its env-var provenance (name + set/unset flag + length).
    """
    await _require_admin(request)
    effective = _current_effective_config()

    try:
        active_row = await postgres_db.get_active_main_cloud_backend_instance()
    except Exception:
        active_row = None
    authority = active_row.get("authority") if isinstance(active_row, dict) else None
    overlay_value: dict[str, Any] = {}
    overlay_updated_at: Optional[str] = None
    credentials_ref: Optional[str] = None
    activation_revision = 0
    secret_refs: dict[str, str] = {}
    if authority is not None:
        overlay_value = authority.routing
        secret_refs = authority.secret_refs
        overlay_value["__secret_fields__"] = sorted(secret_refs)
        distinct_refs = set(secret_refs.values())
        if len(distinct_refs) == 1:
            credentials_ref = next(iter(distinct_refs))
        activated_at = active_row.get("activated_at")
        overlay_updated_at = (
            activated_at.isoformat() if activated_at is not None else None
        )
        activation_revision = int(active_row.get("activation_revision") or 0)
        effective.update(authority.routing)
        effective["backend_instance_id"] = authority.backend_instance_id

    secret_provenance: dict[str, dict[str, Any]] = {}
    for field, reference in secret_refs.items():
        secret_provenance[field] = _env_var_provenance(reference.removeprefix("env:"))

    return {
        "effective": effective,
        "activation_revision": activation_revision,
        "backend_instance": (
            {
                "id": authority.backend_instance_id,
                "routing_sha256": authority.routing_sha256,
                "installation_proof_sha256": (authority.installation_proof_sha256),
                "secret_revision": authority.secret_revision,
            }
            if authority is not None
            else None
        ),
        "overlay": {
            # Compatibility name for the existing Cockpit form. This is the
            # immutable active routing snapshot, not system_settings authority.
            "present": authority is not None,
            "value": overlay_value,
            "credentials_ref": credentials_ref,
            "updated_at": overlay_updated_at,
            "updated_by": None,
        },
        "secrets": secret_provenance,
        "allowed_backends": sorted(_MAIN_CLOUD_ALLOWED_BACKENDS),
    }


@app.put("/api/admin/system-settings/main_cloud")
async def put_main_cloud_settings(
    body: dict[str, Any], request: Request
) -> dict[str, Any]:
    """Attest and CAS-activate a new main-cloud backend instance.

    Admin-only. The request body is ``{"value": {...}, "credentials_ref": "env:..."}``:

    * ``value.backend_id`` must be one of ``allowed_backends``.
    * Secret fields in ``value`` are silently dropped by the sanitizer —
      never persist secrets in the DB. Rotate via the secret store.
    * ``credentials_ref`` is an optional pointer (e.g. ``env:NEW_VAR``)
      that the loader resolves for secret fields at read time.
    * ``expected_activation_revision`` must match the GET snapshot.
    * Routing edits create a new immutable instance UUID. Secret-reference
      edits rotate only the exact same proven installation.
    * Other replicas resolve the durable pointer via the pg_notify LISTEN task.
    """
    admin = await _require_admin(request)

    value_in = body.get("value") or {}
    if not isinstance(value_in, dict):
        raise HTTPException(status_code=400, detail="`value` must be an object")
    backend_id = value_in.get("backend_id")
    if backend_id not in _MAIN_CLOUD_ALLOWED_BACKENDS:
        raise HTTPException(
            status_code=400,
            detail=(
                f"unknown backend_id {backend_id!r}; "
                f"must be one of {sorted(_MAIN_CLOUD_ALLOWED_BACKENDS)}"
            ),
        )
    credentials_ref = body.get("credentials_ref")
    if credentials_ref is not None and not isinstance(credentials_ref, str):
        raise HTTPException(
            status_code=400, detail="`credentials_ref` must be a string or null"
        )
    expected_activation_revision = body.get("expected_activation_revision")
    if (
        type(expected_activation_revision) is not int
        or expected_activation_revision < 0
    ):
        raise HTTPException(
            status_code=400,
            detail="`expected_activation_revision` must be a non-negative integer",
        )

    clean_value = _sanitize_main_cloud_value(backend_id, value_in)

    # Validate the proposed config before persisting — raises on
    # missing required fields so we fail fast with a 422-style message.
    from services.cloud.config import load_main_cloud_config, missing_secret_envs

    probe_overlay = {
        "value": clean_value,
        "credentials_ref": credentials_ref,
    }
    try:
        load_main_cloud_config(db_overlay=probe_overlay)
    except Exception as e:
        raise HTTPException(
            status_code=400, detail=f"invalid main cloud config: {e}"
        ) from e

    # Fail loud if the backend's real secrets are not wired (Issue 5). The
    # loader above validates the *shape* but silently substitutes built-in dev
    # defaults for missing secrets, so a config that could only ever connect
    # with `admin` / `agent-service-dev` would otherwise persist + activate and
    # fail much later at the first cloud call (surviving restarts). Refuse here,
    # naming the exact env var(s) to set.
    missing = missing_secret_envs(backend_id, probe_overlay)
    if missing:
        names = ", ".join(sorted({m["env_var"] for m in missing}))
        raise HTTPException(
            status_code=400,
            detail=(
                f"secret env not set for backend {backend_id!r}: {names}. "
                "Wire the secret(s) into the orchestrator env (Helm/Vault) or "
                "point `credentials_ref` at a set env var, then retry. Refusing "
                "to activate a backend that would fall back to built-in dev "
                "credentials."
            ),
        )

    actor = str(admin.get("id") or admin.get("email") or "admin")
    try:
        activated = await activate_main_cloud_config(
            postgres_db,
            main_cloud_router,
            db_overlay=probe_overlay,
            expected_activation_revision=expected_activation_revision,
            activated_by=actor,
        )
    except Exception as e:
        raise HTTPException(
            status_code=500,
            detail=(
                "main cloud backend attestation failed; no unverified adapter "
                f"was activated: {e}"
            ),
        ) from e
    if activated is None:
        raise HTTPException(
            status_code=409,
            detail=(
                "main cloud activation authority changed; reload the current "
                "settings and retry"
            ),
        )

    # Fan-out to other replicas via pg_notify. Best-effort.
    authority = activated["authority"]
    try:
        await postgres_db.delete_system_setting("main_cloud")
    except Exception:
        logger.warning(
            "Failed to remove inert legacy main_cloud setting after activation",
            exc_info=True,
        )
    await fire_reload(postgres_db, authority.backend_instance_id)
    return {
        "status": "ok",
        "backend_id": backend_id,
        "backend_instance_id": authority.backend_instance_id,
        "activation_revision": activated["activation_revision"],
        "reloaded": True,
    }


@app.post("/api/admin/system-settings/main_cloud/test")
async def test_main_cloud_settings(
    body: dict[str, Any], request: Request
) -> dict[str, Any]:
    """Dry-run a proposed main-cloud config without persisting.

    Builds a backend from the proposed overlay, calls
    ``ensure_initialized()``, and tears it down. Returns whether the
    probe succeeded plus a short detail string. Useful for "Test"
    buttons in the admin UI before the operator commits to saving.
    """
    await _require_admin(request)

    value_in = body.get("value") or {}
    backend_id = value_in.get("backend_id")
    if backend_id not in _MAIN_CLOUD_ALLOWED_BACKENDS:
        raise HTTPException(
            status_code=400,
            detail=f"unknown backend_id {backend_id!r}",
        )
    credentials_ref = body.get("credentials_ref")

    clean_value = _sanitize_main_cloud_value(backend_id, value_in)
    probe_overlay = {
        "value": clean_value,
        "credentials_ref": credentials_ref,
    }

    # Issue 5: surface unwired secrets as the precise reason, instead of letting
    # the probe connect with built-in dev credentials and report a cryptic
    # upstream-auth failure.
    from services.cloud.config import missing_secret_envs

    missing = missing_secret_envs(backend_id, probe_overlay)
    if missing:
        names = ", ".join(sorted({m["env_var"] for m in missing}))
        return {
            "ok": False,
            "detail": (
                f"secret env not set for backend {backend_id!r}: {names} "
                "(would fall back to built-in dev credentials). Wire the "
                "secret(s) or set `credentials_ref` before testing."
            ),
        }

    try:
        probe_backend = build_backend(db_overlay=probe_overlay)
    except Exception as e:
        return {"ok": False, "detail": f"build_backend failed: {e}"}

    try:
        try:
            ok = await probe_backend.ensure_initialized()
        except Exception as e:
            return {"ok": False, "detail": f"ensure_initialized raised: {e}"}
        if not ok:
            return {
                "ok": False,
                "detail": "backend reported not initialized — check config + upstream",
            }
        health = await probe_backend.health_check()
        return {
            "ok": health.ok,
            "detail": health.detail or "",
            "latency_ms": health.latency_ms,
        }
    finally:
        try:
            await probe_backend.close()
        except Exception:
            pass


@app.post("/api/admin/system-settings/main_cloud/reload")
async def reload_main_cloud_settings(request: Request) -> dict[str, Any]:
    """Force a local re-attestation of the durable active instance.

    Admin-only. Useful when an operator has rotated a secret out-of-band
    (new Keycloak client secret in .env) and wants this orchestrator
    replica to rebuild its client after an out-of-band secret-value update.
    The immutable secret reference and installation proof remain unchanged.
    """
    await _require_admin(request)
    try:
        ok = await reload_active_main_cloud_instance(
            postgres_db,
            main_cloud_router,
            force_rebuild=True,
        )
    except Exception as e:
        raise HTTPException(
            status_code=500, detail=f"active instance re-attestation failed: {e}"
        ) from e
    if ok is not True:
        raise HTTPException(
            status_code=409,
            detail="active instance changed during re-attestation; retry",
        )
    return {
        "status": "ok",
        "backend_id": main_cloud_router.active.backend_id,
        "backend_instance_id": main_cloud_router.active_instance_id,
    }


@app.post("/api/admin/system-settings/main_cloud/backfill-instance-authority")
async def backfill_main_cloud_instance_authority(
    request: Request, apply: bool = False
) -> dict[str, Any]:
    """Stamp pre-0186 rows with the installation they actually live on.

    Admin-only. **Dry run by default** — pass ``?apply=true`` to write.

    0186 added ``main_cloud_backend_instance_id`` nullable with no backfill, so
    rows stamped before it name a provider but no installation. The router
    fails closed on that shape, which is correct for effects: those projects
    cannot grant membership, share, or have their folder deleted, because we
    cannot say *which* installation to act on.

    This is deliberately NOT a SQL migration. The design
    (knowledge-base/knowledge/features/protected_session_lifecycle_and_mount_readiness.md)
    requires "an operator-attested single-installation mapping plus a verified
    remote proof", and a migration running inside psql at startup can obtain
    neither. Stamping without that proof would launder a guess into recorded
    authority — silently, permanently, and unquestioned by everything
    downstream. A loud refusal is recoverable; a wrong instance UUID is not.

    So the safety argument here is:

    1. the active instance is **re-attested against the live installation**
       before anything is read, so its proof reflects reality now;
    2. every provider named by an unstamped row must resolve to exactly one
       *installation* in the registry. Two registry rows for one provider are
       not automatically ambiguous — they are commonly two routing snapshots
       of the same installation, which share an
       ``installation_proof_sha256``. Two distinct **proofs** are the genuine
       ambiguity, and abort;
    3. a provider we cannot re-attest right now (not the active backend) is
       never stamped, because nothing proves where its rows live.
    """
    await _require_admin(request)

    survey = await postgres_db.survey_unstamped_main_cloud_rows()
    unstamped_projects = survey["projects"]
    unstamped_threads = survey["threads"]
    if not unstamped_projects and not unstamped_threads:
        return {
            "status": "noop",
            "applied": False,
            "detail": "No rows carry a provider without its backend instance.",
            "projects": 0,
            "threads": 0,
        }

    providers = sorted(
        {str(r["main_cloud_backend"]) for r in unstamped_projects}
        | {str(r["main_cloud_backend"]) for r in unstamped_threads}
    )

    # (1) Re-attest the active installation before trusting its proof.
    try:
        reattested = await reload_active_main_cloud_instance(
            postgres_db,
            main_cloud_router,
            force_rebuild=True,
        )
    except Exception as e:
        raise HTTPException(
            status_code=503,
            detail=f"cannot verify the live installation proof: {e}",
        ) from e
    if reattested is not True:
        raise HTTPException(
            status_code=409,
            detail="active instance changed during re-attestation; retry",
        )

    active = await postgres_db.get_active_main_cloud_backend_instance()
    if not active:
        raise HTTPException(
            status_code=409,
            detail="no active main-cloud instance to attest against",
        )
    active_authority = active["authority"]

    registry = await postgres_db.list_main_cloud_backend_instances()

    # (2)+(3) Resolve one installation per provider, or refuse.
    plan: list[dict[str, Any]] = []
    for provider in providers:
        proofs = {
            a.installation_proof_sha256 for a in registry if a.backend_id == provider
        }
        if len(proofs) != 1:
            raise HTTPException(
                status_code=409,
                detail=(
                    f"provider {provider!r} has {len(proofs)} distinct "
                    "installations in the registry; historical rows cannot be "
                    "attributed to one of them automatically. Resolve this "
                    "mapping by hand."
                ),
            )
        if provider != active_authority.backend_id:
            raise HTTPException(
                status_code=409,
                detail=(
                    f"provider {provider!r} is not the active backend "
                    f"({active_authority.backend_id!r}), so its installation "
                    "cannot be re-attested right now. Activate it first."
                ),
            )
        if proofs != {active_authority.installation_proof_sha256}:
            raise HTTPException(
                status_code=409,
                detail=(
                    f"provider {provider!r} registry proof does not match the "
                    "installation just attested; refusing to attribute "
                    "historical rows to it."
                ),
            )
        plan.append(
            {
                "backend_id": provider,
                "backend_instance_id": active_authority.backend_instance_id,
                "installation_proof_sha256": (
                    active_authority.installation_proof_sha256
                ),
                "projects": [
                    {
                        "id": str(r["id"]),
                        "name": r.get("name"),
                        "status": r.get("status"),
                    }
                    for r in unstamped_projects
                    if str(r["main_cloud_backend"]) == provider
                ],
                "threads": [
                    str(r["id"])
                    for r in unstamped_threads
                    if str(r["main_cloud_backend"]) == provider
                ],
            }
        )

    if not apply:
        return {
            "status": "dry_run",
            "applied": False,
            "detail": "Re-run with ?apply=true to write these stamps.",
            "plan": plan,
            "projects": len(unstamped_projects),
            "threads": len(unstamped_threads),
        }

    stamped = {"projects": 0, "threads": 0}
    for entry in plan:
        counts = await postgres_db.stamp_main_cloud_instance_authority(
            backend_id=entry["backend_id"],
            backend_instance_id=entry["backend_instance_id"],
        )
        stamped["projects"] += counts["projects"]
        stamped["threads"] += counts["threads"]
        logger.warning(
            "main-cloud instance authority backfill: stamped %d project(s) and "
            "%d thread(s) for provider %r with instance %s (proof %s)",
            counts["projects"],
            counts["threads"],
            entry["backend_id"],
            entry["backend_instance_id"],
            entry["installation_proof_sha256"],
        )

    return {
        "status": "ok",
        "applied": True,
        "plan": plan,
        "projects": stamped["projects"],
        "threads": stamped["threads"],
    }


@app.delete("/api/admin/system-settings/main_cloud")
async def delete_main_cloud_settings(request: Request) -> dict[str, Any]:
    """Attest and activate the current env-described installation.

    History is retained; reset never deletes an instance referenced by an
    existing project, session, grant, or staged review.
    """
    admin = await _require_admin(request)
    current = await postgres_db.get_active_main_cloud_backend_instance()
    expected_revision = (
        int(current.get("activation_revision") or 0) if isinstance(current, dict) else 0
    )
    try:
        activated = await activate_main_cloud_config(
            postgres_db,
            main_cloud_router,
            db_overlay=None,
            expected_activation_revision=expected_revision,
            activated_by=str(admin.get("id") or admin.get("email") or "admin"),
        )
    except Exception as e:
        raise HTTPException(
            status_code=500,
            detail=f"env-described main cloud attestation failed: {e}",
        ) from e
    if activated is None:
        raise HTTPException(
            status_code=409,
            detail="main cloud activation authority changed; reload and retry",
        )
    try:
        await postgres_db.delete_system_setting("main_cloud")
    except Exception:
        logger.warning(
            "Failed to remove inert legacy main_cloud setting", exc_info=True
        )
    authority = activated["authority"]
    await fire_reload(postgres_db, authority.backend_instance_id)
    return {
        "status": "ok",
        "existed": current is not None,
        "backend_id": authority.backend_id,
        "backend_instance_id": authority.backend_instance_id,
        "activation_revision": activated["activation_revision"],
    }


def _vm_workspaces_response(row: dict | None) -> dict[str, Any]:
    """Shape the vm_workspaces system_settings row for API responses."""
    value = (row or {}).get("value") or {}
    enabled = True
    if isinstance(value, dict) and value.get("enabled") is False:
        enabled = False
    updated_at = (row or {}).get("updated_at")
    return {
        "enabled": enabled,
        "updated_at": updated_at.isoformat() if updated_at is not None else None,
        "updated_by": (row or {}).get("updated_by"),
    }


