@app.patch("/api/admin/users/{user_id}")
async def admin_patch_user(
    user_id: str, body: AdminUserUpdate, request: Request
) -> dict[str, str]:
    """Toggle privileged user flags (admin-only).

    Accepts partial updates of ``can_use_vm`` and ``is_approved``. Setting
    ``is_approved=True`` admits the user and stamps ``approved_at``/
    ``approved_by``; setting it False is suspension — the flag flips off
    (effective on the user's next request) while ``approved_at`` is kept as
    history. Admin status is NOT settable here — it is owned by the Keycloak
    ``admin`` realm role (see ``AdminUserUpdate``).
    """
    admin = await _require_admin(request)
    approved_at = None
    approved_by = None
    if body.is_approved is True:
        approved_at = datetime.now(timezone.utc)
        approved_by = str(admin.get("id"))
    success = await postgres_db.update_user(
        user_id=user_id,
        can_use_vm=body.can_use_vm,
        is_approved=body.is_approved,
        approved_at=approved_at,
        approved_by=approved_by,
    )
    if not success:
        raise HTTPException(status_code=404, detail=f"User '{user_id}' not found")
    if body.is_approved is True:
        # Admission just granted — provision cloud/Gitea from the row. The JIT
        # ensures are gated on approval and never re-fire for an app-side
        # approved user, so this is their provisioning path. Idempotent.
        row = await postgres_db.get_user(user_id)
        if row:
            await ensure_user_provisioned(row)
    return {"status": "updated"}


@app.post("/api/admin/users/approve")
async def admin_bulk_approve_users(
    body: AdminBulkApprove, request: Request
) -> dict[str, Any]:
    """Bulk-approve pending users (admin-only).

    Stamps approval on every id that resolves to a real row in a single
    transaction and reports per-id status. This is the workflow Keycloak's
    console can't do (no bulk role assignment). Ids that don't match an
    existing user come back as ``not_found`` rather than failing the batch.
    """
    admin = await _require_admin(request)
    approved_ids = await postgres_db.approve_users(
        body.user_ids, approved_by=str(admin.get("id"))
    )
    # Provision cloud/Gitea for each newly-approved user (idempotent; the JIT
    # ensures never re-fire for app-side approvals).
    for uid in approved_ids:
        row = await postgres_db.get_user(uid)
        if row:
            await ensure_user_provisioned(row)
        # Every admin's "new user pending approval" row is settled by whoever
        # approved (D6: resolution is a property of the source).
        await notification_service.resolve_source(
            "user", str(uid), resolved_by=f"user:{admin.get('id')}"
        )
    approved_set = set(approved_ids)
    results = [
        {"id": uid, "status": "approved" if uid in approved_set else "not_found"}
        for uid in body.user_ids
    ]
    return {"approved_count": len(approved_set), "results": results}


@app.get("/api/admin/security-events")
async def admin_list_security_events(
    request: Request,
    limit: int = 100,
    user_id: Optional[str] = None,
    event_type: Optional[str] = None,
    since: Optional[str] = None,
) -> dict[str, Any]:
    """List denied-access security events, newest first (admin-only).

    The read path for the cross-user 403 audit log — every 403 raised by
    a ``security/access.py`` gate (plus admin-gate and IDE-proxy denials)
    lands in ``security_events``. Filters: ``user_id`` (the denied
    caller), ``event_type`` (``access_denied`` / ``admin_denied``),
    ``since`` (ISO 8601). Rows are pruned on retention
    (``SECURITY_EVENTS_RETENTION_DAYS``, default 90). Design:
    knowledge-base/knowledge/features/security_event_log.md.
    """
    await _require_admin(request)
    since_dt: Optional[datetime] = None
    if since:
        try:
            since_dt = datetime.fromisoformat(since)
        except ValueError:
            raise HTTPException(
                status_code=400, detail="'since' must be an ISO 8601 timestamp"
            )
    events = await postgres_db.list_security_events(
        limit=limit,
        user_id=user_id,
        event_type=event_type,
        since=since_dt,
    )
    return {"events": events, "count": len(events)}


# =============================================================================
# Project Endpoints
# =============================================================================


# Per-project locks prevent concurrent heal attempts from creating duplicate
# Spaces (ensure_project_folder is not idempotent — each call makes a new drive).
_project_heal_locks: dict[str, asyncio.Lock] = {}

# Fire-and-forget repair tasks spawned off the project-GET read path (see
# knowledge-base/knowledge/issues/project_page_open_blocks_on_cloud_heal.md part 1). The task set
# holds strong references (bare create_task results are GC-able); the
# last-fired map throttles per key so page views don't hammer Keycloak/the
# cloud backend. Both are bounded by the number of live projects/users.
_bg_repair_tasks: set[asyncio.Task] = set()
_bg_repair_last: dict[str, float] = {}
_BG_REPAIR_COOLDOWN_S = 3600.0


def _fire_background_repair(key: str, coro: Coroutine[Any, Any, Any]) -> bool:
    """Run ``coro`` as a fire-and-forget task, at most once per cooldown per key.

    Returns True if the task was scheduled, False if throttled (the coroutine
    is closed so it never warns "never awaited").
    """
    now = time.monotonic()
    last = _bg_repair_last.get(key)
    if last is not None and now - last < _BG_REPAIR_COOLDOWN_S:
        coro.close()
        return False
    _bg_repair_last[key] = now
    task = asyncio.create_task(coro)
    _bg_repair_tasks.add(task)
    task.add_done_callback(_bg_repair_tasks.discard)
    return True


async def _sync_project_member_to_groups(
    project_id_str: str,
    group_name: str,
    user: dict[str, Any],
    backend: Any,
) -> None:
    """Add one member to the Keycloak group and the LibreGraph group.

    Both writes are needed: Keycloak carries the `groups` token claim (durable
    across OpenCloud re-logins), the direct backend add makes the Space visible
    in the user's currently-active OpenCloud session without waiting for them
    to re-authenticate.
    """
    if keycloak_groups.is_initialized and user.get("keycloak_sub"):
        await keycloak_groups.add_user_to_project_group(
            user["keycloak_sub"], project_id_str
        )
    if backend.is_initialized:
        try:
            resolved = await resolve_user_identity_cached(postgres_db, user, backend)
            if resolved:
                await backend.add_user_to_group(resolved, group_name)
        except Exception as e:
            logger.debug(
                f"Failed to add user {user.get('id')} to backend group "
                f"{group_name}: {e}"
            )


async def _ensure_project_cloud_resources(
    project: dict[str, Any],
) -> dict[str, Any]:
    """Ensure a project has its Keycloak group, main-cloud Space and WebDAV
    datasource — and that every current member is in both groups.

    Two conditional steps:

    * **Folder creation** runs only when `main_cloud_folder_handle` is missing
      (protected by a per-project lock because `ensure_project_folder` is not
      idempotent — each call creates a new Space).
    * **Member sync** runs unconditionally (the Keycloak and LibreGraph adds
      are idempotent). This repairs the common case where the Space already
      exists but the user was never added to the groups — e.g. project created
      while Keycloak admin auth was broken, or a Space adopted out-of-band.
      Primary membership writes happen at mutation time (add_project_member);
      this is pure drift repair, which is why get_project runs it as a
      throttled background task rather than on the request path (it costs
      several external HTTP round-trips — see
      knowledge-base/knowledge/issues/project_page_open_blocks_on_cloud_heal.md).

    Default projects skip both: they piggyback on the owner's personal home
    Space (already attached as a datasource by the user-creation flow), so a
    separate project Space + `project-<id>` group would be dead state. The
    cloud_storage_url branch in `get_project` resolves to the user's home
    browser URL for default projects.

    Returns the (possibly updated) project dict.
    """
    if project.get("is_default"):
        return project

    project_id_str = str(project["id"])
    project_name = project["name"]
    group_name = f"project-{project_id_str}"
    if project.get("main_cloud_backend"):
        backend = main_cloud_router.for_project_optional(project)
        if backend is None:
            # Every step below is a remote effect (ensure_group,
            # ensure_project_folder, LibreGraph member adds) and this row's
            # installation authority is unresolvable — a pre-0186 row, or an
            # instance this replica has not cached. Guessing an installation is
            # exactly what we must not do, and this helper is drift repair, not
            # a primary write path (add_project_member owns those). So skip,
            # loudly. Stamping the row (backfill) is what re-enables it.
            logger.warning(
                "Project %s: skipping cloud resource heal — no resolvable "
                "backend instance for provider %r (row needs a "
                "main_cloud_backend_instance_id backfill).",
                project_id_str,
                project.get("main_cloud_backend"),
            )
            return project
    else:
        backend = main_cloud_router.for_owner()

    handle_str = project.get("main_cloud_folder_handle")
    legacy_folder_id = project.get("nextcloud_folder_id")
    needs_folder = not (handle_str or legacy_folder_id)

    if needs_folder and backend.is_initialized:
        lock = _project_heal_locks.setdefault(project_id_str, asyncio.Lock())
        async with lock:
            fresh = await postgres_db.get_project(project_id_str)
            if fresh:
                project = fresh
            if not (
                project.get("main_cloud_folder_handle")
                or project.get("nextcloud_folder_id")
            ):
                try:
                    if keycloak_groups.is_initialized:
                        await keycloak_groups.ensure_project_group(
                            project_id_str, project_name
                        )
                    await backend.ensure_group(group_name)
                    folder_handle = await backend.ensure_project_folder(
                        project_name=project_name,
                        group_id=group_name,
                    )
                    legacy_id: int | None = None
                    if backend.backend_id == "nextcloud":
                        try:
                            legacy_id = int(folder_handle.native_id)
                        except ValueError:
                            legacy_id = None
                    await postgres_db.update_project(
                        project_id_str,
                        main_cloud_backend=backend.backend_id,
                        main_cloud_backend_instance_id=(backend.backend_instance_id),
                        main_cloud_folder_handle=folder_handle.to_db(),
                        nextcloud_folder_id=legacy_id,
                    )
                    project["main_cloud_backend"] = backend.backend_id
                    project["main_cloud_backend_instance_id"] = (
                        backend.backend_instance_id
                    )
                    project["main_cloud_folder_handle"] = folder_handle.to_db()
                    project["nextcloud_folder_id"] = legacy_id

                    # The project working folder is intentionally NOT attached
                    # as a `webdav` datasource: job/session workspaces get the
                    # folder cloned in (Mode-A baseline for jobs, the `projects/`
                    # sync mount for sessions), so attaching it here would
                    # double-expose the same files through the webdav_* tools.
                    # webdav_* tools are reserved for clouds that are NOT cloned
                    # (the personal home cloud + externally-attached WebDAV).
                    # See knowledge-base/knowledge/issues/main_cloud.md (Issue 1 / Issue 8).
                except Exception as e:
                    logger.warning(
                        f"Failed to create cloud resources for project "
                        f"{project_id_str}: {e}"
                    )

    # Member sync — always runs when this helper does. Idempotent add in both
    # Keycloak and the backend; essential for self-healing projects whose
    # Space exists but whose members were never added to the groups. Callers
    # keep it off latency-sensitive paths (_fire_background_repair).
    if keycloak_groups.is_initialized or backend.is_initialized:
        try:
            if keycloak_groups.is_initialized:
                await keycloak_groups.ensure_project_group(project_id_str, project_name)
            members = await postgres_db.get_project_members(project_id_str)
            if members:
                users = await asyncio.gather(
                    *[postgres_db.get_user(str(m["user_id"])) for m in members],
                    return_exceptions=False,
                )
                await asyncio.gather(
                    *[
                        _sync_project_member_to_groups(
                            project_id_str, group_name, u, backend
                        )
                        for u in users
                        if u
                    ],
                    return_exceptions=True,
                )
        except Exception as e:
            logger.debug(f"Member sync failed for project {project_id_str}: {e}")

    return project


async def _provision_project_knowledge_repo(
    project: dict[str, Any], owner_id: str | None
) -> dict[str, Any] | None:
    """Create the project's knowledge repo and attach it as its own KB.

    Two artifacts, in this order:

    * ``project-<id8>-knowledge`` registered with role ``knowledge`` — the
      vault ``resolve_kb_repo`` prefers from now on, and the repo the
      materialisation endpoint commits notes into.
    * a ``kb`` datasource linked to the project — the design's
      "default-attached datasource" (§6). It is a **management surface**:
      something to see, list and unlink in the cockpit. It is *not* an index
      of its own. Its notes are indexed under ``kb_id = project_id`` by the
      native sweep, which is why the row carries the ``native_project_id``
      marker: without it the external sweep would index the same vault a
      second time under this row's UUID and every note would come back twice
      in search (§8, criterion 5).

    ``connection_url`` is deliberately left null. Managed URLs are now
    credential-free, but the connector is not repository transport authority;
    a second copy of "where the vault lives" is exactly the divergence §10
    warns about. ``project_repositories`` remains the one authoritative answer.

    Returns the created datasource row, or None when Gitea refused the repo.
    """
    from services.kb_datasources import NATIVE_PROJECT_CONFIG_KEY

    project_id = str(project["id"])
    id8 = project_id[:8]
    repo_name = f"project-{id8}-knowledge"
    repository_id = str(uuid4())

    try:
        repo_url, _creation_intent = await create_managed_repository(
            postgres_db,
            gitea_client,
            repo_name=repo_name,
            authority_kind="project_repository",
            authority_id=repository_id,
            project_id=project_id,
            access_mode="none",
        )
    except ManagedRepositoryAuthorityError:
        logger.warning(
            "Gitea did not create knowledge repo '%s'; project %s has no "
            "file-backed vault until provisioning is retried",
            repo_name,
            project_id,
        )
        return None

    await postgres_db.add_project_repository(
        project_id=project_id,
        repository_id=repository_id,
        name=repo_name,
        repo_url=repo_url,
        role="knowledge",
        description="Project knowledge vault (OKF notes under knowledge/)",
        is_managed=True,
    )
    if owner_id:
        try:
            creator = await postgres_db.get_user(owner_id)
            if creator and creator.get("email"):
                await gitea_client.grant_user_repo_access(creator["email"], repo_name)
        except Exception as e:
            logger.warning(
                f"Failed to grant Gitea access for project creator on "
                f"knowledge repo: {e}"
            )

    # Names are unique per (name, type, owner), so the id8 keeps two projects
    # with the same title from colliding on their KB connectors.
    datasource = await postgres_db.create_datasource(
        name=f"{project['name']} Knowledge ({id8})",
        ds_type="kb",
        connection_url=None,
        description=(
            f"This project's knowledge base, stored in `{repo_name}`. "
            "Notes written with kb_write land here."
        ),
        config={"root_path": "knowledge", NATIVE_PROJECT_CONFIG_KEY: project_id},
        created_by=owner_id,
        read_only=True,
        scope_mode="projects",
        auto_attach=True,
        project_ids=[project_id],
    )
    logger.info(
        "Provisioned knowledge repo '%s' + KB connector %s for project %s",
        repo_name,
        datasource["id"],
        project_id,
    )
    return datasource


@dataclass(frozen=True, repr=False)
class _KbVaultPlan:
    """A validated live-vault target, ready to provision.

    It carries the PAT, so it stays local to the provisioning call: never
    logged, never returned (hence the suppressed repr). ``datasource_id`` set
    means an existing connector is being adopted in place instead of a new row
    being created for the same repository.
    """

    repo_url: str
    branch: str
    forge: str
    owner: str
    repo: str
    credentials: dict[str, str]
    explicit_forge: bool
    datasource_id: str | None = None
    policy_revision: int = 0


def _kb_vault_plan(
    repo_url: str | None,
    branch: str,
    credentials: dict[str, str],
    forge_override: str | None,
    *,
    datasource_id: str | None = None,
    policy_revision: int = 0,
) -> _KbVaultPlan:
    """Validate a writable-vault target's URL, transport auth and forge."""
    from src.services.forge import ForgeError, parse_owner_repo

    validated_url = _validate_kb_repository_url(repo_url)
    _validate_kb_repository_auth(validated_url, credentials)

    host = (urlparse(validated_url).hostname or "").lower().rstrip(".")
    explicit = forge_override is not None
    forge = forge_override or (
        "github" if host in {"github.com", "www.github.com"} else ""
    )
    if forge != "github":
        raise HTTPException(
            status_code=400,
            detail=(
                "External writable project KBs currently support GitHub only; "
                "set forge='github' for GitHub Enterprise"
            ),
        )
    try:
        owner, repo = parse_owner_repo(validated_url)
    except ForgeError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    return _KbVaultPlan(
        repo_url=validated_url,
        branch=branch,
        forge=forge,
        owner=owner,
        repo=repo,
        credentials=credentials,
        explicit_forge=explicit,
        datasource_id=datasource_id,
        policy_revision=policy_revision,
    )


async def _plan_kb_vault_from_connector(
    datasource_id: str,
    caller: dict[str, Any] | None,
    project_id: str | None,
) -> _KbVaultPlan:
    """Check that an existing ``kb`` connector can become a project's vault.

    Adoption converts the row (see ``_adopt_kb_connector_as_vault``), so every
    reason it must not be converted is checked here, before anything is
    created.
    """
    from services.kb_datasources import native_kb_project_id

    datasource = await postgres_db.get_datasource(datasource_id)
    if not datasource:
        raise HTTPException(
            status_code=404, detail=f"Connector '{datasource_id}' not found"
        )
    if str(datasource.get("type") or "") != "kb":
        raise HTTPException(
            status_code=400,
            detail=(
                "Only an OKF Knowledge Base connector can back a project knowledge base"
            ),
        )
    is_owner = str(datasource.get("created_by") or "") == str(
        (caller or {}).get("id") or ""
    )
    if not ((caller or {}).get("is_admin") or is_owner):
        raise HTTPException(
            status_code=403,
            detail="Not authorized to use this connector as a knowledge base",
        )
    if native_kb_project_id(datasource):
        raise HTTPException(
            status_code=409,
            detail="This connector is already a project's knowledge base",
        )
    if datasource.get("is_global"):
        # Adoption takes the row private and drops the index every other user
        # was reading. Same reasoning as the project-link check below.
        raise HTTPException(
            status_code=409,
            detail=(
                "This connector is published to everyone; unpublish it before "
                "using it as a project knowledge base"
            ),
        )
    linked = await postgres_db.list_datasource_projects(datasource_id)
    others = sorted(
        {str(value) for value in (linked or [])}
        - ({str(project_id)} if project_id else set())
    )
    if others:
        # Adoption narrows the connector to exactly one project. Doing that
        # silently would revoke every other project's reader access — and
        # their agents would keep listing a KB whose index no longer exists.
        raise HTTPException(
            status_code=409,
            detail=(
                "This connector is shared with other projects; unlink it from "
                "them before using it as a project knowledge base"
            ),
        )

    config = datasource.get("config") or {}
    if not isinstance(config, dict):
        config = {}
    root_path = str(config.get("root_path") or "").strip().strip("/")
    if root_path not in ("", "knowledge"):
        # kb_materialize commits every note to ``knowledge/<slug>.md``; any
        # other root would read a different folder than the agent writes.
        raise HTTPException(
            status_code=400,
            detail=(
                f"A project knowledge base is written to 'knowledge/', but this "
                f"connector reads '{root_path}/'. Set its note root to "
                "'knowledge' first."
            ),
        )

    credentials = datasource.get("credentials") or {}
    if isinstance(credentials, str):
        try:
            credentials = json.loads(credentials)
        except (json.JSONDecodeError, ValueError):
            credentials = {}
    token = (
        str(credentials.get("token") or "").strip()
        if isinstance(credentials, dict)
        else ""
    )
    if not token:
        # Reads clone over git; writes go through the GitHub contents API,
        # which has no SSH equivalent. An SSH-only connector would index fine
        # and fail on every single note write.
        raise HTTPException(
            status_code=400,
            detail=(
                "A writable project knowledge base needs a token credential; "
                "this connector has none (an SSH key cannot write notes)"
            ),
        )

    return _kb_vault_plan(
        datasource.get("connection_url"),
        str(datasource.get("default_branch") or "main"),
        {"auth_method": "token", "token": token},
        str(config.get("forge") or "") or None,
        datasource_id=str(datasource["id"]),
        policy_revision=int(datasource.get("policy_revision") or 0),
    )


async def _plan_external_kb_vault(
    external_kb: ExternalKnowledgeBase,
    *,
    caller: dict[str, Any] | None = None,
    project_id: str | None = None,
) -> _KbVaultPlan:
    """Resolve either request mode into one validated plan.

    Callers run this *before* creating anything, so a rejected vault cannot
    leave a half-created project behind.
    """
    if external_kb.datasource_id:
        return await _plan_kb_vault_from_connector(
            external_kb.datasource_id, caller, project_id
        )
    return _kb_vault_plan(
        external_kb.repo_url,
        external_kb.branch,
        {
            "auth_method": "token",
            "token": (
                external_kb.token.get_secret_value().strip()
                if external_kb.token
                else ""
            ),
        },
        external_kb.forge,
    )


async def _adopt_kb_connector_as_vault(
    plan: _KbVaultPlan, project_id: str, config: dict[str, Any]
) -> dict[str, Any]:
    """Convert an existing connector into this project's vault row, in place.

    Copying it into a second row would leave two connectors on one repository:
    the copy indexed under the project id and the original still swept under
    its own UUID, so every note would answer a search twice — the one failure
    in knowledge-base/knowledge/features/knowledge_base_repo_separation.md that corrupts search
    rather than merely failing it.

    Scope narrows to the adopting project because the row stops being an
    external source the moment the marker lands: anyone else still holding a
    link would bind a KB whose index no longer exists.
    """
    updated = await postgres_db.update_datasource_with_policy(
        str(plan.datasource_id),
        expected_policy_revision=plan.policy_revision,
        scope_mode="projects",
        auto_attach=True,
        project_ids=[project_id],
        config=config,
    )
    if updated is None:
        raise RuntimeError("Knowledge connector disappeared during adoption")
    return updated


async def _provision_external_project_knowledge_repo(
    project: dict[str, Any],
    owner_id: str | None,
    plan: _KbVaultPlan,
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Attach an existing GitHub repo and store its PAT on the native KB row."""
    from services.kb_datasources import NATIVE_PROJECT_CONFIG_KEY

    repo_url = plan.repo_url
    branch = plan.branch
    forge = plan.forge
    repo_name = plan.repo
    credentials = plan.credentials
    project_id = str(project["id"])
    id8 = project_id[:8]
    datasource_ref = await postgres_db.get_native_project_kb_datasource_ref(project_id)
    if (
        plan.datasource_id
        and datasource_ref
        and str(datasource_ref.get("id") or "") != str(plan.datasource_id)
    ):
        # Two rows marked native to one project would make the credential
        # lookup (oldest wins) resolve to a different repository than the one
        # the vault reads and writes.
        raise HTTPException(
            status_code=409,
            detail=(
                "This project already has a knowledge connector; remove it "
                "before attaching another"
            ),
        )
    repo_row = await postgres_db.add_project_repository(
        project_id=project_id,
        name=repo_name,
        repo_url=repo_url,
        role="knowledge",
        description="External project knowledge vault (OKF notes under knowledge/)",
        is_managed=False,
        branch=branch,
    )
    config = {"root_path": "knowledge", NATIVE_PROJECT_CONFIG_KEY: project_id}
    if plan.explicit_forge:
        config["forge"] = forge

    try:
        if plan.datasource_id:
            datasource = await _adopt_kb_connector_as_vault(plan, project_id, config)
        elif datasource_ref and datasource_ref.get("id"):
            datasource_id = str(datasource_ref["id"])
            updated = await postgres_db.update_datasource(
                datasource_id,
                credentials=credentials,
                config=config,
            )
            if not updated:
                raise RuntimeError("Native project KB datasource update failed")
            datasource = await postgres_db.get_datasource(datasource_id)
            if datasource is None:
                raise RuntimeError("Native project KB datasource disappeared")
        else:
            datasource = await postgres_db.create_datasource(
                name=f"{project['name']} Knowledge ({id8})",
                ds_type="kb",
                connection_url=None,
                description=(
                    f"This project's knowledge base, stored in `{repo_name}`. "
                    "Notes written with kb_write land here."
                ),
                credentials=credentials,
                config=config,
                created_by=owner_id,
                read_only=True,
                scope_mode="projects",
                auto_attach=True,
                project_ids=[project_id],
            )
    except Exception:
        repo_id = repo_row.get("id") if isinstance(repo_row, dict) else None
        if repo_id:
            try:
                await postgres_db.remove_project_repository(str(repo_id))
            except Exception:
                logger.exception(
                    "Failed to roll back external KB repository row for project %s",
                    project_id,
                )
        raise

    if plan.datasource_id:
        # The marker is stored, so the sweep has already let go of this row.
        # Whatever it indexed under its own UUID is now unreachable weight that
        # would double every search hit if the row were ever detached again —
        # disposable cleanup, never a reason to fail a provisioned project.
        try:
            await _purge_kb_datasource_index(str(plan.datasource_id))
        except Exception:
            logger.exception(
                "Failed to purge the external index of adopted KB connector %s",
                plan.datasource_id,
            )

    logger.info(
        "Attached external %s knowledge repo '%s' + KB connector %s to project %s",
        forge,
        repo_name,
        datasource["id"],
        project_id,
    )
    return repo_row, datasource


@app.post("/api/projects")
async def create_project(body: ProjectCreate, request: Request) -> dict[str, Any]:
    """Create a new project with the requesting user as owner."""
    # H5: pre-fix, this endpoint had no auth at all and trusted body.user_id,
    # so any unauthenticated caller could create projects owned by anyone.
    # Admins keep the ability to create on behalf of others (legitimate
    # setup flow); regular users get bound to themselves.
    user = await require_approved_user(request, postgres_db)
    owner_id = body.user_id if user.get("is_admin") else str(user["id"])
    # A project's default_config_override is merged UNDER every job created in
    # the project (create_job), so an unvalidated tools block here is a
    # cross-principal escalation: the planter is not the runner, and the PDP
    # keys off the category name, so `tools.canvas: ["run_command"]` binds a
    # shell tool for jobs whose owner has no shell_tools grant. Validated on
    # WRITE only — no existing row is touched, and the field only reaches this
    # check when a caller explicitly sends it.
    validated_project_override = _with_validated_tool_overrides(
        body.default_config_override
    )
    # Same write-only rule for the project's default selector: create_job
    # copies it into jobs.config_name in the legacy compatibility branch, and
    # from there it reaches the pod entrypoint.
    validated_default_config_name = _validated_config_name(body.default_config_name)
    # Resolve the full vault target — URL, auth, forge, and for a connector
    # request every reason it may not be adopted — before creating the project,
    # so a rejected external-vault request cannot leave a half-created one.
    external_kb_plan = (
        await _plan_external_kb_vault(body.external_kb, caller=user)
        if body.external_kb is not None
        else None
    )
    try:
        project = await postgres_db.create_project(
            name=body.name,
            description=body.description,
            goal=body.goal,
            default_config_name=validated_default_config_name,
            default_config_override=validated_project_override,
        )

        # Add creator as owner
        await postgres_db.add_project_member(
            project_id=str(project["id"]),
            user_id=owner_id,
            role="owner",
        )

        # Create only the dedicated KB vault. Root jobs get isolated repositories
        # when they are created; project membership never selects a shared
        # workspace. See project_jobs_repo_retirement.md.
        if external_kb_plan is not None:
            await _provision_external_project_knowledge_repo(
                project, owner_id, external_kb_plan
            )
        elif gitea_client.is_initialized:
            # The vault is written server-side and never cloned into a workspace.
            # A Gitea hiccup remains non-fatal to project creation, but no new
            # project falls back to a jobs repo because none is provisioned.
            try:
                await _provision_project_knowledge_repo(project, owner_id)
            except Exception as e:
                logger.warning(
                    f"Failed to provision knowledge repo for project "
                    f"{project['id']}: {e}"
                )

        # Provision Keycloak group + main-cloud Space + WebDAV datasource,
        # then sync the creator into both the Keycloak and LibreGraph groups.
        # The dual group write is intentional: Keycloak carries the `groups`
        # token claim (durable — OpenCloud's proxy reconciles LibreGraph
        # memberships from it on every login), while the direct backend add
        # makes the Space visible in the creator's currently-active OpenCloud
        # session without waiting for them to re-authenticate.
        project = await _ensure_project_cloud_resources(project)

        return project
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e


@app.post("/api/projects/{project_id}/knowledge/repository")
async def attach_project_knowledge_repository(
    request: Request,
    project_id: str,
    body: ExternalKnowledgeBase,
) -> dict[str, Any]:
    """Attach an external GitHub live vault to an existing repo-less project.

    Replacing or migrating an existing knowledge-role repository is
    deliberately not implicit: v1 has no approved note/history migration.
    """
    caller, project = await require_project_owner(
        request, postgres_db, project_id, allow_archived=False
    )
    existing = await postgres_db.get_project_repositories(project_id, role="knowledge")
    if existing:
        raise HTTPException(
            status_code=409,
            detail=(
                "Project already has a knowledge repository; migration/replacement "
                "is not supported by this attach path"
            ),
        )
    plan = await _plan_external_kb_vault(body, caller=caller, project_id=project_id)
    try:
        repository, datasource = await _provision_external_project_knowledge_repo(
            project,
            str(caller["id"]) if caller.get("id") else None,
            plan,
        )
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(
            status_code=500, detail="Failed to attach external knowledge repository"
        ) from exc
    return {
        "status": "attached",
        "repository": redact_repository(repository),
        "datasource": redact_datasource(datasource),
    }


@app.get("/api/projects")
async def list_projects(
    request: Request,
    user_id: str | None = Query(default=None),
    status: list[str] | None = Query(
        default=None,
        description=(
            "Project lifecycle status(es) to include (repeatable). "
            "Defaults to 'active' — archived projects are excluded unless "
            "asked for, e.g. ?status=archived or ?status=active&status=archived"
        ),
    ),
) -> list[dict[str, Any]]:
    """List projects visible to the caller.

    Visibility model (G2):
        * Admins see the full list, optionally narrowed by ``?user_id=`` or
          by an MCP ``project:<uuid>`` token scope.
        * Non-admins see only the projects they're a member of
          (``get_projects_for_user(caller)``), narrowed by any MCP scope.
        * A non-admin passing ``?user_id=`` for anyone other than themselves
          is rejected (403). Self-query is allowed but redundant.

    Lifecycle (knowledge-base/knowledge/features/project_and_job_list_filtering.md
    §4.2): archived projects are excluded by default on BOTH branches. The
    server does this, not the client — a filter applied in Angular still pays
    for the rows in Postgres and leaves every other consumer unprotected.
    The old admin-branch ``status != 'deleted'`` predicate was dead code:
    ``valid_project_status`` has no such value (deletion is a hard row
    delete), so it never excluded anything.

    ``get_projects_for_user`` keeps its LIMIT 100. With archived excluded that
    ceiling stops being reachable for realistic accounts; if it ever is, the
    projects grid needs paging too (out of scope, phase 1).
    """
    caller = await require_approved_user(request, postgres_db)
    is_admin = bool(caller.get("is_admin"))
    scope_pid = mcp_scope_project_id(caller)
    statuses = normalize_project_statuses(status)

    if user_id is not None and not is_admin and str(user_id) != str(caller["id"]):
        raise HTTPException(
            status_code=403,
            detail="Not authorized to query other users' projects",
        )

    try:
        if is_admin and user_id is None:
            async with postgres_db.acquire() as conn:
                rows = await conn.fetch(
                    "SELECT * FROM projects WHERE "
                    f"{project_status_filter_sql('$1')} "
                    "ORDER BY updated_at DESC LIMIT 100",
                    statuses,
                )
                projects = [dict(r) for r in rows]
        elif user_id is not None:
            projects = await postgres_db.get_projects_for_user(
                user_id, statuses=statuses
            )
        else:
            projects = await postgres_db.get_projects_for_user(
                str(caller["id"]), statuses=statuses
            )

        if scope_pid:
            projects = [p for p in projects if str(p.get("id", "")) == str(scope_pid)]

        return projects
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e


@app.get("/api/projects/{project_id}")
async def get_project(request: Request, project_id: str) -> dict[str, Any]:
    """Get a single project by ID.

    The warm path is pure Postgres — cloud/Keycloak reconciliation and
    identity resolution run as throttled background repairs, never on the
    request (knowledge-base/knowledge/issues/project_page_open_blocks_on_cloud_heal.md
    measured 2.3-5s per page open when they were inline).
    """
    _, project = await require_project_member(request, postgres_db, project_id)

    # Lazy-heal (folder for pre-fix projects + member-group drift repair) —
    # fire-and-forget with a per-project cooldown. A legacy project without a
    # folder handle serves cloud_storage_url=None on this first open and gets
    # the deep-link once the background heal lands; the cockpit hides the
    # button for None. create_project keeps its blocking call — creation is
    # the primary provisioning path.
    _fire_background_repair(
        f"project-heal:{project_id}", _ensure_project_cloud_resources(project)
    )

    # Compute cloud_storage_url for cockpit deep-links.
    #
    # Decorative-only: this whole block produces one optional URL for a button
    # the cockpit hides when it is None. It must never fail the request — a
    # pre-0186 row (provider name stamped, no backend-instance UUID) has no
    # resolvable installation authority, and 500ing the project page over a
    # missing deep-link took every cloud-backed project on dev offline behind a
    # misleading "You don't have access to that project" toast. The row still
    # refuses *effects* through the raising `for_project` at the mutation call
    # sites, which is the behaviour we want.
    project["cloud_storage_url"] = None
    backend = main_cloud_router.for_project_optional(project)
    if backend is not None and backend.is_initialized:
        if project.get("is_default"):
            # Default projects piggyback on the owner's personal home Space —
            # the deep-link must resolve to that home, not to a project Space
            # (which we no longer provision for defaults — see
            # `_ensure_project_cloud_resources`). A stale handle from older
            # deployments is intentionally ignored here.
            try:
                members = await postgres_db.get_project_members(project_id)
                owner = next((m for m in members if m.get("role") == "owner"), None)
                if owner and owner.get("email"):
                    url = await peek_home_browser_url(
                        postgres_db, str(owner["user_id"]), backend.backend_id
                    )
                    if url:
                        project["cloud_storage_url"] = url
                    else:
                        # Cache miss: resolve+persist off the request path;
                        # this open falls back to the generic home URL.
                        owner_user = {
                            "id": owner["user_id"],
                            "email": owner.get("email"),
                            "display_name": owner.get("display_name"),
                        }
                        _fire_background_repair(
                            f"home-url:{owner['user_id']}:{backend.backend_id}",
                            get_home_browser_url_cached(
                                postgres_db, owner_user, backend
                            ),
                        )
            except Exception as e:
                logger.warning(
                    f"Failed to resolve user-home URL for default project "
                    f"{project_id}: {e}"
                )
            if not project["cloud_storage_url"]:
                project["cloud_storage_url"] = backend.get_default_home_browser_url()
        else:
            handle_str = project.get("main_cloud_folder_handle")
            legacy_folder_id = project.get("nextcloud_folder_id")
            if handle_str or legacy_folder_id:
                handle = ProjectFolderHandle.from_db(
                    handle_str or str(legacy_folder_id),
                    backend=project.get("main_cloud_backend") or backend.backend_id,
                )
                # Legacy Nextcloud handles were backfilled without vendor_meta;
                # re-attach the mountpoint from the project name so the URL
                # builder has what it needs.
                if not handle.vendor_meta.get("mountpoint"):
                    handle = ProjectFolderHandle(
                        backend=handle.backend,
                        native_id=handle.native_id,
                        vendor_meta={
                            **handle.vendor_meta,
                            "mountpoint": project["name"],
                        },
                    )
                project["cloud_storage_url"] = backend.get_project_folder_browser_url(
                    handle
                )

    return project


async def _quiesce_archived_project(project_id: str) -> dict[str, Any]:
    """Stop a project's unattended machinery after it is archived (§4.5).

    Never refuses and never raises: across GitHub, GitLab, Jira, Asana, Linear
    and Slack, no product refuses an archive because children are in flight —
    refusing makes archive un-completable exactly when you most want it, i.e.
    when something is wedged and you want it to stop mattering. So the archive
    has already been written by the time we get here; each step below is
    best-effort and reports what it managed to do.

    Three children, matching Slack's deterministic-deactivation tier rather
    than Jira's "your automation rules just start failing":

    * a *running* loop is paused (a paused one is left alone),
    * the officer is held — the same one key the maintenance-hold endpoint
      stamps, with NO ``thread_id``, which is what stops the watchdog's
      stale-hold self-heal from releasing it,
    * jobs the dispatcher has not claimed yet are parked.

    ``processing`` jobs are deliberately untouched: in-flight work, not new
    work. Unarchive does NOT undo any of this — implicitly re-animating
    automation is where the surprises live.
    """
    report: dict[str, Any] = {
        "loop_paused": False,
        "officer_held": False,
        "jobs_parked": 0,
    }

    try:
        loop = await postgres_db.get_active_project_loop(project_id)
        if loop and loop.get("status") == "running":
            await postgres_db.update_project_loop(str(loop["id"]), status="paused")
            report["loop_paused"] = True
    except Exception:
        logger.exception(
            "archive %s: failed to pause the project loop (archive stands)",
            project_id,
        )

    try:
        officer = await postgres_db.get_officer_thread_for_project(project_id)
        if officer and not _thread_officer_meta(officer).get("hold"):
            await postgres_db.set_project_officer_hold(
                project_id,
                expected_thread_id=str(officer["id"]),
                hold={
                    "kind": "project_archived",
                    "since": datetime.now(timezone.utc).isoformat(),
                    "note": "The project was archived.",
                },
                route_reason="officer_hold",
            )
            report["officer_held"] = True
    except Exception:
        logger.exception(
            "archive %s: failed to hold the officer (archive stands)", project_id
        )

    try:
        report["jobs_parked"] = await postgres_db.park_project_jobs_for_archive(
            project_id
        )
    except Exception:
        logger.exception(
            "archive %s: failed to park pending jobs (archive stands)", project_id
        )

    logger.info(
        "archive %s: quiesced (loop_paused=%s officer_held=%s jobs_parked=%s)",
        project_id,
        report["loop_paused"],
        report["officer_held"],
        report["jobs_parked"],
    )
    return report


@app.patch("/api/projects/{project_id}")
async def update_project(
    project_id: str, body: ProjectUpdate, request: Request
) -> dict[str, Any]:
    """Update a project. Caller must be a project owner or admin.

    ALLOW-listed for archived projects because it is the unarchive path — but
    **status-only** while archived (§4.3a). The handler is generic: it also
    covers ``name``, ``goal`` and ``default_config_override``, and that last
    one is merged under *every job in the project*, so leaving it open would
    stop "archived" meaning read-only in the way the shipped UI copy promises.
    The guard flag cannot express this — it fires before the body is
    inspected — so it is a body-level check here. Renaming an archived project
    is a legitimate want; it just needs an unarchive first, which is one click.

    Setting ``status='archived'`` additionally quiesces the project's children
    and reports what it stopped (§4.5).
    """
    # H5: pre-fix, anyone could rename any project, change its goal, or
    # toggle cloud-storage settings.
    # Indexed, not unpacked: several existing tests stand the whole gate up as
    # a bare AsyncMock, which returns a MagicMock rather than a 2-tuple, and
    # `a, b = ...` would blow up on it. Same reasoning as routers/contacts.py.
    project = (await require_project_owner(request, postgres_db, project_id))[1]
    kwargs = {k: v for k, v in body.model_dump().items() if v is not None}
    if not kwargs:
        raise HTTPException(status_code=400, detail="No fields to update")
    if project_is_archived(project) and set(kwargs) - {"status"}:
        # Refuse the WHOLE request rather than applying the status half and
        # dropping the rest: a partially-applied PATCH is the worst outcome
        # here, since the caller has no way to tell which half landed.
        raise HTTPException(
            status_code=409,
            detail=(
                "This project is archived and is read-only apart from its "
                "status. Unarchive it before editing anything else."
            ),
        )
    # Write-only, same rationale as create_project: this layer is merged under
    # every job in the project, so a tools block here escapes the runner's
    # grants. Only fires when the field is explicitly sent — the cockpit's
    # project-memory toggle re-submits the STORED override, so a project
    # already holding an invalid tools block surfaces it here instead of
    # quietly binding foreign tools on every job.
    if "default_config_override" in kwargs:
        kwargs["default_config_override"] = _with_validated_tool_overrides(
            kwargs["default_config_override"]
        )
    # Write-only for the same reason: a project already holding an unbootable
    # default surfaces it when a caller re-submits the field, never on a PATCH
    # that does not name it.
    if "default_config_name" in kwargs:
        kwargs["default_config_name"] = _validated_config_name(
            kwargs["default_config_name"]
        )
    # network_tier is admin-gated: a tier change widens what the project's
    # workspaces can reach at the pod-network layer (e.g. home-allowed
    # exposes the homelab LAN). Letting any project owner choose their own
    # tier defeats the operator-side control plane. See
    # knowledge-base/knowledge/features/workspace_network_isolation.md §3.
    if body.network_tier is not None:
        await _require_admin(request)
    success = await postgres_db.update_project(project_id, **kwargs)
    if not success:
        raise HTTPException(status_code=404, detail=f"Project '{project_id}' not found")

    # Sync cloud_storage_read_only to the project-scoped WebDAV datasource
    if body.cloud_storage_read_only is not None:
        try:
            project_ds = await postgres_db.list_project_datasources(project_id)
            for ds in project_ds:
                if ds["type"] == "webdav":
                    await postgres_db.link_datasource_to_project(
                        project_id=project_id,
                        datasource_id=str(ds["id"]),
                        read_only=body.cloud_storage_read_only,
                    )
                    break
        except Exception as e:
            logger.warning(
                f"Failed to sync cloud_storage_read_only to datasource "
                f"for project {project_id}: {e}"
            )

    # Archiving quiesces the children and says so (§4.5). Only on the
    # transition INTO archived: re-PATCHing an already-archived project must
    # not re-hold an officer the owner deliberately released. Unarchive
    # (status='active') resumes nothing — that stays explicit.
    archiving_now = str(kwargs.get("status") or "").lower() == "archived"
    if archiving_now and not project_is_archived(project):
        quiesced = await _quiesce_archived_project(project_id)
        return {"status": "updated", "archived": True, **quiesced}

    return {"status": "updated"}


@app.delete("/api/projects/{project_id}")
async def delete_project(project_id: str, request: Request) -> dict[str, str]:
    """Delete a project. Caller must be a project owner or admin. Cannot delete default projects."""
    # H5: pre-fix, anyone could cascade-delete any project (repos,
    # Keycloak groups, cloud folders, knowledge index, ...).
    _, project = await require_project_owner(request, postgres_db, project_id)
    if project.get("is_default"):
        raise HTTPException(status_code=400, detail="Cannot delete a default project")

    # Clean up managed repos
    repos = await postgres_db.get_project_repositories(project_id)
    for repo in repos:
        if repo.get("is_managed"):
            if not await revoke_and_delete_managed_repository(
                postgres_db, gitea_client, repo["name"]
            ):
                raise HTTPException(
                    status_code=503,
                    detail="Repository credential revocation is retryable",
                )

    # Clean up knowledge_index in vector DB (no FK cascade across databases)
    try:
        async with vector_db.acquire() as conn:
            await conn.execute(
                "DELETE FROM knowledge_index WHERE project_id = $1", UUID(project_id)
            )
    except Exception as e:
        logger.warning(
            f"Failed to clean up knowledge_index for project {project_id}: {e}"
        )

    # Detach referencing rows that lack ON DELETE CASCADE/SET NULL
    uuid_val = UUID(project_id)
    async with postgres_db.acquire() as conn:
        await conn.execute(
            "UPDATE jobs SET project_id = NULL WHERE project_id = $1", uuid_val
        )
        await conn.execute(
            "UPDATE datasources SET project_id = NULL WHERE project_id = $1", uuid_val
        )

    success = await postgres_db.delete_project(project_id)
    if not success:
        raise HTTPException(status_code=500, detail="Failed to delete project")

    # Clean up Keycloak group
    if keycloak_groups.is_initialized:
        await keycloak_groups.delete_project_group(project_id)

    # Clean up main-cloud project folder via the row's backend dispatch.
    #
    # The DB row is already gone by this point, so raising here would report a
    # delete that actually happened as a 500. An unresolvable installation
    # authority means we cannot say *which* installation holds the folder, and
    # deleting from a guessed one is unacceptable — so leave the folder in
    # place, say so, and let the delete stand.
    backend = main_cloud_router.for_project_optional(project)
    handle_str = project.get("main_cloud_folder_handle") or (
        str(project["nextcloud_folder_id"])
        if project.get("nextcloud_folder_id")
        else None
    )
    if backend is None:
        if handle_str:
            logger.warning(
                "Project %s deleted, but its main-cloud folder (%s on provider "
                "%r) was left in place: no resolvable backend instance for the "
                "row. The folder needs manual cleanup.",
                project_id,
                handle_str,
                project.get("main_cloud_backend"),
            )
    elif handle_str and backend.is_initialized:
        try:
            handle = ProjectFolderHandle.from_db(
                handle_str,
                backend=project.get("main_cloud_backend") or backend.backend_id,
            )
            await backend.delete_project_folder(handle)
        except Exception as e:
            logger.warning(
                f"Failed to delete main-cloud folder for project {project_id}: {e}"
            )

    return {"status": "deleted"}


@app.get("/api/projects/{project_id}/members")
async def list_project_members(
    request: Request, project_id: str
) -> list[dict[str, Any]]:
    """List members of a project with user info."""
    await require_project_member(request, postgres_db, project_id)
    return await postgres_db.get_project_members(project_id)


@app.post("/api/projects/{project_id}/members")
async def add_project_member(
    project_id: str, body: ProjectMemberAdd, request: Request
) -> dict[str, Any]:
    """Add a member to a project. Caller must be a project owner or admin."""
    # H3: pre-fix, anyone could invite themselves as owner of any project
    # and then access everything in it. This is the foundational
    # privilege-escalation path that opens every other gate.
    _, project = await require_project_owner(
        request, postgres_db, project_id, allow_archived=False
    )

    # Resolve the cloud backend BEFORE writing the member row. The cloud group
    # add below is load-bearing (a member without it cannot reach the project's
    # files), so a row we cannot sync is a half-landed member: present in the
    # DB, invisible in the cloud, and reported to the caller as a 500 by the
    # blanket handler below. Refuse up front instead, with a diagnosis — a
    # pre-0186 row has no resolvable installation authority until it is
    # stamped, and we must not guess which installation to grant against.
    backend = main_cloud_router.for_project_optional(project)
    if backend is None:
        raise HTTPException(
            status_code=409,
            detail=(
                "This project's main-cloud installation authority is "
                "unresolved, so project membership cannot be granted on the "
                "cloud backend. The project row needs a "
                "main_cloud_backend_instance_id backfill."
            ),
        )

    try:
        result = await postgres_db.add_project_member(
            project_id=project_id,
            user_id=body.user_id,
            role=body.role,
        )

        # Sync to Keycloak project group AND the main-cloud LibreGraph group.
        # Both writes are load-bearing — see _sync_project_member_to_groups.
        user = await postgres_db.get_user(body.user_id)
        if user:
            await _sync_project_member_to_groups(
                project_id, f"project-{project_id}", user, backend
            )

        # Grant Gitea access to all managed project repos
        if gitea_client.is_initialized:
            try:
                if user and user.get("email"):
                    repos = await postgres_db.get_project_repositories(project_id)
                    for repo in repos:
                        if repo.get("is_managed"):
                            await gitea_client.grant_user_repo_access(
                                user["email"], repo["name"]
                            )
            except Exception as e:
                logger.warning(
                    f"Failed to grant Gitea access for member {body.user_id}: {e}"
                )

        return result
    except Exception as e:
        if "duplicate key" in str(e).lower() or "unique" in str(e).lower():
            raise HTTPException(status_code=409, detail="User is already a member")
        raise HTTPException(status_code=500, detail=str(e)) from e


@app.patch("/api/projects/{project_id}/members/{user_id}")
async def update_project_member(
    project_id: str, user_id: str, body: ProjectMemberUpdate, request: Request
) -> dict[str, str]:
    """Update a member's role in a project. Caller must be a project owner or admin."""
    # H3: role changes are sensitive — restrict to owners/admins.
    await require_project_owner(request, postgres_db, project_id, allow_archived=False)
    success = await postgres_db.update_project_member_role(
        project_id=project_id, user_id=user_id, role=body.role
    )
    if not success:
        raise HTTPException(status_code=404, detail="Member not found")
    return {"status": "updated"}


@app.delete("/api/projects/{project_id}/members/{user_id}")
async def remove_project_member(
    project_id: str, user_id: str, request: Request
) -> dict[str, str]:
    """Remove a member from a project. Owner/admin can remove anyone; any member can remove themselves. Cannot remove the last owner."""
    # H3: pre-fix, anyone could remove anyone (only the last-owner check
    # was enforced). Allow self-removal so members can leave projects.
    caller = await require_approved_user(request, postgres_db)
    if str(caller["id"]) != str(user_id) and not caller.get("is_admin"):
        caller_role = await postgres_db.get_user_role_in_project(
            project_id, str(caller["id"])
        )
        if caller_role != "owner":
            raise HTTPException(status_code=403, detail="Project owner role required")

    # Check if this is the last owner
    role = await postgres_db.get_user_role_in_project(project_id, user_id)
    if role == "owner":
        members = await postgres_db.get_project_members(project_id)
        owner_count = sum(1 for m in members if m.get("role") == "owner")
        if owner_count <= 1:
            raise HTTPException(
                status_code=400, detail="Cannot remove the last owner of a project"
            )

    success = await postgres_db.remove_project_member(project_id, user_id)
    if not success:
        raise HTTPException(status_code=404, detail="Member not found")

    # Remove from Keycloak group
    if keycloak_groups.is_initialized:
        user = await postgres_db.get_user(user_id)
        if user and user.get("keycloak_sub"):
            await keycloak_groups.remove_user_from_project_group(
                user["keycloak_sub"], project_id
            )

    # Revoke Gitea access from managed project repos
    if gitea_client.is_initialized:
        try:
            removed_user = await postgres_db.get_user(user_id)
            if removed_user and removed_user.get("email"):
                repos = await postgres_db.get_project_repositories(project_id)
                for repo in repos:
                    if repo.get("is_managed"):
                        await gitea_client.revoke_user_repo_access(
                            removed_user["email"], repo["name"]
                        )
        except Exception as e:
            logger.warning(f"Failed to revoke Gitea access for member {user_id}: {e}")

    # Main-cloud group removal flows through Keycloak — OpenCloud reconciles
    # LibreGraph memberships from the OIDC `groups` claim on login, so the
    # Keycloak-side remove above is sufficient. No direct backend.remove call
    # needed.

    return {"status": "removed"}


@app.get("/api/projects/{project_id}/repositories")
async def list_project_repositories(
    request: Request,
    project_id: str,
    role: str | None = Query(default=None),
) -> list[dict[str, Any]]:
    """List repositories attached to a project."""
    await require_project_member(request, postgres_db, project_id)
    rows = await postgres_db.get_project_repositories(project_id, role=role)
    # A/C: strip embedded Gitea credentials and rewrite the internal host to the
    # ingress-routable one before the row leaves the orchestrator (see
    # redact_repositories / externalize_gitea_url).
    return redact_repositories(rows)


@app.post("/api/projects/{project_id}/repositories")
async def add_project_repository(
    request: Request, project_id: str, body: ProjectRepositoryCreate
) -> dict[str, Any]:
    """Attach a repository to a project. Owner or admin only (creates managed Gitea repo)."""
    await require_project_owner(request, postgres_db, project_id, allow_archived=False)

    repo_url = body.repo_url
    is_managed = False
    repository_id: str | None = None
    creation_intent: dict[str, Any] | None = None

    # Create a managed Gitea repo if requested
    if body.create_managed and gitea_client.is_initialized:
        repository_id = str(uuid4())
        access_mode = (
            "none"
            if body.role == "knowledge"
            else "read"
            if body.role == "reference" or body.read_only
            else "write"
        )
        try:
            repo_url, creation_intent = await create_managed_repository(
                postgres_db,
                gitea_client,
                repo_name=body.name,
                authority_kind="project_repository",
                authority_id=repository_id,
                project_id=project_id,
                access_mode=access_mode,
            )
        except ManagedRepositoryAuthorityError as exc:
            raise HTTPException(
                status_code=502, detail="Failed to create Gitea repository"
            ) from exc
        is_managed = True

    created: dict[str, Any] | None = None
    try:
        created = await postgres_db.add_project_repository(
            project_id=project_id,
            repository_id=repository_id,
            name=body.name,
            repo_url=repo_url,
            role=body.role,
            description=body.description,
            read_only=body.read_only,
            is_managed=is_managed,
            branch=body.branch,
            clone_path=body.clone_path,
        )
        if is_managed and project_repository_access_mode(created) is not None:
            assert creation_intent is not None
            await ensure_project_repository_authority(
                postgres_db,
                gitea_client,
                created,
                creation_intent_id=str(creation_intent["id"]),
            )
        # Keep the historical redaction boundary even though new managed rows
        # are credential-free. It remains the safe projection for old data.
        return redact_repository(created)
    except Exception as exc:
        # If we created a managed repo but DB insert failed, clean up
        if is_managed and repo_url:
            contained = await revoke_and_delete_managed_repository(
                postgres_db, gitea_client, body.name
            )
            if contained and created is not None:
                await postgres_db.remove_project_repository(str(created["id"]))
        logger.warning(
            "Managed project repository creation failed for project %s",
            project_id,
        )
        raise HTTPException(
            status_code=500,
            detail="Managed repository provisioning failed",
        ) from exc


@app.patch("/api/projects/{project_id}/repositories/{repo_id}")
async def update_project_repository(
    request: Request, project_id: str, repo_id: str, body: ProjectRepositoryUpdate
) -> dict[str, str]:
    """Update a project repository. Owner or admin only."""
    await require_project_owner(request, postgres_db, project_id, allow_archived=False)
    kwargs = {k: v for k, v in body.model_dump().items() if v is not None}
    if not kwargs:
        raise HTTPException(status_code=400, detail="No fields to update")
    repository = await postgres_db.get_project_repository(repo_id)
    if repository is None or str(repository.get("project_id")) != project_id:
        raise HTTPException(status_code=404, detail="Repository not found")
    if (
        repository.get("is_managed")
        and "name" in kwargs
        and str(kwargs["name"]) != str(repository.get("name"))
    ):
        raise HTTPException(
            status_code=409,
            detail={
                "code": "managed_repository_identity_immutable",
                "message": "Create a new managed repository instead of renaming it",
            },
        )
    if (
        repository.get("is_managed")
        and "read_only" in kwargs
        and bool(kwargs["read_only"]) != bool(repository.get("read_only"))
    ):
        target_repository = {**repository, **kwargs}
        try:
            await rotate_project_repository_authority(
                postgres_db,
                gitea_client,
                target_repository,
            )
        except ManagedRepositoryAuthorityError as exc:
            raise HTTPException(
                status_code=503,
                detail={
                    "code": "managed_repository_authority_rotation_failed",
                    "message": "Repository access-mode rotation is retryable",
                },
            ) from exc
    success = await postgres_db.update_project_repository(repo_id, **kwargs)
    if not success:
        raise HTTPException(status_code=404, detail="Repository not found")
    return {"status": "updated"}


@app.delete("/api/projects/{project_id}/repositories/{repo_id}")
async def remove_project_repository(
    request: Request, project_id: str, repo_id: str
) -> dict[str, str]:
    """Remove a repository from a project. Owner or admin only. Cannot remove the jobs repo."""
    await require_project_owner(request, postgres_db, project_id)
    repo = await postgres_db.get_project_repository(repo_id)
    if not repo or str(repo.get("project_id")) != project_id:
        raise HTTPException(status_code=404, detail="Repository not found")
    if repo.get("role") == "jobs":
        raise HTTPException(status_code=400, detail="Cannot remove the jobs repository")

    # A managed row is the durable retry handle for key revocation. Contain
    # its credential before deleting that row; otherwise a transient Gitea
    # outage would turn it into an unowned, still-usable workspace bearer.
    if repo.get("is_managed"):
        if not await revoke_and_delete_managed_repository(
            postgres_db, gitea_client, repo["name"]
        ):
            raise HTTPException(
                status_code=503,
                detail="Repository credential revocation is retryable",
            )

    removed = await postgres_db.remove_project_repository(repo_id)
    if not removed:
        raise HTTPException(status_code=500, detail="Failed to remove repository")

    return {"status": "removed"}


