@app.post("/api/projects/{project_id}/datasources/{datasource_id}")
async def link_datasource_to_project(
    request: Request,
    project_id: str,
    datasource_id: str,
    body: ProjectDatasourceSettings | None = None,
) -> dict[str, str]:
    """Link an existing connector to a project.

    F3: caller must be project owner of the target project AND must be
    able to see the connector (admin / creator / member of one of its
    projects). Prevents a project owner from probing for stranger
    connectors by guessing UUIDs.

    Optionally pass project-level overrides (read_only, description).
    Also creates a knowledge entry so agents discover the connector.
    """
    user, _ = await require_project_owner(
        request, postgres_db, project_id, allow_archived=False
    )
    ds = await postgres_db.get_datasource(datasource_id)
    if not ds:
        raise HTTPException(
            status_code=404, detail=f"Connector '{datasource_id}' not found"
        )
    if not (
        ds.get("is_global") or await user_can_access_datasource(user, postgres_db, ds)
    ):
        raise HTTPException(
            status_code=403, detail="Not authorized to link this connector"
        )

    from services.kb_datasources import native_kb_project_id

    if native_kb_project_id(ds):
        raise HTTPException(
            status_code=409,
            detail="The native knowledge connector cannot be linked to another project",
        )
    is_connector_owner = str(ds.get("created_by") or "") == str(user["id"])
    if (ds.get("scope_mode") == "projects" or not ds.get("is_global")) and not (
        user.get("is_admin") or is_connector_owner
    ):
        raise HTTPException(
            status_code=403,
            detail="Only the connector owner or an admin may add this project link",
        )

    try:
        effective_read_only = (
            True if ds.get("type") == "kb" else (body.read_only if body else None)
        )
        await postgres_db.link_datasource_to_project(
            project_id,
            datasource_id,
            read_only=effective_read_only,
            description=body.description if body else None,
            authority_user_id=str(user["id"]),
            authority_is_admin=bool(user.get("is_admin")),
        )
        return {"status": "linked"}
    except DatasourceProjectAuthorizationError as exc:
        raise HTTPException(
            status_code=403,
            detail="Not authorized to add one or more project links",
        ) from exc
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e


@app.patch("/api/projects/{project_id}/datasources/{datasource_id}")
async def update_project_datasource(
    request: Request,
    project_id: str,
    datasource_id: str,
    body: ProjectDatasourceSettings,
) -> dict[str, str]:
    """Update project-level settings for a linked connector. F3: project owner only.

    Pass null to clear an override and fall back to connector defaults.
    """
    user, _ = await require_project_owner(
        request, postgres_db, project_id, allow_archived=False
    )
    ds = await postgres_db.get_datasource(datasource_id)
    if not ds:
        raise HTTPException(
            status_code=404, detail=f"Connector '{datasource_id}' not found"
        )
    effective_read_only = True if ds.get("type") == "kb" else body.read_only
    try:
        success = await postgres_db.update_project_datasource(
            project_id,
            datasource_id,
            read_only=effective_read_only,
            description=body.description,
            authority_user_id=str(user["id"]),
            authority_is_admin=bool(user.get("is_admin")),
        )
    except DatasourceProjectAuthorizationError as exc:
        raise HTTPException(
            status_code=403,
            detail="Not authorized to modify this project connector link",
        ) from exc
    if not success:
        raise HTTPException(
            status_code=404,
            detail=f"Link between project '{project_id}' and connector '{datasource_id}' not found",
        )

    return {"status": "updated"}


@app.delete("/api/projects/{project_id}/datasources/{datasource_id}")
async def unlink_datasource_from_project(
    request: Request, project_id: str, datasource_id: str
) -> dict[str, str]:
    """Unlink a connector from a project. F3: project owner only.

    Also removes the knowledge entry.
    """
    user = await require_approved_user(request, postgres_db)
    scope_project_id = mcp_scope_project_id(user)
    if scope_project_id and str(scope_project_id) != str(project_id):
        raise HTTPException(
            status_code=403,
            detail="Access denied by MCP token scope",
        )
    ds = await postgres_db.get_datasource(datasource_id)
    if not ds:
        raise HTTPException(status_code=404, detail="Connector not found")
    from services.kb_datasources import native_kb_project_id

    if native_kb_project_id(ds):
        raise HTTPException(
            status_code=409,
            detail="The native knowledge connector link is managed by its project",
        )
    is_connector_owner = str(ds.get("created_by") or "") == str(user["id"])
    if not (user.get("is_admin") or is_connector_owner):
        await require_project_owner(request, postgres_db, project_id)
    try:
        removed = await postgres_db.unlink_datasource_from_project(
            project_id,
            datasource_id,
            authority_user_id=str(user["id"]),
            authority_is_admin=bool(user.get("is_admin")),
        )
    except DatasourceProjectAuthorizationError as exc:
        raise HTTPException(
            status_code=403,
            detail="Not authorized to modify this project connector link",
        ) from exc
    if not removed:
        raise HTTPException(
            status_code=404,
            detail=f"Link between project '{project_id}' and connector '{datasource_id}' not found",
        )

    return {"status": "unlinked"}


@app.post("/api/projects/{project_id}/jobs")
async def create_project_job(
    request: Request, project_id: str, job: JobCreate
) -> dict[str, Any]:
    """Create a job within a project — delegates to create_job. Requires editor or higher."""
    await require_project_member(
        request, postgres_db, project_id, min_role="editor", allow_archived=False
    )
    job.project_id = project_id
    return await create_job(request, job)


@app.get("/api/projects/{project_id}/jobs")
async def list_project_jobs(
    request: Request,
    project_id: str,
    status: str | None = Query(default=None),
    limit: int = Query(default=100, ge=1, le=500),
) -> list[dict[str, Any]]:
    """List jobs belonging to a project."""
    await require_project_member(request, postgres_db, project_id)
    # Direct service-level callers in the existing test/control seam omit the
    # FastAPI-injected value and therefore receive the Query marker itself.
    # HTTP requests are always a string or None.
    status = status if isinstance(status, str) else None
    if status is not None and status not in JOB_STATUS_FILTER_VALUES:
        raise HTTPException(
            status_code=422,
            detail=(
                f"Unknown job status/outcome: {status}. Valid values: "
                f"{', '.join(JOB_STATUS_FILTER_VALUES)}"
            ),
        )
    try:
        async with postgres_db.acquire() as conn:
            query = (
                "SELECT js.*, jcr.delivery_status, jcr.delivery_ref, "
                "jcr.delivery_sha, jcr.record_type AS change_record_type "
                "FROM job_summary js "
                "LEFT JOIN job_change_records jcr ON jcr.job_id = js.id "
                "WHERE js.project_id = $1"
            )
            params: list = [project_id]
            if status:
                params.append(status)
                if status == "blocked_undelivered":
                    query += " AND js.completion_outcome_kind = $2"
                elif status == "cancelled":
                    query += (
                        " AND js.status = $2 AND "
                        "js.completion_outcome_kind IS DISTINCT FROM "
                        "'blocked_undelivered'"
                    )
                else:
                    query += " AND js.status = $2"
            query += " ORDER BY js.created_at DESC LIMIT $" + str(len(params) + 1)
            params.append(limit)
            rows = await conn.fetch(query, *params)

        jobs = [dict(r) for r in rows]

        # cloud_review_mode: all rows share one project, so resolve its
        # cloud-folder state once (the job_summary view has no projects JOIN).
        project = await postgres_db.get_project(project_id)
        has_cloud_folder = bool(project and project.get("main_cloud_folder_handle"))

        # Enrich with audit counts (single batched query, not N+1)
        if audit_reader.is_available:
            counts = await audit_reader.get_audit_counts(
                [str(job["id"]) for job in jobs]
            )
            for job in jobs:
                job["audit_count"] = counts.get(str(job["id"]), 0)
        else:
            for job in jobs:
                job["audit_count"] = None

        result = []
        for job in jobs:
            job = _redact_job_config_override(job)
            job["project_has_cloud_folder"] = has_cloud_folder
            result.append(_with_cloud_review_mode(job))
        return result
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e


