@app.post("/api/jobs/{job_id}/promote")
async def promote_job(
    request: Request,
    job_id: str,
    body: PromoteRequest,
) -> dict[str, Any]:
    """Promote a default-project job into a dedicated project.

    Creates a new project, provisions its cloud/knowledge resources, and moves
    the completed job into it. The job keeps its isolated execution repository;
    no project workspace repository is created.

    P4c: ``body.user_id`` is forced to the caller (mirrors F2 — no cross-user
    promotion).
    """
    caller, _ = await require_job_access(request, postgres_db, job_id)
    body.user_id = caller["id"]

    try:
        # Validate job
        job = await postgres_db.get_job(job_id)
        if not job:
            raise HTTPException(status_code=404, detail=f"Job '{job_id}' not found")

        if job["status"] != "completed":
            raise HTTPException(
                status_code=400,
                detail=f"Job must be completed to promote (status: {job['status']})",
            )

        # Verify job is in a default project
        old_project_id = str(job["project_id"]) if job.get("project_id") else None
        if not old_project_id:
            raise HTTPException(
                status_code=400,
                detail="Job has no project_id — cannot determine source project",
            )

        old_project = await postgres_db.get_project(old_project_id)
        if not old_project:
            raise HTTPException(
                status_code=400,
                detail=f"Source project '{old_project_id}' not found",
            )

        if not old_project.get("is_default"):
            raise HTTPException(
                status_code=400,
                detail="Job can only be promoted from a default project",
            )

        # Create new project
        new_project = await postgres_db.create_project(
            name=body.name,
            description=body.description,
            goal=body.goal,
        )
        new_project_id = str(new_project["id"])

        # Add user as owner
        await postgres_db.add_project_member(
            project_id=new_project_id,
            user_id=body.user_id,
            role="owner",
        )

        # Provision the project-owned resources. The promoted job's own repo is
        # retained as its historical execution surface; it is never promoted
        # into an implicit template for future jobs.
        if gitea_client.is_initialized:
            try:
                await _provision_project_knowledge_repo(new_project, body.user_id)
            except Exception as e:
                logger.warning(
                    f"Promote: knowledge provisioning failed for {new_project_id}: {e}"
                )
        new_project = await _ensure_project_cloud_resources(new_project)

        # Move job to new project
        async with postgres_db.acquire() as conn:
            await conn.execute(
                "UPDATE jobs SET project_id = $1, updated_at = CURRENT_TIMESTAMP WHERE id = $2",
                UUID(new_project_id),
                UUID(job_id),
            )

        logger.info(
            f"Promoted job {job_id[:8]} to project '{body.name}' ({new_project_id[:8]})"
        )

        return {
            "status": "promoted",
            "project_id": new_project_id,
            "project_name": body.name,
            "job_id": job_id,
        }

    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Promote failed for job {job_id}: {e}")
        raise HTTPException(status_code=500, detail=str(e)) from e


# =============================================================================
# Project Knowledge Base Endpoints
# =============================================================================

# Lazy-loaded singleton for Neo4j knowledge operations
_knowledge_graph_db = None


def _get_knowledge_graph():
    """Lazily initialise and return the KnowledgeGraphDB singleton."""
    global _knowledge_graph_db
    if _knowledge_graph_db is not None:
        return _knowledge_graph_db
    try:
        import sys

        project_root = str(Path(__file__).parent.parent)
        if project_root not in sys.path:
            sys.path.insert(0, project_root)
        from src.services.knowledge_graph import KnowledgeGraphDB

        _knowledge_graph_db = KnowledgeGraphDB()
        if not _knowledge_graph_db.connect():
            logger.warning("Could not connect to Neo4j for knowledge base")
            _knowledge_graph_db = None
    except Exception as e:
        logger.warning(f"KnowledgeGraphDB not available: {e}")
        _knowledge_graph_db = None
    return _knowledge_graph_db


def _build_datasource_note_content(ds: dict[str, Any]) -> str:
    """Build markdown content for a connector knowledge entry.

    Content varies by type and access mode:
    - generic: lists env var names + CLI hint
    - repository: cloned path + git usage
    - managed connectors (read-write): CLI tool + env vars
    - managed connectors (read-only): available tools list
    - webdav: always tools
    """
    ds_type = ds.get("type", "unknown")
    ds_name = ds.get("name", "Unnamed")
    desc = ds.get("description") or ""
    is_read_only = ds.get("project_read_only", False)

    if ds_type == "generic":
        return _build_generic_note(ds_name, desc, ds)
    elif ds_type == "repository":
        return _build_repository_note(ds_name, desc, ds)
    elif ds_type == "kb":
        root = str((ds.get("config") or {}).get("root_path") or "")
        lines = [f"## OKF Knowledge Base: {ds_name}"]
        if desc:
            lines.append(desc)
        lines.append("Centrally indexed and read-only to agents in this release.")
        if root:
            lines.append(f"OKF root: `{root}`")
        lines.append("Attach this connector explicitly, then use the `kb_*` tools.")
        return "\n\n".join(lines)
    elif ds_type == "webdav":
        return _build_webdav_note(ds_name, desc, is_read_only)
    elif ds_type in ("postgresql", "neo4j", "mongodb"):
        if is_read_only:
            return _build_managed_readonly_note(ds_name, desc, ds_type)
        else:
            return _build_managed_readwrite_note(ds_name, desc, ds_type)
    else:
        return f"## Connector: {ds_name}\n{desc}"


def _build_generic_note(name: str, desc: str, ds: dict) -> str:
    """KB entry for generic connectors."""
    lines = [f"## Connector: {name}"]
    if desc:
        lines.append(desc)

    url = ds.get("connection_url")
    cli_hint = ds.get("cli_hint")
    if url or cli_hint:
        lines.append("\n### Connection")
        if url:
            lines.append(f"- **URL:** {url} (credentials via env vars)")
        if cli_hint:
            lines.append(f"- **CLI:** `{cli_hint}`")

    creds = ds.get("credentials") or {}
    if isinstance(creds, str):
        try:
            creds = json.loads(creds)
        except (json.JSONDecodeError, ValueError):
            creds = {}
    env_vars = creds.get("env_vars", {})
    if env_vars:
        lines.append("\n### Environment Variables")
        for key in env_vars:
            lines.append(f"- `{key}` — available in workspace")

    return "\n".join(lines)


def _build_repository_note(name: str, desc: str, ds: dict) -> str:
    """KB entry for repository connectors."""
    import re

    slug = re.sub(r"[^a-z0-9]+", "-", name.lower()).strip("-")
    lines = [f"## Repository: {name}"]
    if desc:
        lines.append(desc)
    lines.append("\n### Location")
    lines.append(f"Cloned to `./repos/{slug}/` — git is pre-authenticated.")
    lines.append("\n### Usage")
    lines.append("Use standard git commands:")
    lines.append(f"- `cd repos/{slug} && git status`")
    lines.append("- `git pull`, `git commit`, `git push`")
    lines.append("- No login or credential setup required.")
    branch = ds.get("default_branch")
    if branch:
        lines.append(f"- Default branch: `{branch}`")
    return "\n".join(lines)


def _build_managed_readwrite_note(name: str, desc: str, ds_type: str) -> str:
    """KB entry for managed connectors in read-write (CLI) mode."""
    cli_info = {
        "postgresql": {
            "tool": "psql",
            "env_vars": "`PGHOST`, `PGUSER`, `PGPASSWORD`, `PGDATABASE`",
            "examples": [
                '`psql -c "SELECT * FROM users LIMIT 10"`',
                '`psql -c "CREATE TABLE ..."`',
            ],
        },
        "neo4j": {
            "tool": "cypher-shell",
            "env_vars": "`NEO4J_URI`, `NEO4J_USERNAME`, `NEO4J_PASSWORD`",
            "examples": [
                '`cypher-shell "MATCH (n) RETURN n LIMIT 10"`',
                "`cypher-shell \"CREATE (n:Label {name: 'test'})\"`",
            ],
        },
        "mongodb": {
            "tool": "mongosh",
            "env_vars": "`MONGOSH_URI`",
            "examples": [
                '`mongosh --eval "db.users.find().limit(10)"`',
                '`mongosh --eval "db.users.insertOne({...})"`',
            ],
        },
    }
    info = cli_info.get(ds_type, {})
    lines = [
        f"## Connector: {name}",
        f"**Type:** {ds_type} | **Access:** full (CLI)",
    ]
    if desc:
        lines.append(f"\n{desc}")
    lines.append("\n### Connection")
    lines.append(
        f"Use `{info.get('tool', ds_type)}` to connect — credentials are pre-configured via environment variables."
    )
    lines.append("\n### Environment Variables")
    lines.append(
        f"- {info.get('env_vars', 'Check environment for connection details')} — pre-configured"
    )
    if info.get("examples"):
        lines.append("\n### Examples")
        for ex in info["examples"]:
            lines.append(f"- {ex}")
    return "\n".join(lines)


def _build_managed_readonly_note(name: str, desc: str, ds_type: str) -> str:
    """KB entry for managed connectors in read-only (tools) mode."""
    tool_info = {
        "postgresql": [
            "- `sql_query` — execute SELECT queries",
            "- `sql_schema` — inspect tables, columns, types, constraints",
        ],
        "neo4j": [
            "- `cypher_query` — execute read-only Cypher queries",
            "- `cypher_execute` — execute write Cypher statements (CREATE, MERGE, DELETE, SET)",
            "- `get_database_schema` — inspect labels, relationships, properties",
        ],
        "mongodb": [
            "- `mongo_query` — document queries with filters",
            "- `mongo_aggregate` — aggregation pipelines",
            "- `mongo_schema` — collections, fields, indexes",
        ],
    }
    tools = tool_info.get(ds_type, ["- Check available tools for this connector type"])
    lines = [
        f"## Connector: {name}",
        f"**Type:** {ds_type} | **Access:** read-only (tools)",
    ]
    if desc:
        lines.append(f"\n{desc}")
    lines.append("\n### Available Tools")
    lines.extend(tools)
    lines.append("\nNo CLI access or write operations available.")
    return "\n".join(lines)


def _build_webdav_note(name: str, desc: str, is_read_only: bool) -> str:
    """KB entry for WebDAV connectors (always tools)."""
    access = "read-only" if is_read_only else "read-write"
    lines = [
        f"## Connector: {name}",
        f"**Type:** webdav | **Access:** {access}",
    ]
    if desc:
        lines.append(f"\n{desc}")
    lines.append("\n### Available Tools")
    lines.append("- `webdav_list` — list files and directories")
    lines.append("- `webdav_read` — read file contents")
    lines.append("- `webdav_info` — get file metadata")
    if not is_read_only:
        lines.append("- `webdav_write` — write/upload files")
        lines.append("- `webdav_delete` — delete files")
    return "\n".join(lines)


async def _sync_datasource_knowledge(
    project_id: str,
    datasource: dict[str, Any],
    *,
    strict: bool = False,
) -> None:
    """Create or update a connector knowledge entry in a project."""
    failures: list[str] = []
    ds_id = str(datasource["id"]).replace("-", "")[:8]
    note_id = f"ds-{ds_id}"
    ds_name = datasource.get("name", "Unnamed")
    ds_type = datasource.get("type", "unknown")
    content = _build_datasource_note_content(datasource)

    if ds_type == "repository":
        retrieval_messages = [
            f"{ds_name} repository",
            f"git repo {ds_name}",
            f"How to access {ds_name} code",
            "available repositories",
        ]
    elif ds_type == "kb":
        retrieval_messages = [
            f"{ds_name} knowledge base",
            f"Search {ds_name} with the KB tools",
            "available OKF knowledge bases",
        ]
    elif ds_type == "generic":
        retrieval_messages = [
            f"{ds_name} connection",
            f"How to access {ds_name}",
            "available connectors",
        ]
    else:
        retrieval_messages = [
            f"{ds_name} database connection",
            f"{ds_type} access",
            f"How do I connect to {ds_name}?",
            "What databases are available?",
        ]

    # Write to Neo4j (upsert with deterministic note_id)
    kg = _get_knowledge_graph()
    if kg:
        try:
            title = f"Connector: {ds_name} ({ds_type})"
            from datetime import datetime, timezone

            now = datetime.now(timezone.utc).isoformat()
            kg._db.execute_write(
                """
                MERGE (n:Note {project_id: $pid, id: $nid})
                ON CREATE SET
                    n.type = 'datasource',
                    n.title = $title,
                    n.content = $content,
                    n.status = 'active',
                    n.confidence = 'high',
                    n.retrieval_messages = $retrieval_messages,
                    n.created = datetime($now),
                    n.modified = datetime($now)
                ON MATCH SET
                    n.title = $title,
                    n.content = $content,
                    n.retrieval_messages = $retrieval_messages,
                    n.modified = datetime($now)
                """,
                {
                    "pid": project_id,
                    "nid": note_id,
                    "title": title,
                    "content": content,
                    "retrieval_messages": retrieval_messages,
                    "now": now,
                },
            )
            # Ensure tags exist
            for tag_name in ["datasource", ds_type]:
                kg._db.execute_write(
                    """
                    MATCH (n:Note {project_id: $pid, id: $nid})
                    MERGE (t:Tag {name: $tag, project_id: $pid})
                    MERGE (n)-[:TAGGED]->(t)
                    """,
                    {"pid": project_id, "nid": note_id, "tag": tag_name},
                )
        except Exception as exc:
            failures.append("neo4j")
            logger.warning(
                "Neo4j datasource knowledge sync failed error_class=%s",
                type(exc).__name__,
            )

    # Write to pgvector search index
    try:
        async with vector_db.acquire() as conn:
            await conn.execute(
                """
                INSERT INTO knowledge_index (
                    note_id, project_id, title, note_type, status,
                    confidence, tags, content, retrieval_messages, modified_at
                ) VALUES ($1, $2::uuid, $3, 'datasource', 'active', 'high',
                          $4::text[], $5, $6::text[], NOW())
                ON CONFLICT (project_id, note_id) DO UPDATE SET
                    title = EXCLUDED.title,
                    content = EXCLUDED.content,
                    retrieval_messages = EXCLUDED.retrieval_messages,
                    tags = EXCLUDED.tags,
                    modified_at = NOW(),
                    content_hash = NULL
                """,
                note_id,
                project_id,
                f"Connector: {ds_name} ({ds_type})",
                ["datasource", ds_type],
                content,
                retrieval_messages,
            )
    except Exception as exc:
        failures.append("pgvector")
        logger.warning(
            "pgvector datasource knowledge sync failed error_class=%s",
            type(exc).__name__,
        )

    if strict and failures:
        raise RuntimeError(
            "Datasource knowledge sync failed for " + ", ".join(failures)
        )


async def _delete_datasource_knowledge(
    project_id: str,
    datasource_id: str,
    *,
    strict: bool = False,
) -> None:
    """Remove the knowledge entry for a datasource from a project."""
    failures: list[str] = []
    ds_id = datasource_id.replace("-", "")[:8]
    note_id = f"ds-{ds_id}"

    kg = _get_knowledge_graph()
    if kg:
        try:
            kg._db.execute_write(
                "MATCH (n:Note {project_id: $pid, id: $nid}) DETACH DELETE n",
                {"pid": project_id, "nid": note_id},
            )
        except Exception as exc:
            failures.append("neo4j")
            logger.warning(
                "Neo4j datasource knowledge delete failed error_class=%s",
                type(exc).__name__,
            )

    try:
        async with vector_db.acquire() as conn:
            await conn.execute(
                "DELETE FROM knowledge_index WHERE project_id = $1::uuid AND note_id = $2",
                project_id,
                note_id,
            )
    except Exception as exc:
        failures.append("pgvector")
        logger.warning(
            "pgvector datasource knowledge delete failed error_class=%s",
            type(exc).__name__,
        )

    if strict and failures:
        raise RuntimeError(
            "Datasource knowledge delete failed for " + ", ".join(failures)
        )


@app.get("/api/projects/{project_id}/knowledge/summary")
async def get_knowledge_summary(request: Request, project_id: str) -> dict[str, Any]:
    """Get knowledge base summary statistics for a project. F5: member-only."""
    await require_project_member(request, postgres_db, project_id)

    try:
        async with vector_db.acquire() as conn:
            # Counts by type
            type_rows = await conn.fetch(
                "SELECT note_type, COUNT(*) as cnt FROM knowledge_index "
                "WHERE project_id = $1 GROUP BY note_type ORDER BY cnt DESC",
                project_id,
            )
            by_type = {r["note_type"]: r["cnt"] for r in type_rows}

            # Counts by status
            status_rows = await conn.fetch(
                "SELECT status, COUNT(*) as cnt FROM knowledge_index "
                "WHERE project_id = $1 GROUP BY status ORDER BY cnt DESC",
                project_id,
            )
            by_status = {r["status"]: r["cnt"] for r in status_rows}

            # Total
            total = sum(by_type.values())

            # Recent notes (last 5)
            recent_rows = await conn.fetch(
                "SELECT note_id, title, note_type, status, modified_at "
                "FROM knowledge_index WHERE project_id = $1 "
                "ORDER BY modified_at DESC LIMIT 5",
                project_id,
            )
            recent = [dict(r) for r in recent_rows]

        # kb_gardening G10: hygiene counters beside the raw totals, so the
        # cockpit and MCP summary can show retired-but-on-disk, orphaned
        # nursery, and the oldest tombstone. Best-effort — never fails the
        # summary.
        gardening: dict[str, Any] | None = None
        try:
            from uuid import UUID as _UUID

            from src.services.knowledge_store import KnowledgeStore

            gardening = await KnowledgeStore(
                db=vector_db, embedding_service=None
            ).get_gardening_health(_UUID(project_id))
        except Exception:
            logger.debug(
                "knowledge summary: gardening health unavailable for %s",
                project_id,
                exc_info=True,
            )

        return {
            "total": total,
            "by_type": by_type,
            "by_status": by_status,
            "recent": recent,
            "gardening": gardening,
        }
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e


@app.get("/api/projects/{project_id}/knowledge")
async def list_knowledge_notes(
    request: Request,
    project_id: str,
    note_type: str | None = Query(default=None, alias="type"),
    status: str | None = Query(default=None),
    tag: str | None = Query(default=None),
    job_id: str | None = Query(default=None),
    limit: int = Query(default=50, ge=1, le=200),
    offset: int = Query(default=0, ge=0),
) -> dict[str, Any]:
    """List knowledge notes for a project with optional filters. F5: member-only."""
    await require_project_member(request, postgres_db, project_id)

    try:
        async with vector_db.acquire() as conn:
            conditions = ["project_id = $1"]
            params: list[Any] = [project_id]
            idx = 2

            if note_type:
                conditions.append(f"note_type = ${idx}")
                params.append(note_type)
                idx += 1
            if status:
                conditions.append(f"status = ${idx}")
                params.append(status)
                idx += 1
            if tag:
                conditions.append(f"${idx} = ANY(tags)")
                params.append(tag)
                idx += 1
            if job_id:
                conditions.append(f"job_id = ${idx}::uuid")
                params.append(job_id)
                idx += 1

            where = " AND ".join(conditions)

            # Count total
            count_row = await conn.fetchrow(
                f"SELECT COUNT(*) as cnt FROM knowledge_index WHERE {where}",
                *params,
            )
            total = count_row["cnt"] if count_row else 0

            # Fetch page
            params.extend([limit, offset])
            rows = await conn.fetch(
                f"SELECT id, note_id, title, note_type, status, confidence, "
                f"tags, keywords, job_id, phase, "
                f"LEFT(content, 300) as content_preview, "
                f"created_at, modified_at "
                f"FROM knowledge_index WHERE {where} "
                f"ORDER BY modified_at DESC "
                f"LIMIT ${idx} OFFSET ${idx + 1}",
                *params,
            )
            notes = [dict(r) for r in rows]

        return {"notes": notes, "total": total, "limit": limit, "offset": offset}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e


@app.get("/api/projects/{project_id}/knowledge/{note_id}")
async def get_knowledge_note(
    request: Request, project_id: str, note_id: str
) -> dict[str, Any]:
    """Get a single knowledge note with full content. F5: member-only."""
    await require_project_member(request, postgres_db, project_id)
    try:
        async with vector_db.acquire() as conn:
            row = await conn.fetchrow(
                "SELECT * FROM knowledge_index WHERE project_id = $1 AND note_id = $2",
                project_id,
                note_id,
            )
        if not row:
            raise HTTPException(
                status_code=404,
                detail=f"Note '{note_id}' not found in project '{project_id}'",
            )
        result = dict(row)
        # Remove binary/vector fields from response
        result.pop("embedding", None)
        result.pop("search_doc", None)

        # Fetch relationships from Neo4j if available
        kg = _get_knowledge_graph()
        if kg:
            try:
                neo4j_note = kg.read_note(project_id, note_id)
                if neo4j_note:
                    result["relationships"] = neo4j_note.get("relationships", [])
            except Exception:
                result["relationships"] = []
        else:
            result["relationships"] = []

        return result
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e


async def _build_kb_embedding_service():
    """EmbeddingService for the KB reindexer, catalog-first (slice 3 PR3).

    The orchestrator pod carries no EMBEDDING_* env (models_yaml_removal), so
    the credential comes from the same place dispatch gets it for agents: the
    admin-curated system embedding in the catalog
    (``resolve_default_for_capability`` + ``_inject_env_key_credentials``).
    Env-based construction is the fallback for dev/compose stacks that still
    set EMBEDDING_*. Returns ``None`` when no usable key resolves — the caller
    must skip reindexing (a keyless run could only write vectorless rows).
    """
    from src.services.embedding_service import EmbeddingService

    env: dict[str, Any] = {}
    await _inject_system_kb_embedding_profile(env)
    if env.get("KB_EMBEDDING_API_KEY"):
        return EmbeddingService(
            model=env.get("KB_EMBEDDING_MODEL"),
            base_url=env.get("KB_EMBEDDING_BASE_URL"),
            api_key=env.get("KB_EMBEDDING_API_KEY"),
            provider=env.get("KB_EMBEDDING_PROVIDER"),
            expected_dimensions=int(env.get("KB_EMBEDDING_DIMENSIONS", "4096")),
            profile_identity=env.get("KB_EMBEDDING_PROFILE_ID"),
        )
    # `_inject_system_kb_embedding_profile` already materializes the dev/env
    # fallback when (and only when) there is no catalog pin. Reaching here means
    # either no embedding transport exists or a selected catalog profile is
    # incomplete. Never silently index with a different EMBEDDING_* model: the
    # dispatched KB_* profile would then query incompatible vectors.
    return None


async def _mark_kb_datasource_pending(datasource_id: str) -> None:
    """Best-effort initial/update state; datasource CRUD remains available."""
    try:
        from src.services.knowledge_store import KnowledgeStore

        from services.kb_reindex import kb_index_lock

        kb_id = UUID(datasource_id)
        store = KnowledgeStore(db=vector_db, embedding_service=None)
        async with kb_index_lock(store, kb_id, wait=True) as lock_conn:
            if await _kb_datasource_is_active(datasource_id):
                await store.set_watermark_status(
                    kb_id,
                    "pending",
                    repo_name=f"datasource:{datasource_id}",
                    conn=lock_conn,
                )
    except Exception as exc:
        logger.warning(
            "Could not mark KB datasource %s pending: %s", datasource_id, exc
        )


async def _kb_datasource_is_active(datasource_id: str) -> bool:
    """Re-check external-source ownership at the index mutation boundary."""
    datasource = await postgres_db.get_datasource(datasource_id)
    return bool(datasource and datasource.get("type") == "kb")


async def _reindex_kb_datasource_now(
    datasource: dict[str, Any], *, force_full: bool = False
) -> dict[str, Any]:
    """Resolve embeddings and run one credential-contained external rebuild."""
    from src.services.knowledge_store import KnowledgeStore

    from services.kb_datasources import reindex_kb_datasource
    from services.kb_reindex import kb_index_lock

    datasource_id = str(datasource["id"])
    kb_id = UUID(datasource_id)
    store = KnowledgeStore(db=vector_db, embedding_service=None)
    svc = await _build_kb_embedding_service()
    if svc is None:
        indexed_commit: str | None = None
        async with kb_index_lock(store, kb_id) as claimed:
            if not claimed:
                return {
                    "status": "already-indexing",
                    "indexed_commit": None,
                    "full": False,
                    "upserted": 0,
                    "deleted": 0,
                    "skipped": 0,
                    "errors": 0,
                }
            if not await _kb_datasource_is_active(datasource_id):
                return {
                    "status": "source-deleted",
                    "indexed_commit": None,
                    "full": False,
                    "upserted": 0,
                    "deleted": 0,
                    "skipped": 0,
                    "errors": 0,
                }
            watermark = await store.get_watermark(kb_id)
            indexed_commit = watermark.indexed_commit if watermark else None
            await store.set_watermark_status(
                kb_id,
                "failed",
                repo_name=f"datasource:{datasource_id}",
                branch=datasource.get("default_branch") or None,
                last_error="No embedding service is configured",
            )
        return {
            "status": "no-embedding-service",
            "indexed_commit": indexed_commit,
            "full": False,
            "upserted": 0,
            "deleted": 0,
            "skipped": 0,
            "errors": 1,
        }
    store.embedding_service = svc
    return await reindex_kb_datasource(
        datasource,
        store=store,
        embedding_service=svc,
        force_full=force_full,
        is_active=lambda: _kb_datasource_is_active(datasource_id),
    )


async def _run_scheduled_kb_datasource_reindex(
    datasource_id: str, *, force_full: bool
) -> None:
    from services.kb_datasources import native_kb_project_id

    try:
        datasource = await postgres_db.get_datasource(datasource_id)
        if not datasource or datasource.get("type") != "kb":
            return
        if native_kb_project_id(datasource):
            # Its project's sweep already indexes these notes under the
            # project id; a second pass here would duplicate every one of them.
            logger.debug(
                "Skipping external reindex of native project KB datasource %s",
                datasource_id,
            )
            return
        await _reindex_kb_datasource_now(datasource, force_full=force_full)
    except Exception as exc:
        # Source exceptions are credential-redacted by kb_git_source. Store a
        # bounded diagnostic while retaining the previous indexed_commit.
        logger.warning("KB datasource %s reindex failed: %s", datasource_id, exc)
        try:
            from src.services.knowledge_store import KnowledgeStore

            from services.kb_reindex import kb_index_lock

            kb_id = UUID(datasource_id)
            store = KnowledgeStore(db=vector_db, embedding_service=None)
            async with kb_index_lock(store, kb_id) as claimed:
                if claimed and await _kb_datasource_is_active(datasource_id):
                    await store.set_watermark_status(
                        kb_id,
                        "failed",
                        repo_name=f"datasource:{datasource_id}",
                        last_error=(str(exc)[-2000:] or "Indexing failed"),
                    )
        except Exception as status_exc:
            logger.warning(
                "Could not persist KB datasource %s failure status: %s",
                datasource_id,
                status_exc,
            )


def _schedule_kb_datasource_reindex(datasource_id: str, *, force_full: bool) -> None:
    task = asyncio.create_task(
        _run_scheduled_kb_datasource_reindex(datasource_id, force_full=force_full),
        name=f"kb-datasource-reindex-{datasource_id[:8]}",
    )
    _kb_datasource_tasks.add(task)
    datasource_tasks = _kb_datasource_tasks_by_id.setdefault(datasource_id, set())
    datasource_tasks.add(task)

    def forget_task(done: asyncio.Task) -> None:
        _kb_datasource_tasks.discard(done)
        current = _kb_datasource_tasks_by_id.get(datasource_id)
        if current is None:
            return
        current.discard(done)
        if not current:
            _kb_datasource_tasks_by_id.pop(datasource_id, None)

    task.add_done_callback(forget_task)


async def _cancel_kb_datasource_reindexes(datasource_id: str) -> None:
    """Cancel and drain request-spawned rebuilds for one external source."""
    current_task = asyncio.current_task()
    tasks = [
        task
        for task in _kb_datasource_tasks_by_id.get(datasource_id, ())
        if task is not current_task and not task.done()
    ]
    for task in tasks:
        task.cancel()
    if tasks:
        await asyncio.gather(*tasks, return_exceptions=True)


async def _purge_kb_datasource_index(datasource_id: str) -> None:
    """Drop the chunk index a connector accumulated under its own UUID.

    Deliberately not shared with ``_delete_kb_datasource_with_index``: that one
    holds the claim across the index purge *and* the app-row delete to order
    the two databases. Here the row survives — it has already been marked as a
    project's own KB — so only the disposable index is dropped, under the same
    per-KB claim so an in-flight sweeper cannot write chunks back afterwards.
    """
    from src.services.knowledge_store import KnowledgeStore

    from services.kb_reindex import kb_index_lock

    await _cancel_kb_datasource_reindexes(datasource_id)
    kb_id = UUID(datasource_id)
    store = KnowledgeStore(db=vector_db, embedding_service=None)
    async with kb_index_lock(store, kb_id, wait=True) as lock_conn:
        await store.delete_kb_index(kb_id, conn=lock_conn)


async def _delete_kb_datasource_with_index(
    datasource_id: str,
    *,
    authority_project_scope_id: str | None = None,
    deleted_by: str | None = None,
) -> bool:
    """Order datasource deletion after every writer of its disposable index.

    The app and vector schemas live in separate databases, so this cannot be a
    single SQL transaction. Holding the shared per-KB advisory claim across
    vector cleanup and app-row deletion supplies the required ordering. A
    stale sweeper that captured the row earlier subsequently fails its
    under-lock liveness check and cannot recreate notes or a watermark.

    ``deleted_by`` is passed straight through to the app-row delete's
    tombstone write (Task 12 item C) — this is the KB half of the same
    endpoint the non-kb branch already attributes, not a separate decision.
    """
    from src.services.knowledge_store import KnowledgeStore

    from services.kb_reindex import kb_index_lock

    await _cancel_kb_datasource_reindexes(datasource_id)
    kb_id = UUID(datasource_id)
    store = KnowledgeStore(db=vector_db, embedding_service=None)
    async with kb_index_lock(store, kb_id, wait=True) as lock_conn:
        await store.delete_kb_index(kb_id, conn=lock_conn)
        return await postgres_db.delete_datasource(
            datasource_id,
            authority_project_scope_id=authority_project_scope_id,
            deleted_by=deleted_by,
        )


async def _reindex_project_kb(
    project_id: str,
    *,
    repo_name: str | None = None,
    branch: str | None = None,
    force_full: bool = False,
) -> dict[str, Any]:
    """Bring a project KB's chunk index up to its repo HEAD (slice 3 PR3).

    Shared entry for the post-write trigger and the operator reindex endpoint.
    Resolves the dedicated knowledge vault (with a legacy jobs-role fallback)
    when not supplied, builds the
    catalog-resolved embedding service, and runs the tree-diff reindex. Returns
    the reindex summary dict; ``status`` carries the honesty signal
    (no-repo / no-embedding-service / up-to-date / completed / partial / ...).
    """
    from src.services.knowledge_store import KnowledgeStore

    from services.kb_forge import kb_client_for_repo
    from services.kb_reindex import reindex_kb, resolve_kb_repo

    repo_client = gitea_client
    if not repo_name:
        resolved = await resolve_kb_repo(postgres_db, project_id)
        if not resolved:
            return {"status": "no-repo"}
        repo_name, branch = resolved.repo, resolved.branch
        repo_client = await kb_client_for_repo(postgres_db, gitea_client, resolved)
    svc = await _build_kb_embedding_service()
    if svc is None:
        logger.warning(
            "kb_reindex: no embedding service resolvable for project %s — "
            "skipping (check the system embedding in Admin → Models)",
            project_id,
        )
        return {"status": "no-embedding-service"}
    store = KnowledgeStore(db=vector_db, embedding_service=svc)
    result = await reindex_kb(
        gitea_client=repo_client,
        store=store,
        embedding_service=svc,
        kb_id=UUID(project_id),
        repo_name=repo_name,
        branch=branch or "main",
        force_full=force_full,
    )
    if result.get("status") in {"completed", "up-to-date"}:
        # A successful rebuild is also the recovery path for a canonical Git
        # mutation whose direct projection failed.  The scheduled sweep
        # already settles this ledger; manual/post-write reindex must expose
        # the same truth rather than leaving an eligibility-blocking intent.
        result = dict(result)
        result[
            "projection_intents_synced"
        ] = await postgres_db.mark_knowledge_projections_synced(project_id)
    return result


@app.post("/api/projects/{project_id}/knowledge/reindex")
async def reindex_knowledge(
    request: Request, project_id: str, full: bool = False
) -> dict[str, Any]:
    """Rebuild/refresh the KB chunk index from the vault repo (slice 3 PR3).

    The ``kb reindex --full`` operator hatch (§5): ``full=true`` re-embeds the
    whole vault (model/chunker migration, corrupt-index recovery); the default
    incremental run only touches notes whose git blob changed. F5: member-only,
    same gate as the sibling knowledge endpoints.
    """
    await require_project_member(request, postgres_db, project_id)
    try:
        return await _reindex_project_kb(project_id, force_full=full)
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e


@app.post("/api/projects/{project_id}/knowledge/materialize")
async def materialize_knowledge_note(
    request: Request,
    project_id: str,
    body: KnowledgeMaterializeRequest,
) -> dict[str, Any]:
    """Commit one rendered note to ``knowledge/<slug>.md`` in the project's KB
    repo. **Internal** (P4b) — requires ``X-Internal-Key``.

    Step 3 of knowledge-base/knowledge/features/knowledge_base_repo_separation.md: the agent used
    to write this file into its workspace checkout, which welded the vault to
    the jobs repo and skipped entirely wherever there was no git (persistent
    sessions, lite tiers, repo-less projects). The write is server-side now —
    one note, one commit, into whichever repo ``resolve_kb_repo`` picks.

    Always answers 200 with the service's ``{status, reason, repo, branch,
    path, operation, indexed, index_reason}``; the failure vocabulary lives in
    the body, not the HTTP code. ``indexed`` reports whether the note is
    searchable already — ``false`` with an ``index_reason`` means the commit
    landed and the sweep will finish the job.
    """
    await require_internal(request)
    from services.kb_materialize import (
        materialize_knowledge_note as _materialize_note,
    )

    # Slice A: hand the materialiser an indexer so the note is searchable when
    # this call returns. Both legs are optional by design — a deployment with
    # no resolvable embedding service commits the note and lets the sweep
    # index it, which is exactly the pre-Slice-A behaviour.
    store = None
    svc = None
    try:
        svc = await _build_kb_embedding_service()
        if svc is not None:
            from src.services.knowledge_store import KnowledgeStore

            store = KnowledgeStore(db=vector_db, embedding_service=svc)
        else:
            # INFO, not WARNING: a deployment with no system embedding is a
            # valid degraded configuration, not a fault. But it silently
            # disables inline indexing for EVERY write in the deployment, so
            # it needs one log line an operator can find — without it the
            # only evidence is `indexed=deferred:no-indexer` in a transcript.
            logger.info(
                "kb-materialize: no embedding service resolvable for project "
                "%s — the note will commit and be indexed by the next sweep "
                "(check the system embedding in Admin → Models)",
                project_id,
            )
    except Exception:
        logger.warning(
            "kb-materialize: no inline indexer for project %s — the note will "
            "commit and be indexed by the next sweep",
            project_id,
            exc_info=True,
        )
        store = None
        svc = None

    return await _materialize_note(
        postgres_db=postgres_db,
        gitea_client=gitea_client,
        project_id=project_id,
        slug=body.slug,
        content=body.content,
        job_id=body.job_id,
        store=store,
        embedding_service=svc,
        retrieval_messages=body.retrieval_messages,
        expected_blob_sha=body.expected_blob_sha,
    )


@app.post("/api/projects/{project_id}/knowledge/materialize/{intent_id}/projection")
async def record_knowledge_projection(
    request: Request,
    project_id: str,
    intent_id: str,
    body: KnowledgeProjectionRequest,
) -> dict[str, Any]:
    """Record projection truth after a canonical internal knowledge write."""
    await require_internal(request)
    result = await postgres_db.finish_knowledge_projection(
        intent_id,
        project_id=project_id,
        synced=body.synced,
        error=body.error,
    )
    if result is None:
        raise HTTPException(status_code=404, detail="canonical intent not found")
    return result


@app.post("/api/projects/{project_id}/knowledge/search")
async def search_knowledge(
    request: Request,
    project_id: str,
    body: KnowledgeSearchRequest,
) -> dict[str, Any]:
    """Hybrid search over project knowledge base. F5: member-only."""
    await require_project_member(request, postgres_db, project_id)

    try:
        async with vector_db.acquire() as conn:
            # Try dense+sparse search if embedding service available
            embedding = None
            try:
                import sys

                project_root = str(Path(__file__).parent.parent)
                if project_root not in sys.path:
                    sys.path.insert(0, project_root)
                from src.services.embedding_service import get_embedding_service

                svc = get_embedding_service()
                embedding = await svc.embed(body.query)
            except Exception:
                pass  # Fall back to sparse-only search

            if embedding:
                rows = await conn.fetch(
                    "SELECT * FROM knowledge_hybrid_search($1, $2::vector, $3, $4)",
                    body.query,
                    str(embedding),
                    project_id,
                    body.limit,
                )
            else:
                # Sparse-only fallback: tsvector keyword search
                rows = await conn.fetch(
                    "SELECT * FROM knowledge_index "
                    "WHERE project_id = $1 AND search_doc @@ websearch_to_tsquery($2) "
                    "ORDER BY ts_rank_cd(search_doc, websearch_to_tsquery($2)) DESC "
                    "LIMIT $3",
                    project_id,
                    body.query,
                    body.limit,
                )

            notes = []
            for r in rows:
                d = dict(r)
                d.pop("embedding", None)
                d.pop("search_doc", None)
                notes.append(d)

        return {"notes": notes, "query": body.query, "total": len(notes)}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e


@app.patch("/api/projects/{project_id}/knowledge/{note_id}")
async def update_knowledge_note(
    request: Request,
    project_id: str,
    note_id: str,
    body: KnowledgeNoteUpdate,
) -> dict[str, Any]:
    """Update a knowledge note's status or tags. F5: member-only."""
    # An archived project is read-only, and a note edit is a content mutation
    # rather than teardown — deleting a note stays allowed, editing one does not.
    await require_project_member(request, postgres_db, project_id, allow_archived=False)
    valid_statuses = {"active", "resolved", "superseded", "archived"}
    if body.status and body.status not in valid_statuses:
        raise HTTPException(
            status_code=400,
            detail=f"Invalid status '{body.status}'. Must be one of: {valid_statuses}",
        )

    if not (body.status or body.add_tags or body.remove_tags):
        return {"status": "no_changes"}

    materialization: dict[str, Any] | None = None
    try:
        # The index proves the public note exists, but is never mutated before
        # the canonical git boundary succeeds.
        async with vector_db.acquire() as conn:
            row = await conn.fetchrow(
                "SELECT note_id FROM knowledge_index "
                "WHERE project_id = $1 AND note_id = $2",
                project_id,
                note_id,
            )
            if not row:
                raise HTTPException(
                    status_code=404,
                    detail=f"Note '{note_id}' not found in project '{project_id}'",
                )

        from services.kb_materialize import materialize_knowledge_metadata_update

        materialization = await materialize_knowledge_metadata_update(
            postgres_db=postgres_db,
            gitea_client=gitea_client,
            project_id=project_id,
            slug=note_id,
            status=body.status,
            add_tags=body.add_tags,
            remove_tags=body.remove_tags,
        )
        if materialization.get("canonical_state") != "canonical":
            raise HTTPException(
                status_code=409,
                detail={
                    "status": "pending_sync",
                    "reason": materialization.get("reason"),
                    "retry_state": materialization.get("retry_state"),
                    "intent_id": materialization.get("intent_id"),
                },
            )

        required_metadata = []
        if body.status:
            required_metadata.append("canonical_status")
        if body.add_tags or body.remove_tags:
            required_metadata.extend(("canonical_tags", "canonical_ready_at"))
        if materialization.get("canonical_metadata_complete") is not True or any(
            field not in materialization for field in required_metadata
        ):
            raise HTTPException(
                status_code=409,
                detail={
                    "status": "pending_sync",
                    "reason": materialization.get("reason")
                    or "canonical-metadata-unavailable",
                    "retry_state": materialization.get("retry_state"),
                    "intent_id": materialization.get("intent_id"),
                },
            )

        async with vector_db.acquire() as conn:
            updates = []
            params: list[Any] = [project_id, note_id]
            idx = 3

            if body.status:
                canonical_status = materialization["canonical_status"]
                if canonical_status is None:
                    raise HTTPException(
                        status_code=409,
                        detail={
                            "status": "pending_sync",
                            "reason": "canonical-status-unavailable",
                            "retry_state": materialization.get("retry_state"),
                            "intent_id": materialization.get("intent_id"),
                        },
                    )
                updates.append(f"status = ${idx}")
                params.append(str(canonical_status))
                idx += 1

            if body.add_tags or body.remove_tags:
                canonical_tags = materialization["canonical_tags"]
                if not isinstance(canonical_tags, list):
                    raise HTTPException(
                        status_code=409,
                        detail={
                            "status": "pending_sync",
                            "reason": "canonical-tags-invalid",
                            "retry_state": materialization.get("retry_state"),
                            "intent_id": materialization.get("intent_id"),
                        },
                    )
                raw_ready_at = materialization["canonical_ready_at"]
                if isinstance(raw_ready_at, datetime):
                    canonical_ready_at = raw_ready_at
                elif raw_ready_at is None:
                    canonical_ready_at = None
                else:
                    raise HTTPException(
                        status_code=409,
                        detail={
                            "status": "pending_sync",
                            "reason": "canonical-ready-at-invalid",
                            "retry_state": materialization.get("retry_state"),
                            "intent_id": materialization.get("intent_id"),
                        },
                    )
                if canonical_ready_at is not None and canonical_ready_at.tzinfo is None:
                    canonical_ready_at = canonical_ready_at.replace(tzinfo=timezone.utc)
                updates.append(f"tags = ${idx}::text[]")
                params.append([str(tag) for tag in canonical_tags])
                idx += 1
                updates.append(f"ready_at = ${idx}::timestamptz")
                params.append(canonical_ready_at)
                idx += 1

            updates.append("modified_at = NOW()")
            set_clause = ", ".join(updates)
            projected = await conn.fetchval(
                f"UPDATE knowledge_index SET {set_clause} "
                f"WHERE project_id = $1 AND note_id = $2 RETURNING note_id",
                *params,
            )
            if projected is None:
                raise RuntimeError("knowledge projection row disappeared")

        # Neo4j is an optional derived graph. The durable projection leg is the
        # pgvector index above because the canonical Git reindexer can rebuild
        # it. Do not leave the intent permanently pending for an optional graph
        # outage the reindexer cannot repair.
        kg = _get_knowledge_graph()
        if kg:
            try:
                update_kwargs: dict[str, Any] = {}
                if body.status:
                    update_kwargs["status"] = str(materialization["canonical_status"])
                if body.add_tags:
                    update_kwargs["add_tags"] = body.add_tags
                if body.remove_tags:
                    update_kwargs["remove_tags"] = body.remove_tags
                if update_kwargs:
                    if not kg.update_note(project_id, note_id, **update_kwargs):
                        raise RuntimeError("graph note disappeared during projection")
            except Exception as e:
                logger.warning("Neo4j update failed for %s: %s", note_id, e)

        projection = await postgres_db.finish_knowledge_projection(
            str(materialization["intent_id"]),
            project_id=project_id,
            synced=True,
        )
        if projection is None:
            raise RuntimeError("knowledge projection ledger did not converge")

        return {
            "status": "updated",
            "canonical_state": "canonical",
            "projection_state": "synced",
            "intent_id": materialization.get("intent_id"),
        }
    except HTTPException:
        raise
    except Exception as e:
        if materialization and materialization.get("intent_id"):
            try:
                await postgres_db.finish_knowledge_projection(
                    str(materialization["intent_id"]),
                    project_id=project_id,
                    synced=False,
                    error=str(e),
                )
            except Exception:
                logger.exception("failed to persist knowledge projection failure")
        raise HTTPException(status_code=500, detail=str(e)) from e


@app.delete("/api/projects/{project_id}/knowledge/{note_id}")
async def delete_knowledge_note(
    request: Request, project_id: str, note_id: str
) -> dict[str, Any]:
    """Purge a knowledge note: file-removal commit, then both index stores.

    F5: member-only. A human's delete is immediate and unconditional (no
    compare-and-swap token) — that authority is the point of the cockpit
    button. Before kb_gardening G2 this removed only the index row, and the
    next sweep resurrected the note from the file it never touched.
    """
    await require_project_member(request, postgres_db, project_id)
    from services.kb_materialize import materialize_knowledge_note_delete
    from src.services.knowledge_store import KnowledgeStore

    store = KnowledgeStore(db=vector_db, embedding_service=None)
    try:
        result = await materialize_knowledge_note_delete(
            postgres_db=postgres_db,
            gitea_client=gitea_client,
            project_id=project_id,
            slug=note_id,
            reason="deleted from the cockpit",
            store=store,
        )
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e

    status, reason = result.get("status"), result.get("reason")
    if status == "failed":
        raise HTTPException(
            status_code=409 if reason == "precondition-failed" else 502,
            detail=f"Note '{note_id}' was not removed from the knowledge repo ({reason}).",
        )
    if status == "skipped" and reason not in {"absent", "already-canonical", "no-repo"}:
        raise HTTPException(
            status_code=409,
            detail=f"Note '{note_id}' delete is still in progress ({reason}).",
        )
    file_removed = status == "committed"
    row_deleted = bool(result.get("row_deleted"))
    if not file_removed and not row_deleted and reason in {"absent", "no-repo"}:
        raise HTTPException(
            status_code=404,
            detail=f"Note '{note_id}' not found in project '{project_id}'",
        )

    # Delete from Neo4j if available (optional projection; best-effort).
    kg = _get_knowledge_graph()
    if kg:
        try:
            kg._db.execute_write(
                "MATCH (n:Note {project_id: $pid, id: $nid}) DETACH DELETE n",
                {"pid": project_id, "nid": note_id},
            )
        except Exception as e:
            logger.warning(f"Neo4j delete failed for {note_id}: {e}")

    return {
        "status": "deleted",
        "file_removed": file_removed,
        "row_deleted": row_deleted,
        "path": result.get("path"),
    }


class KnowledgeDeleteRequest(BaseModel):
    """Request body for the internal purge of one note (agent/purge callers)."""

    slug: str = Field(..., description="Note id — knowledge/<slug>.md in the KB repo")
    job_id: str | None = Field(
        None, description="Calling job UUID, for commit attribution"
    )
    reason: str | None = Field(
        None, description="Why — journaled in the commit message"
    )
    expected_blob_sha: str | None = Field(
        None,
        description=(
            "Compare-and-swap token: the blob SHA the caller read. The delete is "
            "refused (failed/precondition-failed) if the repo holds another blob."
        ),
    )


@app.post("/api/projects/{project_id}/knowledge/delete")
async def delete_knowledge_note_internal(
    request: Request,
    project_id: str,
    body: KnowledgeDeleteRequest,
) -> dict[str, Any]:
    """Purge one note from the KB repo and its index. **Internal** — requires
    ``X-Internal-Key``. Same result vocabulary as the materialize endpoint
    (HTTP 200 always; ``status``/``reason`` carry the outcome) plus
    ``row_deleted``. Agents do not call this directly — ``kb_delete`` is a
    tombstone — it exists for the purge lane and for operator tooling.
    """
    await require_internal(request)
    from services.kb_materialize import materialize_knowledge_note_delete
    from src.services.knowledge_store import KnowledgeStore

    store = KnowledgeStore(db=vector_db, embedding_service=None)
    return await materialize_knowledge_note_delete(
        postgres_db=postgres_db,
        gitea_client=gitea_client,
        project_id=project_id,
        slug=body.slug,
        job_id=body.job_id,
        reason=body.reason,
        expected_blob_sha=body.expected_blob_sha,
        store=store,
    )


@app.post("/api/projects/{project_id}/knowledge/export")
async def export_knowledge(request: Request, project_id: str) -> dict[str, Any]:
    """Export project knowledge base as Obsidian-compatible markdown files.

    F5: member-only. Same access requirement as the per-note read endpoint
    — the bulk export is equivalent to scraping the list and getting each
    note individually, so a tighter gate wouldn't close a real gap.
    """
    _, project = await require_project_member(request, postgres_db, project_id)

    kg = _get_knowledge_graph()
    if not kg:
        raise HTTPException(
            status_code=503,
            detail="Neo4j not available — cannot export knowledge base",
        )

    try:
        import tempfile

        export_dir = Path(tempfile.mkdtemp(prefix="kb_export_"))
        notes = kg.get_all_notes_for_export(project_id)

        for note in notes:
            # Build frontmatter
            fm_lines = ["---"]
            fm_lines.append(f"id: {note['id']}")
            fm_lines.append(f"type: {note['type']}")
            if note.get("tags"):
                fm_lines.append(f"tags: [{', '.join(note['tags'])}]")
            if note.get("keywords"):
                fm_lines.append(f"keywords: [{', '.join(note['keywords'])}]")
            if note.get("confidence"):
                fm_lines.append(f"confidence: {note['confidence']}")
            fm_lines.append(f"status: {note.get('status', 'active')}")
            if note.get("job_id"):
                fm_lines.append(f"job_id: {note['job_id']}")
            if note.get("phase"):
                fm_lines.append(f"phase: {note['phase']}")
            if note.get("created"):
                fm_lines.append(f"created: {note['created']}")
            if note.get("modified"):
                fm_lines.append(f"modified: {note['modified']}")
            fm_lines.append("---")
            fm_lines.append("")

            # Title and content
            fm_lines.append(f"# {note.get('title', note['id'])}")
            fm_lines.append("")
            if note.get("content"):
                fm_lines.append(note["content"])
                fm_lines.append("")

            # Relationships as wikilinks
            if note.get("relationships"):
                by_type: dict[str, list[str]] = {}
                for rel in note["relationships"]:
                    rtype = rel.get("type", "REFERENCES")
                    target = rel.get("target", "")
                    by_type.setdefault(rtype, []).append(target)
                for rtype, targets in by_type.items():
                    links = ", ".join(f"[[{t}]]" for t in targets)
                    fm_lines.append(f"**{rtype}:** {links}")

            file_name = f"{note['id']}.md"
            (export_dir / file_name).write_text("\n".join(fm_lines), encoding="utf-8")

        return {
            "status": "exported",
            "path": str(export_dir),
            "note_count": len(notes),
            "project_name": project.get("name", ""),
        }
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e
